-- ============================================================================
-- ROLE GRANTS  -  required for PostgREST / Supabase API access
-- ============================================================================
-- pg_dump --no-acl strips these; on a fresh Supabase project the standard
-- anon/authenticated/service_role roles need explicit grants on every table,
-- sequence, and routine, otherwise PostgREST returns 403 (PG error 42501)
-- before RLS policies are even evaluated.

GRANT USAGE ON SCHEMA public TO postgres, anon, authenticated, service_role;

GRANT ALL ON ALL TABLES    IN SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON ALL ROUTINES  IN SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO postgres, anon, authenticated, service_role;

ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT ALL ON TABLES    TO postgres, anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT ALL ON ROUTINES  TO postgres, anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT ALL ON SEQUENCES TO postgres, anon, authenticated, service_role;


-- ============================================================
-- Source: 20260619120000_workflow_step_conditions_rpc.sql
-- ============================================================
-- ============================================================================
-- update_workflow_step_conditions  -  UPDATE conditional flag + types
-- ============================================================================
-- Lets admins flip an existing approval step between "always trigger" and
-- "trigger only when the workflow's runtime value is in this list".
--
-- Used by the ApprovalChainConfig UI in master-data/users.

CREATE OR REPLACE FUNCTION public.update_workflow_step_conditions(
  p_step_id         UUID,
  p_is_conditional  BOOLEAN,
  p_condition_types TEXT[]
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  UPDATE workflow_approval_steps
  SET is_conditional  = p_is_conditional,
      condition_types = CASE
        WHEN p_is_conditional THEN COALESCE(p_condition_types, ARRAY[]::TEXT[])
        ELSE ARRAY[]::TEXT[]
      END
  WHERE id = p_step_id AND archived_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Step not found or already archived';
  END IF;
END;
$$;

GRANT EXECUTE ON FUNCTION public.update_workflow_step_conditions TO authenticated;

NOTIFY pgrst, 'reload schema';


-- ============================================================
-- Source: 20260619140000_fix_paid_amount_sync.sql
-- ============================================================
-- ============================================================================
-- Fix: allocate_payment_to_bill never updated invoices.paid_amount
-- ============================================================================
-- Symptom: Bill detail page showed "Total Paid: QAR 0.00" even when the
-- Payment History table listed payments totaling the full bill amount.
--
-- Cause: allocate_payment_to_bill recalculated payment_status from the
-- payment_bill_allocations table but never wrote the matching paid_amount
-- back to invoices. The bill row's paid_amount stayed at 0 forever.
--
-- Fix: also UPDATE invoices.paid_amount = SUM(allocations) in the same RPC.
-- Plus a one-shot backfill for every bill whose paid_amount disagrees with
-- its allocation total.

CREATE OR REPLACE FUNCTION public.allocate_payment_to_bill(
  p_payment_id uuid,
  p_bill_id    uuid,
  p_amount     numeric
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_payment_total   NUMERIC;
  v_already_alloc   NUMERIC;
  v_bill_total      NUMERIC;
  v_manually_paid   BOOLEAN;
  v_total_paid      NUMERIC;
  v_new_status      TEXT;
BEGIN
  -- Lock payment row to serialize concurrent allocations
  SELECT amount INTO v_payment_total
  FROM payments WHERE id = p_payment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payment % does not exist', p_payment_id;
  END IF;

  -- Verify bill exists and get manually_paid flag
  SELECT total_amount, manually_paid INTO v_bill_total, v_manually_paid
  FROM invoices WHERE id = p_bill_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bill % does not exist', p_bill_id;
  END IF;

  -- Validate amount
  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'Allocation amount must be greater than zero';
  END IF;

  -- Check total allocations would not exceed payment amount
  SELECT COALESCE(SUM(amount), 0) INTO v_already_alloc
  FROM payment_bill_allocations
  WHERE payment_id = p_payment_id
    AND bill_id != p_bill_id;

  IF v_already_alloc + p_amount > v_payment_total THEN
    RAISE EXCEPTION 'Allocation of % exceeds remaining payment balance of %',
      p_amount, v_payment_total - v_already_alloc;
  END IF;

  -- Upsert allocation
  INSERT INTO payment_bill_allocations (payment_id, bill_id, amount)
  VALUES (p_payment_id, p_bill_id, p_amount)
  ON CONFLICT (payment_id, bill_id)
  DO UPDATE SET amount = EXCLUDED.amount;

  -- Always recalculate the cached totals on the bill, even when manually_paid
  -- so the displayed paid_amount + balance stay correct.
  SELECT COALESCE(SUM(pba.amount), 0)
    INTO v_total_paid
    FROM payment_bill_allocations pba
   WHERE pba.bill_id = p_bill_id;

  v_new_status := CASE
    WHEN v_total_paid >= v_bill_total THEN 'paid'
    WHEN v_total_paid > 0             THEN 'partially_paid'
    ELSE                                   'unpaid'
  END;

  UPDATE invoices
     SET paid_amount    = v_total_paid,
         payment_status = CASE WHEN v_manually_paid THEN payment_status ELSE v_new_status END
   WHERE id = p_bill_id;
END;
$$;

-- One-time backfill: every invoice whose paid_amount disagrees with the
-- allocation total gets corrected.
UPDATE invoices i
   SET paid_amount = COALESCE(a.total, 0)
  FROM (
    SELECT bill_id, SUM(amount) AS total
    FROM payment_bill_allocations
    GROUP BY bill_id
  ) a
 WHERE a.bill_id = i.id
   AND COALESCE(i.paid_amount, 0) <> a.total;

NOTIFY pgrst, 'reload schema';


-- ============================================================
-- Source: 20260620135552_demote_non_seeded_system_roles.sql
-- ============================================================
-- Demote any custom_role that's been incorrectly flagged as is_system = true.
--
-- `is_system = true` is treated as "system admin, bypass all permission checks"
-- everywhere in the app:
--   - src/hooks/usePermissions.ts:41 (client UI)
--   - src/lib/auth/require-admin.ts:119 (server routes)
--   - dozens of RLS policies (invoices.manage, contracts.activate,
--     master_data.services.approve, etc.)
--
-- Only the seeded 'Admin' / 'Owner' roles are meant to carry this flag.
-- If any other role acquired it via manual SQL / Supabase Studio editing,
-- anyone assigned to that role silently gets full access regardless of
-- their `permissions` array. This migration fixes that.

BEGIN;

UPDATE custom_roles
SET    is_system = false
WHERE  is_system = true
  AND  name NOT IN ('Admin', 'Owner');

COMMIT;


-- ============================================================
-- Source: 20260620141523_warehouse_perms_restructure.sql
-- ============================================================
-- Restructure Warehouse permissions: add a top-level access gate +
-- per-tab view keys. Existing action keys (warehouse.transfer.create,
-- warehouse.check.count, warehouse.adjustment.request, etc.) are kept
-- as-is so no existing role loses anything.
--
-- For every role that already holds a related action permission, we
-- seed the matching new view-key here so the tab keeps showing up after
-- the UI starts gating on it.
--
-- New keys introduced:
--   warehouse.access              — master gate (Master Data ▸ Warehouse link)
--   warehouse.warehouses.view     — Warehouses tab
--   warehouse.transfers.view      — Transfers tab
--   warehouse.adjustments.view    — Adjustments tab
--   warehouse.checks.view         — Inv. Checks tab
--   warehouse.stock_value.view    — Stock Value tab
--   warehouse.movements.view      — Movements tab
--   warehouse.receivals.view      — Receivals & Deliveries tab

BEGIN;

-- Helper: idempotent array-append (only adds the key if it isn't there yet).
-- Implemented inline per role / per key so the migration is re-runnable.

-- 1. warehouse.access — anyone with ANY warehouse.* perm
UPDATE custom_roles
SET    permissions = permissions || ARRAY['warehouse.access']
WHERE  deleted_at IS NULL
  AND  NOT ('warehouse.access' = ANY(permissions))
  AND  EXISTS (SELECT 1 FROM unnest(permissions) p WHERE p LIKE 'warehouse.%');

-- 2. warehouse.warehouses.view — anyone who can manage warehouse settings
UPDATE custom_roles
SET    permissions = permissions || ARRAY['warehouse.warehouses.view']
WHERE  deleted_at IS NULL
  AND  NOT ('warehouse.warehouses.view' = ANY(permissions))
  AND  'warehouse.settings.manage' = ANY(permissions);

-- 3. warehouse.transfers.view — anyone with ANY transfer action perm
UPDATE custom_roles
SET    permissions = permissions || ARRAY['warehouse.transfers.view']
WHERE  deleted_at IS NULL
  AND  NOT ('warehouse.transfers.view' = ANY(permissions))
  AND  EXISTS (SELECT 1 FROM unnest(permissions) p WHERE p LIKE 'warehouse.transfer.%');

-- 4. warehouse.adjustments.view — anyone who can request adjustments
UPDATE custom_roles
SET    permissions = permissions || ARRAY['warehouse.adjustments.view']
WHERE  deleted_at IS NULL
  AND  NOT ('warehouse.adjustments.view' = ANY(permissions))
  AND  'warehouse.adjustment.request' = ANY(permissions);

-- 5. warehouse.checks.view — anyone with ANY check perm
UPDATE custom_roles
SET    permissions = permissions || ARRAY['warehouse.checks.view']
WHERE  deleted_at IS NULL
  AND  NOT ('warehouse.checks.view' = ANY(permissions))
  AND  EXISTS (SELECT 1 FROM unnest(permissions) p WHERE p LIKE 'warehouse.check.%');

-- 6. warehouse.stock_value.view — anyone who can view stock
UPDATE custom_roles
SET    permissions = permissions || ARRAY['warehouse.stock_value.view']
WHERE  deleted_at IS NULL
  AND  NOT ('warehouse.stock_value.view' = ANY(permissions))
  AND  'warehouse.stock.view' = ANY(permissions);

-- 7. warehouse.movements.view — anyone who can view stock
UPDATE custom_roles
SET    permissions = permissions || ARRAY['warehouse.movements.view']
WHERE  deleted_at IS NULL
  AND  NOT ('warehouse.movements.view' = ANY(permissions))
  AND  'warehouse.stock.view' = ANY(permissions);

-- 8. warehouse.receivals.view — anyone with purchase.receivals.view or sales.deliveries.view
UPDATE custom_roles
SET    permissions = permissions || ARRAY['warehouse.receivals.view']
WHERE  deleted_at IS NULL
  AND  NOT ('warehouse.receivals.view' = ANY(permissions))
  AND  ('purchase.receivals.view' = ANY(permissions) OR 'sales.deliveries.view' = ANY(permissions));

COMMIT;


-- ============================================================
-- Source: 20260620142808_module_access_gates.sql
-- ============================================================
-- Add *.access permission keys to existing roles so the new nav-level gates
-- (master_data.access, purchase_sales.access, orders.access, invoices.access,
--  contracts.access, teams.access, reports.access) don't regress any role
-- that already had inner-page permissions.
--
-- Each top-level nav dropdown now requires its module's access key. The
-- inner items still have their own per-page permissions. Without this
-- backfill, every role that previously held only inner-page perms
-- (Field RP, Accountant, Purchase Manager, etc.) would lose dropdown
-- visibility.

BEGIN;

-- ── Master Data dropdown ──────────────────────────────────────────────
-- Includes: Warehouses (warehouse.access), Users & Roles, Audit Trail,
-- Admin, Service Customers, Services, Teams & Employees (teams.view),
-- Subscription Packages.
UPDATE custom_roles
SET    permissions = permissions || ARRAY['master_data.access']
WHERE  deleted_at IS NULL
  AND  NOT ('master_data.access' = ANY(permissions))
  AND  EXISTS (
    SELECT 1 FROM unnest(permissions) p
    WHERE p LIKE 'master_data.%'
       OR p = 'warehouse.access'
       OR p = 'teams.view'
  );

-- ── Purchase & Sales dropdown ─────────────────────────────────────────
-- Includes: Suppliers, Customers (master_data.*), Purchase Orders,
-- Approvals, Shipments, Receivals, Landed Costs, Bills, RFQ, Dead Stock
-- (purchase.*), Sale Orders, Invoices, Returns, Deliveries, Credit Notes
-- (sales.*).
UPDATE custom_roles
SET    permissions = permissions || ARRAY['purchase_sales.access']
WHERE  deleted_at IS NULL
  AND  NOT ('purchase_sales.access' = ANY(permissions))
  AND  EXISTS (
    SELECT 1 FROM unnest(permissions) p
    WHERE p LIKE 'purchase.%'
       OR p LIKE 'sales.%'
       OR p IN (
         'master_data.suppliers.view', 'master_data.suppliers.manage',
         'master_data.customers.view', 'master_data.customers.manage'
       )
  );

-- ── Orders dropdown ───────────────────────────────────────────────────
-- Includes: Orders, Quotations.
UPDATE custom_roles
SET    permissions = permissions || ARRAY['orders.access']
WHERE  deleted_at IS NULL
  AND  NOT ('orders.access' = ANY(permissions))
  AND  EXISTS (
    SELECT 1 FROM unnest(permissions) p
    WHERE p LIKE 'orders.%'
       OR p LIKE 'follow_ups.%'
       OR p LIKE 'quotations.%'
  );

-- ── Invoices dropdown ─────────────────────────────────────────────────
-- Includes: Invoices, Payments.
UPDATE custom_roles
SET    permissions = permissions || ARRAY['invoices.access']
WHERE  deleted_at IS NULL
  AND  NOT ('invoices.access' = ANY(permissions))
  AND  EXISTS (
    SELECT 1 FROM unnest(permissions) p
    WHERE p LIKE 'invoices.%' OR p LIKE 'payments.%'
  );

-- ── Contracts dropdown ────────────────────────────────────────────────
UPDATE custom_roles
SET    permissions = permissions || ARRAY['contracts.access']
WHERE  deleted_at IS NULL
  AND  NOT ('contracts.access' = ANY(permissions))
  AND  EXISTS (
    SELECT 1 FROM unnest(permissions) p WHERE p LIKE 'contracts.%'
  );

-- ── Teams dropdown ────────────────────────────────────────────────────
-- Includes: Map, Calendar, Team Leader.
UPDATE custom_roles
SET    permissions = permissions || ARRAY['teams.access']
WHERE  deleted_at IS NULL
  AND  NOT ('teams.access' = ANY(permissions))
  AND  EXISTS (
    SELECT 1 FROM unnest(permissions) p
    WHERE p LIKE 'teams.%' OR p LIKE 'employees.%' OR p LIKE 'calendar.%'
  );

-- ── Reports dropdown ──────────────────────────────────────────────────
UPDATE custom_roles
SET    permissions = permissions || ARRAY['reports.access']
WHERE  deleted_at IS NULL
  AND  NOT ('reports.access' = ANY(permissions))
  AND  EXISTS (
    SELECT 1 FROM unnest(permissions) p WHERE p LIKE 'reports.%'
  );

COMMIT;


-- ============================================================
-- Source: 20260620143410_seed_system_admin_on_owner_roles.sql
-- ============================================================
-- Seed the `system.admin` permission key on every role that currently
-- has `is_system = true`. This makes the full-access bypass authorable
-- from the role-edit UI (toggle "Full System Access (Owner)" in the
-- System module) instead of being DB-only via the is_system column.
--
-- Both mechanisms are checked in code now (usePermissions hook +
-- requireAdmin/requirePermission server gates + admin layout):
--   is_system = true OR permissions @> '{system.admin}' → bypass.

BEGIN;

UPDATE custom_roles
SET    permissions = permissions || ARRAY['system.admin']
WHERE  deleted_at IS NULL
  AND  is_system = true
  AND  NOT ('system.admin' = ANY(permissions));

COMMIT;


