-- ============================================================
-- Source: 20260620150100_country_codes_seq_align.sql
-- ============================================================
-- Idempotent: re-align country_codes.id sequence to MAX(id).
-- Needed on environments where rows were inserted with explicit IDs (e.g. fresh staging
-- seed) so the SERIAL sequence doesn't collide with existing primary keys.

SELECT setval(
  pg_get_serial_sequence('public.country_codes', 'id'),
  COALESCE((SELECT MAX(id) FROM public.country_codes), 1),
  true
);


-- ============================================================
-- Source: 20260620153000_normalize_approval_chain_tier_roles.sql
-- ============================================================
-- Normalize legacy snake_case role slugs in approval_chain_tiers.required_roles
-- to the current custom_roles.name (Title Case).
--
-- Background: tiers were originally created when the approver list was a fixed
-- enum of slugs ('purchase_manager', 'accountant', 'owner'). After the unified
-- roles migration, custom_roles.name became the source of truth and uses Title
-- Case display names. The UI compares required_roles against custom_roles.name,
-- so any tier still holding a slug shows up as "no assignees" even when users
-- are correctly assigned to the corresponding role.
--
-- workflow_approval_steps.step_key still carries the legacy slug and
-- workflow_approval_steps.role_id points to the matching custom_roles row, so
-- the slug → display-name mapping is recoverable from the DB itself rather
-- than hardcoded.

WITH slug_map AS (
  SELECT DISTINCT wf.step_key AS old_slug, cr.name AS new_name
  FROM workflow_approval_steps wf
  JOIN custom_roles cr ON cr.id = wf.role_id
  WHERE wf.workflow = 'po'
    AND wf.archived_at IS NULL
    AND cr.deleted_at IS NULL
)
UPDATE approval_chain_tiers t
SET required_roles = (
  SELECT array_agg(
    COALESCE((SELECT new_name FROM slug_map WHERE old_slug = elem), elem)
  )
  FROM unnest(t.required_roles) AS elem
)
WHERE t.deleted_at IS NULL
  AND EXISTS (
    SELECT 1
    FROM unnest(t.required_roles) AS elem
    WHERE elem IN (SELECT old_slug FROM slug_map)
  );


-- ============================================================
-- Source: 20260621100000_profiles_has_contact_centre_access.sql
-- ============================================================
-- Add a direct per-user toggle for Contact Centre access that is independent
-- of the role-permission system. Mirrors the pattern used for `is_division_manager`.
--
-- Backwards compatibility: anyone whose role currently grants the
-- `contact_centre.view` permission is backfilled to `true` so day-1 behaviour
-- is identical to before this column existed. The gate checks BOTH this flag
-- AND the role permission going forward.

ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS has_contact_centre_access boolean NOT NULL DEFAULT false;

-- Backfill from existing role assignments. Idempotent: re-running has no effect
-- because every matching row already has the value we'd set.
UPDATE public.profiles p
SET    has_contact_centre_access = true
WHERE  p.has_contact_centre_access = false
  AND  EXISTS (
    SELECT 1
    FROM   public.user_custom_roles ucr
    JOIN   public.custom_roles cr ON cr.id = ucr.role_id
    WHERE  ucr.profile_id = p.id
      AND  'contact_centre.view' = ANY (cr.permissions)
  );

COMMENT ON COLUMN public.profiles.has_contact_centre_access IS
  'Direct toggle granting Contact Centre access (chats + 3CX calls). Additive to the contact_centre.view role permission — either source is sufficient.';


-- ============================================================
-- Source: 20260624100000_perf_drop_duplicate_indexes.sql
-- ============================================================
-- Wave 1 of the Supabase performance cleanup.
--
-- Supabase's linter flagged two pairs of identical indexes. Identical indexes
-- waste write throughput (every INSERT/UPDATE must update both) and disk space
-- without giving the planner any new option. We drop one of each pair, keeping
-- the more descriptive `idx_<table>_<col>` name.
--
-- Source: lint 0009_duplicate_index
--   * chat_messages: chat_messages_conv_created_idx ≡ idx_chat_messages_conversation_created
--   * team_schedule_assignments: idx_tsa_team ≡ idx_team_sched_team_id

DROP INDEX IF EXISTS public.chat_messages_conv_created_idx;
DROP INDEX IF EXISTS public.idx_tsa_team;


-- ============================================================
-- Source: 20260624110000_perf_rls_init_plan.sql
-- ============================================================
-- Wave 2 of the Supabase performance cleanup.
--
-- Supabase lint 0003_auth_rls_initplan flagged 14 RLS policies that call
-- auth.<fn>() directly inside USING / WITH CHECK clauses. Postgres re-evaluates
-- such calls once per scanned row instead of caching the result for the whole
-- statement. Wrapping the call in (SELECT auth.<fn>()) turns it into a stable
-- initplan that runs exactly once per query.
--
-- Semantics are identical — auth.uid() and auth.role() return the same value
-- for the duration of a single query — so each policy is dropped and recreated
-- with the wrapped form. No row visibility changes.
--
-- Reference: https://supabase.com/docs/guides/database/postgres/row-level-security#call-functions-with-select

------------------------------------------------------------------------------
-- service_brands ------------------------------------------------------------
------------------------------------------------------------------------------
DROP POLICY IF EXISTS "Manage services write service_brands" ON public.service_brands;

CREATE POLICY "Manage services write service_brands"
  ON public.service_brands FOR ALL TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.profiles p
      JOIN public.user_custom_roles ucr ON ucr.profile_id = p.id
      JOIN public.custom_roles cr ON cr.id = ucr.role_id
      WHERE p.auth_user_id = (SELECT auth.uid())
        AND (cr.is_system = true OR 'master_data.services.manage' = ANY(cr.permissions))
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.profiles p
      JOIN public.user_custom_roles ucr ON ucr.profile_id = p.id
      JOIN public.custom_roles cr ON cr.id = ucr.role_id
      WHERE p.auth_user_id = (SELECT auth.uid())
        AND (cr.is_system = true OR 'master_data.services.manage' = ANY(cr.permissions))
    )
  );

------------------------------------------------------------------------------
-- traccar_geofences ---------------------------------------------------------
------------------------------------------------------------------------------
DROP POLICY IF EXISTS "Authenticated users can read geofences"   ON public.traccar_geofences;
DROP POLICY IF EXISTS "Authenticated users can insert geofences" ON public.traccar_geofences;
DROP POLICY IF EXISTS "Authenticated users can update geofences" ON public.traccar_geofences;
DROP POLICY IF EXISTS "Authenticated users can delete geofences" ON public.traccar_geofences;

CREATE POLICY "Authenticated users can read geofences"
  ON public.traccar_geofences FOR SELECT
  USING ((SELECT auth.role()) = 'authenticated');

CREATE POLICY "Authenticated users can insert geofences"
  ON public.traccar_geofences FOR INSERT
  WITH CHECK ((SELECT auth.role()) = 'authenticated');

CREATE POLICY "Authenticated users can update geofences"
  ON public.traccar_geofences FOR UPDATE
  USING ((SELECT auth.role()) = 'authenticated');

CREATE POLICY "Authenticated users can delete geofences"
  ON public.traccar_geofences FOR DELETE
  USING ((SELECT auth.role()) = 'authenticated');

------------------------------------------------------------------------------
-- user_ui_preferences -------------------------------------------------------
------------------------------------------------------------------------------
DROP POLICY IF EXISTS user_ui_preferences_self_select ON public.user_ui_preferences;
DROP POLICY IF EXISTS user_ui_preferences_self_upsert ON public.user_ui_preferences;
DROP POLICY IF EXISTS user_ui_preferences_self_update ON public.user_ui_preferences;

CREATE POLICY user_ui_preferences_self_select
  ON public.user_ui_preferences FOR SELECT
  USING (user_id = (SELECT auth.uid()));

CREATE POLICY user_ui_preferences_self_upsert
  ON public.user_ui_preferences FOR INSERT
  WITH CHECK (user_id = (SELECT auth.uid()));

CREATE POLICY user_ui_preferences_self_update
  ON public.user_ui_preferences FOR UPDATE
  USING (user_id = (SELECT auth.uid()))
  WITH CHECK (user_id = (SELECT auth.uid()));

------------------------------------------------------------------------------
-- service_change_requests ---------------------------------------------------
------------------------------------------------------------------------------
DROP POLICY IF EXISTS scr_select ON public.service_change_requests;

CREATE POLICY scr_select
  ON public.service_change_requests FOR SELECT TO authenticated
  USING (
    requested_by = (SELECT id FROM public.profiles WHERE auth_user_id = (SELECT auth.uid()))
    OR EXISTS (
      SELECT 1 FROM public.user_custom_roles ucr
      JOIN public.custom_roles cr ON cr.id = ucr.role_id
      WHERE ucr.profile_id = (SELECT id FROM public.profiles WHERE auth_user_id = (SELECT auth.uid()))
        AND cr.deleted_at IS NULL
        AND (cr.is_system = true OR 'master_data.services.approve' = ANY(cr.permissions))
    )
  );

------------------------------------------------------------------------------
-- purge_batches -------------------------------------------------------------
------------------------------------------------------------------------------
DROP POLICY IF EXISTS "Admins read purge batches" ON public.purge_batches;

CREATE POLICY "Admins read purge batches"
  ON public.purge_batches FOR SELECT TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.user_custom_roles ur
      JOIN public.custom_roles cr ON cr.id = ur.role_id
      WHERE ur.profile_id = (SELECT auth.uid())
        AND 'contact_centre.admin.purge' = ANY(cr.permissions)
    )
  );

------------------------------------------------------------------------------
-- team_live_locations -------------------------------------------------------
------------------------------------------------------------------------------
DROP POLICY IF EXISTS tll_insert ON public.team_live_locations;
DROP POLICY IF EXISTS tll_update ON public.team_live_locations;

CREATE POLICY tll_insert
  ON public.team_live_locations FOR INSERT TO authenticated
  WITH CHECK (
    team_id = (
      SELECT t.id FROM public.teams t
      JOIN public.employees e ON e.id = t.leader_id
      JOIN public.profiles p ON p.id = e.profile_id
      WHERE p.auth_user_id = (SELECT auth.uid())
    )
  );

CREATE POLICY tll_update
  ON public.team_live_locations FOR UPDATE TO authenticated
  USING (
    team_id = (
      SELECT t.id FROM public.teams t
      JOIN public.employees e ON e.id = t.leader_id
      JOIN public.profiles p ON p.id = e.profile_id
      WHERE p.auth_user_id = (SELECT auth.uid())
    )
  )
  WITH CHECK (
    team_id = (
      SELECT t.id FROM public.teams t
      JOIN public.employees e ON e.id = t.leader_id
      JOIN public.profiles p ON p.id = e.profile_id
      WHERE p.auth_user_id = (SELECT auth.uid())
    )
  );

------------------------------------------------------------------------------
-- chat_messages -------------------------------------------------------------
------------------------------------------------------------------------------
DROP POLICY IF EXISTS chat_messages_insert_strict ON public.chat_messages;

CREATE POLICY chat_messages_insert_strict
  ON public.chat_messages FOR INSERT TO authenticated
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.chat_conversations cc
      WHERE cc.id = chat_messages.conversation_id
    )
    AND EXISTS (
      SELECT 1 FROM public.profiles p
      JOIN public.user_custom_roles ur ON ur.profile_id = p.id
      JOIN public.custom_roles cr ON cr.id = ur.role_id
      WHERE p.auth_user_id = (SELECT auth.uid())
        AND 'contact_centre.view' = ANY(cr.permissions)
    )
  );

------------------------------------------------------------------------------
-- follow_up_requests --------------------------------------------------------
------------------------------------------------------------------------------
DROP POLICY IF EXISTS fur_insert ON public.follow_up_requests;

CREATE POLICY fur_insert
  ON public.follow_up_requests FOR INSERT TO authenticated
  WITH CHECK (requested_by_user_id = (SELECT auth.uid()));


-- ============================================================
-- Source: 20260625100000_po_versions_stage_column.sql
-- ============================================================
-- Wipe po_versions and rebuild with per-stage versioning.
-- Only this snapshot table is touched — purchase_orders, receivals, bills,
-- inventory_movements, FIFO layers, sales are all untouched.

TRUNCATE TABLE public.po_versions RESTART IDENTITY;

ALTER TABLE public.po_versions
  ADD COLUMN stage text NOT NULL
  CHECK (stage IN ('rfq', 'draft', 'po'));

ALTER TABLE public.po_versions
  DROP CONSTRAINT IF EXISTS po_versions_po_id_version_number_key;

CREATE UNIQUE INDEX po_versions_po_stage_version_uidx
  ON public.po_versions (po_id, stage, version_number);

CREATE INDEX po_versions_po_stage_idx
  ON public.po_versions (po_id, stage);


-- ============================================================
-- Source: 20260625120000_perf_consolidate_overlapping_policies.sql
-- ============================================================
-- Wave 3 of the Supabase performance cleanup.
--
-- (a) Consolidate 9 tables flagged by lint 0006_multiple_permissive_policies.
--     Each table has two permissive policies firing on the same role+action.
--     For 7 of them the bodies are identical (both USING(true)) so the redundant
--     read-only policy is dropped; the remaining FOR ALL policy continues to
--     cover SELECT/INSERT/UPDATE/DELETE. For service_brands and invoices the
--     bodies differ — those merges preserve original semantics, see comments.
--
-- (b) Switch warehouse_stock_view from SECURITY DEFINER to SECURITY INVOKER
--     (lint 0010_security_definer_view). All underlying tables already have
--     `USING (true)` policies for authenticated users, so the switch doesn't
--     change what authenticated callers can read.

------------------------------------------------------------------------------
-- 1-7. Tables with identical USING(true) on both policies: drop the FOR SELECT
--      duplicate. The remaining FOR ALL policy covers reads.
------------------------------------------------------------------------------
DROP POLICY IF EXISTS "Authenticated users can read employee_services" ON public.employee_services;
DROP POLICY IF EXISTS "Authenticated users can read installed_products" ON public.installed_products;
DROP POLICY IF EXISTS "Authenticated users can read tool_assignments"   ON public.tool_assignments;
DROP POLICY IF EXISTS internal_select_service_customer_addresses        ON public.service_customer_addresses;
DROP POLICY IF EXISTS internal_select_service_customer_phones           ON public.service_customer_phones;
DROP POLICY IF EXISTS internal_select_service_customers                 ON public.service_customers;
DROP POLICY IF EXISTS service_instructions_read                         ON public.service_instructions;

------------------------------------------------------------------------------
-- 8. service_brands — the read policy permits all authenticated SELECT
--    (USING true), while the manage policy is FOR ALL with a restrictive role
--    check. Postgres fires BOTH on SELECT (the lint warning). Splitting the
--    manage FOR ALL into per-action INSERT/UPDATE/DELETE policies removes it
--    from SELECT evaluation while preserving write gating semantics.
------------------------------------------------------------------------------
DROP POLICY IF EXISTS "Manage services write service_brands" ON public.service_brands;

CREATE POLICY "Manage services insert service_brands"
  ON public.service_brands FOR INSERT TO authenticated
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.profiles p
      JOIN public.user_custom_roles ucr ON ucr.profile_id = p.id
      JOIN public.custom_roles cr ON cr.id = ucr.role_id
      WHERE p.auth_user_id = (SELECT auth.uid())
        AND (cr.is_system = true OR 'master_data.services.manage' = ANY(cr.permissions))
    )
  );

CREATE POLICY "Manage services update service_brands"
  ON public.service_brands FOR UPDATE TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.profiles p
      JOIN public.user_custom_roles ucr ON ucr.profile_id = p.id
      JOIN public.custom_roles cr ON cr.id = ucr.role_id
      WHERE p.auth_user_id = (SELECT auth.uid())
        AND (cr.is_system = true OR 'master_data.services.manage' = ANY(cr.permissions))
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.profiles p
      JOIN public.user_custom_roles ucr ON ucr.profile_id = p.id
      JOIN public.custom_roles cr ON cr.id = ucr.role_id
      WHERE p.auth_user_id = (SELECT auth.uid())
        AND (cr.is_system = true OR 'master_data.services.manage' = ANY(cr.permissions))
    )
  );

CREATE POLICY "Manage services delete service_brands"
  ON public.service_brands FOR DELETE TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.profiles p
      JOIN public.user_custom_roles ucr ON ucr.profile_id = p.id
      JOIN public.custom_roles cr ON cr.id = ucr.role_id
      WHERE p.auth_user_id = (SELECT auth.uid())
        AND (cr.is_system = true OR 'master_data.services.manage' = ANY(cr.permissions))
    )
  );

------------------------------------------------------------------------------
-- 9. invoices — two UPDATE policies. Original behaviour (combined permissive):
--      USING:  true (non-void policy + void policy combined)
--      CHECK:  new.status != 'void' OR (new.status = 'void' AND admin)
--    Single merged policy below replicates this exactly with one evaluation
--    per row instead of two.
------------------------------------------------------------------------------
DROP POLICY IF EXISTS "Accounting/admin can void invoices"        ON public.invoices;
DROP POLICY IF EXISTS "Authenticated can update invoices (non-void)" ON public.invoices;

CREATE POLICY "Authenticated can update invoices"
  ON public.invoices FOR UPDATE TO authenticated
  USING (true)
  WITH CHECK (
    status IS DISTINCT FROM 'void'::public.invoice_status
    OR (
      status = 'void'::public.invoice_status
      AND EXISTS (
        SELECT 1 FROM public.profiles p
        JOIN public.user_custom_roles ucr ON ucr.profile_id = p.id
        JOIN public.custom_roles cr ON cr.id = ucr.role_id
        WHERE p.auth_user_id = (SELECT auth.uid())
          AND cr.deleted_at IS NULL
          AND (cr.is_system = true OR 'invoices.manage' = ANY(cr.permissions))
      )
    )
  );

------------------------------------------------------------------------------
-- 10. warehouse_stock_view — SECURITY DEFINER → SECURITY INVOKER.
--     Underlying tables (fifo_cost_layers, inventory_brand_variants,
--     inventory_items, inventory_categories, warehouse_stock_allocations)
--     all permit authenticated SELECT via USING(true) policies, so switching
--     to invoker semantics doesn't change what callers can read.
------------------------------------------------------------------------------
ALTER VIEW public.warehouse_stock_view SET (security_invoker = true);


-- ============================================================
-- Source: 20260625130000_po_edit_requests.sql
-- ============================================================
-- Phase D — edit request workflow. A non-Owner user files a request to
-- amend an approved/pending PO; any approval-slot role holder approves;
-- once approved, anyone with purchase access can submit ONE amendment,
-- which consumes the unlock.

CREATE TABLE public.po_edit_requests (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  po_id           uuid NOT NULL REFERENCES public.purchase_orders(id) ON DELETE CASCADE,
  requested_by    uuid NOT NULL REFERENCES public.profiles(id),
  reason          text NOT NULL,
  status          text NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'approved', 'declined', 'used')),
  reviewed_by     uuid REFERENCES public.profiles(id),
  reviewed_at     timestamptz,
  review_comment  text,
  used_at         timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX po_edit_requests_po_idx
  ON public.po_edit_requests(po_id);

CREATE INDEX po_edit_requests_pending_idx
  ON public.po_edit_requests(po_id) WHERE status = 'pending';

-- At most one approved-unused request per PO at a time.
CREATE UNIQUE INDEX po_edit_requests_one_approved_per_po
  ON public.po_edit_requests(po_id) WHERE status = 'approved';

ALTER TABLE public.po_edit_requests ENABLE ROW LEVEL SECURITY;

CREATE POLICY po_edit_requests_select
  ON public.po_edit_requests FOR SELECT TO authenticated USING (true);

CREATE POLICY po_edit_requests_insert
  ON public.po_edit_requests FOR INSERT TO authenticated
  WITH CHECK (
    requested_by = (SELECT id FROM public.profiles WHERE auth_user_id = (SELECT auth.uid()))
  );

CREATE POLICY po_edit_requests_update
  ON public.po_edit_requests FOR UPDATE TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.user_custom_roles ucr
      JOIN public.custom_roles cr ON cr.id = ucr.role_id
      JOIN public.profiles p ON p.id = ucr.profile_id
      WHERE p.auth_user_id = (SELECT auth.uid())
        AND cr.is_approval_slot = true
        AND cr.deleted_at IS NULL
    )
  );


-- ============================================================
-- Source: 20260626120000_customer_credit_docs.sql
-- ============================================================
-- supabase/migrations/20260626120000_customer_credit_docs.sql
-- Boss-review correction: require uploaded credit docs before assigning a customer
-- to a credit group, and gate credit-group changes behind a dedicated permission.
--
-- - Adds doc-path + uploaded-at columns to `customers`
-- - Creates the private `customer-credit-docs` storage bucket with role-gated RLS
BEGIN;

-- ─── customers: doc paths + timestamps ───────────────────────────────────────
ALTER TABLE public.customers
  ADD COLUMN IF NOT EXISTS cr_url                  TEXT,
  ADD COLUMN IF NOT EXISTS cr_uploaded_at          TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS establishment_id_url    TEXT,
  ADD COLUMN IF NOT EXISTS establishment_id_uploaded_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS signed_credit_form_url  TEXT,
  ADD COLUMN IF NOT EXISTS signed_credit_form_uploaded_at TIMESTAMPTZ;

-- ─── storage bucket ──────────────────────────────────────────────────────────
INSERT INTO storage.buckets (id, name, public)
VALUES ('customer-credit-docs', 'customer-credit-docs', false)
ON CONFLICT (id) DO NOTHING;

-- Helper: can the calling auth user write credit docs?
-- Anyone with master_data.customers.manage OR master_data.customers.change_credit_group
-- can upload; system roles bypass the check (Owner / Admin).
CREATE OR REPLACE FUNCTION storage_customer_credit_docs_write_allowed()
RETURNS BOOLEAN
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, auth
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM   profiles p
    JOIN   user_custom_roles ucr ON ucr.profile_id = p.id
    JOIN   custom_roles cr      ON cr.id           = ucr.role_id
    WHERE  p.auth_user_id = auth.uid()
    AND    (
      cr.is_system = true
      OR 'master_data.customers.manage' = ANY(cr.permissions)
      OR 'master_data.customers.change_credit_group' = ANY(cr.permissions)
    )
  )
$$;

-- Read: any authenticated user (downloads still require a signed URL)
CREATE POLICY "customer_credit_docs_select"
  ON storage.objects FOR SELECT TO authenticated
  USING (bucket_id = 'customer-credit-docs');

CREATE POLICY "customer_credit_docs_insert"
  ON storage.objects FOR INSERT TO authenticated
  WITH CHECK (bucket_id = 'customer-credit-docs' AND storage_customer_credit_docs_write_allowed());

CREATE POLICY "customer_credit_docs_update"
  ON storage.objects FOR UPDATE TO authenticated
  USING      (bucket_id = 'customer-credit-docs' AND storage_customer_credit_docs_write_allowed())
  WITH CHECK (bucket_id = 'customer-credit-docs' AND storage_customer_credit_docs_write_allowed());

CREATE POLICY "customer_credit_docs_delete"
  ON storage.objects FOR DELETE TO authenticated
  USING (bucket_id = 'customer-credit-docs' AND storage_customer_credit_docs_write_allowed());

COMMIT;


-- ============================================================
-- Source: 20260627090000_cleanup_credit_customers_in_cash_group.sql
-- ============================================================
-- supabase/migrations/20260627090000_cleanup_credit_customers_in_cash_group.sql
-- One-time cleanup: any customer with customer_type = 'credit' but assigned to
-- the "Cash Customers" credit group is in an inconsistent state. The Cash
-- Customers group is reserved for cash-type customers. Flip these rows to
-- customer_type = 'cash' so the dataset matches the rule the app now enforces.
BEGIN;

UPDATE public.customers
SET    customer_type = 'cash',
       updated_at    = now()
WHERE  customer_type = 'credit'
  AND  credit_group_id IN (
    SELECT id FROM public.credit_groups WHERE name = 'Cash Customers'
  );

COMMIT;


-- ============================================================
-- Source: 20260627100000_sales_approval_chains.sql
-- ============================================================
-- Sales Approval Chains — schema foundation.
--
-- Adds two new workflows (`sales_margin`, `sales_credit`) to the existing
-- workflow-steps machinery, and two matching scope values to user-role
-- assignments. Extends `approval_requests` with the columns it needs to act
-- as a per-role slip log (mirroring `po_approvals`).
BEGIN;

-- ─── Extend workflow_approval_steps.workflow CHECK ──────────────────────────
ALTER TABLE public.workflow_approval_steps
  DROP CONSTRAINT IF EXISTS workflow_approval_steps_workflow_check;
ALTER TABLE public.workflow_approval_steps
  ADD CONSTRAINT workflow_approval_steps_workflow_check
  CHECK (workflow = ANY (ARRAY['po','inv_check','stock_adj','sales_margin','sales_credit']));

-- ─── Extend user_custom_roles.approval_scopes CHECK ─────────────────────────
ALTER TABLE public.user_custom_roles
  DROP CONSTRAINT IF EXISTS user_custom_roles_approval_scopes_chk;
ALTER TABLE public.user_custom_roles
  ADD CONSTRAINT user_custom_roles_approval_scopes_chk
  CHECK (
    approval_scopes IS NULL
    OR approval_scopes <@ ARRAY['po','inv_check','stock_adj','sales_margin','sales_credit']::text[]
  );

-- ─── Extend approval_requests with per-role-slip columns ────────────────────
-- approval_requests currently stores ONE row per slip. We extend it so each
-- approval chain step lives as its own row (just like po_approvals).
ALTER TABLE public.approval_requests
  ADD COLUMN IF NOT EXISTS step_role  TEXT,
  ADD COLUMN IF NOT EXISTS step_order INT DEFAULT 1 NOT NULL,
  ADD COLUMN IF NOT EXISTS is_active  BOOLEAN DEFAULT false NOT NULL,
  ADD COLUMN IF NOT EXISTS iteration  INT DEFAULT 1 NOT NULL,
  ADD COLUMN IF NOT EXISTS decided_at TIMESTAMPTZ;

-- New invariant: when status moves off 'pending', stamp decided_at via trigger
CREATE OR REPLACE FUNCTION public.set_approval_request_decided_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.status <> 'pending' AND OLD.status = 'pending' THEN
    NEW.decided_at = now();
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_approval_requests_decided_at ON public.approval_requests;
CREATE TRIGGER trg_approval_requests_decided_at
  BEFORE UPDATE ON public.approval_requests
  FOR EACH ROW EXECUTE FUNCTION public.set_approval_request_decided_at();

-- Indexes for the queue queries
CREATE INDEX IF NOT EXISTS approval_requests_pending_idx
  ON public.approval_requests (source_id, approval_type, iteration)
  WHERE status = 'pending' AND is_active = true;

CREATE INDEX IF NOT EXISTS approval_requests_source_idx
  ON public.approval_requests (source_type, source_id, approval_type, iteration);

COMMIT;


-- ============================================================
-- Source: 20260627100001_create_sale_order_approval_gates.sql
-- ============================================================
-- Replace create_sale_order to also fire the margin (below-cost) gate and
-- create approval_requests slip rows for whichever gates trigger.
--
-- Gates:
--   credit  → customer_open_balance + total_qar > credit_limit
--   margin  → any line has unit_price < avg_cost
-- Both gates can fire on the same SO; each creates an independent slip group.
BEGIN;

DROP FUNCTION IF EXISTS public.create_sale_order(uuid, text, text, numeric, date, text, text, jsonb, text, text, text, integer, numeric, text, text, jsonb, uuid);

CREATE FUNCTION public.create_sale_order(
  p_customer_id          uuid,
  p_intent               text,
  p_currency             text,
  p_exchange_rate        numeric,
  p_expected_delivery    date,
  p_payment_terms        text,
  p_payment_terms_notes  text,
  p_payment_milestones   jsonb,
  p_delivery_terms       text,
  p_delivery_terms_notes text,
  p_customer_notes       text,
  p_validity_days        integer,
  p_discount_amount      numeric,
  p_discount_label       text,
  p_discount_type        text,
  p_line_items           jsonb,
  p_division_id          uuid DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_so_number         TEXT;
  v_count             INTEGER;
  v_subtotal          NUMERIC;
  v_discount_resolved NUMERIC;
  v_total             NUMERIC;
  v_total_qar         NUMERIC;
  v_credit_limit      NUMERIC;
  v_group_name        TEXT;
  v_open_total        NUMERIC;
  v_available         NUMERIC;
  v_so_status         sale_order_status;
  v_so_id             UUID;
  v_profile_id        UUID;
  v_customer_type     TEXT;
  v_exceeds_credit    BOOLEAN := false;
  v_has_below_cost    BOOLEAN := false;
  v_below_cost_lines  JSONB   := '[]'::jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(
    ('x' || substr(md5(p_customer_id::text), 1, 15))::bit(60)::bigint
  );

  SELECT id INTO v_profile_id FROM profiles WHERE auth_user_id = auth.uid();

  SELECT COUNT(*) + 1 INTO v_count FROM sale_orders;
  v_so_number := 'SO-' || LPAD(v_count::text, 5, '0');

  SELECT COALESCE(SUM((item->>'total')::NUMERIC), 0)
  INTO   v_subtotal
  FROM   jsonb_array_elements(p_line_items) AS item;

  v_discount_resolved := CASE p_discount_type
    WHEN 'percentage' THEN (v_subtotal * p_discount_amount) / 100
    ELSE p_discount_amount
  END;
  v_total     := v_subtotal - v_discount_resolved;
  v_total_qar := v_total * p_exchange_rate;

  SELECT c.customer_type, cg.credit_limit, cg.name
  INTO   v_customer_type, v_credit_limit, v_group_name
  FROM   customers c
  LEFT JOIN credit_groups cg ON cg.id = c.credit_group_id
  WHERE  c.id = p_customer_id;

  -- ── Margin gate (below cost) — runs for EVERY submission, cash or credit
  IF p_intent = 'confirm' THEN
    SELECT jsonb_agg(item) FILTER (
      WHERE (item->>'avg_cost')::NUMERIC > 0
        AND (item->>'unit_price')::NUMERIC < (item->>'avg_cost')::NUMERIC
    )
    INTO v_below_cost_lines
    FROM jsonb_array_elements(p_line_items) AS item;

    IF v_below_cost_lines IS NOT NULL AND jsonb_array_length(v_below_cost_lines) > 0 THEN
      v_has_below_cost := true;
    END IF;
  END IF;

  -- ── Credit gate (over limit) — credit customers only
  IF COALESCE(v_customer_type, 'credit') = 'cash' THEN
    v_credit_limit := 0;
    v_group_name   := 'Cash';
    v_open_total   := 0;
    v_available    := 0;
  ELSE
    IF v_credit_limit IS NULL THEN
      RAISE EXCEPTION 'no_credit_group';
    END IF;

    SELECT COALESCE(SUM(total), 0)
    INTO   v_open_total
    FROM   sale_orders
    WHERE  customer_id = p_customer_id
      AND  status      NOT IN ('cancelled')
      AND  deleted_at  IS NULL;

    v_available := v_credit_limit - v_open_total;

    IF p_intent = 'confirm' AND v_total_qar > v_available THEN
      v_exceeds_credit := true;
    END IF;
  END IF;

  -- ── Compute final SO status
  v_so_status := CASE
    WHEN p_intent <> 'confirm'                       THEN 'quotation'::sale_order_status
    WHEN v_exceeds_credit OR v_has_below_cost        THEN 'pending_approval'::sale_order_status
    ELSE                                                  'confirmed'::sale_order_status
  END;

  -- Insert SO
  INSERT INTO sale_orders (
    so_number, customer_id, status,
    subtotal, tax, total,
    discount_amount, discount_label, discount_type, discount_amount_resolved,
    currency, exchange_rate, expected_delivery,
    payment_terms, payment_terms_notes, payment_milestones,
    delivery_terms, delivery_terms_notes,
    customer_notes, validity_days,
    created_by
  ) VALUES (
    v_so_number, p_customer_id, v_so_status,
    v_subtotal, 0, v_total,
    p_discount_amount, p_discount_label, p_discount_type, v_discount_resolved,
    p_currency, p_exchange_rate, p_expected_delivery,
    p_payment_terms, p_payment_terms_notes, p_payment_milestones,
    p_delivery_terms, p_delivery_terms_notes,
    p_customer_notes, p_validity_days,
    v_profile_id
  )
  RETURNING id INTO v_so_id;

  -- Insert lines (unchanged)
  INSERT INTO sale_order_lines (
    sale_order_id, item_name, sku, qty, unit,
    unit_price, total, line_type,
    brand_variant_id, tool_asset_item_id, avg_cost, created_by
  )
  SELECT
    v_so_id,
    item->>'item_name',
    NULLIF(item->>'sku', ''),
    (item->>'qty')::INTEGER,
    COALESCE(NULLIF(item->>'unit', ''), 'pcs'),
    (item->>'unit_price')::NUMERIC,
    (item->>'total')::NUMERIC,
    COALESCE(NULLIF(item->>'line_type', ''), 'products'),
    CASE
      WHEN (item->>'brand_variant_id') IS NOT NULL
        AND (item->>'brand_variant_id') NOT IN ('', 'null')
      THEN (item->>'brand_variant_id')::UUID
      ELSE NULL
    END,
    CASE
      WHEN (item->>'tool_asset_item_id') IS NOT NULL
        AND (item->>'tool_asset_item_id') NOT IN ('', 'null')
      THEN (item->>'tool_asset_item_id')::UUID
      ELSE NULL
    END,
    COALESCE(NULLIF(item->>'avg_cost', '')::NUMERIC, 0),
    v_profile_id
  FROM jsonb_array_elements(p_line_items) AS item;

  -- Reserve stock (unchanged)
  PERFORM batch_update_reserved_qty(
    (SELECT jsonb_agg(
       jsonb_build_object(
         'bv_id', (item->>'brand_variant_id')::UUID,
         'delta', (item->>'qty')::INTEGER))
     FROM   jsonb_array_elements(p_line_items) AS item
     WHERE  (item->>'brand_variant_id') IS NOT NULL
       AND  (item->>'brand_variant_id') NOT IN ('', 'null')
       AND  (item->>'qty')::INTEGER > 0)
  );

  -- ── Build approval slip rows for each gate that fired
  IF v_exceeds_credit THEN
    PERFORM public.build_sales_approval_chain(
      v_so_id, 'credit',
      jsonb_build_object(
        'available', GREATEST(v_available, 0),
        'overage',   v_total_qar - v_available,
        'requested_by', v_profile_id
      )
    );
  END IF;

  IF v_has_below_cost THEN
    PERFORM public.build_sales_approval_chain(
      v_so_id, 'margin',
      jsonb_build_object(
        'lines',       v_below_cost_lines,
        'requested_by', v_profile_id
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'so_id',          v_so_id,
    'so_number',      v_so_number,
    'status',         v_so_status,
    'credit_limit',   v_credit_limit,
    'group_name',     v_group_name,
    'open_total',     v_open_total,
    'available',      GREATEST(v_available, 0),
    'exceeds_credit', v_exceeds_credit,
    'has_below_cost', v_has_below_cost
  );
END;
$$;

COMMIT;


-- ============================================================
-- Source: 20260627100002_create_sale_order_restore_division_id.sql
-- ============================================================
-- Restore division_id in create_sale_order INSERT.
-- The Task 3 replacement (20260627100001) dropped division_id from the INSERT
-- column list, which would silently NULL out division on every new SO.
-- This re-issues the function with division_id wired back in.
BEGIN;

CREATE OR REPLACE FUNCTION public.create_sale_order(
  p_customer_id          uuid,
  p_intent               text,
  p_currency             text,
  p_exchange_rate        numeric,
  p_expected_delivery    date,
  p_payment_terms        text,
  p_payment_terms_notes  text,
  p_payment_milestones   jsonb,
  p_delivery_terms       text,
  p_delivery_terms_notes text,
  p_customer_notes       text,
  p_validity_days        integer,
  p_discount_amount      numeric,
  p_discount_label       text,
  p_discount_type        text,
  p_line_items           jsonb,
  p_division_id          uuid DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_so_number         TEXT;
  v_count             INTEGER;
  v_subtotal          NUMERIC;
  v_discount_resolved NUMERIC;
  v_total             NUMERIC;
  v_total_qar         NUMERIC;
  v_credit_limit      NUMERIC;
  v_group_name        TEXT;
  v_open_total        NUMERIC;
  v_available         NUMERIC;
  v_so_status         sale_order_status;
  v_so_id             UUID;
  v_profile_id        UUID;
  v_customer_type     TEXT;
  v_exceeds_credit    BOOLEAN := false;
  v_has_below_cost    BOOLEAN := false;
  v_below_cost_lines  JSONB   := '[]'::jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(
    ('x' || substr(md5(p_customer_id::text), 1, 15))::bit(60)::bigint
  );

  SELECT id INTO v_profile_id FROM profiles WHERE auth_user_id = auth.uid();

  SELECT COUNT(*) + 1 INTO v_count FROM sale_orders;
  v_so_number := 'SO-' || LPAD(v_count::text, 5, '0');

  SELECT COALESCE(SUM((item->>'total')::NUMERIC), 0)
  INTO   v_subtotal
  FROM   jsonb_array_elements(p_line_items) AS item;

  v_discount_resolved := CASE p_discount_type
    WHEN 'percentage' THEN (v_subtotal * p_discount_amount) / 100
    ELSE p_discount_amount
  END;
  v_total     := v_subtotal - v_discount_resolved;
  v_total_qar := v_total * p_exchange_rate;

  SELECT c.customer_type, cg.credit_limit, cg.name
  INTO   v_customer_type, v_credit_limit, v_group_name
  FROM   customers c
  LEFT JOIN credit_groups cg ON cg.id = c.credit_group_id
  WHERE  c.id = p_customer_id;

  -- ── Margin gate (below cost) — runs for EVERY submission, cash or credit
  IF p_intent = 'confirm' THEN
    SELECT jsonb_agg(item) FILTER (
      WHERE (item->>'avg_cost')::NUMERIC > 0
        AND (item->>'unit_price')::NUMERIC < (item->>'avg_cost')::NUMERIC
    )
    INTO v_below_cost_lines
    FROM jsonb_array_elements(p_line_items) AS item;

    IF v_below_cost_lines IS NOT NULL AND jsonb_array_length(v_below_cost_lines) > 0 THEN
      v_has_below_cost := true;
    END IF;
  END IF;

  -- ── Credit gate (over limit) — credit customers only
  IF COALESCE(v_customer_type, 'credit') = 'cash' THEN
    v_credit_limit := 0;
    v_group_name   := 'Cash';
    v_open_total   := 0;
    v_available    := 0;
  ELSE
    IF v_credit_limit IS NULL THEN
      RAISE EXCEPTION 'no_credit_group';
    END IF;

    SELECT COALESCE(SUM(total), 0)
    INTO   v_open_total
    FROM   sale_orders
    WHERE  customer_id = p_customer_id
      AND  status      NOT IN ('cancelled')
      AND  deleted_at  IS NULL;

    v_available := v_credit_limit - v_open_total;

    IF p_intent = 'confirm' AND v_total_qar > v_available THEN
      v_exceeds_credit := true;
    END IF;
  END IF;

  -- ── Compute final SO status
  v_so_status := CASE
    WHEN p_intent <> 'confirm'                       THEN 'quotation'::sale_order_status
    WHEN v_exceeds_credit OR v_has_below_cost        THEN 'pending_approval'::sale_order_status
    ELSE                                                  'confirmed'::sale_order_status
  END;

  -- Insert SO
  INSERT INTO sale_orders (
    so_number, customer_id, status,
    subtotal, tax, total,
    discount_amount, discount_label, discount_type, discount_amount_resolved,
    currency, exchange_rate, expected_delivery,
    payment_terms, payment_terms_notes, payment_milestones,
    delivery_terms, delivery_terms_notes,
    customer_notes, validity_days,
    division_id,
    created_by
  ) VALUES (
    v_so_number, p_customer_id, v_so_status,
    v_subtotal, 0, v_total,
    p_discount_amount, p_discount_label, p_discount_type, v_discount_resolved,
    p_currency, p_exchange_rate, p_expected_delivery,
    p_payment_terms, p_payment_terms_notes, p_payment_milestones,
    p_delivery_terms, p_delivery_terms_notes,
    p_customer_notes, p_validity_days,
    p_division_id,
    v_profile_id
  )
  RETURNING id INTO v_so_id;

  -- Insert lines (unchanged)
  INSERT INTO sale_order_lines (
    sale_order_id, item_name, sku, qty, unit,
    unit_price, total, line_type,
    brand_variant_id, tool_asset_item_id, avg_cost, created_by
  )
  SELECT
    v_so_id,
    item->>'item_name',
    NULLIF(item->>'sku', ''),
    (item->>'qty')::INTEGER,
    COALESCE(NULLIF(item->>'unit', ''), 'pcs'),
    (item->>'unit_price')::NUMERIC,
    (item->>'total')::NUMERIC,
    COALESCE(NULLIF(item->>'line_type', ''), 'products'),
    CASE
      WHEN (item->>'brand_variant_id') IS NOT NULL
        AND (item->>'brand_variant_id') NOT IN ('', 'null')
      THEN (item->>'brand_variant_id')::UUID
      ELSE NULL
    END,
    CASE
      WHEN (item->>'tool_asset_item_id') IS NOT NULL
        AND (item->>'tool_asset_item_id') NOT IN ('', 'null')
      THEN (item->>'tool_asset_item_id')::UUID
      ELSE NULL
    END,
    COALESCE(NULLIF(item->>'avg_cost', '')::NUMERIC, 0),
    v_profile_id
  FROM jsonb_array_elements(p_line_items) AS item;

  -- Reserve stock (unchanged)
  PERFORM batch_update_reserved_qty(
    (SELECT jsonb_agg(
       jsonb_build_object(
         'bv_id', (item->>'brand_variant_id')::UUID,
         'delta', (item->>'qty')::INTEGER))
     FROM   jsonb_array_elements(p_line_items) AS item
     WHERE  (item->>'brand_variant_id') IS NOT NULL
       AND  (item->>'brand_variant_id') NOT IN ('', 'null')
       AND  (item->>'qty')::INTEGER > 0)
  );

  -- ── Build approval slip rows for each gate that fired
  IF v_exceeds_credit THEN
    PERFORM public.build_sales_approval_chain(
      v_so_id, 'credit',
      jsonb_build_object(
        'available', GREATEST(v_available, 0),
        'overage',   v_total_qar - v_available,
        'requested_by', v_profile_id
      )
    );
  END IF;

  IF v_has_below_cost THEN
    PERFORM public.build_sales_approval_chain(
      v_so_id, 'margin',
      jsonb_build_object(
        'lines',       v_below_cost_lines,
        'requested_by', v_profile_id
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'so_id',          v_so_id,
    'so_number',      v_so_number,
    'status',         v_so_status,
    'credit_limit',   v_credit_limit,
    'group_name',     v_group_name,
    'open_total',     v_open_total,
    'available',      GREATEST(v_available, 0),
    'exceeds_credit', v_exceeds_credit,
    'has_below_cost', v_has_below_cost
  );
END;
$$;

COMMIT;


-- ============================================================
-- Source: 20260627100003_sales_approval_rpcs.sql
-- ============================================================
-- Sales approval state machine.
--
-- Helpers:
--   build_sales_approval_chain(so_id, type, payload) — called by create_sale_order
--   advance_sales_approval(so_id, type)              — moves to next step or confirms SO
--   approve_sales_request(req_id, comment)
--   reject_sales_request(req_id, reason)
--   resubmit_sale_order(so_id)                       — bumps iteration after rejection
BEGIN;

-- ─── build_sales_approval_chain ─────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.build_sales_approval_chain(
  p_so_id          uuid,
  p_approval_type  approval_type,       -- 'margin' | 'credit'
  p_payload        jsonb
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_workflow    TEXT;
  v_iteration   INT;
  v_step        RECORD;
  v_role_name   TEXT;
  v_first       BOOLEAN := true;
BEGIN
  v_workflow := CASE p_approval_type
    WHEN 'margin' THEN 'sales_margin'
    WHEN 'credit' THEN 'sales_credit'
  END;

  SELECT COALESCE(MAX(iteration), 0) + 1 INTO v_iteration
  FROM   approval_requests
  WHERE  source_id     = p_so_id
    AND  approval_type = p_approval_type;

  FOR v_step IN
    SELECT was.step_order, cr.name AS role_name
    FROM   workflow_approval_steps was
    JOIN   custom_roles cr ON cr.id = was.role_id
    WHERE  was.workflow   = v_workflow
      AND  was.is_active  = true
      AND  was.archived_at IS NULL
    ORDER  BY was.step_order
  LOOP
    INSERT INTO approval_requests (
      source_type, source_id, approval_type, status,
      requested_by, reason,
      step_role, step_order, is_active, iteration
    ) VALUES (
      'sale_order', p_so_id, p_approval_type, 'pending',
      (p_payload->>'requested_by')::uuid,
      p_payload::text,
      v_step.role_name, v_step.step_order, v_first, v_iteration
    );
    v_first := false;
  END LOOP;
END;
$$;

-- ─── advance_sales_approval ─────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.advance_sales_approval(
  p_so_id         uuid,
  p_approval_type approval_type
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_iteration  INT;
  v_next_order INT;
  v_all_done   BOOLEAN;
  v_open_other BOOLEAN;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext(p_so_id::text || p_approval_type::text));

  SELECT COALESCE(MAX(iteration), 1) INTO v_iteration
  FROM   approval_requests
  WHERE  source_id = p_so_id AND approval_type = p_approval_type;

  -- Are all active steps in this chain approved?
  SELECT NOT EXISTS (
    SELECT 1 FROM approval_requests
    WHERE  source_id     = p_so_id
      AND  approval_type = p_approval_type
      AND  iteration     = v_iteration
      AND  is_active     = true
      AND  status        <> 'approved'
  ) INTO v_all_done;

  IF NOT v_all_done THEN RETURN; END IF;

  -- Activate next step if any
  SELECT MIN(step_order) INTO v_next_order
  FROM   approval_requests
  WHERE  source_id     = p_so_id
    AND  approval_type = p_approval_type
    AND  iteration     = v_iteration
    AND  is_active     = false
    AND  status        = 'pending';

  IF v_next_order IS NOT NULL THEN
    UPDATE approval_requests
    SET    is_active = true
    WHERE  source_id     = p_so_id
      AND  approval_type = p_approval_type
      AND  iteration     = v_iteration
      AND  step_order    = v_next_order;
    RETURN;
  END IF;

  -- This chain is fully approved. If the OTHER chain still has pending
  -- approvals, the SO must stay in pending_approval. Otherwise → confirmed.
  SELECT EXISTS (
    SELECT 1 FROM approval_requests
    WHERE  source_id     = p_so_id
      AND  approval_type <> p_approval_type
      AND  status        = 'pending'
  ) INTO v_open_other;

  IF NOT v_open_other THEN
    UPDATE sale_orders SET status = 'confirmed' WHERE id = p_so_id;
  END IF;
END;
$$;

-- ─── approve_sales_request ──────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.approve_sales_request(
  p_request_id uuid,
  p_comment    text
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_req        RECORD;
  v_profile_id uuid;
  v_full_name  TEXT;
BEGIN
  SELECT id, full_name INTO v_profile_id, v_full_name
  FROM   profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT * INTO v_req FROM approval_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND OR v_req.status <> 'pending' OR NOT v_req.is_active THEN
    RAISE EXCEPTION 'Request not actionable';
  END IF;

  -- Four-eyes guard: same user must not approve two roles in the same iteration
  IF EXISTS (
    SELECT 1 FROM approval_requests
    WHERE  source_id     = v_req.source_id
      AND  approval_type = v_req.approval_type
      AND  iteration     = v_req.iteration
      AND  decided_by    = v_profile_id
      AND  id            <> p_request_id
  ) THEN
    RAISE EXCEPTION 'You have already approved another role on this slip';
  END IF;

  UPDATE approval_requests
  SET    status          = 'approved',
         decided_by      = v_profile_id,
         decided_by_name = v_full_name,
         comment         = p_comment
  WHERE  id = p_request_id;

  PERFORM public.advance_sales_approval(v_req.source_id, v_req.approval_type);
END;
$$;

-- ─── reject_sales_request ───────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.reject_sales_request(
  p_request_id uuid,
  p_reason     text
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_req        RECORD;
  v_profile_id uuid;
  v_full_name  TEXT;
BEGIN
  IF COALESCE(TRIM(p_reason), '') = '' THEN
    RAISE EXCEPTION 'A reason is required to reject';
  END IF;

  SELECT id, full_name INTO v_profile_id, v_full_name
  FROM   profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT * INTO v_req FROM approval_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND OR v_req.status <> 'pending' OR NOT v_req.is_active THEN
    RAISE EXCEPTION 'Request not actionable';
  END IF;

  -- Mark this row rejected
  UPDATE approval_requests
  SET    status          = 'rejected',
         decided_by      = v_profile_id,
         decided_by_name = v_full_name,
         reason          = p_reason
  WHERE  id = p_request_id;

  -- Mark all sibling pending rows in the same iteration as rejected too
  -- (the salesperson must fix the SO before any further review)
  UPDATE approval_requests
  SET    status   = 'rejected',
         reason   = 'Cancelled — sibling step rejected'
  WHERE  source_id     = v_req.source_id
    AND  approval_type = v_req.approval_type
    AND  iteration     = v_req.iteration
    AND  status        = 'pending'
    AND  id            <> p_request_id;

  -- Bounce SO back to quotation so it can be edited and resubmitted
  UPDATE sale_orders SET status = 'quotation' WHERE id = v_req.source_id;
END;
$$;

-- ─── resubmit_sale_order ────────────────────────────────────────────────────
-- Called when a salesperson resubmits a previously rejected quotation. Re-runs
-- both gates against the SO's current lines and creates new slip rows (with
-- iteration = max + 1) for whichever gates fire.
CREATE OR REPLACE FUNCTION public.resubmit_sale_order(p_so_id uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_so              RECORD;
  v_customer        RECORD;
  v_total_qar       NUMERIC;
  v_open_total      NUMERIC;
  v_available       NUMERIC;
  v_exceeds_credit  BOOLEAN := false;
  v_has_below_cost  BOOLEAN := false;
  v_below_cost_lines JSONB := '[]'::jsonb;
  v_profile_id      uuid;
BEGIN
  SELECT id INTO v_profile_id FROM profiles WHERE auth_user_id = auth.uid();

  SELECT * INTO v_so FROM sale_orders WHERE id = p_so_id;
  IF NOT FOUND OR v_so.status <> 'quotation' THEN
    RAISE EXCEPTION 'SO not resubmittable';
  END IF;

  SELECT c.customer_type, cg.credit_limit
  INTO   v_customer
  FROM   customers c
  LEFT JOIN credit_groups cg ON cg.id = c.credit_group_id
  WHERE  c.id = v_so.customer_id;

  v_total_qar := v_so.total * COALESCE(v_so.exchange_rate, 1);

  -- Margin
  SELECT jsonb_agg(jsonb_build_object(
           'item_name', item_name, 'unit_price', unit_price, 'avg_cost', avg_cost
         )) FILTER (WHERE avg_cost > 0 AND unit_price < avg_cost)
  INTO   v_below_cost_lines
  FROM   sale_order_lines WHERE sale_order_id = p_so_id;

  IF v_below_cost_lines IS NOT NULL AND jsonb_array_length(v_below_cost_lines) > 0 THEN
    v_has_below_cost := true;
  END IF;

  -- Credit
  IF COALESCE(v_customer.customer_type, 'credit') <> 'cash'
     AND v_customer.credit_limit IS NOT NULL THEN
    SELECT COALESCE(SUM(total), 0) INTO v_open_total
    FROM   sale_orders
    WHERE  customer_id = v_so.customer_id AND status NOT IN ('cancelled')
      AND  deleted_at IS NULL AND id <> p_so_id;
    v_available := v_customer.credit_limit - v_open_total;
    IF v_total_qar > v_available THEN v_exceeds_credit := true; END IF;
  END IF;

  IF v_exceeds_credit OR v_has_below_cost THEN
    UPDATE sale_orders SET status = 'pending_approval' WHERE id = p_so_id;
    IF v_exceeds_credit THEN
      PERFORM public.build_sales_approval_chain(
        p_so_id, 'credit',
        jsonb_build_object('available', GREATEST(v_available,0),
                           'overage',   v_total_qar - COALESCE(v_available, 0),
                           'requested_by', v_profile_id)
      );
    END IF;
    IF v_has_below_cost THEN
      PERFORM public.build_sales_approval_chain(
        p_so_id, 'margin',
        jsonb_build_object('lines', v_below_cost_lines, 'requested_by', v_profile_id)
      );
    END IF;
  ELSE
    UPDATE sale_orders SET status = 'confirmed' WHERE id = p_so_id;
  END IF;

  RETURN jsonb_build_object(
    'exceeds_credit', v_exceeds_credit,
    'has_below_cost', v_has_below_cost
  );
END;
$$;

COMMIT;


-- ============================================================
-- Source: 20260627100004_sales_approval_rpc_fixes.sql
-- ============================================================
-- Sales approval RPC fixes (follow-up to 20260627100003).
--
-- 1. build_sales_approval_chain — hard-fail if no active steps exist for the
--    workflow, so a misconfigured chain doesn't strand the SO in pending_approval.
-- 2. reject_sales_request — cascade message goes into `comment`, not `reason`,
--    so each sibling row preserves its original trigger payload for audit.
-- 3. resubmit_sale_order — recompute total directly from sale_order_lines so
--    margin and credit gates can't disagree if sale_orders.total is stale;
--    also add the v_profile_id IS NULL guard used by the other RPCs.
BEGIN;

-- ─── build_sales_approval_chain ─────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.build_sales_approval_chain(
  p_so_id          uuid,
  p_approval_type  approval_type,       -- 'margin' | 'credit'
  p_payload        jsonb
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_workflow    TEXT;
  v_iteration   INT;
  v_step        RECORD;
  v_role_name   TEXT;
  v_first       BOOLEAN := true;
  v_inserted    INT     := 0;
BEGIN
  v_workflow := CASE p_approval_type
    WHEN 'margin' THEN 'sales_margin'
    WHEN 'credit' THEN 'sales_credit'
  END;

  SELECT COALESCE(MAX(iteration), 0) + 1 INTO v_iteration
  FROM   approval_requests
  WHERE  source_id     = p_so_id
    AND  approval_type = p_approval_type;

  FOR v_step IN
    SELECT was.step_order, cr.name AS role_name
    FROM   workflow_approval_steps was
    JOIN   custom_roles cr ON cr.id = was.role_id
    WHERE  was.workflow   = v_workflow
      AND  was.is_active  = true
      AND  was.archived_at IS NULL
    ORDER  BY was.step_order
  LOOP
    INSERT INTO approval_requests (
      source_type, source_id, approval_type, status,
      requested_by, reason,
      step_role, step_order, is_active, iteration
    ) VALUES (
      'sale_order', p_so_id, p_approval_type, 'pending',
      (p_payload->>'requested_by')::uuid,
      p_payload::text,
      v_step.role_name, v_step.step_order, v_first, v_iteration
    );
    v_first    := false;
    v_inserted := v_inserted + 1;
  END LOOP;

  IF v_inserted = 0 THEN
    RAISE EXCEPTION 'No active approval chain configured for workflow %. Configure steps in Master Data → User Roles → Approval Chain Management before submitting this sale order.', v_workflow;
  END IF;
END;
$$;

-- ─── reject_sales_request ───────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.reject_sales_request(
  p_request_id uuid,
  p_reason     text
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_req        RECORD;
  v_profile_id uuid;
  v_full_name  TEXT;
BEGIN
  IF COALESCE(TRIM(p_reason), '') = '' THEN
    RAISE EXCEPTION 'A reason is required to reject';
  END IF;

  SELECT id, full_name INTO v_profile_id, v_full_name
  FROM   profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT * INTO v_req FROM approval_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND OR v_req.status <> 'pending' OR NOT v_req.is_active THEN
    RAISE EXCEPTION 'Request not actionable';
  END IF;

  -- Mark this row rejected
  UPDATE approval_requests
  SET    status          = 'rejected',
         decided_by      = v_profile_id,
         decided_by_name = v_full_name,
         reason          = p_reason
  WHERE  id = p_request_id;

  -- Mark all sibling pending rows in the same iteration as rejected too
  -- (the salesperson must fix the SO before any further review).
  -- Cancellation message goes into `comment` so the original trigger payload
  -- in `reason` is preserved on every sibling row for audit history.
  UPDATE approval_requests
  SET    status  = 'rejected',
         comment = 'Cancelled — sibling step rejected'
  WHERE  source_id     = v_req.source_id
    AND  approval_type = v_req.approval_type
    AND  iteration     = v_req.iteration
    AND  status        = 'pending'
    AND  id            <> p_request_id;

  -- Bounce SO back to quotation so it can be edited and resubmitted
  UPDATE sale_orders SET status = 'quotation' WHERE id = v_req.source_id;
END;
$$;

-- ─── resubmit_sale_order ────────────────────────────────────────────────────
-- Called when a salesperson resubmits a previously rejected quotation. Re-runs
-- both gates against the SO's current lines and creates new slip rows (with
-- iteration = max + 1) for whichever gates fire.
CREATE OR REPLACE FUNCTION public.resubmit_sale_order(p_so_id uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_so              RECORD;
  v_customer        RECORD;
  v_total_qar       NUMERIC;
  v_open_total      NUMERIC;
  v_available       NUMERIC;
  v_exceeds_credit  BOOLEAN := false;
  v_has_below_cost  BOOLEAN := false;
  v_below_cost_lines JSONB := '[]'::jsonb;
  v_profile_id      uuid;
BEGIN
  SELECT id INTO v_profile_id FROM profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT * INTO v_so FROM sale_orders WHERE id = p_so_id;
  IF NOT FOUND OR v_so.status <> 'quotation' THEN
    RAISE EXCEPTION 'SO not resubmittable';
  END IF;

  SELECT c.customer_type, cg.credit_limit
  INTO   v_customer
  FROM   customers c
  LEFT JOIN credit_groups cg ON cg.id = c.credit_group_id
  WHERE  c.id = v_so.customer_id;

  -- Compute total directly from lines to avoid any drift with sale_orders.total
  SELECT COALESCE(SUM(total), 0) INTO v_total_qar
  FROM   sale_order_lines
  WHERE  sale_order_id = p_so_id;
  v_total_qar := v_total_qar * COALESCE(v_so.exchange_rate, 1);

  -- Margin
  SELECT jsonb_agg(jsonb_build_object(
           'item_name', item_name, 'unit_price', unit_price, 'avg_cost', avg_cost
         )) FILTER (WHERE avg_cost > 0 AND unit_price < avg_cost)
  INTO   v_below_cost_lines
  FROM   sale_order_lines WHERE sale_order_id = p_so_id;

  IF v_below_cost_lines IS NOT NULL AND jsonb_array_length(v_below_cost_lines) > 0 THEN
    v_has_below_cost := true;
  END IF;

  -- Credit
  IF COALESCE(v_customer.customer_type, 'credit') <> 'cash'
     AND v_customer.credit_limit IS NOT NULL THEN
    SELECT COALESCE(SUM(total), 0) INTO v_open_total
    FROM   sale_orders
    WHERE  customer_id = v_so.customer_id AND status NOT IN ('cancelled')
      AND  deleted_at IS NULL AND id <> p_so_id;
    v_available := v_customer.credit_limit - v_open_total;
    IF v_total_qar > v_available THEN v_exceeds_credit := true; END IF;
  END IF;

  IF v_exceeds_credit OR v_has_below_cost THEN
    UPDATE sale_orders SET status = 'pending_approval' WHERE id = p_so_id;
    IF v_exceeds_credit THEN
      PERFORM public.build_sales_approval_chain(
        p_so_id, 'credit',
        jsonb_build_object('available', GREATEST(v_available,0),
                           'overage',   v_total_qar - COALESCE(v_available, 0),
                           'requested_by', v_profile_id)
      );
    END IF;
    IF v_has_below_cost THEN
      PERFORM public.build_sales_approval_chain(
        p_so_id, 'margin',
        jsonb_build_object('lines', v_below_cost_lines, 'requested_by', v_profile_id)
      );
    END IF;
  ELSE
    UPDATE sale_orders SET status = 'confirmed' WHERE id = p_so_id;
  END IF;

  RETURN jsonb_build_object(
    'exceeds_credit', v_exceeds_credit,
    'has_below_cost', v_has_below_cost
  );
END;
$$;

COMMIT;


-- ============================================================
-- Source: 20260627100005_sales_approval_role_guard.sql
-- ============================================================
-- Sales Approval — role + scope guard for approve/reject RPCs.
--
-- Background: the original approve_sales_request / reject_sales_request only
-- checked four-eyes (caller hasn't already decided another row in this
-- iteration). The UI hook usePendingSalesApprovals filters slips by the
-- caller's roles + scopes before showing them, but the SQL itself never
-- verified that the caller actually held the role named in step_role with
-- the matching scope (sales_margin / sales_credit). A user with the anon
-- key could bypass the UI filter and approve any slip via direct RPC call.
--
-- This migration replaces both functions to enforce the role+scope check
-- server-side. Behaviour change for legitimate users: none (the UI already
-- only surfaces slips they have the role for). Behaviour change for crafted
-- direct RPC calls: hard-fail with a clear message.
BEGIN;

-- ─── approve_sales_request ──────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.approve_sales_request(
  p_request_id uuid,
  p_comment    text
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_req         RECORD;
  v_profile_id  uuid;
  v_full_name   TEXT;
  v_scope       TEXT;
BEGIN
  SELECT id, full_name INTO v_profile_id, v_full_name
  FROM   profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT * INTO v_req FROM approval_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND OR v_req.status <> 'pending' OR NOT v_req.is_active THEN
    RAISE EXCEPTION 'Request not actionable';
  END IF;

  v_scope := CASE v_req.approval_type
    WHEN 'margin' THEN 'sales_margin'
    WHEN 'credit' THEN 'sales_credit'
  END;
  IF v_scope IS NULL THEN
    RAISE EXCEPTION 'Unknown sales approval type %', v_req.approval_type;
  END IF;

  -- Role + scope guard: caller must hold an approval-slot role named step_role
  -- with either NULL (all scopes) or the matching sales scope in approval_scopes.
  IF NOT EXISTS (
    SELECT 1
    FROM   user_custom_roles ucr
    JOIN   custom_roles cr ON cr.id = ucr.role_id
    WHERE  ucr.profile_id        = v_profile_id
      AND  cr.name               = v_req.step_role
      AND  cr.is_approval_slot   = true
      AND  cr.deleted_at         IS NULL
      AND  (ucr.approval_scopes IS NULL
            OR v_scope = ANY(ucr.approval_scopes))
  ) THEN
    RAISE EXCEPTION 'You do not hold the role required for this approval step';
  END IF;

  -- Four-eyes guard: same user must not approve two roles in the same iteration
  IF EXISTS (
    SELECT 1 FROM approval_requests
    WHERE  source_id     = v_req.source_id
      AND  approval_type = v_req.approval_type
      AND  iteration     = v_req.iteration
      AND  decided_by    = v_profile_id
      AND  id            <> p_request_id
  ) THEN
    RAISE EXCEPTION 'You have already approved another role on this slip';
  END IF;

  UPDATE approval_requests
  SET    status          = 'approved',
         decided_by      = v_profile_id,
         decided_by_name = v_full_name,
         comment         = p_comment
  WHERE  id = p_request_id;

  PERFORM public.advance_sales_approval(v_req.source_id, v_req.approval_type);
END;
$$;

-- ─── reject_sales_request ───────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.reject_sales_request(
  p_request_id uuid,
  p_reason     text
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_req         RECORD;
  v_profile_id  uuid;
  v_full_name   TEXT;
  v_scope       TEXT;
BEGIN
  IF COALESCE(TRIM(p_reason), '') = '' THEN
    RAISE EXCEPTION 'A reason is required to reject';
  END IF;

  SELECT id, full_name INTO v_profile_id, v_full_name
  FROM   profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT * INTO v_req FROM approval_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND OR v_req.status <> 'pending' OR NOT v_req.is_active THEN
    RAISE EXCEPTION 'Request not actionable';
  END IF;

  v_scope := CASE v_req.approval_type
    WHEN 'margin' THEN 'sales_margin'
    WHEN 'credit' THEN 'sales_credit'
  END;
  IF v_scope IS NULL THEN
    RAISE EXCEPTION 'Unknown sales approval type %', v_req.approval_type;
  END IF;

  -- Role + scope guard (same as approve)
  IF NOT EXISTS (
    SELECT 1
    FROM   user_custom_roles ucr
    JOIN   custom_roles cr ON cr.id = ucr.role_id
    WHERE  ucr.profile_id        = v_profile_id
      AND  cr.name               = v_req.step_role
      AND  cr.is_approval_slot   = true
      AND  cr.deleted_at         IS NULL
      AND  (ucr.approval_scopes IS NULL
            OR v_scope = ANY(ucr.approval_scopes))
  ) THEN
    RAISE EXCEPTION 'You do not hold the role required to reject this approval step';
  END IF;

  -- Mark this row rejected
  UPDATE approval_requests
  SET    status          = 'rejected',
         decided_by      = v_profile_id,
         decided_by_name = v_full_name,
         reason          = p_reason
  WHERE  id = p_request_id;

  -- Mark all sibling pending rows in the same iteration as rejected too
  -- (the salesperson must fix the SO before any further review)
  UPDATE approval_requests
  SET    status   = 'rejected',
         reason   = 'Cancelled — sibling step rejected'
  WHERE  source_id     = v_req.source_id
    AND  approval_type = v_req.approval_type
    AND  iteration     = v_req.iteration
    AND  status        = 'pending'
    AND  id            <> p_request_id;

  -- Bounce SO back to quotation so it can be edited and resubmitted
  UPDATE sale_orders SET status = 'quotation' WHERE id = v_req.source_id;
END;
$$;

COMMIT;


-- ============================================================
-- Source: 20260627100006_widen_add_workflow_step_allowlist.sql
-- ============================================================
-- Widen the hardcoded workflow allow-list in add_workflow_step /
-- add_workflow_step_for_role to include the two new sales workflows.
--
-- The CHECK constraint on workflow_approval_steps.workflow was already
-- widened by 20260627100000_sales_approval_chains.sql, but the two RPCs
-- carry their own NOT IN guard list which still rejected 'sales_margin' /
-- 'sales_credit' with "Invalid workflow: sales_margin" when the admin tried
-- to add the first step on the Sales — Margin chain.
BEGIN;

-- ─── add_workflow_step (legacy variant — takes role NAME) ───────────────────
CREATE OR REPLACE FUNCTION public.add_workflow_step(
  p_workflow         text,
  p_role_name        text,
  p_role_desc        text DEFAULT ''::text,
  p_is_conditional   boolean DEFAULT false,
  p_condition_types  text[] DEFAULT '{}'::text[]
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_role_id   UUID;
  v_max_order INT;
  v_step_key  TEXT;
  v_step      workflow_approval_steps;
BEGIN
  IF p_workflow NOT IN ('po','inv_check','stock_adj','sales_margin','sales_credit') THEN
    RAISE EXCEPTION 'Invalid workflow: %', p_workflow;
  END IF;
  IF TRIM(p_role_name) = '' THEN
    RAISE EXCEPTION 'Role name cannot be empty';
  END IF;

  SELECT id INTO v_role_id
  FROM custom_roles
  WHERE name = p_role_name AND deleted_at IS NULL;

  IF v_role_id IS NULL THEN
    INSERT INTO custom_roles (name, description, is_approval_slot, is_system, permissions)
    VALUES (TRIM(p_role_name), NULLIF(TRIM(p_role_desc),''), true, false, '[]'::jsonb)
    RETURNING id INTO v_role_id;
  ELSE
    UPDATE custom_roles SET is_approval_slot = true WHERE id = v_role_id;
  END IF;

  v_step_key := LOWER(REGEXP_REPLACE(TRIM(p_role_name), '\s+', '_', 'g'));

  SELECT COALESCE(MAX(step_order), 0) INTO v_max_order
  FROM workflow_approval_steps
  WHERE workflow = p_workflow AND archived_at IS NULL;

  INSERT INTO workflow_approval_steps (
    workflow, role_id, step_key, step_label, step_order,
    is_conditional, condition_types
  ) VALUES (
    p_workflow, v_role_id, v_step_key, TRIM(p_role_name), v_max_order + 1,
    p_is_conditional, p_condition_types
  )
  RETURNING * INTO v_step;

  RETURN to_jsonb(v_step);
END;
$$;

-- ─── add_workflow_step_for_role (current variant — takes role UUID) ─────────
CREATE OR REPLACE FUNCTION public.add_workflow_step_for_role(
  p_workflow         text,
  p_role_id          uuid,
  p_is_conditional   boolean DEFAULT false,
  p_condition_types  text[] DEFAULT '{}'::text[]
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_role_name TEXT;
  v_max_order INT;
  v_step_key  TEXT;
  v_step      workflow_approval_steps;
BEGIN
  IF p_workflow NOT IN ('po','inv_check','stock_adj','sales_margin','sales_credit') THEN
    RAISE EXCEPTION 'Invalid workflow: %', p_workflow;
  END IF;

  SELECT name INTO v_role_name
  FROM custom_roles
  WHERE id = p_role_id
    AND is_approval_slot = true
    AND deleted_at IS NULL;

  IF v_role_name IS NULL THEN
    RAISE EXCEPTION 'Role not found or is not an approval-slot role';
  END IF;

  IF EXISTS (
    SELECT 1 FROM workflow_approval_steps
    WHERE workflow = p_workflow
      AND role_id  = p_role_id
      AND archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'This role is already a step in the % workflow', p_workflow;
  END IF;

  v_step_key := LOWER(REGEXP_REPLACE(TRIM(v_role_name), '\s+', '_', 'g'));

  IF EXISTS (
    SELECT 1 FROM workflow_approval_steps
    WHERE workflow = p_workflow AND step_key = v_step_key
  ) THEN
    v_step_key := v_step_key || '_' || substr(gen_random_uuid()::text, 1, 6);
  END IF;

  SELECT COALESCE(MAX(step_order), 0) INTO v_max_order
  FROM workflow_approval_steps
  WHERE workflow = p_workflow AND archived_at IS NULL;

  INSERT INTO workflow_approval_steps (
    workflow, role_id, step_key, step_label, step_order,
    is_conditional, condition_types
  ) VALUES (
    p_workflow, p_role_id, v_step_key, v_role_name, v_max_order + 1,
    p_is_conditional, p_condition_types
  )
  RETURNING * INTO v_step;

  RETURN to_jsonb(v_step);
END;
$$;

COMMIT;


-- ============================================================
-- Source: 20260627100007_drop_create_sale_order_legacy_overload.sql
-- ============================================================
-- Drop the 16-arg create_sale_order overload that pre-existed in the baseline.
--
-- 20260627100001_create_sale_order_approval_gates.sql replaced the 17-arg
-- variant (the one with p_division_id) but left the 16-arg variant from the
-- baseline (20240101000000_baseline_schema.sql) intact. The client calls
-- create_sale_order with 17 named args (p_division_id always passed, NULL
-- when not chosen), and PostgREST cannot pick between the two overloads,
-- so order confirmation fails with:
--
--   PGRST203 "Could not choose the best candidate function between:
--   public.create_sale_order(...16 args...),
--   public.create_sale_order(...17 args...)"
--
-- Drop the legacy 16-arg overload. The 17-arg overload remains and is the
-- only signature the client ever wants.
BEGIN;

DROP FUNCTION IF EXISTS public.create_sale_order(
  uuid, text, text, numeric, date, text, text, jsonb,
  text, text, text, integer, numeric, text, text, jsonb
);

COMMIT;


-- ============================================================
-- Source: 20260627100008_credit_groups_default_payment_terms.sql
-- ============================================================
-- Add default_payment_terms to credit_groups so the SO create page can
-- pre-select a payment-terms preset based on the chosen customer's credit
-- group. Cash customers still bypass payment terms entirely; this is
-- credit-group-scoped only.
--
-- Allowed values match the PAYMENT_PRESETS list in SoTermsSection.tsx —
-- '100% Advance', '100% After Delivery', '50/50', 'Net 30', 'Net 60',
-- 'Custom'. NULL means no default; UI falls back to whatever the user
-- last set (or none).
BEGIN;

ALTER TABLE public.credit_groups
  ADD COLUMN IF NOT EXISTS default_payment_terms TEXT;

ALTER TABLE public.credit_groups
  DROP CONSTRAINT IF EXISTS credit_groups_default_payment_terms_chk;
ALTER TABLE public.credit_groups
  ADD CONSTRAINT credit_groups_default_payment_terms_chk
  CHECK (
    default_payment_terms IS NULL
    OR default_payment_terms IN (
      '100% Advance', '100% After Delivery', '50/50',
      'Net 30', 'Net 60', 'Custom'
    )
  );

COMMIT;


-- ============================================================
-- Source: 20260627101900_sales_pdf_cache.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Sales PDF cache — URL columns + storage buckets + invalidation triggers
--
-- Background: @react-pdf/renderer crashes on Next 15 because Next ships React
-- 19-canary which doesn't expose `__SECRET_INTERNALS_DO_NOT_USE_OR_YOU_WILL_BE_FIRED`.
-- Migrating SO Quotation / AR Invoice / Credit-Debit Note PDFs to the same
-- Puppeteer + HTML pipeline used by `orders.confirmation_pdf_url`.
--
-- For each document we:
--   1. Add `<doc>_pdf_url TEXT` to the parent row.
--   2. Create a public storage bucket (read-only for anon; service-role writes).
--   3. Install a BEFORE-UPDATE trigger on the parent that nulls the URL on any
--      data change, EXCEPT when the API route is writing the URL itself
--      (signalled via the `app.skip_pdf_invalidation` GUC).
--   4. For SO + AR Invoice (which have separate line-item tables), install an
--      AFTER-INSERT/UPDATE/DELETE trigger on the line table that nulls the
--      parent URL — credit_notes stores lines inline as jsonb so no cascade.
--
-- Why a GUC and not a "URL-only column compare": columns evolve over time, and
-- enumerating every other column in the trigger predicate is brittle. The GUC
-- approach is explicit and survives schema changes.
-- ─────────────────────────────────────────────────────────────────────────────

-- ── 1. Columns ──────────────────────────────────────────────────────────────

ALTER TABLE public.sale_orders
  ADD COLUMN IF NOT EXISTS quotation_pdf_url TEXT;
COMMENT ON COLUMN public.sale_orders.quotation_pdf_url IS
  'Public URL of the generated SO quotation PDF. NULL = needs (re)generating.';

ALTER TABLE public.invoices
  ADD COLUMN IF NOT EXISTS pdf_url TEXT;
COMMENT ON COLUMN public.invoices.pdf_url IS
  'Public URL of the generated invoice PDF (AR direction). NULL = needs (re)generating.';

ALTER TABLE public.credit_notes
  ADD COLUMN IF NOT EXISTS pdf_url TEXT;
COMMENT ON COLUMN public.credit_notes.pdf_url IS
  'Public URL of the generated credit/debit note PDF. NULL = needs (re)generating.';

-- ── 2. Storage buckets ──────────────────────────────────────────────────────

INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES
  ('quotation-pdfs',   'quotation-pdfs',   true, 10 * 1024 * 1024, ARRAY['application/pdf']),
  ('invoice-pdfs',     'invoice-pdfs',     true, 10 * 1024 * 1024, ARRAY['application/pdf']),
  ('credit-note-pdfs', 'credit-note-pdfs', true, 10 * 1024 * 1024, ARRAY['application/pdf'])
ON CONFLICT (id) DO UPDATE SET
  public             = EXCLUDED.public,
  file_size_limit    = EXCLUDED.file_size_limit,
  allowed_mime_types = EXCLUDED.allowed_mime_types;

-- Storage policies — public read, service-role write/update (matches the
-- booking-confirmations bucket pattern).
DO $$
DECLARE b TEXT;
BEGIN
  FOREACH b IN ARRAY ARRAY['quotation-pdfs', 'invoice-pdfs', 'credit-note-pdfs'] LOOP
    -- Public read
    IF NOT EXISTS (
      SELECT 1 FROM pg_policies
      WHERE schemaname = 'storage' AND tablename = 'objects'
        AND policyname = b || '_public_read'
    ) THEN
      EXECUTE format(
        'CREATE POLICY %I ON storage.objects FOR SELECT USING (bucket_id = %L)',
        b || '_public_read', b
      );
    END IF;

    -- Service-role insert
    IF NOT EXISTS (
      SELECT 1 FROM pg_policies
      WHERE schemaname = 'storage' AND tablename = 'objects'
        AND policyname = b || '_service_write'
    ) THEN
      EXECUTE format(
        'CREATE POLICY %I ON storage.objects FOR INSERT TO service_role WITH CHECK (bucket_id = %L)',
        b || '_service_write', b
      );
    END IF;

    -- Service-role update (overwrite cached file on regeneration)
    IF NOT EXISTS (
      SELECT 1 FROM pg_policies
      WHERE schemaname = 'storage' AND tablename = 'objects'
        AND policyname = b || '_service_update'
    ) THEN
      EXECUTE format(
        'CREATE POLICY %I ON storage.objects FOR UPDATE TO service_role USING (bucket_id = %L) WITH CHECK (bucket_id = %L)',
        b || '_service_update', b, b
      );
    END IF;
  END LOOP;
END$$;

-- ── 3. Invalidation trigger functions ───────────────────────────────────────

-- The API route's PDF cache writer wraps its UPDATE in
--   SET LOCAL app.skip_pdf_invalidation = 'true';
-- so the trigger lets the URL through.

CREATE OR REPLACE FUNCTION public.sale_orders_invalidate_pdf_cache_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF current_setting('app.skip_pdf_invalidation', true) = 'true' THEN
    RETURN NEW;
  END IF;
  NEW.quotation_pdf_url := NULL;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.invoices_invalidate_pdf_cache_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF current_setting('app.skip_pdf_invalidation', true) = 'true' THEN
    RETURN NEW;
  END IF;
  NEW.pdf_url := NULL;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.credit_notes_invalidate_pdf_cache_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF current_setting('app.skip_pdf_invalidation', true) = 'true' THEN
    RETURN NEW;
  END IF;
  NEW.pdf_url := NULL;
  RETURN NEW;
END;
$$;

-- Cascade from line tables: any insert/update/delete of an SO line nulls the
-- parent SO's quotation PDF URL. Same for invoice_line_items → invoices.
CREATE OR REPLACE FUNCTION public.sale_order_lines_invalidate_parent_pdf_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE v_so_id UUID;
BEGIN
  v_so_id := COALESCE(NEW.sale_order_id, OLD.sale_order_id);
  IF v_so_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  UPDATE public.sale_orders
     SET quotation_pdf_url = NULL
   WHERE id = v_so_id
     AND quotation_pdf_url IS NOT NULL;
  RETURN COALESCE(NEW, OLD);
END;
$$;

CREATE OR REPLACE FUNCTION public.invoice_line_items_invalidate_parent_pdf_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE v_invoice_id UUID;
BEGIN
  v_invoice_id := COALESCE(NEW.invoice_id, OLD.invoice_id);
  IF v_invoice_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  UPDATE public.invoices
     SET pdf_url = NULL
   WHERE id = v_invoice_id
     AND pdf_url IS NOT NULL;
  RETURN COALESCE(NEW, OLD);
END;
$$;

-- ── 4. Triggers ─────────────────────────────────────────────────────────────

DROP TRIGGER IF EXISTS sale_orders_invalidate_pdf_cache  ON public.sale_orders;
CREATE TRIGGER       sale_orders_invalidate_pdf_cache
  BEFORE UPDATE ON public.sale_orders
  FOR EACH ROW
  EXECUTE FUNCTION public.sale_orders_invalidate_pdf_cache_fn();

DROP TRIGGER IF EXISTS invoices_invalidate_pdf_cache  ON public.invoices;
CREATE TRIGGER       invoices_invalidate_pdf_cache
  BEFORE UPDATE ON public.invoices
  FOR EACH ROW
  EXECUTE FUNCTION public.invoices_invalidate_pdf_cache_fn();

DROP TRIGGER IF EXISTS credit_notes_invalidate_pdf_cache  ON public.credit_notes;
CREATE TRIGGER       credit_notes_invalidate_pdf_cache
  BEFORE UPDATE ON public.credit_notes
  FOR EACH ROW
  EXECUTE FUNCTION public.credit_notes_invalidate_pdf_cache_fn();

DROP TRIGGER IF EXISTS sale_order_lines_cascade_pdf_invalidation  ON public.sale_order_lines;
CREATE TRIGGER       sale_order_lines_cascade_pdf_invalidation
  AFTER INSERT OR UPDATE OR DELETE ON public.sale_order_lines
  FOR EACH ROW
  EXECUTE FUNCTION public.sale_order_lines_invalidate_parent_pdf_fn();

DROP TRIGGER IF EXISTS invoice_line_items_cascade_pdf_invalidation  ON public.invoice_line_items;
CREATE TRIGGER       invoice_line_items_cascade_pdf_invalidation
  AFTER INSERT OR UPDATE OR DELETE ON public.invoice_line_items
  FOR EACH ROW
  EXECUTE FUNCTION public.invoice_line_items_invalidate_parent_pdf_fn();


-- ============================================================
-- Source: 20260627101901_sales_pdf_cache_rpc.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Sales PDF cache — service-role RPCs to write the URL without tripping the
-- invalidation trigger.
--
-- Each RPC sets the transaction-local GUC `app.skip_pdf_invalidation` to
-- 'true' before its UPDATE, which the BEFORE-UPDATE trigger reads to decide
-- whether to null the URL. The GUC is automatically reset at COMMIT (because
-- `is_local = true` in set_config).
--
-- These are SECURITY DEFINER and only callable by service_role — the
-- application's API routes invoke them via supabase-js .rpc() using the
-- service-role key. Anon/auth roles cannot trigger them.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.set_sale_order_pdf_url(p_id UUID, p_url TEXT)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  PERFORM set_config('app.skip_pdf_invalidation', 'true', true);
  UPDATE public.sale_orders SET quotation_pdf_url = p_url WHERE id = p_id;
END;
$$;

REVOKE ALL ON FUNCTION public.set_sale_order_pdf_url(UUID, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_sale_order_pdf_url(UUID, TEXT) TO service_role;

CREATE OR REPLACE FUNCTION public.set_invoice_pdf_url(p_id UUID, p_url TEXT)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  PERFORM set_config('app.skip_pdf_invalidation', 'true', true);
  UPDATE public.invoices SET pdf_url = p_url WHERE id = p_id;
END;
$$;

REVOKE ALL ON FUNCTION public.set_invoice_pdf_url(UUID, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_invoice_pdf_url(UUID, TEXT) TO service_role;

CREATE OR REPLACE FUNCTION public.set_credit_note_pdf_url(p_id UUID, p_url TEXT)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  PERFORM set_config('app.skip_pdf_invalidation', 'true', true);
  UPDATE public.credit_notes SET pdf_url = p_url WHERE id = p_id;
END;
$$;

REVOKE ALL ON FUNCTION public.set_credit_note_pdf_url(UUID, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_credit_note_pdf_url(UUID, TEXT) TO service_role;


-- ============================================================
-- Source: 20260627102000_sales_force_approve.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Force-approve for sales approval slips (Owner only).
--
-- Mirrors the PO `useForceApproveAllSteps` flow but inside one RPC:
--   force_approve_sales_request(p_so_id, p_approval_type, p_comment)
--
--   1. Caller must hold the Owner approval slot (custom_role.name='Owner',
--      is_approval_slot=true).
--   2. For the latest iteration of the (so, approval_type) slip, every
--      pending row is marked approved with `force_approved=true` and the
--      owner stamped as the decider.
--   3. `advance_sales_approval` is invoked so the state machine confirms the
--      SO when both chains are clear.
--
-- Also adds `force_approved` / `force_comment` columns to approval_requests
-- so a reader can tell at a glance which slips were bypassed.
-- ─────────────────────────────────────────────────────────────────────────────

BEGIN;

ALTER TABLE public.approval_requests
  ADD COLUMN IF NOT EXISTS force_approved BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS force_comment  TEXT;

COMMENT ON COLUMN public.approval_requests.force_approved IS
  'TRUE when the row was approved via force_approve_sales_request (Owner bypass) rather than the normal per-step flow.';
COMMENT ON COLUMN public.approval_requests.force_comment IS
  'Optional Owner-supplied justification recorded at force-approve time.';

CREATE OR REPLACE FUNCTION public.force_approve_sales_request(
  p_so_id          uuid,
  p_approval_type  approval_type,    -- 'margin' | 'credit'
  p_comment        text DEFAULT NULL
) RETURNS INT
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_profile_id  uuid;
  v_full_name   TEXT;
  v_is_owner    BOOLEAN;
  v_iteration   INT;
  v_count       INT;
BEGIN
  -- ── Caller identity ───────────────────────────────────────────────
  SELECT id, full_name INTO v_profile_id, v_full_name
  FROM   profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  -- ── Owner gate ────────────────────────────────────────────────────
  SELECT EXISTS (
    SELECT 1
    FROM   user_custom_roles ucr
    JOIN   custom_roles cr ON cr.id = ucr.role_id
    WHERE  ucr.profile_id      = v_profile_id
      AND  cr.name             = 'Owner'
      AND  cr.is_approval_slot = true
      AND  cr.deleted_at       IS NULL
  ) INTO v_is_owner;
  IF NOT v_is_owner THEN
    RAISE EXCEPTION 'Only users with the Owner role can force-approve';
  END IF;

  -- ── Latest iteration for this slip ────────────────────────────────
  SELECT COALESCE(MAX(iteration), 1) INTO v_iteration
  FROM   approval_requests
  WHERE  source_type   = 'sale_order'
    AND  source_id     = p_so_id
    AND  approval_type = p_approval_type;

  -- ── Bulk-approve every pending row in this iteration ──────────────
  UPDATE approval_requests
  SET    status          = 'approved',
         decided_by      = v_profile_id,
         decided_by_name = v_full_name,
         comment         = COALESCE(comment, p_comment),
         force_approved  = true,
         force_comment   = NULLIF(TRIM(COALESCE(p_comment, '')), ''),
         is_active       = true
  WHERE  source_type   = 'sale_order'
    AND  source_id     = p_so_id
    AND  approval_type = p_approval_type
    AND  iteration     = v_iteration
    AND  status        = 'pending';

  GET DIAGNOSTICS v_count = ROW_COUNT;

  IF v_count = 0 THEN
    RAISE EXCEPTION 'No pending steps to force-approve on this slip';
  END IF;

  -- ── Advance the chain (confirms the SO if both chains are clear) ──
  PERFORM public.advance_sales_approval(p_so_id, p_approval_type);

  RETURN v_count;
END;
$$;

REVOKE ALL ON FUNCTION public.force_approve_sales_request(uuid, approval_type, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.force_approve_sales_request(uuid, approval_type, text) TO authenticated;

COMMIT;


-- ============================================================
-- Source: 20260627103000_sales_approval_parallel.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Switch sales approval chains from SEQUENTIAL → PARALLEL.
--
-- Old behaviour: build_sales_approval_chain marked only the first step as
-- is_active=true; advance_sales_approval promoted the next step on each
-- approval. Approvers had to act in order (step_order asc), and the queue
-- only surfaced the slip to the role currently holding the active step.
--
-- New behaviour: every step in a new chain is is_active=true from the start.
-- Any approver whose role is listed in the chain can act at any time, in any
-- order. The chain completes when every active row in the latest iteration
-- has been approved.
--
-- Backfill: existing pending rows are flipped to is_active=true so today's
-- in-flight slips become visible to every relevant approver immediately.
-- ─────────────────────────────────────────────────────────────────────────────

BEGIN;

-- ── 1. Rebuild the chain-builder to activate every step at creation ─────────
CREATE OR REPLACE FUNCTION public.build_sales_approval_chain(
  p_so_id          uuid,
  p_approval_type  approval_type,
  p_payload        jsonb
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_workflow    TEXT;
  v_iteration   INT;
  v_step        RECORD;
BEGIN
  v_workflow := CASE p_approval_type
    WHEN 'margin' THEN 'sales_margin'
    WHEN 'credit' THEN 'sales_credit'
  END;

  SELECT COALESCE(MAX(iteration), 0) + 1 INTO v_iteration
  FROM   approval_requests
  WHERE  source_id     = p_so_id
    AND  approval_type = p_approval_type;

  FOR v_step IN
    SELECT was.step_order, cr.name AS role_name
    FROM   workflow_approval_steps was
    JOIN   custom_roles cr ON cr.id = was.role_id
    WHERE  was.workflow   = v_workflow
      AND  was.is_active  = true
      AND  was.archived_at IS NULL
    ORDER  BY was.step_order
  LOOP
    INSERT INTO approval_requests (
      source_type, source_id, approval_type, status,
      requested_by, reason,
      step_role, step_order, is_active, iteration
    ) VALUES (
      'sale_order', p_so_id, p_approval_type, 'pending',
      (p_payload->>'requested_by')::uuid,
      p_payload::text,
      v_step.role_name, v_step.step_order,
      true,                                   -- ⬅ every step active in parallel
      v_iteration
    );
  END LOOP;
END;
$$;

-- ── 2. Simplify advance_sales_approval — no sequential activation needed ────
CREATE OR REPLACE FUNCTION public.advance_sales_approval(
  p_so_id         uuid,
  p_approval_type approval_type
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_iteration  INT;
  v_all_done   BOOLEAN;
  v_open_other BOOLEAN;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext(p_so_id::text || p_approval_type::text));

  SELECT COALESCE(MAX(iteration), 1) INTO v_iteration
  FROM   approval_requests
  WHERE  source_id = p_so_id AND approval_type = p_approval_type;

  -- Has every step in this chain (latest iteration) been approved?
  SELECT NOT EXISTS (
    SELECT 1 FROM approval_requests
    WHERE  source_id     = p_so_id
      AND  approval_type = p_approval_type
      AND  iteration     = v_iteration
      AND  status        <> 'approved'
  ) INTO v_all_done;

  IF NOT v_all_done THEN RETURN; END IF;

  -- Chain fully cleared. If the OTHER chain still has pending rows, hold the
  -- SO in pending_approval; otherwise promote to confirmed.
  SELECT EXISTS (
    SELECT 1 FROM approval_requests
    WHERE  source_id     = p_so_id
      AND  approval_type <> p_approval_type
      AND  status        = 'pending'
  ) INTO v_open_other;

  IF NOT v_open_other THEN
    UPDATE sale_orders SET status = 'confirmed' WHERE id = p_so_id;
  END IF;
END;
$$;

-- ── 3. Backfill: flip every in-flight pending row to is_active=true ─────────
UPDATE public.approval_requests
SET    is_active = true
WHERE  source_type = 'sale_order'
  AND  status     = 'pending'
  AND  is_active  = false;

COMMIT;


-- ============================================================
-- Source: 20260627104000_relax_so_invoice_gate.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Relax the SO → invoice gate in generate_invoice_from_so.
--
-- Old rule: status must be 'partial_delivery' or 'delivered'.
-- Problem:  cash-paid SOs that are simply confirmed (no delivery recorded yet)
--           couldn't be invoiced, even though the RPC already inserts ALL
--           sale_order_lines into invoice_line_items at SO-line qty (it never
--           consulted delivered_qty), so there's no functional reason to
--           require a delivery stage. Salesperson got opaque `so_not_deliverable`.
--
-- New rule: allow confirmed | partial_delivery | delivered. Anything earlier
-- (quotation / pending_approval) or terminal (cancelled / closed) still blocks.
-- The existing `invoice_exists` guard prevents double-invoicing.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.generate_invoice_from_so(p_so_id uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_so              RECORD;
  v_invoice_id_str  TEXT;
  v_invoice_type    TEXT;
  v_issued_date     DATE;
  v_due_date        DATE;
  v_inv_count       INT;
  v_new_inv_id      uuid;
  v_new_inv_str     TEXT;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('invoices_serial'));

  IF EXISTS (
    SELECT 1 FROM invoices
    WHERE  sale_order_id = p_so_id AND direction = 'ar'
  ) THEN
    RAISE EXCEPTION 'invoice_exists';
  END IF;

  SELECT
    so.id,
    so.so_number,
    so.status,
    so.customer_id,
    so.subtotal,
    COALESCE(so.tax, 0)                 AS tax,
    so.total                            AS total_amount,
    COALESCE(c.customer_type, 'credit') AS customer_type
  INTO v_so
  FROM sale_orders so
  JOIN customers   c  ON c.id = so.customer_id
  WHERE so.id = p_so_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'so_not_found';
  END IF;

  IF v_so.status NOT IN ('confirmed', 'partial_delivery', 'delivered') THEN
    RAISE EXCEPTION 'so_not_invoiceable';
  END IF;

  SELECT COUNT(*) + 1 INTO v_inv_count FROM invoices;
  v_invoice_id_str := 'INV-' || LPAD(v_inv_count::text, 5, '0');

  v_invoice_type := v_so.customer_type;
  v_issued_date  := CURRENT_DATE;
  v_due_date     := CASE v_invoice_type
    WHEN 'cash' THEN CURRENT_DATE
    ELSE             CURRENT_DATE + 30
  END;

  INSERT INTO invoices (
    invoice_id, customer_id, direction, sale_order_id,
    invoice_type, doc_status, status, payment_status, needs_refresh,
    total_amount, subtotal, tax,
    issued_date, due_date,
    source, source_id, source_label
  ) VALUES (
    v_invoice_id_str, v_so.customer_id, 'ar', p_so_id,
    v_invoice_type, 'draft', 'draft', 'unpaid', false,
    v_so.total_amount, v_so.subtotal, v_so.tax,
    v_issued_date, v_due_date,
    'order', p_so_id::text, 'SO #' || v_so.so_number
  )
  RETURNING id, invoice_id INTO v_new_inv_id, v_new_inv_str;

  INSERT INTO invoice_line_items (invoice_id, description, qty, unit_price, total)
  SELECT v_new_inv_id, sol.item_name, sol.qty, sol.unit_price, sol.total
  FROM   sale_order_lines sol
  WHERE  sol.sale_order_id = p_so_id;

  RETURN jsonb_build_object(
    'id',           v_new_inv_id,
    'invoice_id',   v_new_inv_str,
    'invoice_type', v_invoice_type
  );
END;
$$;


-- ============================================================
-- Source: 20260627104100_backfill_sales_approval_activity.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Backfill: sales approval activity entries were written with module='sales',
-- but the SO detail dialog filters by module='sale_orders'. Renaming the
-- existing rows so they show up in the Activity tab now that the hooks write
-- the correct module name going forward.
-- ─────────────────────────────────────────────────────────────────────────────

UPDATE public.activity_log
SET    module = 'sale_orders'
WHERE  module = 'sales'
  AND  entity_type = 'sale_order'
  AND  action IN (
         'Sales Approval Approved',
         'Sales Approval Rejected',
         'Sales Approval Force-Approved (margin)',
         'Sales Approval Force-Approved (credit)'
       );


-- ============================================================
-- Source: 20260627105000_sales_approval_activity_trigger.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Auto-log every sales approval decision into activity_log.
--
-- Background: the client-side `void logActivity(...)` in the approve / reject /
-- force-approve hooks was unreliable — the request races the mutation success
-- and the modal closing, and in some browsers the fetch was being cancelled
-- before it landed. The user reported approval details missing from the SO
-- detail Activity tab even on freshly-approved SOs.
--
-- Fix: a single AFTER UPDATE trigger on approval_requests. When a row moves
-- from status='pending' to 'approved' or 'rejected' (for source_type='sale_order'),
-- the trigger writes an activity_log entry stamped with the approver's name,
-- the chain (margin/credit), the role they decided as, force-approve flag, and
-- the comment. Always wins because it runs in the same transaction as the
-- status change.
-- ─────────────────────────────────────────────────────────────────────────────

BEGIN;

CREATE OR REPLACE FUNCTION public.log_sales_approval_decision()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  v_action  TEXT;
  v_details TEXT;
BEGIN
  IF NEW.source_type <> 'sale_order' THEN RETURN NEW; END IF;
  IF OLD.status = NEW.status      THEN RETURN NEW; END IF;
  IF NEW.status NOT IN ('approved', 'rejected') THEN RETURN NEW; END IF;

  -- Build a readable action string. Force-approved rows get a louder label so
  -- they stand out in the timeline next to normal approvals.
  IF NEW.status = 'approved' AND NEW.force_approved THEN
    v_action := format('Sales Approval Force-Approved — %s (%s)',
                       INITCAP(REPLACE(NEW.step_role, '_', ' ')),
                       NEW.approval_type);
  ELSIF NEW.status = 'approved' THEN
    v_action := format('Sales Approval Approved — %s (%s)',
                       INITCAP(REPLACE(NEW.step_role, '_', ' ')),
                       NEW.approval_type);
  ELSE
    v_action := format('Sales Approval Rejected — %s (%s)',
                       INITCAP(REPLACE(NEW.step_role, '_', ' ')),
                       NEW.approval_type);
  END IF;

  v_details := jsonb_build_object(
    'approval_type', NEW.approval_type,
    'step_role',     NEW.step_role,
    'iteration',     NEW.iteration,
    'comment',       NULLIF(NEW.comment, ''),
    'reason',        CASE WHEN NEW.status = 'rejected' THEN NEW.reason ELSE NULL END,
    'force',         NEW.force_approved
  )::text;

  INSERT INTO public.activity_log (
    action, module, entity_type, entity_id,
    performer_name, severity, details
  ) VALUES (
    v_action,
    'sale_orders',
    'sale_order',
    NEW.source_id,
    NEW.decided_by_name,
    CASE
      WHEN NEW.status = 'rejected'        THEN 'warning'
      WHEN NEW.force_approved              THEN 'critical'
      ELSE                                       'info'
    END,
    v_details
  );

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_log_sales_approval_decision ON public.approval_requests;
CREATE TRIGGER       trg_log_sales_approval_decision
  AFTER UPDATE ON public.approval_requests
  FOR EACH ROW
  EXECUTE FUNCTION public.log_sales_approval_decision();

-- ─────────────────────────────────────────────────────────────────────────────
-- Backfill any already-decided rows that don't have a matching activity_log
-- entry yet. Match heuristic: same SO, action LIKE 'Sales Approval%', within
-- 1 minute of decided_at. New entries are seeded for anything not yet logged.
-- ─────────────────────────────────────────────────────────────────────────────
INSERT INTO public.activity_log (action, module, entity_type, entity_id, performer_name, severity, details, created_at)
SELECT
  CASE
    WHEN ar.status = 'approved' AND ar.force_approved
      THEN format('Sales Approval Force-Approved — %s (%s)',
                  INITCAP(REPLACE(ar.step_role, '_', ' ')), ar.approval_type)
    WHEN ar.status = 'approved'
      THEN format('Sales Approval Approved — %s (%s)',
                  INITCAP(REPLACE(ar.step_role, '_', ' ')), ar.approval_type)
    ELSE     format('Sales Approval Rejected — %s (%s)',
                  INITCAP(REPLACE(ar.step_role, '_', ' ')), ar.approval_type)
  END                                                            AS action,
  'sale_orders'                                                  AS module,
  'sale_order'                                                   AS entity_type,
  ar.source_id                                                   AS entity_id,
  ar.decided_by_name                                             AS performer_name,
  CASE WHEN ar.status = 'rejected' THEN 'warning'
       WHEN ar.force_approved      THEN 'critical'
       ELSE                              'info' END              AS severity,
  jsonb_build_object(
    'approval_type', ar.approval_type,
    'step_role',     ar.step_role,
    'iteration',     ar.iteration,
    'comment',       NULLIF(ar.comment, ''),
    'reason',        CASE WHEN ar.status = 'rejected' THEN ar.reason ELSE NULL END,
    'force',         ar.force_approved
  )::text                                                        AS details,
  COALESCE(ar.decided_at, ar.updated_at, now())                  AS created_at
FROM public.approval_requests ar
WHERE ar.source_type = 'sale_order'
  AND ar.status     IN ('approved', 'rejected')
  AND NOT EXISTS (
    SELECT 1 FROM public.activity_log al
    WHERE al.entity_id   = ar.source_id
      AND al.module      = 'sale_orders'
      AND al.action      LIKE 'Sales Approval%'
      AND (al.details::jsonb ->> 'iteration')::int = ar.iteration
      AND (al.details::jsonb ->> 'step_role')      = ar.step_role
      AND (al.details::jsonb ->> 'approval_type')  = ar.approval_type::text
  );

COMMIT;


-- ============================================================
-- Source: 20260627105100_invoice_inherits_so_payments.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- generate_invoice_from_so now seeds invoice.paid_amount + payment_status from
-- payments already recorded against the SO. Without this the freshly-generated
-- invoice showed "Paid QAR 0.00" even when the SO had been fully paid before
-- the invoice was generated.
--
-- We also re-point the existing payment rows from source=sale_order to
-- source=invoice so the invoice's payment history surfaces them. The SO's
-- Payments tab can still find them via the invoice link, and any new payment
-- recorded on either side will live on the invoice from here on.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.generate_invoice_from_so(p_so_id uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_so               RECORD;
  v_invoice_id_str   TEXT;
  v_invoice_type     TEXT;
  v_issued_date      DATE;
  v_due_date         DATE;
  v_inv_count        INT;
  v_new_inv_id       uuid;
  v_new_inv_str      TEXT;
  v_paid_amount      NUMERIC;
  v_payment_status   TEXT;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('invoices_serial'));

  IF EXISTS (
    SELECT 1 FROM invoices
    WHERE  sale_order_id = p_so_id AND direction = 'ar'
  ) THEN
    RAISE EXCEPTION 'invoice_exists';
  END IF;

  SELECT
    so.id, so.so_number, so.status, so.customer_id,
    so.subtotal,
    COALESCE(so.tax, 0)                 AS tax,
    so.total                            AS total_amount,
    COALESCE(c.customer_type, 'credit') AS customer_type
  INTO v_so
  FROM sale_orders so
  JOIN customers   c  ON c.id = so.customer_id
  WHERE so.id = p_so_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'so_not_found';
  END IF;

  IF v_so.status NOT IN ('confirmed', 'partial_delivery', 'delivered') THEN
    RAISE EXCEPTION 'so_not_invoiceable';
  END IF;

  -- Sum payments already recorded against the SO (QAR-equivalent if present).
  SELECT COALESCE(SUM(COALESCE(amount_qar, amount)), 0)
    INTO v_paid_amount
  FROM   public.payments
  WHERE  source_type = 'sale_order'
    AND  source_id   = p_so_id
    AND  deleted_at IS NULL;

  v_payment_status := CASE
    WHEN v_paid_amount >= v_so.total_amount THEN 'paid'
    WHEN v_paid_amount > 0                  THEN 'partially_paid'
    ELSE                                          'unpaid'
  END;

  SELECT COUNT(*) + 1 INTO v_inv_count FROM invoices;
  v_invoice_id_str := 'INV-' || LPAD(v_inv_count::text, 5, '0');

  v_invoice_type := v_so.customer_type;
  v_issued_date  := CURRENT_DATE;
  v_due_date     := CASE v_invoice_type
    WHEN 'cash' THEN CURRENT_DATE
    ELSE             CURRENT_DATE + 30
  END;

  INSERT INTO invoices (
    invoice_id, customer_id, direction, sale_order_id,
    invoice_type, doc_status, status, payment_status, needs_refresh,
    total_amount, subtotal, tax, paid_amount,
    issued_date, due_date,
    source, source_id, source_label
  ) VALUES (
    v_invoice_id_str, v_so.customer_id, 'ar', p_so_id,
    v_invoice_type, 'draft', 'draft', v_payment_status, false,
    v_so.total_amount, v_so.subtotal, v_so.tax, v_paid_amount,
    v_issued_date, v_due_date,
    'order', p_so_id::text, 'SO #' || v_so.so_number
  )
  RETURNING id, invoice_id INTO v_new_inv_id, v_new_inv_str;

  -- Re-point the SO's payments at the new invoice so the invoice's payment
  -- history surfaces them. New payments from here on go on the invoice too.
  UPDATE public.payments
  SET    source_type = 'invoice',
         source_id   = v_new_inv_id
  WHERE  source_type = 'sale_order'
    AND  source_id   = p_so_id
    AND  deleted_at IS NULL;

  INSERT INTO invoice_line_items (invoice_id, description, qty, unit_price, total)
  SELECT v_new_inv_id, sol.item_name, sol.qty, sol.unit_price, sol.total
  FROM   sale_order_lines sol
  WHERE  sol.sale_order_id = p_so_id;

  RETURN jsonb_build_object(
    'id',           v_new_inv_id,
    'invoice_id',   v_new_inv_str,
    'invoice_type', v_invoice_type,
    'paid_amount',  v_paid_amount
  );
END;
$$;


-- ============================================================
-- Source: 20260627105200_backfill_invoice_paid_amount.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- One-off backfill: AR invoices generated BEFORE 20260627105100 went live still
-- show paid_amount=0 even though their parent SO had payments. Re-point those
-- payments at the invoice and resync the invoice's paid_amount + payment_status.
-- Idempotent — safe to leave in the migration history.
-- ─────────────────────────────────────────────────────────────────────────────

BEGIN;

-- Re-point SO payments at their AR invoice (if one exists)
UPDATE public.payments p
SET    source_type = 'invoice',
       source_id   = i.id
FROM   public.invoices i
WHERE  p.source_type = 'sale_order'
  AND  p.deleted_at IS NULL
  AND  i.sale_order_id = p.source_id
  AND  i.direction = 'ar';

-- Recompute paid_amount + payment_status for every AR invoice
WITH sums AS (
  SELECT  i.id                                       AS invoice_id,
          i.total_amount                             AS total,
          COALESCE(SUM(COALESCE(p.amount_qar, p.amount)), 0) AS paid
  FROM    public.invoices i
  LEFT    JOIN public.payments p
          ON  p.source_type = 'invoice'
          AND p.source_id   = i.id
          AND p.deleted_at IS NULL
  WHERE   i.direction = 'ar'
  GROUP   BY i.id, i.total_amount
)
UPDATE public.invoices i
SET    paid_amount    = sums.paid,
       payment_status = CASE
         WHEN sums.paid >= sums.total THEN 'paid'
         WHEN sums.paid > 0           THEN 'partially_paid'
         ELSE                              'unpaid'
       END
FROM   sums
WHERE  i.id = sums.invoice_id;

COMMIT;


-- ============================================================
-- Source: 20260627105300_invalidate_sales_pdf_cache.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- One-off cache invalidation after the SO Quotation / AR Invoice PDF redesign
-- (bilingual layout matching the order-confirmation). Existing cached URLs
-- still point at the old visual, so we null them — next "View PDF" / "Download"
-- click regenerates with the new design.
--
-- The cache-invalidation trigger fires on the UPDATE but only zeros the URL,
-- which is exactly what we want. The skip-flag isn't needed here.
-- ─────────────────────────────────────────────────────────────────────────────

UPDATE public.sale_orders
   SET quotation_pdf_url = NULL
 WHERE quotation_pdf_url IS NOT NULL;

UPDATE public.invoices
   SET pdf_url = NULL
 WHERE pdf_url IS NOT NULL
   AND direction = 'ar';


-- ============================================================
-- Source: 20260627106000_invoice_paid_amount_sync.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Keep invoices.paid_amount + payment_status synced with the payments table.
--
-- Two triggers on `payments`:
--
-- 1. BEFORE INSERT — if a payment is being recorded against a sale_order that
--    already has an AR invoice, transparently redirect it to the invoice
--    (source_type='invoice', source_id=<invoice.id>). This means the
--    salesperson can press "Record Payment" on either the SO or the invoice;
--    the data always lands on the invoice.
--
-- 2. AFTER INSERT/UPDATE/DELETE — recompute paid_amount + payment_status on
--    every invoice affected by the change. Catches direct invoice payments,
--    redirected ones, deletions, and rare manual `source_type` rewrites.
--
-- Plus a one-off backfill at the end so SO-00003's existing payment
-- (recorded after INV-00004 was generated) lands on the invoice now.
-- ─────────────────────────────────────────────────────────────────────────────

BEGIN;

-- ── BEFORE-INSERT redirect ──────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.payments_redirect_to_invoice_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  v_invoice_id uuid;
BEGIN
  IF NEW.source_type <> 'sale_order' OR NEW.source_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT id INTO v_invoice_id
  FROM   public.invoices
  WHERE  sale_order_id = NEW.source_id AND direction = 'ar'
  LIMIT  1;
  IF v_invoice_id IS NOT NULL THEN
    NEW.source_type := 'invoice';
    NEW.source_id   := v_invoice_id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_payments_redirect_to_invoice ON public.payments;
CREATE TRIGGER       trg_payments_redirect_to_invoice
  BEFORE INSERT ON public.payments
  FOR EACH ROW
  EXECUTE FUNCTION public.payments_redirect_to_invoice_fn();

-- ── AFTER-write recompute ───────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.invoice_recompute_paid_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  v_invoice_id uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.source_type = 'invoice' THEN v_invoice_id := OLD.source_id; END IF;
  ELSE
    IF NEW.source_type = 'invoice' THEN v_invoice_id := NEW.source_id; END IF;
  END IF;

  IF v_invoice_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  WITH summed AS (
    SELECT COALESCE(SUM(COALESCE(amount_qar, amount)), 0) AS paid
    FROM   public.payments
    WHERE  source_type = 'invoice'
      AND  source_id   = v_invoice_id
      AND  deleted_at IS NULL
  )
  UPDATE public.invoices i
  SET    paid_amount    = summed.paid,
         payment_status = CASE
           WHEN summed.paid >= i.total_amount THEN 'paid'
           WHEN summed.paid > 0               THEN 'partially_paid'
           ELSE                                    'unpaid'
         END
  FROM   summed
  WHERE  i.id = v_invoice_id;

  -- If the prior row pointed to a different invoice (rare: someone moved a
  -- payment from invoice A to invoice B in a single UPDATE), recompute A too.
  IF TG_OP = 'UPDATE'
     AND OLD.source_type = 'invoice'
     AND OLD.source_id <> v_invoice_id THEN
    WITH summed AS (
      SELECT COALESCE(SUM(COALESCE(amount_qar, amount)), 0) AS paid
      FROM   public.payments
      WHERE  source_type = 'invoice'
        AND  source_id   = OLD.source_id
        AND  deleted_at IS NULL
    )
    UPDATE public.invoices i
    SET    paid_amount    = summed.paid,
           payment_status = CASE
             WHEN summed.paid >= i.total_amount THEN 'paid'
             WHEN summed.paid > 0               THEN 'partially_paid'
             ELSE                                    'unpaid'
           END
    FROM   summed
    WHERE  i.id = OLD.source_id;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;

DROP TRIGGER IF EXISTS trg_invoice_recompute_paid ON public.payments;
CREATE TRIGGER       trg_invoice_recompute_paid
  AFTER INSERT OR UPDATE OR DELETE ON public.payments
  FOR EACH ROW
  EXECUTE FUNCTION public.invoice_recompute_paid_fn();

-- ── Backfill: re-point existing SO-linked payments that have an AR invoice ─
UPDATE public.payments p
SET    source_type = 'invoice',
       source_id   = i.id
FROM   public.invoices i
WHERE  p.source_type = 'sale_order'
  AND  p.deleted_at IS NULL
  AND  i.sale_order_id = p.source_id
  AND  i.direction = 'ar';

-- ── Backfill: recompute every AR invoice's paid_amount + status ────────────
WITH sums AS (
  SELECT  i.id                                              AS invoice_id,
          i.total_amount,
          COALESCE(SUM(COALESCE(p.amount_qar, p.amount)), 0) AS paid
  FROM    public.invoices i
  LEFT    JOIN public.payments p
          ON  p.source_type = 'invoice'
          AND p.source_id   = i.id
          AND p.deleted_at IS NULL
  WHERE   i.direction = 'ar'
  GROUP   BY i.id, i.total_amount
)
UPDATE public.invoices i
SET    paid_amount    = sums.paid,
       payment_status = CASE
         WHEN sums.paid >= sums.total_amount THEN 'paid'
         WHEN sums.paid > 0                  THEN 'partially_paid'
         ELSE                                     'unpaid'
       END
FROM   sums
WHERE  i.id = sums.invoice_id;

COMMIT;


-- ============================================================
-- Source: 20260627107000_sync_invoice_id_column.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- `payments` has both `invoice_id` (legacy direct FK) and `source_type`/
-- `source_id` (polymorphic). Some hooks read the legacy column
-- (useCustomerPayments → query .eq('invoice_id', ...)), others read the
-- polymorphic pair. Mirror them so both stay consistent.
--
-- 1. Update the BEFORE-INSERT redirect trigger to also stamp `invoice_id`
--    when redirecting a sale_order payment to its AR invoice.
-- 2. New BEFORE-INSERT/UPDATE trigger that keeps `invoice_id` ↔
--    `source_id` aligned whenever `source_type='invoice'`.
-- 3. Backfill existing rows so anything pointing at an invoice via the
--    polymorphic pair also has its `invoice_id` populated.
-- ─────────────────────────────────────────────────────────────────────────────

BEGIN;

-- 1. Redirect trigger — now also writes the legacy column
CREATE OR REPLACE FUNCTION public.payments_redirect_to_invoice_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  v_invoice_id uuid;
BEGIN
  IF NEW.source_type <> 'sale_order' OR NEW.source_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT id INTO v_invoice_id
  FROM   public.invoices
  WHERE  sale_order_id = NEW.source_id AND direction = 'ar'
  LIMIT  1;
  IF v_invoice_id IS NOT NULL THEN
    NEW.source_type := 'invoice';
    NEW.source_id   := v_invoice_id;
    NEW.invoice_id  := v_invoice_id;        -- keep legacy column aligned
  END IF;
  RETURN NEW;
END;
$$;

-- 2. Sync trigger — fires on every insert / update so the two columns can
--    never drift, no matter which one the caller filled in
CREATE OR REPLACE FUNCTION public.payments_sync_invoice_id_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.source_type = 'invoice' AND NEW.source_id IS NOT NULL THEN
    NEW.invoice_id := NEW.source_id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_payments_sync_invoice_id ON public.payments;
CREATE TRIGGER       trg_payments_sync_invoice_id
  BEFORE INSERT OR UPDATE ON public.payments
  FOR EACH ROW
  EXECUTE FUNCTION public.payments_sync_invoice_id_fn();

-- 3. Backfill
UPDATE public.payments
SET    invoice_id = source_id
WHERE  source_type = 'invoice'
  AND  source_id IS NOT NULL
  AND  (invoice_id IS NULL OR invoice_id <> source_id);

COMMIT;


-- ============================================================
-- Source: 20260627108000_force_pdf_regen_after_cdn_fix.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Force a regeneration of every cached sales PDF.
--
-- The generators now upload with cacheControl=0 and append `?v=<timestamp>` to
-- the persisted public URL, so each regeneration bypasses CDN/browser cache.
-- Without this backfill the previously-stored URLs would keep getting served
-- from the CDN until they expired naturally.
-- ─────────────────────────────────────────────────────────────────────────────

UPDATE public.sale_orders
   SET quotation_pdf_url = NULL
 WHERE quotation_pdf_url IS NOT NULL;

UPDATE public.invoices
   SET pdf_url = NULL
 WHERE pdf_url IS NOT NULL
   AND direction = 'ar';

UPDATE public.credit_notes
   SET pdf_url = NULL
 WHERE pdf_url IS NOT NULL;


-- ============================================================
-- Source: 20260627109000_credit_used_reflects_payments.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Customer-credit usage now reflects payments.
--
-- Old rule (in create_sale_order + resubmit_sale_order):
--     credit_used = SUM(total) for every non-cancelled SO of the customer
-- That counts a fully paid SO at its full total — so the credit limit never
-- frees up after the customer pays. Reported by the user.
--
-- New rule:
--   credit_used = SUM(invoice.total_amount - invoice.paid_amount)
--                   for the customer's AR invoices that aren't cancelled
--               + SUM(sale_order.total_qar)
--                   for the customer's open SOs that have NO invoice yet
--   Excludes a specific SO id when supplied (so the SO being created /
--   resubmitted doesn't double-count itself).
--
-- A new helper `customer_credit_used(customer_id, exclude_so_id)` keeps the
-- formula in one place so both RPCs (and any UI later) read the same answer.
-- ─────────────────────────────────────────────────────────────────────────────

BEGIN;

CREATE OR REPLACE FUNCTION public.customer_credit_used(
  p_customer_id   uuid,
  p_exclude_so_id uuid DEFAULT NULL
) RETURNS NUMERIC
LANGUAGE sql STABLE
SET search_path TO 'public'
AS $$
  WITH invoiced AS (
    SELECT COALESCE(SUM(GREATEST(i.total_amount - COALESCE(i.paid_amount, 0), 0)), 0) AS outstanding
    FROM   invoices i
    WHERE  i.customer_id = p_customer_id
      AND  i.direction   = 'ar'
      AND  COALESCE(i.status, 'draft') <> 'cancelled'
      AND  (p_exclude_so_id IS NULL OR COALESCE(i.sale_order_id, gen_random_uuid()) <> p_exclude_so_id)
  ),
  uninvoiced AS (
    SELECT COALESCE(SUM(so.total * COALESCE(so.exchange_rate, 1)), 0) AS open_total
    FROM   sale_orders so
    LEFT   JOIN invoices i
           ON  i.sale_order_id = so.id
           AND i.direction     = 'ar'
    WHERE  so.customer_id = p_customer_id
      AND  so.status      NOT IN ('cancelled')
      AND  so.deleted_at  IS NULL
      AND  (p_exclude_so_id IS NULL OR so.id <> p_exclude_so_id)
      AND  i.id IS NULL
  )
  SELECT (SELECT outstanding FROM invoiced)
       + (SELECT open_total  FROM uninvoiced);
$$;

REVOKE ALL ON FUNCTION public.customer_credit_used(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.customer_credit_used(uuid, uuid) TO authenticated, service_role;

-- ── create_sale_order — replace the v_open_total block ──────────────────────
CREATE OR REPLACE FUNCTION public.create_sale_order(
  p_customer_id          uuid,
  p_intent               text,
  p_currency             text,
  p_exchange_rate        numeric,
  p_subtotal             numeric,
  p_discount_amount      numeric,
  p_discount_label       text,
  p_discount_type        text,
  p_payment_terms        text,
  p_payment_terms_notes  text,
  p_payment_milestones   jsonb,
  p_delivery_terms       text,
  p_delivery_terms_notes text,
  p_customer_notes       text,
  p_validity_days        integer,
  p_notes                text,
  p_line_items           jsonb,
  p_division_id          uuid
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_customer_type     TEXT;
  v_subtotal          NUMERIC := COALESCE(p_subtotal, 0);
  v_discount_resolved NUMERIC;
  v_total             NUMERIC;
  v_total_qar         NUMERIC;
  v_credit_limit      NUMERIC;
  v_group_name        TEXT;
  v_open_total        NUMERIC;
  v_available         NUMERIC;
  v_so_status         sale_order_status;
  v_so_id             UUID;
  v_profile_id        UUID;
  v_so_number         TEXT;
  v_exceeds_credit    BOOLEAN := false;
  v_has_below_cost    BOOLEAN := false;
  v_below_cost_lines  JSONB := '[]'::jsonb;
  v_line              JSONB;
BEGIN
  SELECT id INTO v_profile_id FROM profiles WHERE auth_user_id = auth.uid();

  v_discount_resolved := COALESCE(p_discount_amount, 0);
  v_total     := v_subtotal - v_discount_resolved;
  v_total_qar := v_total * p_exchange_rate;

  SELECT c.customer_type, cg.credit_limit, cg.name
  INTO   v_customer_type, v_credit_limit, v_group_name
  FROM   customers c
  LEFT JOIN credit_groups cg ON cg.id = c.credit_group_id
  WHERE  c.id = p_customer_id;

  -- ── Margin gate (below-cost) ──────────────────────────────────────────
  SELECT jsonb_agg(jsonb_build_object(
           'item_name',  (li->>'item_name'),
           'unit_price', (li->>'unit_price')::numeric,
           'avg_cost',   COALESCE((li->>'avg_cost')::numeric, 0)
         )) FILTER (WHERE COALESCE((li->>'avg_cost')::numeric, 0) > 0
                       AND (li->>'unit_price')::numeric < COALESCE((li->>'avg_cost')::numeric, 0))
  INTO   v_below_cost_lines
  FROM   jsonb_array_elements(p_line_items) li;

  IF v_below_cost_lines IS NOT NULL AND jsonb_array_length(v_below_cost_lines) > 0 THEN
    v_has_below_cost := true;
  END IF;

  -- ── Credit gate (over limit) — credit customers only
  IF COALESCE(v_customer_type, 'credit') = 'cash' THEN
    v_credit_limit := 0;
    v_group_name   := 'Cash';
    v_open_total   := 0;
    v_available    := 0;
  ELSE
    IF v_credit_limit IS NULL THEN
      RAISE EXCEPTION 'no_credit_group';
    END IF;

    -- New formula: outstanding on AR invoices + uninvoiced open SOs.
    v_open_total := public.customer_credit_used(p_customer_id, NULL);
    v_available  := v_credit_limit - v_open_total;

    IF p_intent = 'confirm' AND v_total_qar > v_available THEN
      v_exceeds_credit := true;
    END IF;
  END IF;

  -- ── Decide SO status
  IF p_intent = 'save_quote' THEN
    v_so_status := 'quotation';
  ELSIF v_exceeds_credit OR v_has_below_cost THEN
    v_so_status := 'pending_approval';
  ELSE
    v_so_status := 'confirmed';
  END IF;

  -- ── Insert SO
  v_so_number := generate_so_id();
  INSERT INTO sale_orders (
    so_number, customer_id, status, currency, exchange_rate,
    subtotal, discount_amount, discount_amount_resolved, discount_label, discount_type,
    total, validity_days, payment_terms, payment_terms_notes, payment_milestones,
    delivery_terms, delivery_terms_notes, customer_notes, notes,
    created_by, division_id
  ) VALUES (
    v_so_number, p_customer_id, v_so_status, p_currency, p_exchange_rate,
    v_subtotal, v_discount_resolved, v_discount_resolved, p_discount_label, p_discount_type,
    v_total, p_validity_days, p_payment_terms, p_payment_terms_notes, p_payment_milestones,
    p_delivery_terms, p_delivery_terms_notes, p_customer_notes, p_notes,
    v_profile_id, p_division_id
  ) RETURNING id INTO v_so_id;

  -- ── Insert lines
  FOR v_line IN SELECT * FROM jsonb_array_elements(p_line_items) LOOP
    INSERT INTO sale_order_lines (
      sale_order_id, item_name, sku, qty, unit, unit_price, total,
      line_type, brand_variant_id, tool_asset_item_id, avg_cost
    ) VALUES (
      v_so_id,
      (v_line->>'item_name'),
      (v_line->>'sku'),
      (v_line->>'qty')::numeric,
      (v_line->>'unit'),
      (v_line->>'unit_price')::numeric,
      (v_line->>'total')::numeric,
      (v_line->>'line_type'),
      NULLIF((v_line->>'brand_variant_id'), '')::uuid,
      NULLIF((v_line->>'tool_asset_item_id'), '')::uuid,
      COALESCE((v_line->>'avg_cost')::numeric, 0)
    );
  END LOOP;

  -- ── Build approval chains
  IF v_exceeds_credit THEN
    PERFORM public.build_sales_approval_chain(
      v_so_id, 'credit',
      jsonb_build_object(
        'available',     GREATEST(v_available, 0),
        'overage',       v_total_qar - v_available,
        'requested_by',  v_profile_id
      )
    );
  END IF;
  IF v_has_below_cost THEN
    PERFORM public.build_sales_approval_chain(
      v_so_id, 'margin',
      jsonb_build_object(
        'lines',         v_below_cost_lines,
        'requested_by',  v_profile_id
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'so_id',          v_so_id,
    'so_number',      v_so_number,
    'status',         v_so_status,
    'credit_limit',   v_credit_limit,
    'group_name',     v_group_name,
    'open_total',     v_open_total,
    'available',      GREATEST(v_available, 0),
    'exceeds_credit', v_exceeds_credit,
    'has_below_cost', v_has_below_cost
  );
END;
$$;

-- ── resubmit_sale_order — same formula change ──────────────────────────────
CREATE OR REPLACE FUNCTION public.resubmit_sale_order(p_so_id uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_so               RECORD;
  v_customer         RECORD;
  v_total_qar        NUMERIC;
  v_open_total       NUMERIC;
  v_available        NUMERIC;
  v_exceeds_credit   BOOLEAN := false;
  v_has_below_cost   BOOLEAN := false;
  v_below_cost_lines JSONB := '[]'::jsonb;
  v_profile_id       uuid;
BEGIN
  SELECT id INTO v_profile_id FROM profiles WHERE auth_user_id = auth.uid();

  SELECT * INTO v_so FROM sale_orders WHERE id = p_so_id;
  IF NOT FOUND OR v_so.status <> 'quotation' THEN
    RAISE EXCEPTION 'SO not resubmittable';
  END IF;

  SELECT c.customer_type, cg.credit_limit
  INTO   v_customer
  FROM   customers c
  LEFT JOIN credit_groups cg ON cg.id = c.credit_group_id
  WHERE  c.id = v_so.customer_id;

  v_total_qar := v_so.total * COALESCE(v_so.exchange_rate, 1);

  SELECT jsonb_agg(jsonb_build_object(
           'item_name', item_name, 'unit_price', unit_price, 'avg_cost', avg_cost
         )) FILTER (WHERE avg_cost > 0 AND unit_price < avg_cost)
  INTO   v_below_cost_lines
  FROM   sale_order_lines WHERE sale_order_id = p_so_id;

  IF v_below_cost_lines IS NOT NULL AND jsonb_array_length(v_below_cost_lines) > 0 THEN
    v_has_below_cost := true;
  END IF;

  IF COALESCE(v_customer.customer_type, 'credit') <> 'cash'
     AND v_customer.credit_limit IS NOT NULL THEN
    -- Exclude THIS SO so we don't double-count it
    v_open_total := public.customer_credit_used(v_so.customer_id, p_so_id);
    v_available  := v_customer.credit_limit - v_open_total;
    IF v_total_qar > v_available THEN v_exceeds_credit := true; END IF;
  END IF;

  IF v_exceeds_credit OR v_has_below_cost THEN
    UPDATE sale_orders SET status = 'pending_approval' WHERE id = p_so_id;
    IF v_exceeds_credit THEN
      PERFORM public.build_sales_approval_chain(
        p_so_id, 'credit',
        jsonb_build_object('available', GREATEST(v_available,0),
                           'overage',   v_total_qar - COALESCE(v_available, 0),
                           'requested_by', v_profile_id)
      );
    END IF;
    IF v_has_below_cost THEN
      PERFORM public.build_sales_approval_chain(
        p_so_id, 'margin',
        jsonb_build_object('lines', v_below_cost_lines, 'requested_by', v_profile_id)
      );
    END IF;
  ELSE
    UPDATE sale_orders SET status = 'confirmed' WHERE id = p_so_id;
  END IF;

  RETURN jsonb_build_object(
    'exceeds_credit', v_exceeds_credit,
    'has_below_cost', v_has_below_cost
  );
END;
$$;

COMMIT;


-- ============================================================
-- Source: 20260627110000_customer_credit_summary_view.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- View: customer_credit_summary
--
-- One row per customer with everything the UI / API needs to render "credit
-- remaining" without computing it client-side. Reads through
-- customer_credit_used() so it stays consistent with the SO-creation gate —
-- pay an invoice, the next read returns the new available number.
--
-- Note: `customers.credit_limit` is a legacy per-customer override that some
-- older rows still use. The credit_groups.credit_limit is the canonical source
-- for credit customers today, so we prefer that and fall back to the legacy
-- column when the customer isn't in a credit group.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE VIEW public.customer_credit_summary AS
SELECT
  c.id                                              AS customer_id,
  c.name                                            AS customer_name,
  c.name_ar                                         AS customer_name_ar,
  c.customer_type                                   AS customer_type,
  c.is_blocked                                      AS is_blocked,
  c.credit_group_id                                 AS credit_group_id,
  cg.name                                           AS credit_group_name,
  -- credit_limit: 0 for cash customers, else group limit, else legacy column
  CASE
    WHEN c.customer_type = 'cash' THEN 0
    WHEN cg.credit_limit IS NOT NULL THEN cg.credit_limit
    ELSE COALESCE(c.credit_limit, 0)
  END                                               AS credit_limit,
  -- live computed used amount via the shared helper
  public.customer_credit_used(c.id, NULL)           AS credit_used,
  -- available = limit - used (never below 0; nothing is negative credit)
  GREATEST(
    CASE
      WHEN c.customer_type = 'cash' THEN 0
      WHEN cg.credit_limit IS NOT NULL THEN cg.credit_limit
      ELSE COALESCE(c.credit_limit, 0)
    END
    - public.customer_credit_used(c.id, NULL),
    0
  )                                                 AS credit_available,
  -- utilization 0..100 (NULL when limit is 0 to avoid divide-by-zero)
  CASE
    WHEN COALESCE(
           CASE WHEN c.customer_type = 'cash' THEN 0
                WHEN cg.credit_limit IS NOT NULL THEN cg.credit_limit
                ELSE COALESCE(c.credit_limit, 0) END,
           0) = 0
      THEN NULL
    ELSE LEAST(
      ROUND(
        public.customer_credit_used(c.id, NULL)
        / NULLIF(CASE
                   WHEN c.customer_type = 'cash' THEN 0
                   WHEN cg.credit_limit IS NOT NULL THEN cg.credit_limit
                   ELSE COALESCE(c.credit_limit, 0)
                 END, 0)
        * 100, 1),
      100
    )
  END                                               AS credit_utilization_pct
FROM   public.customers c
LEFT   JOIN public.credit_groups cg ON cg.id = c.credit_group_id;

COMMENT ON VIEW public.customer_credit_summary IS
  'Live per-customer credit utilization. credit_used is computed from outstanding AR invoices + uninvoiced open SOs; pay an invoice and the row reflects it on the next read.';

GRANT SELECT ON public.customer_credit_summary TO authenticated, service_role;


-- ============================================================
-- Source: 20260627111000_invoice_paid_amount_unify.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Unify the two invoice-payment shapes so `invoices.paid_amount` stays correct
-- (and the credit limit frees up) no matter which button recorded the payment.
--
-- Until now, payments could land in the table in two distinct shapes:
--
--   A. source_type='invoice', source_id=<invoice.id>            — SO/SO-Payments
--      tab path, redirected by trg_payments_redirect_to_invoice
--   B. invoice_id=<invoice.id>, source_type=NULL                — Invoice tab
--      path (useCreateCustomerPayment); legacy customer-payment flow
--
-- The old `invoice_recompute_paid_fn` trigger only watched for shape (A), so
-- shape-(B) payments updated `payment_status` (set client-side) but NEVER
-- updated `paid_amount`. Since `customer_credit_used()` calculates
-- `total_amount - paid_amount`, the customer's credit appeared stuck at fully
-- used after paying through the Invoice tab.
--
-- Fix:
--   1. Extend `invoice_recompute_paid_fn` to also fire on shape-(B) payments
--      and to sum BOTH shapes when recomputing paid_amount.
--   2. Backfill `paid_amount` + `payment_status` for every AR invoice using
--      both shapes so existing customers who already paid have their credit
--      freed immediately.
-- ─────────────────────────────────────────────────────────────────────────────

BEGIN;

CREATE OR REPLACE FUNCTION public.invoice_recompute_paid_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  v_invoice_id     uuid;
  v_old_invoice_id uuid;
BEGIN
  -- Pick the invoice this row points at, regardless of which shape it uses.
  IF TG_OP = 'DELETE' THEN
    IF OLD.source_type = 'invoice' THEN v_invoice_id := OLD.source_id;
    ELSIF OLD.invoice_id IS NOT NULL THEN v_invoice_id := OLD.invoice_id;
    END IF;
  ELSE
    IF NEW.source_type = 'invoice' THEN v_invoice_id := NEW.source_id;
    ELSIF NEW.invoice_id IS NOT NULL THEN v_invoice_id := NEW.invoice_id;
    END IF;
  END IF;

  IF v_invoice_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  WITH summed AS (
    SELECT COALESCE(SUM(COALESCE(amount_qar, amount)), 0) AS paid
    FROM   public.payments
    WHERE  (
             (source_type = 'invoice' AND source_id = v_invoice_id)
             OR invoice_id = v_invoice_id
           )
      AND  deleted_at IS NULL
      AND  direction  = 'incoming'
  )
  UPDATE public.invoices i
  SET    paid_amount    = summed.paid,
         payment_status = CASE
           WHEN summed.paid >= i.total_amount THEN 'paid'
           WHEN summed.paid > 0               THEN 'partially_paid'
           ELSE                                    'unpaid'
         END
  FROM   summed
  WHERE  i.id = v_invoice_id;

  -- UPDATE that moves a payment between invoices: resync the prior invoice too.
  IF TG_OP = 'UPDATE' THEN
    IF OLD.source_type = 'invoice' THEN v_old_invoice_id := OLD.source_id;
    ELSIF OLD.invoice_id IS NOT NULL THEN v_old_invoice_id := OLD.invoice_id;
    END IF;

    IF v_old_invoice_id IS NOT NULL AND v_old_invoice_id <> v_invoice_id THEN
      WITH summed AS (
        SELECT COALESCE(SUM(COALESCE(amount_qar, amount)), 0) AS paid
        FROM   public.payments
        WHERE  (
                 (source_type = 'invoice' AND source_id = v_old_invoice_id)
                 OR invoice_id = v_old_invoice_id
               )
          AND  deleted_at IS NULL
          AND  direction  = 'incoming'
      )
      UPDATE public.invoices i
      SET    paid_amount    = summed.paid,
             payment_status = CASE
               WHEN summed.paid >= i.total_amount THEN 'paid'
               WHEN summed.paid > 0               THEN 'partially_paid'
               ELSE                                    'unpaid'
             END
      FROM   summed
      WHERE  i.id = v_old_invoice_id;
    END IF;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;

-- Trigger definition unchanged; re-pointing to the updated function is enough.
DROP TRIGGER IF EXISTS trg_invoice_recompute_paid ON public.payments;
CREATE TRIGGER       trg_invoice_recompute_paid
  AFTER INSERT OR UPDATE OR DELETE ON public.payments
  FOR EACH ROW
  EXECUTE FUNCTION public.invoice_recompute_paid_fn();

-- ── Backfill: every AR invoice's paid_amount + status from BOTH shapes ──────
WITH sums AS (
  SELECT  i.id                                              AS invoice_id,
          i.total_amount                                    AS total,
          COALESCE(SUM(COALESCE(p.amount_qar, p.amount)), 0) AS paid
  FROM    public.invoices i
  LEFT    JOIN public.payments p
          ON  (
                (p.source_type = 'invoice' AND p.source_id = i.id)
                OR p.invoice_id = i.id
              )
          AND p.deleted_at IS NULL
          AND p.direction  = 'incoming'
  WHERE   i.direction = 'ar'
  GROUP   BY i.id, i.total_amount
)
UPDATE public.invoices i
SET    paid_amount    = sums.paid,
       payment_status = CASE
         WHEN sums.paid >= sums.total THEN 'paid'
         WHEN sums.paid > 0           THEN 'partially_paid'
         ELSE                              'unpaid'
       END
FROM   sums
WHERE  i.id = sums.invoice_id;

COMMIT;


-- ============================================================
-- Source: 20260627112000_rename_approval_tables.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Rename approval-related tables to clearer, scope-honest names.
--
-- Goal: stop using generic names for what are really module-specific tables.
--   approval_chains              → po_approval_chains
--   approval_chain_tiers         → po_approval_chain_tiers
--   approval_requests            → sale_order_approvals
--   workflow_approval_steps      → approval_workflow_steps
--   service_change_requests      → service_edit_requests
--
-- Strategy: real ALTER TABLE RENAME at the storage level (preserves every FK,
-- index, trigger, and RLS policy — those are bound by OID, not by table name).
-- Then create COMPATIBILITY VIEWS with the old names so the ~25+ PL/pgSQL
-- functions that reference these tables in their bodies (sales approval flow,
-- PO chain build, inv-check chain, stock-adjustment chain, service-change
-- workflow, workflow-step admin RPCs, baseline triggers) keep compiling and
-- running without a single change. Updatable simple views translate
-- SELECT/INSERT/UPDATE/DELETE straight through to the underlying renamed
-- table.
--
-- The compat views are intentionally permanent for now — we'll retire them
-- one at a time as each function is touched for unrelated reasons. That keeps
-- the rename non-breaking and reversible.
--
-- Enum renames (approval_type → sales_approval_type) and the source_type
-- column drop are NOT part of this migration. They'd require touching every
-- function signature/body that mentions the enum, so they're deferred until
-- the compat views are dropped.
-- ─────────────────────────────────────────────────────────────────────────────

BEGIN;

-- ── 1. Rename the underlying tables ─────────────────────────────────────────
ALTER TABLE public.approval_chains          RENAME TO po_approval_chains;
ALTER TABLE public.approval_chain_tiers     RENAME TO po_approval_chain_tiers;
ALTER TABLE public.approval_requests        RENAME TO sale_order_approvals;
ALTER TABLE public.workflow_approval_steps  RENAME TO approval_workflow_steps;
ALTER TABLE public.service_change_requests  RENAME TO service_edit_requests;

-- ── 2. Compatibility views: old name → new table ────────────────────────────
-- Simple SELECT * views are updatable in PostgreSQL, so existing functions
-- that INSERT/UPDATE/DELETE through the old name keep working unchanged.
CREATE VIEW public.approval_chains          AS SELECT * FROM public.po_approval_chains;
CREATE VIEW public.approval_chain_tiers     AS SELECT * FROM public.po_approval_chain_tiers;
CREATE VIEW public.approval_requests        AS SELECT * FROM public.sale_order_approvals;
CREATE VIEW public.workflow_approval_steps  AS SELECT * FROM public.approval_workflow_steps;
CREATE VIEW public.service_change_requests  AS SELECT * FROM public.service_edit_requests;

COMMENT ON VIEW public.approval_chains IS
  'Compat alias for po_approval_chains. Retire once every dependent function has been rewritten to use the new name.';
COMMENT ON VIEW public.approval_chain_tiers IS
  'Compat alias for po_approval_chain_tiers. Retire alongside approval_chains.';
COMMENT ON VIEW public.approval_requests IS
  'Compat alias for sale_order_approvals. Retire once every sales-approval function (build/advance/approve/reject/force-approve/log) has been rewritten.';
COMMENT ON VIEW public.workflow_approval_steps IS
  'Compat alias for approval_workflow_steps. Retire once add_workflow_step / add_workflow_step_for_role / update_workflow_step_conditions / archive_workflow_step / toggle_workflow_step / update_workflow_step_role and the chain-builders for PO + inv_check + stock_adj have been rewritten.';
COMMENT ON VIEW public.service_change_requests IS
  'Compat alias for service_edit_requests. Retire once approve/reject/submit/update/withdraw service-change RPCs have been rewritten.';

-- ── 3. Mirror RLS through the views ─────────────────────────────────────────
-- Views don't carry the base table's RLS by default. authenticated users hit
-- the views from PostgREST (Supabase API), so we need them to be readable.
-- Writes through the views still execute against the underlying table and
-- are subject to its RLS — no security regression.
GRANT SELECT, INSERT, UPDATE, DELETE ON public.approval_chains          TO authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.approval_chain_tiers     TO authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.approval_requests        TO authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.approval_workflow_steps  TO authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.workflow_approval_steps  TO authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.service_change_requests  TO authenticated, service_role;

-- New tables — re-grant explicitly (the rename preserves grants, but the new
-- names need to be explicitly callable from the Supabase API namespace).
GRANT SELECT, INSERT, UPDATE, DELETE ON public.po_approval_chains       TO authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.po_approval_chain_tiers  TO authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.sale_order_approvals     TO authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.service_edit_requests    TO authenticated, service_role;

-- ── 4. Notify PostgREST so its schema cache picks up the new names ──────────
NOTIFY pgrst, 'reload schema';

COMMIT;


-- ============================================================
-- Source: 20260627113000_approval_compat_views_security_invoker.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- The five compatibility views added in 20260627112000 (approval_chains,
-- approval_chain_tiers, approval_requests, workflow_approval_steps,
-- service_change_requests) shipped without security_invoker, so they ran as
-- the view owner (postgres) and bypassed the underlying table's RLS. Supabase
-- Studio flagged this with an "UNRESTRICTED" badge.
--
-- Setting security_invoker=true makes each view execute as the calling user,
-- which means SELECT/INSERT/UPDATE/DELETE through the old-name view enforce
-- the SAME RLS policies that protect the renamed underlying table. The badge
-- goes away and the safety net is no longer a security hole.
-- ─────────────────────────────────────────────────────────────────────────────

BEGIN;

ALTER VIEW public.approval_chains          SET (security_invoker = true);
ALTER VIEW public.approval_chain_tiers     SET (security_invoker = true);
ALTER VIEW public.approval_requests        SET (security_invoker = true);
ALTER VIEW public.workflow_approval_steps  SET (security_invoker = true);
ALTER VIEW public.service_change_requests  SET (security_invoker = true);

COMMIT;


-- ============================================================
-- Source: 20260627114000_drop_approval_compat_views.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Retire the compatibility views from 20260627112000.
--
-- That migration renamed five tables and created same-name views so the ~20
-- existing PL/pgSQL functions that referenced the old names kept compiling
-- and running. This migration takes the second step: every dependent function
-- is recreated with the NEW table names, and the compat views are dropped.
-- After this runs, only the four real renamed tables remain
-- (sale_order_approvals, approval_workflow_steps, po_approval_chains,
-- po_approval_chain_tiers, service_edit_requests) — no more aliases.
--
-- Function-by-function rewrite covers:
--   approval_requests        → sale_order_approvals     (8 functions)
--   workflow_approval_steps  → approval_workflow_steps  (9 functions)
--   service_change_requests  → service_edit_requests    (7 functions)
-- (some functions touch more than one of these, so the counts overlap.)
-- ─────────────────────────────────────────────────────────────────────────────

BEGIN;

-- ╔═══════════════════════════════════════════════════════════════════════════╗
-- ║ 1. SALES APPROVAL FAMILY — uses sale_order_approvals                      ║
-- ╚═══════════════════════════════════════════════════════════════════════════╝

-- set_approval_request_decided_at — trigger that stamps decided_at when status
-- moves off 'pending'. Trigger itself was created against approval_requests;
-- we re-attach it to sale_order_approvals below.
CREATE OR REPLACE FUNCTION public.set_approval_request_decided_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.status <> 'pending' AND OLD.status = 'pending' THEN
    NEW.decided_at = now();
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_approval_requests_decided_at ON public.sale_order_approvals;
CREATE TRIGGER trg_approval_requests_decided_at
  BEFORE UPDATE ON public.sale_order_approvals
  FOR EACH ROW EXECUTE FUNCTION public.set_approval_request_decided_at();

-- The generic updated_at trigger was attached to the old name; reattach.
DROP TRIGGER IF EXISTS trg_approval_requests_updated_at ON public.sale_order_approvals;
CREATE TRIGGER trg_approval_requests_updated_at
  BEFORE UPDATE ON public.sale_order_approvals
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- build_sales_approval_chain — parallel-chain version (was 20260627103000)
CREATE OR REPLACE FUNCTION public.build_sales_approval_chain(
  p_so_id          uuid,
  p_approval_type  approval_type,
  p_payload        jsonb
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_workflow    TEXT;
  v_iteration   INT;
  v_step        RECORD;
BEGIN
  v_workflow := CASE p_approval_type
    WHEN 'margin' THEN 'sales_margin'
    WHEN 'credit' THEN 'sales_credit'
  END;

  SELECT COALESCE(MAX(iteration), 0) + 1 INTO v_iteration
  FROM   sale_order_approvals
  WHERE  source_id     = p_so_id
    AND  approval_type = p_approval_type;

  FOR v_step IN
    SELECT was.step_order, cr.name AS role_name
    FROM   approval_workflow_steps was
    JOIN   custom_roles cr ON cr.id = was.role_id
    WHERE  was.workflow   = v_workflow
      AND  was.is_active  = true
      AND  was.archived_at IS NULL
    ORDER  BY was.step_order
  LOOP
    INSERT INTO sale_order_approvals (
      source_type, source_id, approval_type, status,
      requested_by, reason,
      step_role, step_order, is_active, iteration
    ) VALUES (
      'sale_order', p_so_id, p_approval_type, 'pending',
      (p_payload->>'requested_by')::uuid,
      p_payload::text,
      v_step.role_name, v_step.step_order,
      true,
      v_iteration
    );
  END LOOP;
END;
$$;

-- advance_sales_approval — parallel-chain version
CREATE OR REPLACE FUNCTION public.advance_sales_approval(
  p_so_id         uuid,
  p_approval_type approval_type
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_iteration  INT;
  v_all_done   BOOLEAN;
  v_open_other BOOLEAN;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext(p_so_id::text || p_approval_type::text));

  SELECT COALESCE(MAX(iteration), 1) INTO v_iteration
  FROM   sale_order_approvals
  WHERE  source_id = p_so_id AND approval_type = p_approval_type;

  SELECT NOT EXISTS (
    SELECT 1 FROM sale_order_approvals
    WHERE  source_id     = p_so_id
      AND  approval_type = p_approval_type
      AND  iteration     = v_iteration
      AND  status        <> 'approved'
  ) INTO v_all_done;

  IF NOT v_all_done THEN RETURN; END IF;

  SELECT EXISTS (
    SELECT 1 FROM sale_order_approvals
    WHERE  source_id     = p_so_id
      AND  approval_type <> p_approval_type
      AND  status        = 'pending'
  ) INTO v_open_other;

  IF NOT v_open_other THEN
    UPDATE sale_orders SET status = 'confirmed' WHERE id = p_so_id;
  END IF;
END;
$$;

-- approve_sales_request — role+scope guard version (was 20260627100005)
CREATE OR REPLACE FUNCTION public.approve_sales_request(
  p_request_id uuid,
  p_comment    text
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_req         RECORD;
  v_profile_id  uuid;
  v_full_name   TEXT;
  v_scope       TEXT;
BEGIN
  SELECT id, full_name INTO v_profile_id, v_full_name
  FROM   profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT * INTO v_req FROM sale_order_approvals WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND OR v_req.status <> 'pending' OR NOT v_req.is_active THEN
    RAISE EXCEPTION 'Request not actionable';
  END IF;

  v_scope := CASE v_req.approval_type
    WHEN 'margin' THEN 'sales_margin'
    WHEN 'credit' THEN 'sales_credit'
  END;
  IF v_scope IS NULL THEN
    RAISE EXCEPTION 'Unknown sales approval type %', v_req.approval_type;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM   user_custom_roles ucr
    JOIN   custom_roles cr ON cr.id = ucr.role_id
    WHERE  ucr.profile_id        = v_profile_id
      AND  cr.name               = v_req.step_role
      AND  cr.is_approval_slot   = true
      AND  cr.deleted_at         IS NULL
      AND  (ucr.approval_scopes IS NULL
            OR v_scope = ANY(ucr.approval_scopes))
  ) THEN
    RAISE EXCEPTION 'You do not hold the role required for this approval step';
  END IF;

  IF EXISTS (
    SELECT 1 FROM sale_order_approvals
    WHERE  source_id     = v_req.source_id
      AND  approval_type = v_req.approval_type
      AND  iteration     = v_req.iteration
      AND  decided_by    = v_profile_id
      AND  id            <> p_request_id
  ) THEN
    RAISE EXCEPTION 'You have already approved another role on this slip';
  END IF;

  UPDATE sale_order_approvals
  SET    status          = 'approved',
         decided_by      = v_profile_id,
         decided_by_name = v_full_name,
         comment         = p_comment
  WHERE  id = p_request_id;

  PERFORM public.advance_sales_approval(v_req.source_id, v_req.approval_type);
END;
$$;

-- reject_sales_request — role+scope guard version
CREATE OR REPLACE FUNCTION public.reject_sales_request(
  p_request_id uuid,
  p_reason     text
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_req         RECORD;
  v_profile_id  uuid;
  v_full_name   TEXT;
  v_scope       TEXT;
BEGIN
  IF COALESCE(TRIM(p_reason), '') = '' THEN
    RAISE EXCEPTION 'A reason is required to reject';
  END IF;

  SELECT id, full_name INTO v_profile_id, v_full_name
  FROM   profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT * INTO v_req FROM sale_order_approvals WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND OR v_req.status <> 'pending' OR NOT v_req.is_active THEN
    RAISE EXCEPTION 'Request not actionable';
  END IF;

  v_scope := CASE v_req.approval_type
    WHEN 'margin' THEN 'sales_margin'
    WHEN 'credit' THEN 'sales_credit'
  END;
  IF v_scope IS NULL THEN
    RAISE EXCEPTION 'Unknown sales approval type %', v_req.approval_type;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM   user_custom_roles ucr
    JOIN   custom_roles cr ON cr.id = ucr.role_id
    WHERE  ucr.profile_id        = v_profile_id
      AND  cr.name               = v_req.step_role
      AND  cr.is_approval_slot   = true
      AND  cr.deleted_at         IS NULL
      AND  (ucr.approval_scopes IS NULL
            OR v_scope = ANY(ucr.approval_scopes))
  ) THEN
    RAISE EXCEPTION 'You do not hold the role required to reject this approval step';
  END IF;

  UPDATE sale_order_approvals
  SET    status          = 'rejected',
         decided_by      = v_profile_id,
         decided_by_name = v_full_name,
         reason          = p_reason
  WHERE  id = p_request_id;

  UPDATE sale_order_approvals
  SET    status   = 'rejected',
         reason   = 'Cancelled — sibling step rejected'
  WHERE  source_id     = v_req.source_id
    AND  approval_type = v_req.approval_type
    AND  iteration     = v_req.iteration
    AND  status        = 'pending'
    AND  id            <> p_request_id;

  UPDATE sale_orders SET status = 'quotation' WHERE id = v_req.source_id;
END;
$$;

-- force_approve_sales_request — Owner bypass (was 20260627102000)
CREATE OR REPLACE FUNCTION public.force_approve_sales_request(
  p_so_id          uuid,
  p_approval_type  approval_type,
  p_comment        text DEFAULT NULL
) RETURNS INT
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_profile_id  uuid;
  v_full_name   TEXT;
  v_is_owner    BOOLEAN;
  v_iteration   INT;
  v_count       INT;
BEGIN
  SELECT id, full_name INTO v_profile_id, v_full_name
  FROM   profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM   user_custom_roles ucr
    JOIN   custom_roles cr ON cr.id = ucr.role_id
    WHERE  ucr.profile_id      = v_profile_id
      AND  cr.name             = 'Owner'
      AND  cr.is_approval_slot = true
      AND  cr.deleted_at       IS NULL
  ) INTO v_is_owner;
  IF NOT v_is_owner THEN
    RAISE EXCEPTION 'Only users with the Owner role can force-approve';
  END IF;

  SELECT COALESCE(MAX(iteration), 1) INTO v_iteration
  FROM   sale_order_approvals
  WHERE  source_type   = 'sale_order'
    AND  source_id     = p_so_id
    AND  approval_type = p_approval_type;

  UPDATE sale_order_approvals
  SET    status          = 'approved',
         decided_by      = v_profile_id,
         decided_by_name = v_full_name,
         comment         = COALESCE(comment, p_comment),
         force_approved  = true,
         force_comment   = NULLIF(TRIM(COALESCE(p_comment, '')), ''),
         is_active       = true
  WHERE  source_type   = 'sale_order'
    AND  source_id     = p_so_id
    AND  approval_type = p_approval_type
    AND  iteration     = v_iteration
    AND  status        = 'pending';

  GET DIAGNOSTICS v_count = ROW_COUNT;

  IF v_count = 0 THEN
    RAISE EXCEPTION 'No pending steps to force-approve on this slip';
  END IF;

  PERFORM public.advance_sales_approval(p_so_id, p_approval_type);

  RETURN v_count;
END;
$$;

-- log_sales_approval_decision — activity-log trigger (was 20260627105000)
CREATE OR REPLACE FUNCTION public.log_sales_approval_decision()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  v_action  TEXT;
  v_details TEXT;
BEGIN
  IF NEW.source_type <> 'sale_order' THEN RETURN NEW; END IF;
  IF OLD.status = NEW.status      THEN RETURN NEW; END IF;
  IF NEW.status NOT IN ('approved', 'rejected') THEN RETURN NEW; END IF;

  IF NEW.status = 'approved' AND NEW.force_approved THEN
    v_action := format('Sales Approval Force-Approved — %s (%s)',
                       INITCAP(REPLACE(NEW.step_role, '_', ' ')),
                       NEW.approval_type);
  ELSIF NEW.status = 'approved' THEN
    v_action := format('Sales Approval Approved — %s (%s)',
                       INITCAP(REPLACE(NEW.step_role, '_', ' ')),
                       NEW.approval_type);
  ELSE
    v_action := format('Sales Approval Rejected — %s (%s)',
                       INITCAP(REPLACE(NEW.step_role, '_', ' ')),
                       NEW.approval_type);
  END IF;

  v_details := jsonb_build_object(
    'approval_type', NEW.approval_type,
    'step_role',     NEW.step_role,
    'iteration',     NEW.iteration,
    'comment',       NULLIF(NEW.comment, ''),
    'reason',        CASE WHEN NEW.status = 'rejected' THEN NEW.reason ELSE NULL END,
    'force',         NEW.force_approved
  )::text;

  INSERT INTO public.activity_log (
    action, module, entity_type, entity_id,
    performer_name, severity, details
  ) VALUES (
    v_action,
    'sale_orders',
    'sale_order',
    NEW.source_id,
    NEW.decided_by_name,
    CASE
      WHEN NEW.status = 'rejected'        THEN 'warning'
      WHEN NEW.force_approved              THEN 'critical'
      ELSE                                       'info'
    END,
    v_details
  );

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_log_sales_approval_decision ON public.sale_order_approvals;
CREATE TRIGGER trg_log_sales_approval_decision
  AFTER UPDATE ON public.sale_order_approvals
  FOR EACH ROW
  EXECUTE FUNCTION public.log_sales_approval_decision();

-- ╔═══════════════════════════════════════════════════════════════════════════╗
-- ║ 2. WORKFLOW STEP ADMIN — uses approval_workflow_steps                     ║
-- ╚═══════════════════════════════════════════════════════════════════════════╝

-- add_workflow_step — legacy variant (was 20260627100006)
CREATE OR REPLACE FUNCTION public.add_workflow_step(
  p_workflow         text,
  p_role_name        text,
  p_role_desc        text DEFAULT ''::text,
  p_is_conditional   boolean DEFAULT false,
  p_condition_types  text[] DEFAULT '{}'::text[]
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_role_id   UUID;
  v_max_order INT;
  v_step_key  TEXT;
  v_step      approval_workflow_steps;
BEGIN
  IF p_workflow NOT IN ('po','inv_check','stock_adj','sales_margin','sales_credit') THEN
    RAISE EXCEPTION 'Invalid workflow: %', p_workflow;
  END IF;
  IF TRIM(p_role_name) = '' THEN
    RAISE EXCEPTION 'Role name cannot be empty';
  END IF;

  SELECT id INTO v_role_id
  FROM custom_roles
  WHERE name = p_role_name AND deleted_at IS NULL;

  IF v_role_id IS NULL THEN
    INSERT INTO custom_roles (name, description, is_approval_slot, is_system, permissions)
    VALUES (TRIM(p_role_name), NULLIF(TRIM(p_role_desc),''), true, false, '[]'::jsonb)
    RETURNING id INTO v_role_id;
  ELSE
    UPDATE custom_roles SET is_approval_slot = true WHERE id = v_role_id;
  END IF;

  v_step_key := LOWER(REGEXP_REPLACE(TRIM(p_role_name), '\s+', '_', 'g'));

  SELECT COALESCE(MAX(step_order), 0) INTO v_max_order
  FROM approval_workflow_steps
  WHERE workflow = p_workflow AND archived_at IS NULL;

  INSERT INTO approval_workflow_steps (
    workflow, role_id, step_key, step_label, step_order,
    is_conditional, condition_types
  ) VALUES (
    p_workflow, v_role_id, v_step_key, TRIM(p_role_name), v_max_order + 1,
    p_is_conditional, p_condition_types
  )
  RETURNING * INTO v_step;

  RETURN to_jsonb(v_step);
END;
$$;

-- add_workflow_step_for_role — current variant
CREATE OR REPLACE FUNCTION public.add_workflow_step_for_role(
  p_workflow         text,
  p_role_id          uuid,
  p_is_conditional   boolean DEFAULT false,
  p_condition_types  text[] DEFAULT '{}'::text[]
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_role_name TEXT;
  v_max_order INT;
  v_step_key  TEXT;
  v_step      approval_workflow_steps;
BEGIN
  IF p_workflow NOT IN ('po','inv_check','stock_adj','sales_margin','sales_credit') THEN
    RAISE EXCEPTION 'Invalid workflow: %', p_workflow;
  END IF;

  SELECT name INTO v_role_name
  FROM custom_roles
  WHERE id = p_role_id
    AND is_approval_slot = true
    AND deleted_at IS NULL;

  IF v_role_name IS NULL THEN
    RAISE EXCEPTION 'Role not found or is not an approval-slot role';
  END IF;

  IF EXISTS (
    SELECT 1 FROM approval_workflow_steps
    WHERE workflow = p_workflow
      AND role_id  = p_role_id
      AND archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'This role is already a step in the % workflow', p_workflow;
  END IF;

  v_step_key := LOWER(REGEXP_REPLACE(TRIM(v_role_name), '\s+', '_', 'g'));

  IF EXISTS (
    SELECT 1 FROM approval_workflow_steps
    WHERE workflow = p_workflow AND step_key = v_step_key
  ) THEN
    v_step_key := v_step_key || '_' || substr(gen_random_uuid()::text, 1, 6);
  END IF;

  SELECT COALESCE(MAX(step_order), 0) INTO v_max_order
  FROM approval_workflow_steps
  WHERE workflow = p_workflow AND archived_at IS NULL;

  INSERT INTO approval_workflow_steps (
    workflow, role_id, step_key, step_label, step_order,
    is_conditional, condition_types
  ) VALUES (
    p_workflow, p_role_id, v_step_key, v_role_name, v_max_order + 1,
    p_is_conditional, p_condition_types
  )
  RETURNING * INTO v_step;

  RETURN to_jsonb(v_step);
END;
$$;

-- update_workflow_step_conditions (was 20260619120000)
CREATE OR REPLACE FUNCTION public.update_workflow_step_conditions(
  p_step_id         UUID,
  p_is_conditional  BOOLEAN,
  p_condition_types TEXT[]
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  UPDATE approval_workflow_steps
  SET is_conditional  = p_is_conditional,
      condition_types = CASE
        WHEN p_is_conditional THEN COALESCE(p_condition_types, ARRAY[]::TEXT[])
        ELSE ARRAY[]::TEXT[]
      END
  WHERE id = p_step_id AND archived_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Step not found or already archived';
  END IF;
END;
$$;

-- archive_workflow_step (baseline)
CREATE OR REPLACE FUNCTION public.archive_workflow_step(p_step_id uuid, p_profile_id uuid)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_owner BOOLEAN;
BEGIN
  SELECT EXISTS (
    SELECT 1
    FROM user_custom_roles ucr
    JOIN custom_roles cr ON cr.id = ucr.role_id
    WHERE ucr.profile_id = p_profile_id
      AND cr.name = 'Owner'
      AND cr.is_approval_slot = true
      AND cr.deleted_at IS NULL
  ) INTO v_is_owner;

  IF NOT v_is_owner THEN
    RAISE EXCEPTION 'Only owners can archive approval chain steps';
  END IF;

  UPDATE approval_workflow_steps
  SET archived_at = now(), archived_by = p_profile_id
  WHERE id = p_step_id AND archived_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Step not found or already archived';
  END IF;
END;
$$;

-- toggle_workflow_step (baseline)
CREATE OR REPLACE FUNCTION public.toggle_workflow_step(p_step_id uuid, p_active boolean)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  UPDATE approval_workflow_steps
  SET is_active = p_active
  WHERE id = p_step_id AND archived_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Step not found or already archived';
  END IF;
END;
$$;

-- update_workflow_step_role (baseline)
CREATE OR REPLACE FUNCTION public.update_workflow_step_role(p_step_id uuid, p_role_id uuid)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_role_name TEXT;
BEGIN
  SELECT name INTO v_role_name
  FROM custom_roles
  WHERE id = p_role_id
    AND is_approval_slot = true
    AND deleted_at IS NULL;

  IF v_role_name IS NULL THEN
    RAISE EXCEPTION 'Role not found or is not an approval-slot role';
  END IF;

  UPDATE approval_workflow_steps
  SET role_id    = p_role_id,
      step_label = v_role_name
  WHERE id = p_step_id
    AND archived_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Step not found or already archived';
  END IF;
END;
$$;

-- build_inv_check_approval_chain (baseline)
CREATE OR REPLACE FUNCTION public.build_inv_check_approval_chain(
  p_has_damage_or_writeoff boolean DEFAULT false,
  p_has_variance boolean DEFAULT true
) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_steps JSONB;
BEGIN
  IF NOT p_has_variance THEN
    SELECT jsonb_agg(jsonb_build_object(
      'step_order', 1,
      'step_role',  step_key,
      'step_label', step_label
    ))
    INTO v_steps
    FROM approval_workflow_steps
    WHERE workflow = 'inv_check'
      AND step_key = 'inventory_manager'
      AND is_active = true
      AND archived_at IS NULL;

    RETURN COALESCE(v_steps, '[]'::jsonb);
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'step_order', rn,
      'step_role',  step_key,
      'step_label', step_label
    ) ORDER BY rn
  )
  INTO v_steps
  FROM (
    SELECT step_key, step_label,
           ROW_NUMBER() OVER (ORDER BY step_order) AS rn
    FROM   approval_workflow_steps
    WHERE  workflow = 'inv_check'
      AND  is_active = true
      AND  archived_at IS NULL
      AND  (
        NOT is_conditional
        OR (is_conditional AND p_has_damage_or_writeoff)
      )
  ) sub;

  RETURN COALESCE(v_steps, '[]'::jsonb);
END;
$$;

-- create_stock_adjustment_v2 (baseline)
CREATE OR REPLACE FUNCTION public.create_stock_adjustment_v2(
  p_warehouse_id uuid,
  p_brand_variant_id uuid,
  p_adjustment_type text,
  p_qty numeric,
  p_reason text,
  p_notes text,
  p_photo_urls text[],
  p_requested_by uuid,
  p_requested_by_name text
) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id   UUID;
  v_step RECORD;
  v_ord  INT := 0;
BEGIN
  IF p_adjustment_type NOT IN ('increase','decrease','damage','write_off') THEN
    RAISE EXCEPTION 'Invalid adjustment_type: %', p_adjustment_type;
  END IF;
  IF p_qty IS NULL OR p_qty <= 0 THEN
    RAISE EXCEPTION 'qty must be > 0';
  END IF;

  INSERT INTO stock_adjustments (
    warehouse_id, brand_variant_id, adjustment_type, qty,
    reason, notes, photo_urls, status,
    requested_by, requested_by_name, created_by
  ) VALUES (
    p_warehouse_id, p_brand_variant_id, p_adjustment_type, p_qty,
    p_reason, NULLIF(p_notes,''), COALESCE(p_photo_urls, '{}'::text[]),
    'pending_approval',
    p_requested_by, p_requested_by_name, p_requested_by
  )
  RETURNING id INTO v_id;

  FOR v_step IN
    SELECT step_key, step_label, is_conditional, condition_types
    FROM   approval_workflow_steps
    WHERE  workflow = 'stock_adj'
      AND  is_active = true
      AND  archived_at IS NULL
    ORDER BY step_order
  LOOP
    IF v_step.is_conditional AND NOT (p_adjustment_type = ANY(v_step.condition_types)) THEN
      CONTINUE;
    END IF;

    v_ord := v_ord + 1;
    INSERT INTO stock_adjustment_approvals (adjustment_id, step_order, step_role, step_label)
    VALUES (v_id, v_ord, v_step.step_key, v_step.step_label);
  END LOOP;

  IF v_ord = 0 THEN
    RAISE EXCEPTION 'No approval steps configured for stock_adj workflow';
  END IF;

  RETURN v_id;
END;
$$;

-- user_can_action_adjustment_step (baseline)
CREATE OR REPLACE FUNCTION public.user_can_action_adjustment_step(
  p_profile_id uuid,
  p_step_role text,
  p_warehouse_id uuid
) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT
    EXISTS (
      SELECT 1
      FROM   user_custom_roles ucr
      JOIN   custom_roles cr ON cr.id = ucr.role_id
      WHERE  ucr.profile_id = p_profile_id
        AND  cr.name = 'Admin'
        AND  cr.deleted_at IS NULL
    )
    OR (
      p_step_role = 'responsible_person'
      AND EXISTS (
        SELECT 1 FROM warehouse_field_rps
        WHERE  profile_id   = p_profile_id
          AND  warehouse_id = p_warehouse_id
      )
    )
    OR (
      p_step_role <> 'responsible_person'
      AND EXISTS (
        SELECT 1
        FROM   approval_workflow_steps was
        JOIN   user_custom_roles      ucr ON ucr.role_id = was.role_id
        WHERE  was.workflow    = 'stock_adj'
          AND  was.step_key    = p_step_role
          AND  was.archived_at IS NULL
          AND  ucr.profile_id  = p_profile_id
      )
    )
$$;

-- ╔═══════════════════════════════════════════════════════════════════════════╗
-- ║ 3. SERVICE EDIT REQUESTS — uses service_edit_requests                     ║
-- ╚═══════════════════════════════════════════════════════════════════════════╝

-- approve_service_change (baseline) — long body, only table refs change
CREATE OR REPLACE FUNCTION public.approve_service_change(p_request_id uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $_$
DECLARE
  v_profile_id    UUID;
  v_req           RECORD;
  v_live          RECORD;
  v_key           TEXT;
  v_old_val       TEXT;
  v_live_val      TEXT;
  v_new_service_id UUID;
BEGIN
  SELECT id INTO v_profile_id FROM profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated or profile not found';
  END IF;

  IF NOT _user_has_permission(v_profile_id, 'master_data.services.approve') THEN
    RAISE EXCEPTION 'Permission denied: master_data.services.approve required';
  END IF;

  SELECT * INTO v_req FROM service_edit_requests WHERE id = p_request_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Change request not found'; END IF;
  IF v_req.status != 'pending' THEN
    RAISE EXCEPTION 'Request is not pending (status: %)', v_req.status;
  END IF;

  CASE v_req.change_type
    WHEN 'edit' THEN
      SELECT * INTO v_live FROM services WHERE id = v_req.service_id;
      IF NOT FOUND THEN RAISE EXCEPTION 'Service no longer exists'; END IF;

      FOR v_key IN SELECT jsonb_object_keys(v_req.changes) LOOP
        v_old_val := v_req.changes->v_key->>'old';
        EXECUTE format('SELECT ($1.%I)::TEXT', v_key) INTO v_live_val USING v_live;
        IF v_old_val IS DISTINCT FROM v_live_val THEN
          RAISE EXCEPTION 'Stale data: "%" has changed since this request was submitted (expected "%" but found "%"). Reject this request and ask for a new one.',
            v_key, v_old_val, v_live_val;
        END IF;
      END LOOP;

      UPDATE services SET
        name_en           = CASE WHEN v_req.changes ? 'name_en'           THEN v_req.changes->'name_en'->>'new'                   ELSE name_en           END,
        name_ar           = CASE WHEN v_req.changes ? 'name_ar'           THEN v_req.changes->'name_ar'->>'new'                   ELSE name_ar           END,
        code              = CASE WHEN v_req.changes ? 'code'              THEN v_req.changes->'code'->>'new'                      ELSE code              END,
        price             = CASE WHEN v_req.changes ? 'price'             THEN (v_req.changes->'price'->>'new')::NUMERIC           ELSE price             END,
        emergency_price   = CASE WHEN v_req.changes ? 'emergency_price'   THEN (v_req.changes->'emergency_price'->>'new')::NUMERIC ELSE emergency_price   END,
        discount          = CASE WHEN v_req.changes ? 'discount'          THEN (v_req.changes->'discount'->>'new')::NUMERIC        ELSE discount          END,
        duration          = CASE WHEN v_req.changes ? 'duration'          THEN (v_req.changes->'duration'->>'new')::INT            ELSE duration          END,
        warranty          = CASE WHEN v_req.changes ? 'warranty'          THEN (v_req.changes->'warranty'->>'new')::INT            ELSE warranty          END,
        status            = CASE WHEN v_req.changes ? 'status'            THEN (v_req.changes->'status'->>'new')::service_status   ELSE status            END,
        item_kind         = CASE WHEN v_req.changes ? 'item_kind'         THEN v_req.changes->'item_kind'->>'new'                  ELSE item_kind         END,
        pricing_mode      = CASE WHEN v_req.changes ? 'pricing_mode'      THEN v_req.changes->'pricing_mode'->>'new'               ELSE pricing_mode      END,
        discount_scope    = CASE WHEN v_req.changes ? 'discount_scope'    THEN v_req.changes->'discount_scope'->>'new'             ELSE discount_scope    END,
        invoice_text_en   = CASE WHEN v_req.changes ? 'invoice_text_en'   THEN v_req.changes->'invoice_text_en'->>'new'            ELSE invoice_text_en   END,
        invoice_text_ar   = CASE WHEN v_req.changes ? 'invoice_text_ar'   THEN v_req.changes->'invoice_text_ar'->>'new'            ELSE invoice_text_ar   END,
        catalog_image_url = CASE WHEN v_req.changes ? 'catalog_image_url' THEN v_req.changes->'catalog_image_url'->>'new'          ELSE catalog_image_url END,
        updated_at        = now()
      WHERE id = v_req.service_id;

    WHEN 'add' THEN
      v_new_service_id := gen_random_uuid();
      BEGIN
        INSERT INTO services (
          id, parent_id, tree_type, sort_order, division,
          name_en, name_ar, code,
          price, emergency_price, duration, warranty,
          status, category, service_type, contract_type,
          item_kind, pricing_mode, discount_scope,
          invoice_text_en, invoice_text_ar, photo_requirement
        ) VALUES (
          v_new_service_id,
          (v_req.changes->'parent_id'->>'new')::UUID,
          v_req.changes->'tree_type'->>'new',
          0,
          v_req.division,
          v_req.changes->'name_en'->>'new',
          v_req.changes->'name_ar'->>'new',
          v_req.changes->'code'->>'new',
          (v_req.changes->'price'->>'new')::NUMERIC,
          (v_req.changes->'emergency_price'->>'new')::NUMERIC,
          (v_req.changes->'duration'->>'new')::INT,
          (v_req.changes->'warranty'->>'new')::INT,
          COALESCE(v_req.changes->'status'->>'new', 'active')::service_status,
          CASE WHEN v_req.changes ? 'category' AND v_req.changes->'category'->>'new' IS NOT NULL
               THEN (v_req.changes->'category'->>'new')::service_category
               ELSE NULL END,
          CASE WHEN v_req.changes ? 'service_type' AND v_req.changes->'service_type'->>'new' IS NOT NULL
               THEN (v_req.changes->'service_type'->>'new')::service_type
               ELSE NULL END,
          CASE WHEN v_req.changes ? 'contract_type' AND v_req.changes->'contract_type'->>'new' IS NOT NULL
               THEN (v_req.changes->'contract_type'->>'new')::contract_type
               ELSE NULL END,
          v_req.changes->'item_kind'->>'new',
          v_req.changes->'pricing_mode'->>'new',
          v_req.changes->'discount_scope'->>'new',
          v_req.changes->'invoice_text_en'->>'new',
          v_req.changes->'invoice_text_ar'->>'new',
          v_req.changes->'photo_requirement'->>'new'
        );
      EXCEPTION WHEN unique_violation THEN
        RAISE EXCEPTION 'A service with this name already exists in this division. Reject this request instead.';
      END;
      UPDATE service_edit_requests SET service_id = v_new_service_id WHERE id = p_request_id;

    WHEN 'delete' THEN
      IF EXISTS (
        SELECT 1 FROM order_services os
        JOIN orders o ON o.id = os.order_id
        WHERE os.service_id = v_req.service_id
          AND o.status NOT IN ('completed', 'cancelled')
          AND o.deleted_at IS NULL
      ) THEN
        RAISE EXCEPTION 'Cannot delete: service has active orders. Reject this request instead.';
      END IF;
      UPDATE services
      SET deleted_at = now(), status = 'inactive'::service_status, updated_at = now()
      WHERE id = v_req.service_id;

  END CASE;

  UPDATE service_edit_requests
  SET status = 'approved', reviewed_by = v_profile_id, reviewed_at = now(), updated_at = now()
  WHERE id = p_request_id;

  RETURN jsonb_build_object('ok', true, 'service_id', COALESCE(v_new_service_id, v_req.service_id));
END;
$_$;

-- reject_service_change (baseline)
CREATE OR REPLACE FUNCTION public.reject_service_change(p_request_id uuid, p_reason text)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_profile_id UUID;
BEGIN
  SELECT id INTO v_profile_id FROM profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated or profile not found';
  END IF;

  IF NOT _user_has_permission(v_profile_id, 'master_data.services.approve') THEN
    RAISE EXCEPTION 'Permission denied: master_data.services.approve required';
  END IF;

  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'Rejection reason is required';
  END IF;

  UPDATE service_edit_requests
  SET
    status           = 'rejected',
    reviewed_by      = v_profile_id,
    reviewed_at      = now(),
    rejection_reason = trim(p_reason),
    updated_at       = now()
  WHERE id = p_request_id AND status = 'pending';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Request not found or not pending';
  END IF;

  RETURN jsonb_build_object('ok', true);
END;
$$;

-- submit_service_change (baseline) — large body, only INSERT INTO service_change_requests changed
CREATE OR REPLACE FUNCTION public.submit_service_change(p_payload jsonb)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_profile_id     UUID;
  v_has_approve    BOOLEAN;
  v_has_manage     BOOLEAN;
  v_service_id     UUID;
  v_change_type    service_change_type;
  v_changes        JSONB;
  v_division       TEXT[];
  v_tree_type      TEXT;
  v_parent_id      UUID;
  v_has_pending    BOOLEAN;
  v_new_id         UUID;
  v_needs_approval BOOLEAN := false;
  v_key            TEXT;
  v_approval_fields TEXT[] := ARRAY['name_en', 'name_ar', 'price', 'emergency_price', 'status'];
BEGIN
  SELECT id INTO v_profile_id FROM profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated or profile not found';
  END IF;

  v_has_approve := _user_has_permission(v_profile_id, 'master_data.services.approve');
  v_has_manage  := _user_has_permission(v_profile_id, 'master_data.services.manage');

  IF NOT v_has_manage THEN
    RAISE EXCEPTION 'Permission denied: master_data.services.manage required';
  END IF;

  v_service_id  := (p_payload->>'service_id')::UUID;
  v_change_type := (p_payload->>'change_type')::service_change_type;
  v_changes     := p_payload->'changes';
  v_tree_type   := p_payload->>'tree_type';
  v_parent_id   := (p_payload->>'parent_id')::UUID;

  SELECT COALESCE(array_agg(elem::TEXT), '{}')
  INTO v_division
  FROM jsonb_array_elements_text(p_payload->'division') AS elem;

  IF v_change_type IN ('add', 'delete') THEN
    v_needs_approval := true;
  ELSIF v_change_type = 'edit' THEN
    FOR v_key IN SELECT jsonb_object_keys(v_changes) LOOP
      IF v_key = ANY(v_approval_fields) THEN
        v_needs_approval := true;
        EXIT;
      END IF;
    END LOOP;
  END IF;

  IF v_has_approve OR NOT v_needs_approval THEN
    CASE v_change_type
      WHEN 'add' THEN
        v_new_id := gen_random_uuid();
        INSERT INTO services (
          id, parent_id, tree_type, sort_order, division,
          name_en, name_ar, code, legacy_service_id,
          price, emergency_price, discount, price_unit,
          duration, warranty, status, category, service_type, contract_type,
          item_kind, pricing_mode, discount_scope,
          invoice_text_en, invoice_text_ar, photo_requirement,
          catalog_image_url, brands_supported, includes_notes,
          spare_parts, qc_checklist, instructions, reminder_days,
          booking_time_matrix, inventory_items, components, qc_items
        ) VALUES (
          v_new_id, v_parent_id, v_tree_type, 0, v_division,
          v_changes->'name_en'->>'new',
          v_changes->'name_ar'->>'new',
          v_changes->'code'->>'new',
          v_changes->'legacy_service_id'->>'new',
          (v_changes->'price'->>'new')::NUMERIC,
          (v_changes->'emergency_price'->>'new')::NUMERIC,
          (v_changes->'discount'->>'new')::NUMERIC,
          v_changes->'price_unit'->>'new',
          (v_changes->'duration'->>'new')::INT,
          (v_changes->'warranty'->>'new')::INT,
          COALESCE(v_changes->'status'->>'new', 'active')::service_status,
          CASE WHEN v_changes ? 'category' AND v_changes->'category'->>'new' IS NOT NULL
               THEN (v_changes->'category'->>'new')::service_category
               ELSE NULL END,
          CASE WHEN v_changes ? 'service_type' AND v_changes->'service_type'->>'new' IS NOT NULL
               THEN (v_changes->'service_type'->>'new')::service_type
               ELSE NULL END,
          CASE WHEN v_changes ? 'contract_type' AND v_changes->'contract_type'->>'new' IS NOT NULL
               THEN (v_changes->'contract_type'->>'new')::contract_type
               ELSE NULL END,
          v_changes->'item_kind'->>'new',
          v_changes->'pricing_mode'->>'new',
          v_changes->'discount_scope'->>'new',
          v_changes->'invoice_text_en'->>'new',
          v_changes->'invoice_text_ar'->>'new',
          v_changes->'photo_requirement'->>'new',
          v_changes->'catalog_image_url'->>'new',
          COALESCE((v_changes->'brands_supported'->>'new')::INT, 0),
          COALESCE((v_changes->'includes_notes'->>'new')::BOOLEAN, false),
          COALESCE((v_changes->'spare_parts'->>'new')::BOOLEAN, false),
          COALESCE((v_changes->'qc_checklist'->>'new')::BOOLEAN, false),
          COALESCE((v_changes->'instructions'->>'new')::BOOLEAN, false),
          (v_changes->'reminder_days'->>'new')::INT,
          CASE WHEN v_changes ? 'booking_time_matrix' THEN v_changes->'booking_time_matrix'->'new' ELSE NULL END,
          CASE WHEN v_changes ? 'inventory_items'     THEN v_changes->'inventory_items'->'new'     ELSE NULL END,
          CASE WHEN v_changes ? 'components'          THEN v_changes->'components'->'new'          ELSE NULL END,
          CASE WHEN v_changes ? 'qc_items'            THEN v_changes->'qc_items'->'new'            ELSE NULL END
        );
        v_service_id := v_new_id;

      WHEN 'edit' THEN
        UPDATE services SET
          name_en           = CASE WHEN v_changes ? 'name_en'           THEN v_changes->'name_en'->>'new'                    ELSE name_en           END,
          name_ar           = CASE WHEN v_changes ? 'name_ar'           THEN v_changes->'name_ar'->>'new'                    ELSE name_ar           END,
          code              = CASE WHEN v_changes ? 'code'              THEN v_changes->'code'->>'new'                       ELSE code              END,
          legacy_service_id = CASE WHEN v_changes ? 'legacy_service_id' THEN v_changes->'legacy_service_id'->>'new'          ELSE legacy_service_id END,
          price             = CASE WHEN v_changes ? 'price'             THEN (v_changes->'price'->>'new')::NUMERIC            ELSE price             END,
          emergency_price   = CASE WHEN v_changes ? 'emergency_price'   THEN (v_changes->'emergency_price'->>'new')::NUMERIC  ELSE emergency_price   END,
          discount          = CASE WHEN v_changes ? 'discount'          THEN (v_changes->'discount'->>'new')::NUMERIC         ELSE discount          END,
          price_unit        = CASE WHEN v_changes ? 'price_unit'        THEN v_changes->'price_unit'->>'new'                  ELSE price_unit        END,
          duration          = CASE WHEN v_changes ? 'duration'          THEN (v_changes->'duration'->>'new')::INT             ELSE duration          END,
          warranty          = CASE WHEN v_changes ? 'warranty'          THEN (v_changes->'warranty'->>'new')::INT             ELSE warranty          END,
          status            = CASE WHEN v_changes ? 'status'            THEN (v_changes->'status'->>'new')::service_status    ELSE status            END,
          service_type      = CASE WHEN v_changes ? 'service_type'      THEN (v_changes->'service_type'->>'new')::service_type ELSE service_type     END,
          contract_type     = CASE WHEN v_changes ? 'contract_type'     THEN
                                CASE WHEN v_changes->'contract_type'->>'new' IS NOT NULL
                                     THEN (v_changes->'contract_type'->>'new')::contract_type
                                     ELSE NULL END                                                                            ELSE contract_type     END,
          item_kind         = CASE WHEN v_changes ? 'item_kind'         THEN v_changes->'item_kind'->>'new'                   ELSE item_kind         END,
          pricing_mode      = CASE WHEN v_changes ? 'pricing_mode'      THEN v_changes->'pricing_mode'->>'new'                ELSE pricing_mode      END,
          discount_scope    = CASE WHEN v_changes ? 'discount_scope'    THEN v_changes->'discount_scope'->>'new'              ELSE discount_scope    END,
          invoice_text_en   = CASE WHEN v_changes ? 'invoice_text_en'   THEN v_changes->'invoice_text_en'->>'new'             ELSE invoice_text_en   END,
          invoice_text_ar   = CASE WHEN v_changes ? 'invoice_text_ar'   THEN v_changes->'invoice_text_ar'->>'new'             ELSE invoice_text_ar   END,
          photo_requirement = CASE WHEN v_changes ? 'photo_requirement' THEN v_changes->'photo_requirement'->>'new'           ELSE photo_requirement END,
          catalog_image_url = CASE WHEN v_changes ? 'catalog_image_url' THEN v_changes->'catalog_image_url'->>'new'           ELSE catalog_image_url END,
          brands_supported  = CASE WHEN v_changes ? 'brands_supported'  THEN (v_changes->'brands_supported'->>'new')::INT  ELSE brands_supported  END,
          includes_notes    = CASE WHEN v_changes ? 'includes_notes'    THEN (v_changes->'includes_notes'->>'new')::BOOLEAN    ELSE includes_notes    END,
          spare_parts       = CASE WHEN v_changes ? 'spare_parts'       THEN (v_changes->'spare_parts'->>'new')::BOOLEAN       ELSE spare_parts       END,
          qc_checklist      = CASE WHEN v_changes ? 'qc_checklist'      THEN (v_changes->'qc_checklist'->>'new')::BOOLEAN      ELSE qc_checklist      END,
          instructions      = CASE WHEN v_changes ? 'instructions'      THEN (v_changes->'instructions'->>'new')::BOOLEAN      ELSE instructions      END,
          reminder_days     = CASE WHEN v_changes ? 'reminder_days'     THEN (v_changes->'reminder_days'->>'new')::INT         ELSE reminder_days     END,
          updated_at        = now()
        WHERE id = v_service_id AND deleted_at IS NULL;

      WHEN 'delete' THEN
        IF EXISTS (
          SELECT 1 FROM order_services os
          JOIN orders o ON o.id = os.order_id
          WHERE os.service_id = v_service_id
            AND o.status NOT IN ('completed', 'cancelled')
            AND o.deleted_at IS NULL
        ) THEN
          RAISE EXCEPTION 'Cannot delete: service has active orders';
        END IF;
        UPDATE services
        SET deleted_at = now(), status = 'inactive'::service_status, updated_at = now()
        WHERE id = v_service_id AND deleted_at IS NULL;

    END CASE;

    INSERT INTO activity_log (action, module, entity_type, entity_id, details)
    VALUES (
      'services/service-' || v_change_type || 'd',
      'services',
      'service',
      v_service_id,
      jsonb_build_object('change_type', v_change_type, 'applied_by', v_profile_id)::TEXT
    );

    RETURN jsonb_build_object('action', 'applied', 'id', v_service_id);

  ELSE
    IF v_service_id IS NOT NULL THEN
      SELECT has_pending_change INTO v_has_pending FROM services WHERE id = v_service_id;
      IF v_has_pending THEN
        RAISE EXCEPTION 'This service already has a pending change awaiting approval';
      END IF;
    END IF;

    INSERT INTO service_edit_requests (service_id, division, change_type, changes, requested_by)
    VALUES (v_service_id, v_division, v_change_type, v_changes, v_profile_id)
    RETURNING id INTO v_new_id;

    RETURN jsonb_build_object('action', 'pending', 'id', v_new_id);
  END IF;
END;
$$;

-- update_pending_service_change (baseline)
CREATE OR REPLACE FUNCTION public.update_pending_service_change(
  p_request_id uuid,
  p_new_changes jsonb
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_profile_id UUID;
  v_req        RECORD;
BEGIN
  SELECT id INTO v_profile_id FROM profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated or profile not found';
  END IF;

  SELECT * INTO v_req FROM service_edit_requests WHERE id = p_request_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Request not found'; END IF;
  IF v_req.requested_by != v_profile_id THEN
    RAISE EXCEPTION 'Only the requester can update this request';
  END IF;
  IF v_req.status != 'pending' THEN
    RAISE EXCEPTION 'Request is not pending (status: %)', v_req.status;
  END IF;

  UPDATE service_edit_requests
  SET changes = p_new_changes, updated_at = now()
  WHERE id = p_request_id;

  RETURN jsonb_build_object('ok', true);
END;
$$;

-- withdraw_service_change (baseline)
CREATE OR REPLACE FUNCTION public.withdraw_service_change(p_request_id uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_profile_id UUID;
  v_req        RECORD;
BEGIN
  SELECT id INTO v_profile_id FROM profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated or profile not found';
  END IF;

  SELECT * INTO v_req FROM service_edit_requests WHERE id = p_request_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Request not found'; END IF;
  IF v_req.requested_by != v_profile_id THEN
    RAISE EXCEPTION 'Only the requester can withdraw this request';
  END IF;
  IF v_req.status != 'pending' THEN
    RAISE EXCEPTION 'Request is not pending (status: %)', v_req.status;
  END IF;

  DELETE FROM service_edit_requests WHERE id = p_request_id;

  RETURN jsonb_build_object('ok', true);
END;
$$;

-- sync_service_pending_lock (baseline trigger fn)
CREATE OR REPLACE FUNCTION public.sync_service_pending_lock()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  target_service_id UUID;
BEGIN
  target_service_id := COALESCE(NEW.service_id, OLD.service_id);
  IF target_service_id IS NULL THEN
    RETURN NULL;
  END IF;
  UPDATE services
  SET has_pending_change = EXISTS (
    SELECT 1 FROM service_edit_requests
    WHERE service_id = target_service_id AND status = 'pending'
  )
  WHERE id = target_service_id;
  RETURN NULL;
END;
$$;

-- auto_reject_pending_on_service_delete (baseline trigger fn)
CREATE OR REPLACE FUNCTION public.auto_reject_pending_on_service_delete()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN
    UPDATE service_edit_requests
    SET status = 'rejected',
        rejection_reason = 'Service was deleted',
        reviewed_at = now(),
        updated_at = now()
    WHERE service_id = NEW.id AND status = 'pending';
  END IF;
  RETURN NEW;
END;
$$;

