-- ║ 4. Drop the compatibility views                                           ║
-- ╚═══════════════════════════════════════════════════════════════════════════╝

DROP VIEW IF EXISTS public.approval_requests;
DROP VIEW IF EXISTS public.workflow_approval_steps;
DROP VIEW IF EXISTS public.approval_chains;
DROP VIEW IF EXISTS public.approval_chain_tiers;
DROP VIEW IF EXISTS public.service_change_requests;

-- Tell PostgREST to reload its schema cache so the API stops advertising the
-- old names.
NOTIFY pgrst, 'reload schema';

COMMIT;


-- ============================================================
-- Source: 20260627115000_rename_divisions_to_company_divisions.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Rename divisions → company_divisions to make the name self-explanatory: a
-- division is owned by a company. The legacy `divisions` name is ambiguous
-- enough that newcomers often confuse it with company-wide settings.
--
-- Same staged pattern as the approval-tables rename (20260627112000):
--
--   1. ALTER TABLE RENAME (preserves every FK, index, trigger, RLS policy
--      because they're bound by OID, not table name).
--   2. CREATE VIEW with the old name pointing at the new table, marked
--      security_invoker so RLS on the underlying table still applies.
--      This keeps every PL/pgSQL function that still references the old
--      name compiling and running without an immediate rewrite.
--   3. Same treatment for user_divisions → user_company_divisions so the
--      junction table is consistent with its parent.
--
-- A follow-up migration will rewrite the ~25 dependent functions to use the
-- new names and drop the compat views.
-- ─────────────────────────────────────────────────────────────────────────────

BEGIN;

-- ── 1. Rename the underlying tables ─────────────────────────────────────────
ALTER TABLE public.divisions       RENAME TO company_divisions;
ALTER TABLE public.user_divisions  RENAME TO user_company_divisions;

-- ── 2. Compatibility views: old name → new table ────────────────────────────
CREATE VIEW public.divisions      WITH (security_invoker = true) AS
  SELECT * FROM public.company_divisions;

CREATE VIEW public.user_divisions WITH (security_invoker = true) AS
  SELECT * FROM public.user_company_divisions;

COMMENT ON VIEW public.divisions IS
  'Compat alias for company_divisions. Retire once every dependent PL/pgSQL function has been rewritten to use the new name.';
COMMENT ON VIEW public.user_divisions IS
  'Compat alias for user_company_divisions. Retire alongside divisions.';

-- ── 3. Grants — views need their own grants ────────────────────────────────
GRANT SELECT, INSERT, UPDATE, DELETE ON public.divisions               TO authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.user_divisions          TO authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.company_divisions       TO authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.user_company_divisions  TO authenticated, service_role;

-- ── 4. Reload PostgREST schema cache ───────────────────────────────────────
NOTIFY pgrst, 'reload schema';

COMMIT;


-- ============================================================
-- Source: 20260627116000_drop_divisions_compat_views.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Retire the divisions / user_divisions compatibility views from
-- 20260627115000.
--
-- Only 3 PL/pgSQL functions still reference the old names in their bodies
-- (everything else was either app code we already updated, or other
-- views/functions that are OID-bound to the renamed underlying tables and
-- therefore unaffected). Recreate the 3 with the new names, then drop the
-- two compat views.
--
--   custom_access_token_hook     — Supabase Auth claims hook
--   get_customer_pending_balances — pending-payments RPC
--   is_contract_visible          — contracts RLS helper
--
-- The dependent views (calendar_visits, v_team_monthly_overtime) keep working
-- because PostgreSQL stores view dependencies by OID, not by name: when we
-- renamed `divisions` → `company_divisions`, the OID was preserved, so
-- existing views' SELECTs still resolve to the same table.
-- ─────────────────────────────────────────────────────────────────────────────

BEGIN;

-- ── 1. custom_access_token_hook ─────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.custom_access_token_hook(event jsonb)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_type    TEXT;
  v_division_ids UUID[];
  claims         JSONB;
BEGIN
  SELECT
    CASE
      WHEN bool_or(cr.name = 'Owner')            THEN 'owner'
      WHEN bool_or(cr.name = 'Accountant')        THEN 'accountant'
      WHEN bool_or(cr.name = 'Purchase Manager') THEN 'purchase_manager'
      WHEN bool_or(cr.name = 'Employee')          THEN 'employee'
      ELSE 'employee'
    END,
    ARRAY_AGG(DISTINCT ud.division_id) FILTER (WHERE ud.division_id IS NOT NULL)
  INTO   v_user_type, v_division_ids
  FROM   profiles p
  LEFT JOIN user_custom_roles      ucr ON ucr.profile_id = p.id
  LEFT JOIN custom_roles           cr  ON cr.id          = ucr.role_id
                                       AND cr.is_approval_slot = true
                                       AND cr.deleted_at IS NULL
  LEFT JOIN user_company_divisions ud  ON ud.profile_id  = p.id
  WHERE  p.auth_user_id = (event ->> 'user_id')::UUID
  GROUP BY p.id;

  claims := event -> 'claims';
  claims := jsonb_set(claims, '{user_type}',    to_jsonb(COALESCE(v_user_type, 'employee')));
  claims := jsonb_set(claims, '{division_ids}', to_jsonb(COALESCE(v_division_ids, '{}'::UUID[])));

  RETURN jsonb_set(event, '{claims}', claims);
END;
$$;

-- ── 2. get_customer_pending_balances ────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.get_customer_pending_balances()
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_agg(to_jsonb(grouped))
  INTO result
  FROM (
    SELECT
      c.id                                        AS customer_id,
      c.name                                      AS customer_name,
      (
        SELECT COALESCE(
                 jsonb_agg(
                   jsonb_build_object(
                     'id',         cp.id,
                     'phone',      cp.phone,
                     'is_primary', cp.is_primary,
                     'label',      cp.label
                   )
                   ORDER BY cp.is_primary DESC, cp.created_at ASC
                 ),
                 '[]'::jsonb
               )
        FROM   customer_phones cp
        WHERE  cp.customer_id = c.id
      )                                           AS phones,
      i.division_id,
      d.name                                      AS division_name,
      SUM(COALESCE(i.total_amount, 0) - COALESCE(i.paid_amount, 0))
                                                  AS total_pending,
      COUNT(i.id)                                 AS invoice_count,
      COUNT(i.id) FILTER (WHERE i.payment_status = 'overdue')
                                                  AS overdue_count,
      jsonb_agg(
        jsonb_build_object(
          'id',             i.id,
          'invoice_id',     i.invoice_id,
          'phone_id',       i.phone_id,
          'division_id',    i.division_id,
          'division_name',  d.name,
          'source_type',    i.source::text,
          'source_id',      i.source_id,
          'source_label',   i.source_label,
          'issued_date',    i.issued_date,
          'due_date',       i.due_date,
          'total_amount',   i.total_amount,
          'paid_amount',    COALESCE(i.paid_amount, 0),
          'payment_status', i.payment_status
        )
        ORDER BY i.due_date ASC
      )                                           AS invoices
    FROM   invoices i
    JOIN   customers c          ON c.id = i.customer_id
    LEFT JOIN company_divisions d ON d.id = i.division_id
    WHERE  i.direction = 'ar'
      AND  i.status NOT IN ('void', 'cancelled')
      AND  i.payment_status NOT IN ('paid')
      AND  (COALESCE(i.total_amount, 0) - COALESCE(i.paid_amount, 0)) > 0
    GROUP BY c.id, c.name, i.division_id, d.name
    ORDER BY total_pending DESC
  ) grouped;

  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;

-- ── 3. is_contract_visible ──────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.is_contract_visible(p_contract_id uuid)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT (
    -- (a) System Admin role
    EXISTS (
      SELECT 1
      FROM profiles p
      JOIN user_custom_roles ucr ON ucr.profile_id = p.id
      JOIN custom_roles cr ON cr.id = ucr.role_id AND cr.deleted_at IS NULL
      WHERE p.auth_user_id = auth.uid()
        AND cr.is_system = true
    )
    OR
    -- (b) Super-viewer (owner / accountant) via JWT
    (auth.jwt() ->> 'user_type') IN ('owner', 'accountant')
    OR
    -- (c) Has any contracts permission AND division overlap
    EXISTS (
      SELECT 1
      FROM contracts c
      JOIN profiles p ON p.auth_user_id = auth.uid()
      JOIN user_custom_roles      ucr ON ucr.profile_id = p.id
      JOIN custom_roles           cr  ON cr.id = ucr.role_id AND cr.deleted_at IS NULL
      JOIN user_company_divisions ud  ON ud.profile_id = p.id
      JOIN company_divisions      d   ON d.id = ud.division_id
      WHERE c.id = p_contract_id
        AND d.slug = ANY(c.divisions)
        AND (
          'contracts.quotations.view'   = ANY(cr.permissions) OR
          'contracts.quotations.manage' = ANY(cr.permissions) OR
          'contracts.live.view'         = ANY(cr.permissions) OR
          'contracts.live.manage'       = ANY(cr.permissions) OR
          'contracts.activate'          = ANY(cr.permissions)
        )
    )
    OR
    -- (d) Legacy JWT-based division match
    EXISTS (
      SELECT 1
      FROM contracts c
      JOIN company_divisions d ON d.slug = ANY(c.divisions)
      WHERE c.id = p_contract_id
        AND d.id = ANY(
          ARRAY(
            SELECT jsonb_array_elements_text(auth.jwt() -> 'division_ids')
          )::UUID[]
        )
    )
  );
$$;

-- ── 4. Drop the compatibility views ─────────────────────────────────────────
DROP VIEW IF EXISTS public.user_divisions;
DROP VIEW IF EXISTS public.divisions;

NOTIFY pgrst, 'reload schema';

COMMIT;


-- ============================================================
-- Source: 20260627117000_custom_roles_is_field_rp.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Promote "Field RP" from a hardcoded role name to a role-level toggle,
-- mirroring how `is_approval_slot` works.
--
-- Before: useFieldRPCandidates queried `custom_roles.name = 'field_rp'`. Only
-- the one role with that exact name qualified. Renaming it or having multiple
-- roles serve the same purpose (e.g. "Warehouse Manager" who is also a Field
-- RP) was impossible.
--
-- After: any custom_role with `is_field_rp = true` qualifies. Multiple roles
-- can be flagged. The role's name becomes informational.
--
-- The legacy `field_rp` role is auto-flagged so existing assignments continue
-- to surface as Field RP candidates without manual intervention.
-- ─────────────────────────────────────────────────────────────────────────────

BEGIN;

ALTER TABLE public.custom_roles
  ADD COLUMN IF NOT EXISTS is_field_rp boolean NOT NULL DEFAULT false;

COMMENT ON COLUMN public.custom_roles.is_field_rp IS
  'When TRUE, users holding this role appear as Field RP candidates in the Warehouse dialog. Mirrors is_approval_slot. Any role can be flagged; the legacy "field_rp" name is no longer special.';

-- Backfill: keep the existing field_rp role's behaviour
UPDATE public.custom_roles
SET    is_field_rp = true
WHERE  name = 'field_rp'
  AND  deleted_at IS NULL;

NOTIFY pgrst, 'reload schema';

COMMIT;


-- ============================================================
-- Source: 20260627118000_reason_list_categories.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Promote reason-list categories from a hardcoded TS array (9 values) to a
-- managed DB table. Admins can now add / rename / soft-delete categories
-- from the Reason Lists page.
--
-- Design:
--   - reason_list_categories holds the catalog (one row per category).
--   - reason_lists.category stays as a text slug for backward compatibility
--     (every existing consumer reads `category` directly, e.g.
--     useReasonLists('cancellation')). We add a FK-by-slug constraint via a
--     CHECK trigger so dropping a category fails noisily if reasons still
--     reference it.
--
-- The 9 hardcoded slugs are seeded so existing dialogs (cancel, void,
-- refund, adjustment, etc.) keep working without changes.
-- ─────────────────────────────────────────────────────────────────────────────

BEGIN;

CREATE TABLE IF NOT EXISTS public.reason_list_categories (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug        text NOT NULL UNIQUE
              CHECK (slug ~ '^[a-z][a-z0-9_]*$'),
  label       text NOT NULL,
  sort_order  integer NOT NULL DEFAULT 0,
  active      boolean NOT NULL DEFAULT true,
  deleted_at  timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE public.reason_list_categories IS
  'Catalog of valid `reason_lists.category` slugs. Editable from Master Data > Reason Lists.';

ALTER TABLE public.reason_list_categories ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Authenticated can read reason_list_categories"
  ON public.reason_list_categories FOR SELECT TO authenticated USING (true);

CREATE POLICY "Admins can manage reason_list_categories"
  ON public.reason_list_categories FOR ALL TO authenticated
  USING (true) WITH CHECK (true);

GRANT SELECT, INSERT, UPDATE, DELETE ON public.reason_list_categories
  TO authenticated, service_role;

-- ── Seed the 9 historical slugs so nothing breaks ──────────────────────────
INSERT INTO public.reason_list_categories (slug, label, sort_order) VALUES
  ('cancellation', 'Cancellation', 10),
  ('return',       'Return',       20),
  ('adjustment',   'Adjustment',   30),
  ('credit_note',  'Credit Note',  40),
  ('refund',       'Refund',       50),
  ('discount',     'Discount',     60),
  ('complaint',    'Complaint',    70),
  ('reschedule',   'Reschedule',   80),
  ('void',         'Void',         90)
ON CONFLICT (slug) DO NOTHING;

-- ── Integrity trigger: prevent inserting a reason for an unknown category ──
CREATE OR REPLACE FUNCTION public.reason_lists_category_must_exist()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.reason_list_categories
    WHERE slug = NEW.category AND deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Unknown reason category: %. Add it to reason_list_categories first.', NEW.category
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_reason_lists_category_must_exist ON public.reason_lists;
CREATE TRIGGER trg_reason_lists_category_must_exist
  BEFORE INSERT OR UPDATE OF category ON public.reason_lists
  FOR EACH ROW
  EXECUTE FUNCTION public.reason_lists_category_must_exist();

-- ── Integrity trigger: prevent deleting a category that has reasons ────────
CREATE OR REPLACE FUNCTION public.reason_list_categories_no_orphan_delete()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  v_count INTEGER;
BEGIN
  -- Hard delete blocked when reasons exist; soft delete still works because
  -- it's an UPDATE not a DELETE, and reasons can also be soft-archived
  -- separately by toggling reason_lists.active.
  SELECT COUNT(*) INTO v_count
  FROM   public.reason_lists
  WHERE  category = OLD.slug AND deleted_at IS NULL;

  IF v_count > 0 THEN
    RAISE EXCEPTION 'Cannot delete category "%": % active reason(s) still reference it. Soft-delete (set deleted_at) or move the reasons first.',
      OLD.slug, v_count
      USING ERRCODE = '23503';
  END IF;
  RETURN OLD;
END;
$$;

DROP TRIGGER IF EXISTS trg_reason_list_categories_no_orphan_delete ON public.reason_list_categories;
CREATE TRIGGER trg_reason_list_categories_no_orphan_delete
  BEFORE DELETE ON public.reason_list_categories
  FOR EACH ROW
  EXECUTE FUNCTION public.reason_list_categories_no_orphan_delete();

NOTIFY pgrst, 'reload schema';

COMMIT;


-- ============================================================
-- Source: 20260627119000_credit_group_approval_workflow.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Credit Group assignment approval workflow.
--
-- Today: changing a customer's credit_group_id is a direct UPDATE — anyone
-- with master_data.customers.change_credit_group permission can move a
-- customer onto any credit group instantly.
--
-- New: assigning a credit group with a NON-ZERO credit_limit triggers a
-- 3-step approval chain (Purchase Manager → Accountant → Owner). The
-- customer's credit_group_id only flips after the chain fully approves.
-- On reject, the customer stays on whichever group they were on before.
--
-- Reuses the same shape as sale_order_approvals: one request row +
-- per-step rows in customer_credit_group_approvals. Owner step runs in
-- parallel (any-owner-approves).
--
-- Requires the 3 credit docs (CR + Establishment ID + Signed Credit Form)
-- to be uploaded on the customer before submit_credit_group_change accepts
-- the request.
-- ─────────────────────────────────────────────────────────────────────────────

BEGIN;

-- ── 1. Tables ───────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.customer_credit_group_requests (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  customer_id           uuid NOT NULL REFERENCES public.customers(id) ON DELETE CASCADE,
  requested_group_id    uuid NOT NULL REFERENCES public.credit_groups(id),
  previous_group_id     uuid          REFERENCES public.credit_groups(id),
  status                text NOT NULL DEFAULT 'pending'
                        CHECK (status IN ('pending', 'approved', 'rejected', 'cancelled')),
  requested_by          uuid REFERENCES public.profiles(id),
  decided_by            uuid REFERENCES public.profiles(id),
  decided_at            timestamptz,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS ccgr_customer_pending_idx
  ON public.customer_credit_group_requests (customer_id)
  WHERE status = 'pending';

ALTER TABLE public.customer_credit_group_requests ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Authenticated can read credit-group requests"
  ON public.customer_credit_group_requests FOR SELECT TO authenticated USING (true);

GRANT SELECT ON public.customer_credit_group_requests TO authenticated, service_role;

DROP TRIGGER IF EXISTS trg_ccgr_updated_at ON public.customer_credit_group_requests;
CREATE TRIGGER trg_ccgr_updated_at
  BEFORE UPDATE ON public.customer_credit_group_requests
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TABLE IF NOT EXISTS public.customer_credit_group_approvals (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  request_id      uuid NOT NULL REFERENCES public.customer_credit_group_requests(id) ON DELETE CASCADE,
  step_role       text NOT NULL,
  step_order      integer NOT NULL,
  status          text NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending', 'approved', 'rejected')),
  decided_by      uuid REFERENCES public.profiles(id),
  decided_by_name text,
  decided_at      timestamptz,
  is_active       boolean NOT NULL DEFAULT true,
  iteration       integer NOT NULL DEFAULT 1,
  comment         text,
  reason          text,
  created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS ccga_request_idx
  ON public.customer_credit_group_approvals (request_id);
CREATE INDEX IF NOT EXISTS ccga_pending_idx
  ON public.customer_credit_group_approvals (request_id) WHERE status = 'pending' AND is_active;

ALTER TABLE public.customer_credit_group_approvals ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Authenticated can read credit-group approval slips"
  ON public.customer_credit_group_approvals FOR SELECT TO authenticated USING (true);

GRANT SELECT ON public.customer_credit_group_approvals TO authenticated, service_role;

-- ── 2. Wire 'credit_group' into the existing approval_workflow_steps table ──

ALTER TABLE public.approval_workflow_steps
  DROP CONSTRAINT IF EXISTS workflow_approval_steps_workflow_check;
ALTER TABLE public.approval_workflow_steps
  ADD CONSTRAINT workflow_approval_steps_workflow_check
  CHECK (workflow = ANY (ARRAY[
    'po','inv_check','stock_adj','sales_margin','sales_credit','credit_group'
  ]));

-- Seed the 3 default steps if none exist. Roles must already exist as
-- approval-slot custom_roles — we look them up by name. If a role is
-- missing, the step is skipped silently and the admin can add it from the
-- Approval Workflows page later.
DO $$
DECLARE
  v_role_id     uuid;
  v_role_name   text;
  v_step_order  integer := 0;
BEGIN
  IF EXISTS (SELECT 1 FROM public.approval_workflow_steps WHERE workflow = 'credit_group') THEN
    RETURN;
  END IF;
  FOREACH v_role_name IN ARRAY ARRAY['Purchase Manager', 'Accountant', 'Owner']
  LOOP
    SELECT id INTO v_role_id FROM public.custom_roles
      WHERE name = v_role_name
        AND COALESCE(is_approval_slot, false) = true
        AND deleted_at IS NULL
      LIMIT 1;
    IF v_role_id IS NULL THEN CONTINUE; END IF;
    v_step_order := v_step_order + 1;
    INSERT INTO public.approval_workflow_steps (
      workflow, role_id, step_key, step_label, step_order,
      is_conditional, condition_types, is_active
    ) VALUES (
      'credit_group', v_role_id,
      LOWER(REPLACE(v_role_name, ' ', '_')), v_role_name, v_step_order,
      false, ARRAY[]::text[], true
    );
  END LOOP;
END $$;

-- Also extend the user-role assignment scopes so admins can scope a role
-- holder to credit-group approvals specifically (alongside sales_margin /
-- sales_credit).
ALTER TABLE public.user_custom_roles
  DROP CONSTRAINT IF EXISTS user_custom_roles_approval_scopes_chk;
ALTER TABLE public.user_custom_roles
  ADD CONSTRAINT user_custom_roles_approval_scopes_chk
  CHECK (
    approval_scopes IS NULL
    OR approval_scopes <@ ARRAY['po','inv_check','stock_adj','sales_margin','sales_credit','credit_group']::text[]
  );

-- ── 3. RPC: submit_credit_group_change ──────────────────────────────────────
-- Validates: 3 docs uploaded; new group has non-zero limit; no existing
-- pending request. Creates the request + per-step approval rows.

CREATE OR REPLACE FUNCTION public.submit_credit_group_change(
  p_customer_id        uuid,
  p_requested_group_id uuid
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_customer        RECORD;
  v_new_group       RECORD;
  v_profile_id      uuid;
  v_request_id      uuid;
  v_step            RECORD;
  v_step_count      integer := 0;
BEGIN
  SELECT id INTO v_profile_id FROM profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT id, credit_group_id,
         cr_url,
         establishment_id_url,
         signed_credit_form_url
    INTO v_customer
  FROM customers
  WHERE id = p_customer_id;
  IF v_customer.id IS NULL THEN
    RAISE EXCEPTION 'Customer not found';
  END IF;

  SELECT id, name, credit_limit INTO v_new_group
  FROM credit_groups WHERE id = p_requested_group_id;
  IF v_new_group.id IS NULL THEN
    RAISE EXCEPTION 'Credit group not found';
  END IF;

  -- Trigger gate: only fire approval for non-zero limit groups
  IF COALESCE(v_new_group.credit_limit, 0) = 0 THEN
    RAISE EXCEPTION 'Approval only required for credit groups with a non-zero limit. Assign this group directly.';
  END IF;

  -- No-op guard
  IF v_customer.credit_group_id = p_requested_group_id THEN
    RAISE EXCEPTION 'Customer is already on this credit group';
  END IF;

  -- Doc gate: all 3 must be uploaded
  IF v_customer.cr_url IS NULL
     OR v_customer.establishment_id_url IS NULL
     OR v_customer.signed_credit_form_url IS NULL THEN
    RAISE EXCEPTION 'Upload all 3 required docs first (CR, Establishment ID, Signed Credit Form)'
      USING ERRCODE = 'P0001';
  END IF;

  -- One-active-request guard
  IF EXISTS (
    SELECT 1 FROM customer_credit_group_requests
    WHERE customer_id = p_customer_id AND status = 'pending'
  ) THEN
    RAISE EXCEPTION 'There is already a pending credit-group change for this customer';
  END IF;

  -- Create the request
  INSERT INTO customer_credit_group_requests (
    customer_id, requested_group_id, previous_group_id, status, requested_by
  ) VALUES (
    p_customer_id, p_requested_group_id, v_customer.credit_group_id, 'pending', v_profile_id
  )
  RETURNING id INTO v_request_id;

  -- Build the chain
  FOR v_step IN
    SELECT was.step_order, cr.name AS role_name
    FROM   approval_workflow_steps was
    JOIN   custom_roles            cr ON cr.id = was.role_id
    WHERE  was.workflow    = 'credit_group'
      AND  was.is_active   = true
      AND  was.archived_at IS NULL
    ORDER BY was.step_order
  LOOP
    INSERT INTO customer_credit_group_approvals (
      request_id, step_role, step_order, status, is_active, iteration
    ) VALUES (
      v_request_id, v_step.role_name, v_step.step_order, 'pending', true, 1
    );
    v_step_count := v_step_count + 1;
  END LOOP;

  IF v_step_count = 0 THEN
    -- No steps configured → auto-approve (admin hasn't configured the workflow yet)
    UPDATE customers SET credit_group_id = p_requested_group_id WHERE id = p_customer_id;
    UPDATE customer_credit_group_requests
      SET status = 'approved', decided_by = v_profile_id, decided_at = now()
      WHERE id = v_request_id;
  END IF;

  -- Activity log
  INSERT INTO public.activity_log (action, module, entity_type, entity_id, performer_name, severity, details)
  VALUES (
    'Credit Group Change Requested',
    'customers',
    'customer',
    p_customer_id,
    (SELECT full_name FROM profiles WHERE id = v_profile_id),
    'info',
    jsonb_build_object(
      'request_id',       v_request_id,
      'requested_group',  v_new_group.name,
      'previous_group_id',v_customer.credit_group_id,
      'auto_approved',    v_step_count = 0
    )::text
  );

  RETURN jsonb_build_object(
    'request_id',  v_request_id,
    'step_count',  v_step_count,
    'status',      CASE WHEN v_step_count = 0 THEN 'approved' ELSE 'pending' END
  );
END;
$$;

REVOKE ALL ON FUNCTION public.submit_credit_group_change(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_credit_group_change(uuid, uuid) TO authenticated;

-- ── 4. RPC: approve_credit_group_change ─────────────────────────────────────

CREATE OR REPLACE FUNCTION public.approve_credit_group_change(
  p_approval_id uuid,
  p_comment     text DEFAULT NULL
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_row            RECORD;
  v_request        RECORD;
  v_profile_id     uuid;
  v_full_name      TEXT;
  v_all_done       BOOLEAN;
BEGIN
  SELECT id, full_name INTO v_profile_id, v_full_name
  FROM   profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT * INTO v_row FROM customer_credit_group_approvals
    WHERE id = p_approval_id FOR UPDATE;
  IF NOT FOUND OR v_row.status <> 'pending' OR NOT v_row.is_active THEN
    RAISE EXCEPTION 'Approval step not actionable';
  END IF;

  -- Role+scope guard
  IF NOT EXISTS (
    SELECT 1
    FROM   user_custom_roles ucr
    JOIN   custom_roles cr ON cr.id = ucr.role_id
    WHERE  ucr.profile_id        = v_profile_id
      AND  cr.name               = v_row.step_role
      AND  cr.is_approval_slot   = true
      AND  cr.deleted_at         IS NULL
      AND  (ucr.approval_scopes IS NULL
            OR 'credit_group' = ANY(ucr.approval_scopes))
  ) THEN
    RAISE EXCEPTION 'You do not hold the role required for this approval step';
  END IF;

  -- Four-eyes
  IF EXISTS (
    SELECT 1 FROM customer_credit_group_approvals
    WHERE  request_id  = v_row.request_id
      AND  iteration   = v_row.iteration
      AND  decided_by  = v_profile_id
      AND  id          <> p_approval_id
  ) THEN
    RAISE EXCEPTION 'You have already actioned another step on this request';
  END IF;

  UPDATE customer_credit_group_approvals
  SET    status          = 'approved',
         decided_by      = v_profile_id,
         decided_by_name = v_full_name,
         decided_at      = now(),
         comment         = p_comment
  WHERE  id = p_approval_id;

  -- Has every step in this iteration been approved?
  SELECT NOT EXISTS (
    SELECT 1 FROM customer_credit_group_approvals
    WHERE  request_id  = v_row.request_id
      AND  iteration   = v_row.iteration
      AND  status     <> 'approved'
  ) INTO v_all_done;

  IF v_all_done THEN
    SELECT * INTO v_request FROM customer_credit_group_requests
      WHERE id = v_row.request_id FOR UPDATE;

    UPDATE customers
       SET credit_group_id = v_request.requested_group_id
     WHERE id = v_request.customer_id;

    UPDATE customer_credit_group_requests
       SET status     = 'approved',
           decided_by = v_profile_id,
           decided_at = now()
     WHERE id = v_request.id;

    INSERT INTO public.activity_log (action, module, entity_type, entity_id, performer_name, severity, details)
    VALUES (
      'Credit Group Change Approved',
      'customers',
      'customer',
      v_request.customer_id,
      v_full_name,
      'info',
      jsonb_build_object('request_id', v_request.id)::text
    );
  END IF;
END;
$$;

REVOKE ALL ON FUNCTION public.approve_credit_group_change(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.approve_credit_group_change(uuid, text) TO authenticated;

-- ── 5. RPC: reject_credit_group_change ──────────────────────────────────────

CREATE OR REPLACE FUNCTION public.reject_credit_group_change(
  p_approval_id uuid,
  p_reason      text
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_row         RECORD;
  v_profile_id  uuid;
  v_full_name   TEXT;
BEGIN
  IF COALESCE(TRIM(p_reason), '') = '' THEN
    RAISE EXCEPTION 'A reason is required to reject';
  END IF;

  SELECT id, full_name INTO v_profile_id, v_full_name
  FROM   profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT * INTO v_row FROM customer_credit_group_approvals
    WHERE id = p_approval_id FOR UPDATE;
  IF NOT FOUND OR v_row.status <> 'pending' OR NOT v_row.is_active THEN
    RAISE EXCEPTION 'Approval step not actionable';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM   user_custom_roles ucr
    JOIN   custom_roles cr ON cr.id = ucr.role_id
    WHERE  ucr.profile_id        = v_profile_id
      AND  cr.name               = v_row.step_role
      AND  cr.is_approval_slot   = true
      AND  cr.deleted_at         IS NULL
      AND  (ucr.approval_scopes IS NULL
            OR 'credit_group' = ANY(ucr.approval_scopes))
  ) THEN
    RAISE EXCEPTION 'You do not hold the role required to reject this step';
  END IF;

  -- Reject this step
  UPDATE customer_credit_group_approvals
  SET    status          = 'rejected',
         decided_by      = v_profile_id,
         decided_by_name = v_full_name,
         decided_at      = now(),
         reason          = p_reason
  WHERE  id = p_approval_id;

  -- Cancel sibling pending steps in same iteration
  UPDATE customer_credit_group_approvals
  SET    status = 'rejected',
         reason = 'Cancelled — sibling step rejected'
  WHERE  request_id = v_row.request_id
    AND  iteration  = v_row.iteration
    AND  status     = 'pending'
    AND  id        <> p_approval_id;

  -- Close the parent request (customer's credit_group stays untouched)
  UPDATE customer_credit_group_requests
  SET    status     = 'rejected',
         decided_by = v_profile_id,
         decided_at = now()
  WHERE  id = v_row.request_id;

  INSERT INTO public.activity_log (action, module, entity_type, entity_id, performer_name, severity, details)
  SELECT
    'Credit Group Change Rejected',
    'customers',
    'customer',
    r.customer_id,
    v_full_name,
    'warning',
    jsonb_build_object('request_id', r.id, 'step_role', v_row.step_role, 'reason', p_reason)::text
  FROM customer_credit_group_requests r WHERE r.id = v_row.request_id;
END;
$$;

REVOKE ALL ON FUNCTION public.reject_credit_group_change(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.reject_credit_group_change(uuid, text) TO authenticated;

NOTIFY pgrst, 'reload schema';

COMMIT;


-- ============================================================
-- Source: 20260627120000_widen_workflow_allowlist_for_credit_group.sql
-- ============================================================
-- Widen the hardcoded workflow allow-list in add_workflow_step /
-- add_workflow_step_for_role to include 'credit_group'.
--
-- The CHECK constraint on approval_workflow_steps.workflow was widened by
-- 20260627119000_credit_group_approval_workflow.sql, but the two RPCs that
-- create new steps carry their own NOT IN guard list and still rejected
-- 'credit_group' with "Invalid workflow: credit_group" when an admin tried
-- to edit the chain from the Approval Workflows page.
BEGIN;

-- ─── add_workflow_step (legacy variant — takes role NAME) ───────────────────
CREATE OR REPLACE FUNCTION public.add_workflow_step(
  p_workflow         text,
  p_role_name        text,
  p_role_desc        text DEFAULT ''::text,
  p_is_conditional   boolean DEFAULT false,
  p_condition_types  text[] DEFAULT '{}'::text[]
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_role_id   UUID;
  v_max_order INT;
  v_step_key  TEXT;
  v_step      approval_workflow_steps;
BEGIN
  IF p_workflow NOT IN ('po','inv_check','stock_adj','sales_margin','sales_credit','credit_group') THEN
    RAISE EXCEPTION 'Invalid workflow: %', p_workflow;
  END IF;
  IF TRIM(p_role_name) = '' THEN
    RAISE EXCEPTION 'Role name cannot be empty';
  END IF;

  SELECT id INTO v_role_id
  FROM custom_roles
  WHERE name = p_role_name AND deleted_at IS NULL;

  IF v_role_id IS NULL THEN
    INSERT INTO custom_roles (name, description, is_approval_slot, is_system, permissions)
    VALUES (TRIM(p_role_name), NULLIF(TRIM(p_role_desc),''), true, false, '[]'::jsonb)
    RETURNING id INTO v_role_id;
  ELSE
    UPDATE custom_roles SET is_approval_slot = true WHERE id = v_role_id;
  END IF;

  v_step_key := LOWER(REGEXP_REPLACE(TRIM(p_role_name), '\s+', '_', 'g'));

  SELECT COALESCE(MAX(step_order), 0) INTO v_max_order
  FROM approval_workflow_steps
  WHERE workflow = p_workflow AND archived_at IS NULL;

  INSERT INTO approval_workflow_steps (
    workflow, role_id, step_key, step_label, step_order,
    is_conditional, condition_types
  ) VALUES (
    p_workflow, v_role_id, v_step_key, TRIM(p_role_name), v_max_order + 1,
    p_is_conditional, p_condition_types
  )
  RETURNING * INTO v_step;

  RETURN to_jsonb(v_step);
END;
$$;

-- ─── add_workflow_step_for_role (current variant — takes role UUID) ─────────
CREATE OR REPLACE FUNCTION public.add_workflow_step_for_role(
  p_workflow         text,
  p_role_id          uuid,
  p_is_conditional   boolean DEFAULT false,
  p_condition_types  text[] DEFAULT '{}'::text[]
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_role_name TEXT;
  v_max_order INT;
  v_step_key  TEXT;
  v_step      approval_workflow_steps;
BEGIN
  IF p_workflow NOT IN ('po','inv_check','stock_adj','sales_margin','sales_credit','credit_group') THEN
    RAISE EXCEPTION 'Invalid workflow: %', p_workflow;
  END IF;

  SELECT name INTO v_role_name
  FROM custom_roles
  WHERE id = p_role_id
    AND is_approval_slot = true
    AND deleted_at IS NULL;

  IF v_role_name IS NULL THEN
    RAISE EXCEPTION 'Role not found or is not an approval-slot role';
  END IF;

  IF EXISTS (
    SELECT 1 FROM approval_workflow_steps
    WHERE workflow = p_workflow
      AND role_id  = p_role_id
      AND archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'This role is already a step in the % workflow', p_workflow;
  END IF;

  v_step_key := LOWER(REGEXP_REPLACE(TRIM(v_role_name), '\s+', '_', 'g'));

  IF EXISTS (
    SELECT 1 FROM approval_workflow_steps
    WHERE workflow = p_workflow AND step_key = v_step_key
  ) THEN
    v_step_key := v_step_key || '_' || substr(gen_random_uuid()::text, 1, 6);
  END IF;

  SELECT COALESCE(MAX(step_order), 0) INTO v_max_order
  FROM approval_workflow_steps
  WHERE workflow = p_workflow AND archived_at IS NULL;

  INSERT INTO approval_workflow_steps (
    workflow, role_id, step_key, step_label, step_order,
    is_conditional, condition_types
  ) VALUES (
    p_workflow, p_role_id, v_step_key, v_role_name, v_max_order + 1,
    p_is_conditional, p_condition_types
  )
  RETURNING * INTO v_step;

  RETURN to_jsonb(v_step);
END;
$$;

COMMIT;


-- ============================================================
-- Source: 20260627121000_force_approve_credit_group.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Force-approve support for the credit-group approval workflow.
--
-- Mirrors the PO + SO force-approve pattern: only an Owner can bypass the
-- pending chain. Already-approved steps keep their original attribution
-- (decided_by / decided_at) so the audit trail stays honest — only the
-- remaining pending+active rows in the current iteration get force_approved.
--
-- Adds two columns to customer_credit_group_approvals (force_approved,
-- force_comment) and the RPC force_approve_credit_group_change(request_id,
-- comment). When the last pending step is force-cleared, the customer's
-- credit_group_id flips to the requested group and the parent request is
-- marked 'approved' — same terminal state as a normal chain completion.
-- ─────────────────────────────────────────────────────────────────────────────

BEGIN;

-- ── 1. Force-approval columns on the chain-slip table ───────────────────────
ALTER TABLE public.customer_credit_group_approvals
  ADD COLUMN IF NOT EXISTS force_approved boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS force_comment  text;

-- ── 2. RPC: force_approve_credit_group_change ───────────────────────────────
CREATE OR REPLACE FUNCTION public.force_approve_credit_group_change(
  p_request_id uuid,
  p_comment    text DEFAULT NULL
) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_profile_id   uuid;
  v_full_name    TEXT;
  v_is_owner     BOOLEAN;
  v_request      RECORD;
  v_iteration    INT;
  v_count        INT;
BEGIN
  SELECT id, full_name INTO v_profile_id, v_full_name
  FROM   profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  -- Owner-only gate (same as PO + SO force-approve)
  SELECT EXISTS (
    SELECT 1
    FROM   user_custom_roles ucr
    JOIN   custom_roles cr ON cr.id = ucr.role_id
    WHERE  ucr.profile_id      = v_profile_id
      AND  cr.name             = 'Owner'
      AND  cr.is_approval_slot = true
      AND  cr.deleted_at       IS NULL
  ) INTO v_is_owner;
  IF NOT v_is_owner THEN
    RAISE EXCEPTION 'Only users with the Owner role can force-approve';
  END IF;

  SELECT * INTO v_request FROM customer_credit_group_requests
    WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Credit-group request not found';
  END IF;
  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'Request is no longer pending (status: %)', v_request.status;
  END IF;

  -- Current iteration
  SELECT COALESCE(MAX(iteration), 1) INTO v_iteration
  FROM   customer_credit_group_approvals
  WHERE  request_id = p_request_id;

  -- Force-approve every pending+active step in the current iteration.
  -- Already-approved rows are NOT touched — the original approver keeps
  -- their decided_by / decided_at attribution. force_approved=true marks
  -- the bypassed rows so the activity log + chain badge can distinguish.
  UPDATE customer_credit_group_approvals
  SET    status          = 'approved',
         decided_by      = v_profile_id,
         decided_by_name = v_full_name,
         decided_at      = now(),
         force_approved  = true,
         force_comment   = NULLIF(TRIM(COALESCE(p_comment, '')), ''),
         comment         = COALESCE(comment, p_comment)
  WHERE  request_id = p_request_id
    AND  iteration  = v_iteration
    AND  status     = 'pending'
    AND  is_active  = true;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  IF v_count = 0 THEN
    RAISE EXCEPTION 'No pending steps to force-approve on this request';
  END IF;

  -- Iteration is now fully cleared → flip the customer's group + close request.
  UPDATE customers
     SET credit_group_id = v_request.requested_group_id
   WHERE id = v_request.customer_id;

  UPDATE customer_credit_group_requests
     SET status     = 'approved',
         decided_by = v_profile_id,
         decided_at = now()
   WHERE id = p_request_id;

  INSERT INTO public.activity_log (
    action, module, entity_type, entity_id, performer_name, severity, details
  ) VALUES (
    'Credit Group Change Force-Approved',
    'customers',
    'customer',
    v_request.customer_id,
    v_full_name,
    'critical',
    jsonb_build_object(
      'request_id',     v_request.id,
      'iteration',      v_iteration,
      'forced_count',   v_count,
      'force_comment',  NULLIF(TRIM(COALESCE(p_comment, '')), '')
    )::text
  );

  RETURN v_count;
END;
$$;

REVOKE ALL ON FUNCTION public.force_approve_credit_group_change(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.force_approve_credit_group_change(uuid, text) TO authenticated;

NOTIFY pgrst, 'reload schema';

COMMIT;


-- ============================================================
-- Source: 20260628200000_credit_note_resolution.sql
-- ============================================================
-- Credit Note Resolution + Payment Redesign schema changes

-- 1. Add delivery type and return link to sale_deliveries
ALTER TABLE sale_deliveries
  ADD COLUMN IF NOT EXISTS type text NOT NULL DEFAULT 'standard',
  ADD COLUMN IF NOT EXISTS return_id uuid REFERENCES returns(id) ON DELETE SET NULL;

ALTER TABLE sale_deliveries
  ADD CONSTRAINT sale_deliveries_type_check CHECK (type IN ('standard', 'replacement'));

-- 2. Add resolution tracking to credit_notes
ALTER TABLE credit_notes
  ADD COLUMN IF NOT EXISTS resolution_type text;

ALTER TABLE credit_notes
  ADD CONSTRAINT credit_notes_resolution_type_check
    CHECK (resolution_type IN ('refund', 'replacement', 'store_credit'));

-- 3. Create the missing increment_credit_balance RPC
CREATE OR REPLACE FUNCTION increment_credit_balance(p_customer_id uuid, p_amount numeric)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  UPDATE customers
  SET credit_balance = COALESCE(credit_balance, 0) + p_amount,
      updated_at = now()
  WHERE id = p_customer_id;
END;
$$;


-- ============================================================
-- Source: 20260628210000_payment_method_enum_to_text.sql
-- ============================================================
-- Change payments.method and credit_notes.refund_method from payment_method enum to text.
-- The app now uses the payment_methods table (slug column) as the source of truth,
-- so the enum is too restrictive and rejects new slugs like "cdc".

-- 1. Convert payments.method from enum to text
ALTER TABLE payments
  ALTER COLUMN method TYPE text USING method::text;

-- 2. Convert credit_notes.refund_method from enum to text
ALTER TABLE credit_notes
  ALTER COLUMN refund_method TYPE text USING refund_method::text;

-- 3. Drop the enum since it is no longer referenced by any column
DROP TYPE IF EXISTS payment_method;


-- ============================================================
-- Source: 20260628220000_block_customer_pending_credit_approval.sql
-- ============================================================
-- Block new customers while their credit group approval is pending.
-- "New" = previous_group_id IS NULL (customer was just created, not changing groups).
-- On approve / force-approve: unblock. On reject: keep blocked (admin can unblock manually).

BEGIN;

-- ── 1. submit: block new customers on request creation ─────────────────────

CREATE OR REPLACE FUNCTION public.submit_credit_group_change(
  p_customer_id        uuid,
  p_requested_group_id uuid
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_customer        RECORD;
  v_new_group       RECORD;
  v_profile_id      uuid;
  v_request_id      uuid;
  v_step            RECORD;
  v_step_count      integer := 0;
BEGIN
  SELECT id INTO v_profile_id FROM profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT id, credit_group_id,
         cr_url,
         establishment_id_url,
         signed_credit_form_url
    INTO v_customer
  FROM customers
  WHERE id = p_customer_id;
  IF v_customer.id IS NULL THEN
    RAISE EXCEPTION 'Customer not found';
  END IF;

  SELECT id, name, credit_limit INTO v_new_group
  FROM credit_groups WHERE id = p_requested_group_id;
  IF v_new_group.id IS NULL THEN
    RAISE EXCEPTION 'Credit group not found';
  END IF;

  IF COALESCE(v_new_group.credit_limit, 0) = 0 THEN
    RAISE EXCEPTION 'Approval only required for credit groups with a non-zero limit. Assign this group directly.';
  END IF;

  IF v_customer.credit_group_id = p_requested_group_id THEN
    RAISE EXCEPTION 'Customer is already on this credit group';
  END IF;

  IF v_customer.cr_url IS NULL
     OR v_customer.establishment_id_url IS NULL
     OR v_customer.signed_credit_form_url IS NULL THEN
    RAISE EXCEPTION 'Upload all 3 required docs first (CR, Establishment ID, Signed Credit Form)'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1 FROM customer_credit_group_requests
    WHERE customer_id = p_customer_id AND status = 'pending'
  ) THEN
    RAISE EXCEPTION 'There is already a pending credit-group change for this customer';
  END IF;

  INSERT INTO customer_credit_group_requests (
    customer_id, requested_group_id, previous_group_id, status, requested_by
  ) VALUES (
    p_customer_id, p_requested_group_id, v_customer.credit_group_id, 'pending', v_profile_id
  )
  RETURNING id INTO v_request_id;

  FOR v_step IN
    SELECT was.step_order, cr.name AS role_name
    FROM   approval_workflow_steps was
    JOIN   custom_roles            cr ON cr.id = was.role_id
    WHERE  was.workflow    = 'credit_group'
      AND  was.is_active   = true
      AND  was.archived_at IS NULL
    ORDER BY was.step_order
  LOOP
    INSERT INTO customer_credit_group_approvals (
      request_id, step_role, step_order, status, is_active, iteration
    ) VALUES (
      v_request_id, v_step.role_name, v_step.step_order, 'pending', true, 1
    );
    v_step_count := v_step_count + 1;
  END LOOP;

  IF v_step_count = 0 THEN
    UPDATE customers SET credit_group_id = p_requested_group_id,
                         is_blocked = false, block_reason = NULL
     WHERE id = p_customer_id;
    UPDATE customer_credit_group_requests
      SET status = 'approved', decided_by = v_profile_id, decided_at = now()
      WHERE id = v_request_id;
  ELSE
    -- Block new customers (no previous group) while approval is pending
    IF v_customer.credit_group_id IS NULL THEN
      UPDATE customers
         SET is_blocked   = true,
             block_reason = 'Pending credit group approval'
       WHERE id = p_customer_id;
    END IF;
  END IF;

  INSERT INTO public.activity_log (action, module, entity_type, entity_id, performer_name, severity, details)
  VALUES (
    'Credit Group Change Requested',
    'customers',
    'customer',
    p_customer_id,
    (SELECT full_name FROM profiles WHERE id = v_profile_id),
    'info',
    jsonb_build_object(
      'request_id',       v_request_id,
      'requested_group',  v_new_group.name,
      'previous_group_id',v_customer.credit_group_id,
      'auto_approved',    v_step_count = 0
    )::text
  );

  RETURN jsonb_build_object(
    'request_id',  v_request_id,
    'step_count',  v_step_count,
    'status',      CASE WHEN v_step_count = 0 THEN 'approved' ELSE 'pending' END
  );
END;
$$;

-- ── 2. approve: unblock customer on full chain completion ──────────────────

CREATE OR REPLACE FUNCTION public.approve_credit_group_change(
  p_approval_id uuid,
  p_comment     text DEFAULT NULL
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_row            RECORD;
  v_request        RECORD;
  v_profile_id     uuid;
  v_full_name      TEXT;
  v_all_done       BOOLEAN;
BEGIN
  SELECT id, full_name INTO v_profile_id, v_full_name
  FROM   profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT * INTO v_row FROM customer_credit_group_approvals
    WHERE id = p_approval_id FOR UPDATE;
  IF NOT FOUND OR v_row.status <> 'pending' OR NOT v_row.is_active THEN
    RAISE EXCEPTION 'Approval step not actionable';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM   user_custom_roles ucr
    JOIN   custom_roles cr ON cr.id = ucr.role_id
    WHERE  ucr.profile_id        = v_profile_id
      AND  cr.name               = v_row.step_role
      AND  cr.is_approval_slot   = true
      AND  cr.deleted_at         IS NULL
      AND  (ucr.approval_scopes IS NULL
            OR 'credit_group' = ANY(ucr.approval_scopes))
  ) THEN
    RAISE EXCEPTION 'You do not hold the role required for this approval step';
  END IF;

  IF EXISTS (
    SELECT 1 FROM customer_credit_group_approvals
    WHERE  request_id  = v_row.request_id
      AND  iteration   = v_row.iteration
      AND  decided_by  = v_profile_id
      AND  id          <> p_approval_id
  ) THEN
    RAISE EXCEPTION 'You have already actioned another step on this request';
  END IF;

  UPDATE customer_credit_group_approvals
  SET    status          = 'approved',
         decided_by      = v_profile_id,
         decided_by_name = v_full_name,
         decided_at      = now(),
         comment         = p_comment
  WHERE  id = p_approval_id;

  SELECT NOT EXISTS (
    SELECT 1 FROM customer_credit_group_approvals
    WHERE  request_id  = v_row.request_id
      AND  iteration   = v_row.iteration
      AND  status     <> 'approved'
  ) INTO v_all_done;

  IF v_all_done THEN
    SELECT * INTO v_request FROM customer_credit_group_requests
      WHERE id = v_row.request_id FOR UPDATE;

    UPDATE customers
       SET credit_group_id = v_request.requested_group_id,
           is_blocked      = false,
           block_reason    = NULL
     WHERE id = v_request.customer_id;

    UPDATE customer_credit_group_requests
       SET status     = 'approved',
           decided_by = v_profile_id,
           decided_at = now()
     WHERE id = v_request.id;

    INSERT INTO public.activity_log (action, module, entity_type, entity_id, performer_name, severity, details)
    VALUES (
      'Credit Group Change Approved',
      'customers',
      'customer',
      v_request.customer_id,
      v_full_name,
      'info',
      jsonb_build_object('request_id', v_request.id)::text
    );
  END IF;
END;
$$;

-- ── 3. force-approve: unblock customer ─────────────────────────────────────

CREATE OR REPLACE FUNCTION public.force_approve_credit_group_change(
  p_request_id uuid,
  p_comment    text DEFAULT NULL
) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_profile_id   uuid;
  v_full_name    TEXT;
  v_is_owner     BOOLEAN;
  v_request      RECORD;
  v_iteration    INT;
  v_count        INT;
BEGIN
  SELECT id, full_name INTO v_profile_id, v_full_name
  FROM   profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM   user_custom_roles ucr
    JOIN   custom_roles cr ON cr.id = ucr.role_id
    WHERE  ucr.profile_id      = v_profile_id
      AND  cr.name             = 'Owner'
      AND  cr.is_approval_slot = true
      AND  cr.deleted_at       IS NULL
  ) INTO v_is_owner;
  IF NOT v_is_owner THEN
    RAISE EXCEPTION 'Only users with the Owner role can force-approve';
  END IF;

  SELECT * INTO v_request FROM customer_credit_group_requests
    WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Credit-group request not found';
  END IF;
  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'Request is no longer pending (status: %)', v_request.status;
  END IF;

  SELECT COALESCE(MAX(iteration), 1) INTO v_iteration
  FROM   customer_credit_group_approvals
  WHERE  request_id = p_request_id;

  UPDATE customer_credit_group_approvals
  SET    status          = 'approved',
         decided_by      = v_profile_id,
         decided_by_name = v_full_name,
         decided_at      = now(),
         force_approved  = true,
         force_comment   = NULLIF(TRIM(COALESCE(p_comment, '')), ''),
         comment         = COALESCE(comment, p_comment)
  WHERE  request_id = p_request_id
    AND  iteration  = v_iteration
    AND  status     = 'pending'
    AND  is_active  = true;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  IF v_count = 0 THEN
    RAISE EXCEPTION 'No pending steps to force-approve on this request';
  END IF;

  UPDATE customers
     SET credit_group_id = v_request.requested_group_id,
         is_blocked      = false,
         block_reason    = NULL
   WHERE id = v_request.customer_id;

  UPDATE customer_credit_group_requests
     SET status     = 'approved',
         decided_by = v_profile_id,
         decided_at = now()
   WHERE id = p_request_id;

  INSERT INTO public.activity_log (
    action, module, entity_type, entity_id, performer_name, severity, details
  ) VALUES (
    'Credit Group Change Force-Approved',
    'customers',
    'customer',
    v_request.customer_id,
    v_full_name,
    'critical',
    jsonb_build_object(
      'request_id',     v_request.id,
      'iteration',      v_iteration,
      'forced_count',   v_count,
      'force_comment',  NULLIF(TRIM(COALESCE(p_comment, '')), '')
    )::text
  );

  RETURN v_count;
END;
$$;

NOTIFY pgrst, 'reload schema';

COMMIT;


-- ============================================================
-- Source: 20260628230000_receival_edit_approval_workflow.sql
-- ============================================================
-- Add 'receival_edit' to the approval workflow system.
-- Any user holding a configured role can approve a receival edit request
-- (single-step, not a sequential chain).

BEGIN;

-- ── 1. Widen CHECK constraint ─────────────────────────────────────────────────

ALTER TABLE public.approval_workflow_steps
  DROP CONSTRAINT IF EXISTS workflow_approval_steps_workflow_check;
ALTER TABLE public.approval_workflow_steps
  ADD CONSTRAINT workflow_approval_steps_workflow_check
  CHECK (workflow = ANY (ARRAY[
    'po','inv_check','stock_adj','sales_margin','sales_credit','credit_group','receival_edit'
  ]));

-- ── 2. Widen add_workflow_step (legacy) ───────────────────────────────────────

CREATE OR REPLACE FUNCTION public.add_workflow_step(
  p_workflow         text,
  p_role_name        text,
  p_role_desc        text DEFAULT ''::text,
  p_is_conditional   boolean DEFAULT false,
  p_condition_types  text[] DEFAULT '{}'::text[]
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_role_id   UUID;
  v_max_order INT;
  v_step_key  TEXT;
  v_step      approval_workflow_steps;
BEGIN
  IF p_workflow NOT IN ('po','inv_check','stock_adj','sales_margin','sales_credit','credit_group','receival_edit') THEN
    RAISE EXCEPTION 'Invalid workflow: %', p_workflow;
  END IF;
  IF TRIM(p_role_name) = '' THEN
    RAISE EXCEPTION 'Role name cannot be empty';
  END IF;

  SELECT id INTO v_role_id
  FROM custom_roles
  WHERE name = p_role_name AND deleted_at IS NULL;

  IF v_role_id IS NULL THEN
    INSERT INTO custom_roles (name, description, is_approval_slot, is_system, permissions)
    VALUES (TRIM(p_role_name), NULLIF(TRIM(p_role_desc),''), true, false, '[]'::jsonb)
    RETURNING id INTO v_role_id;
  ELSE
    UPDATE custom_roles SET is_approval_slot = true WHERE id = v_role_id;
  END IF;

  v_step_key := LOWER(REGEXP_REPLACE(TRIM(p_role_name), '\s+', '_', 'g'));

  SELECT COALESCE(MAX(step_order), 0) INTO v_max_order
  FROM approval_workflow_steps
  WHERE workflow = p_workflow AND archived_at IS NULL;

  INSERT INTO approval_workflow_steps (
    workflow, role_id, step_key, step_label, step_order,
    is_conditional, condition_types
  ) VALUES (
    p_workflow, v_role_id, v_step_key, TRIM(p_role_name), v_max_order + 1,
    p_is_conditional, p_condition_types
  )
  RETURNING * INTO v_step;

  RETURN to_jsonb(v_step);
END;
$$;

-- ── 3. Widen add_workflow_step_for_role ────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.add_workflow_step_for_role(
  p_workflow         text,
  p_role_id          uuid,
  p_is_conditional   boolean DEFAULT false,
  p_condition_types  text[] DEFAULT '{}'::text[]
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_role_name TEXT;
  v_max_order INT;
  v_step_key  TEXT;
  v_step      approval_workflow_steps;
BEGIN
  IF p_workflow NOT IN ('po','inv_check','stock_adj','sales_margin','sales_credit','credit_group','receival_edit') THEN
    RAISE EXCEPTION 'Invalid workflow: %', p_workflow;
  END IF;

  SELECT name INTO v_role_name
  FROM custom_roles
  WHERE id = p_role_id
    AND is_approval_slot = true
    AND deleted_at IS NULL;

  IF v_role_name IS NULL THEN
    RAISE EXCEPTION 'Role not found or is not an approval-slot role';
  END IF;

  IF EXISTS (
    SELECT 1 FROM approval_workflow_steps
    WHERE workflow = p_workflow
      AND role_id  = p_role_id
      AND archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'This role is already a step in the % workflow', p_workflow;
  END IF;

  v_step_key := LOWER(REGEXP_REPLACE(TRIM(v_role_name), '\s+', '_', 'g'));

  IF EXISTS (
    SELECT 1 FROM approval_workflow_steps
    WHERE workflow = p_workflow AND step_key = v_step_key
      AND archived_at IS NULL
  ) THEN
    v_step_key := v_step_key || '_' || substr(gen_random_uuid()::text, 1, 4);
  END IF;

  SELECT COALESCE(MAX(step_order), 0) INTO v_max_order
  FROM approval_workflow_steps
  WHERE workflow = p_workflow AND archived_at IS NULL;

  INSERT INTO approval_workflow_steps (
    workflow, role_id, step_key, step_label, step_order,
    is_conditional, condition_types
  ) VALUES (
    p_workflow, p_role_id, v_step_key, v_role_name, v_max_order + 1,
    p_is_conditional, p_condition_types
  )
  RETURNING * INTO v_step;

  RETURN to_jsonb(v_step);
END;
$$;

NOTIFY pgrst, 'reload schema';

COMMIT;


-- ============================================================
-- Source: 20260629100000_rename_payment_method_rpc.sql
-- ============================================================
-- Atomically rename a payment method (name + slug) and cascade
-- the slug change into every credit_groups.payment_methods[] array.
CREATE OR REPLACE FUNCTION rename_payment_method(
  p_id       UUID,
  p_new_name TEXT,
  p_new_slug TEXT
) RETURNS VOID AS $$
DECLARE
  v_old_slug TEXT;
BEGIN
  SELECT slug INTO v_old_slug FROM payment_methods WHERE id = p_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment method % not found', p_id;
  END IF;

  UPDATE payment_methods
     SET name = p_new_name, slug = p_new_slug
   WHERE id = p_id;

  IF v_old_slug IS DISTINCT FROM p_new_slug THEN
    UPDATE credit_groups
       SET payment_methods = array_replace(payment_methods, v_old_slug, p_new_slug)
     WHERE v_old_slug = ANY(payment_methods);
  END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- ============================================================
-- Source: 20260629110000_credit_group_payment_methods_junction.sql
-- ============================================================
-- Migrate credit_groups.payment_methods text[] → junction table with FK integrity.

-- 1. Create junction table
CREATE TABLE credit_group_payment_methods (
  credit_group_id UUID NOT NULL REFERENCES credit_groups(id) ON DELETE CASCADE,
  payment_method_id UUID NOT NULL REFERENCES payment_methods(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY (credit_group_id, payment_method_id)
);

-- 2. RLS
ALTER TABLE credit_group_payment_methods ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Authenticated users can read"
  ON credit_group_payment_methods FOR SELECT TO authenticated USING (true);

CREATE POLICY "Authenticated users can manage"
  ON credit_group_payment_methods FOR ALL TO authenticated USING (true) WITH CHECK (true);

-- 3. Backfill from existing text[] arrays
INSERT INTO credit_group_payment_methods (credit_group_id, payment_method_id)
SELECT cg.id, pm.id
FROM credit_groups cg
CROSS JOIN LATERAL unnest(cg.payment_methods) AS m(method_slug)
JOIN payment_methods pm ON pm.slug = m.method_slug
ON CONFLICT DO NOTHING;

-- 4. Drop the old text[] column
ALTER TABLE credit_groups DROP COLUMN payment_methods;

-- 5. Simplify rename RPC — cascade no longer needed (junction uses IDs, not slugs)
CREATE OR REPLACE FUNCTION rename_payment_method(
  p_id       UUID,
  p_new_name TEXT,
  p_new_slug TEXT
) RETURNS VOID AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM payment_methods WHERE id = p_id) THEN
    RAISE EXCEPTION 'payment method % not found', p_id;
  END IF;

  UPDATE payment_methods
     SET name = p_new_name, slug = p_new_slug
   WHERE id = p_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- ============================================================
-- Source: 20260629120000_approval_workflow_groups.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Multi-path approval groups.
--
-- Each workflow's approval chain can have multiple "paths" (groups).
-- Each path has its own mode:
--   • any_one  — first approved step in the group completes it
--   • all_must — every step in the group must be approved
--
-- Paths relate to each other with OR logic: if ANY path completes,
-- the entire workflow request is approved.
--
-- Example:
--   Path A (all_must): [PM, Accountant]  — both must sign off
--   Path B (any_one):  [GM, Director]    — either alone is enough
--   → If Path A OR Path B is satisfied → approved.
--
-- Backfill: creates one "Default" group per workflow (mode: any_one)
-- and assigns all existing steps to it — zero behavior change.
-- ─────────────────────────────────────────────────────────────────────────────

BEGIN;

-- ── 1. approval_workflow_groups table ────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.approval_workflow_groups (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workflow    text NOT NULL
              CHECK (workflow = ANY(ARRAY[
                'po','inv_check','stock_adj','sales_margin','sales_credit',
                'credit_group','receival_edit'
              ])),
  group_label text NOT NULL DEFAULT 'Default',
  group_order integer NOT NULL DEFAULT 1,
  mode        text NOT NULL DEFAULT 'any_one'
              CHECK (mode IN ('any_one', 'all_must')),
  is_active   boolean NOT NULL DEFAULT true,
  created_at  timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.approval_workflow_groups ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Authenticated can read workflow groups"
  ON public.approval_workflow_groups FOR SELECT TO authenticated USING (true);

CREATE POLICY "Authenticated can insert workflow groups"
  ON public.approval_workflow_groups FOR INSERT TO authenticated WITH CHECK (true);

CREATE POLICY "Authenticated can update workflow groups"
  ON public.approval_workflow_groups FOR UPDATE TO authenticated USING (true) WITH CHECK (true);

CREATE POLICY "Authenticated can delete workflow groups"
  ON public.approval_workflow_groups FOR DELETE TO authenticated USING (true);

GRANT SELECT, INSERT, UPDATE, DELETE ON public.approval_workflow_groups TO authenticated, service_role;

-- ── 2. Add group_id FK to approval_workflow_steps ────────────────────────────

ALTER TABLE public.approval_workflow_steps
  ADD COLUMN IF NOT EXISTS group_id uuid
    REFERENCES public.approval_workflow_groups(id) ON DELETE SET NULL;

-- ── 3. Backfill: one default group per workflow ──────────────────────────────

DO $$
DECLARE
  v_workflow text;
  v_group_id uuid;
BEGIN
  FOR v_workflow IN
    SELECT DISTINCT workflow
    FROM   public.approval_workflow_steps
    WHERE  archived_at IS NULL
  LOOP
    INSERT INTO public.approval_workflow_groups
      (workflow, group_label, group_order, mode)
    VALUES
      (v_workflow, 'Default', 1, 'any_one')
    RETURNING id INTO v_group_id;

    UPDATE public.approval_workflow_steps
    SET    group_id = v_group_id
    WHERE  workflow    = v_workflow
      AND  archived_at IS NULL;
  END LOOP;
END $$;

-- ── 4. Update add_workflow_step_for_role — accept p_group_id ─────────────────

CREATE OR REPLACE FUNCTION public.add_workflow_step_for_role(
  p_workflow         text,
  p_role_id          uuid,
  p_is_conditional   boolean DEFAULT false,
  p_condition_types  text[] DEFAULT '{}'::text[],
  p_group_id         uuid   DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_role_name TEXT;
  v_max_order INT;
  v_step_key  TEXT;
  v_step      approval_workflow_steps;
  v_group_id  uuid := p_group_id;
BEGIN
  IF p_workflow NOT IN (
    'po','inv_check','stock_adj','sales_margin','sales_credit',
    'credit_group','receival_edit'
  ) THEN
    RAISE EXCEPTION 'Invalid workflow: %', p_workflow;
  END IF;

  SELECT name INTO v_role_name
  FROM   custom_roles
  WHERE  id = p_role_id
    AND  is_approval_slot = true
    AND  deleted_at IS NULL;

  IF v_role_name IS NULL THEN
    RAISE EXCEPTION 'Role not found or is not an approval-slot role';
  END IF;

  IF EXISTS (
    SELECT 1 FROM approval_workflow_steps
    WHERE  workflow = p_workflow
      AND  role_id  = p_role_id
      AND  archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'This role is already a step in the % workflow', p_workflow;
  END IF;

  -- Auto-detect group when not provided
  IF v_group_id IS NULL THEN
    SELECT id INTO v_group_id
    FROM   approval_workflow_groups
    WHERE  workflow = p_workflow AND is_active = true
    ORDER BY group_order
    LIMIT  1;

    IF v_group_id IS NULL THEN
      INSERT INTO approval_workflow_groups (workflow, group_label, group_order, mode)
      VALUES (p_workflow, 'Default', 1, 'any_one')
      RETURNING id INTO v_group_id;
    END IF;
  END IF;

  v_step_key := LOWER(REGEXP_REPLACE(TRIM(v_role_name), '\s+', '_', 'g'));

  IF EXISTS (
    SELECT 1 FROM approval_workflow_steps
    WHERE  workflow = p_workflow AND step_key = v_step_key
      AND  archived_at IS NULL
  ) THEN
    v_step_key := v_step_key || '_' || substr(gen_random_uuid()::text, 1, 4);
  END IF;

  SELECT COALESCE(MAX(step_order), 0) INTO v_max_order
  FROM   approval_workflow_steps
  WHERE  workflow = p_workflow AND archived_at IS NULL;

  INSERT INTO approval_workflow_steps (
    workflow, role_id, step_key, step_label, step_order,
    is_conditional, condition_types, group_id
  ) VALUES (
    p_workflow, p_role_id, v_step_key, v_role_name, v_max_order + 1,
    p_is_conditional, p_condition_types, v_group_id
  )
  RETURNING * INTO v_step;

  RETURN to_jsonb(v_step);
END;
$$;

-- ── 5. Update legacy add_workflow_step — accept p_group_id ───────────────────

CREATE OR REPLACE FUNCTION public.add_workflow_step(
  p_workflow         text,
  p_role_name        text,
  p_role_desc        text DEFAULT ''::text,
  p_is_conditional   boolean DEFAULT false,
  p_condition_types  text[] DEFAULT '{}'::text[],
  p_group_id         uuid   DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_role_id   UUID;
  v_max_order INT;
  v_step_key  TEXT;
  v_step      approval_workflow_steps;
  v_group_id  uuid := p_group_id;
BEGIN
  IF p_workflow NOT IN (
    'po','inv_check','stock_adj','sales_margin','sales_credit',
    'credit_group','receival_edit'
  ) THEN
    RAISE EXCEPTION 'Invalid workflow: %', p_workflow;
  END IF;
  IF TRIM(p_role_name) = '' THEN
    RAISE EXCEPTION 'Role name cannot be empty';
  END IF;

  SELECT id INTO v_role_id
  FROM   custom_roles
  WHERE  name = p_role_name AND deleted_at IS NULL;

  IF v_role_id IS NULL THEN
    INSERT INTO custom_roles (name, description, is_approval_slot, is_system, permissions)
    VALUES (TRIM(p_role_name), NULLIF(TRIM(p_role_desc),''), true, false, '[]'::jsonb)
    RETURNING id INTO v_role_id;
  ELSE
    UPDATE custom_roles SET is_approval_slot = true WHERE id = v_role_id;
  END IF;

  IF v_group_id IS NULL THEN
    SELECT id INTO v_group_id
    FROM   approval_workflow_groups
    WHERE  workflow = p_workflow AND is_active = true
    ORDER BY group_order
    LIMIT  1;

    IF v_group_id IS NULL THEN
      INSERT INTO approval_workflow_groups (workflow, group_label, group_order, mode)
      VALUES (p_workflow, 'Default', 1, 'any_one')
      RETURNING id INTO v_group_id;
    END IF;
  END IF;

  v_step_key := LOWER(REGEXP_REPLACE(TRIM(p_role_name), '\s+', '_', 'g'));

  SELECT COALESCE(MAX(step_order), 0) INTO v_max_order
  FROM   approval_workflow_steps
  WHERE  workflow = p_workflow AND archived_at IS NULL;

  INSERT INTO approval_workflow_steps (
    workflow, role_id, step_key, step_label, step_order,
    is_conditional, condition_types, group_id
  ) VALUES (
    p_workflow, v_role_id, v_step_key, TRIM(p_role_name), v_max_order + 1,
    p_is_conditional, p_condition_types, v_group_id
  )
  RETURNING * INTO v_step;

  RETURN to_jsonb(v_step);
END;
$$;

NOTIFY pgrst, 'reload schema';

COMMIT;


-- ============================================================
-- Source: 20260629130000_fix_receival_edit_item_name.sql
-- ============================================================
-- Fix: apply_receival_edit referenced ibv.item_name / ibv.sku on
-- inventory_brand_variants, but those columns live on inventory_items.
-- Join through ibv → ii to resolve the correct item_name and sku.

CREATE OR REPLACE FUNCTION public.apply_receival_edit(p_edit_request_id uuid, p_items jsonb)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_req             RECORD;
  v_receival        RECORD;
  v_item_input      JSONB;
  v_bv_id           UUID;
  v_pli_id          UUID;
  v_old_qty         INT;
  v_new_qty         INT;
  v_old_cost        NUMERIC;
  v_new_cost        NUMERIC;
  v_delta           INT;
  v_layer_remaining BIGINT;
  v_sold_qty        BIGINT;
  v_has_applied_lc  BOOLEAN;
  v_lc_rec          RECORD;
  v_total_remaining BIGINT;
  v_receival_date   DATE;
  v_stock_level     INT;
  v_reserved_qty    INT;
BEGIN
  -- ── 1. Lock and validate the edit request ──────────────────────────────────
  SELECT * INTO v_req FROM receival_edit_requests WHERE id = p_edit_request_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Edit request % not found', p_edit_request_id;
  END IF;
  IF v_req.status <> 'approved' THEN
    RAISE EXCEPTION 'Edit request % is not approved (status: %)', p_edit_request_id, v_req.status;
  END IF;
  IF v_req.expires_at IS NOT NULL AND v_req.expires_at < now() THEN
    UPDATE receival_edit_requests SET status = 'expired' WHERE id = p_edit_request_id;
    RAISE EXCEPTION 'Edit window expired. Please request a new edit.';
  END IF;

  -- ── 2. Lock the receival ────────────────────────────────────────────────────
  SELECT id, date INTO v_receival FROM receivals WHERE id = v_req.receival_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Receival % not found', v_req.receival_id;
  END IF;
  v_receival_date := v_receival.date;

  -- ── 3. Pre-flight LC check ──────────────────────────────────────────────────
  PERFORM 1 FROM landed_costs
  WHERE v_req.receival_id = ANY(attached_receival_ids)
    AND applied_at IS NOT NULL AND voided_at IS NULL
  FOR SHARE;

  SELECT EXISTS(
    SELECT 1 FROM landed_costs
    WHERE v_req.receival_id = ANY(attached_receival_ids)
      AND applied_at IS NOT NULL AND voided_at IS NULL
  ) INTO v_has_applied_lc;

  -- ── 4. Process each item ────────────────────────────────────────────────────
  FOR v_item_input IN SELECT * FROM jsonb_array_elements(p_items) LOOP

    SELECT ri.qty_received, ri.unit_cost, ri.brand_variant_id, ri.po_line_item_id
    INTO v_old_qty, v_old_cost, v_bv_id, v_pli_id
    FROM receival_items ri
    WHERE ri.id = (v_item_input->>'receival_item_id')::UUID
      AND ri.receival_id = v_req.receival_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'receival_item % not found (or does not belong to receival %)',
        v_item_input->>'receival_item_id', v_req.receival_id;
    END IF;

    v_new_qty  := (v_item_input->>'new_qty')::INT;
    v_new_cost := (v_item_input->>'new_unit_cost')::NUMERIC;
    v_delta    := v_new_qty - v_old_qty;

    IF v_new_qty IS NULL OR v_new_qty <= 0 THEN
      RAISE EXCEPTION 'new_qty must be a positive integer for item %', v_item_input->>'receival_item_id';
    END IF;
    IF v_new_cost IS NULL OR v_new_cost < 0 THEN
      RAISE EXCEPTION 'new_unit_cost must be non-negative for item %', v_item_input->>'receival_item_id';
    END IF;

    -- Sync PO line item received_qty (always, regardless of inventory linkage)
    IF v_delta <> 0 AND v_pli_id IS NOT NULL THEN
      UPDATE po_line_items
      SET received_qty = GREATEST(0, received_qty + v_delta)
      WHERE id = v_pli_id;
    END IF;

    CONTINUE WHEN v_bv_id IS NULL;

    -- ── QTY CHANGE ────────────────────────────────────────────────────────────
    IF v_delta <> 0 THEN
      IF v_has_applied_lc THEN
        RAISE EXCEPTION 'Cannot change qty: an applied Landed Cost references this receival. Void the LC first.';
      END IF;

      IF v_delta > 0 THEN
        UPDATE fifo_cost_layers
        SET qty           = qty           + v_delta,
            remaining_qty = remaining_qty + v_delta
        WHERE receival_id = v_req.receival_id::TEXT AND brand_variant_id = v_bv_id;

        UPDATE inventory_brand_variants
        SET stock_level = stock_level + v_delta, updated_at = now()
        WHERE id = v_bv_id;

        INSERT INTO inventory_stock_movements
          (brand_variant_id, item_name, sku, movement_type, qty, unit_cost,
           reference_type, reference_id, notes)
        SELECT v_bv_id, ii.name_en, ii.sku,
               'receival_edit', v_delta, v_old_cost,
               'receival_edit_request', p_edit_request_id,
               'Qty increase edit on receival ' || v_req.receival_id
        FROM inventory_brand_variants ibv
        JOIN inventory_items ii ON ii.id = ibv.item_id
        WHERE ibv.id = v_bv_id;

      ELSE  -- v_delta < 0
        SELECT COALESCE(SUM(remaining_qty), 0) INTO v_layer_remaining
        FROM (
          SELECT remaining_qty FROM fifo_cost_layers
          WHERE receival_id = v_req.receival_id::TEXT AND brand_variant_id = v_bv_id
          ORDER BY id ASC FOR UPDATE
        ) sub;

        IF v_layer_remaining < ABS(v_delta) THEN
          RAISE EXCEPTION
            'Cannot reduce qty by %: only % units remain from this receival (% were sold)',
            ABS(v_delta), v_layer_remaining, v_old_qty - v_layer_remaining;
        END IF;

        SELECT COALESCE(stock_level, 0), COALESCE(reserved_qty, 0)
        INTO v_stock_level, v_reserved_qty
        FROM inventory_brand_variants
        WHERE id = v_bv_id
        FOR UPDATE;

        IF (v_stock_level - ABS(v_delta)) < v_reserved_qty THEN
          RAISE EXCEPTION
            'Cannot reduce qty by % for variant %: new stock level (%) would be below reserved qty (%)',
            ABS(v_delta), v_bv_id,
            v_stock_level - ABS(v_delta),
            v_reserved_qty;
        END IF;

        UPDATE fifo_cost_layers
        SET qty           = qty           - ABS(v_delta),
            remaining_qty = remaining_qty - ABS(v_delta)
        WHERE receival_id = v_req.receival_id::TEXT AND brand_variant_id = v_bv_id;

        UPDATE inventory_brand_variants
        SET stock_level = stock_level - ABS(v_delta), updated_at = now()
        WHERE id = v_bv_id;

        INSERT INTO inventory_stock_movements
          (brand_variant_id, item_name, sku, movement_type, qty, unit_cost,
           reference_type, reference_id, notes)
        SELECT v_bv_id, ii.name_en, ii.sku,
               'receival_edit', -ABS(v_delta), v_old_cost,
               'receival_edit_request', p_edit_request_id,
               'Qty decrease edit on receival ' || v_req.receival_id
        FROM inventory_brand_variants ibv
        JOIN inventory_items ii ON ii.id = ibv.item_id
        WHERE ibv.id = v_bv_id;
      END IF;
    END IF;

    -- ── UNIT COST CHANGE ──────────────────────────────────────────────────────
    IF v_new_cost <> v_old_cost THEN
      IF v_has_applied_lc THEN
        RAISE EXCEPTION 'Cannot change unit cost: an applied Landed Cost references this receival. Void the LC first.';
      END IF;

      SELECT COALESCE(SUM(qty - remaining_qty), 0) INTO v_sold_qty
      FROM fifo_cost_layers
      WHERE receival_id = v_req.receival_id::TEXT AND brand_variant_id = v_bv_id;

      IF v_sold_qty > 0 THEN
        UPDATE cogs_entries
        SET unit_cost  = v_new_cost,
            total_cost = v_new_cost * qty
        WHERE id IN (
          SELECT id FROM cogs_entries
          WHERE brand_variant_id = v_bv_id
            AND unit_cost = v_old_cost
            AND date >= v_receival_date
          ORDER BY date ASC
          LIMIT v_sold_qty
        );
      END IF;

      UPDATE fifo_cost_layers
      SET unit_cost       = v_new_cost,
          total_unit_cost = v_new_cost + landed_cost_per_unit
      WHERE receival_id = v_req.receival_id::TEXT AND brand_variant_id = v_bv_id;
    END IF;

    PERFORM recalc_average_cost(v_bv_id);

    IF v_delta < 0 THEN
      FOR v_lc_rec IN
        SELECT id, attached_receival_ids FROM landed_costs
        WHERE v_req.receival_id = ANY(attached_receival_ids)
          AND applied_at IS NULL AND voided_at IS NULL
      LOOP
        SELECT COALESCE(SUM(fcl.remaining_qty), 0) INTO v_total_remaining
        FROM fifo_cost_layers fcl
        WHERE fcl.receival_id = ANY(
          SELECT unnest(v_lc_rec.attached_receival_ids)::TEXT
        );
        IF v_total_remaining = 0 THEN
          UPDATE landed_costs SET all_items_sold = TRUE, updated_at = now()
          WHERE id = v_lc_rec.id;
        END IF;
      END LOOP;
    END IF;

    UPDATE receival_items
    SET qty_received = v_new_qty, unit_cost = v_new_cost
    WHERE id = (v_item_input->>'receival_item_id')::UUID;

  END LOOP;

  -- ── 5. Mark edit request as completed ────────────────────────────────────────
  UPDATE receival_edit_requests
  SET status = 'completed'
  WHERE id = p_edit_request_id;

  RETURN jsonb_build_object('ok', true);
END;
$$;


-- ============================================================
-- Source: 20260629131000_fix_receival_edit_status_column.sql
-- ============================================================
-- Fix: apply_receival_edit used "applied_at" column and "applied" status,
-- but the table has "approved_at" and the CHECK constraint only allows "completed".
-- Re-create with corrected final UPDATE.

CREATE OR REPLACE FUNCTION public.apply_receival_edit(p_edit_request_id uuid, p_items jsonb)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_req             RECORD;
  v_receival        RECORD;
  v_item_input      JSONB;
  v_bv_id           UUID;
  v_pli_id          UUID;
  v_old_qty         INT;
  v_new_qty         INT;
  v_old_cost        NUMERIC;
  v_new_cost        NUMERIC;
  v_delta           INT;
  v_layer_remaining BIGINT;
  v_sold_qty        BIGINT;
  v_has_applied_lc  BOOLEAN;
  v_lc_rec          RECORD;
  v_total_remaining BIGINT;
  v_receival_date   DATE;
  v_stock_level     INT;
  v_reserved_qty    INT;
BEGIN
  -- ── 1. Lock and validate the edit request ──────────────────────────────────
  SELECT * INTO v_req FROM receival_edit_requests WHERE id = p_edit_request_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Edit request % not found', p_edit_request_id;
  END IF;
  IF v_req.status <> 'approved' THEN
    RAISE EXCEPTION 'Edit request % is not approved (status: %)', p_edit_request_id, v_req.status;
  END IF;
  IF v_req.expires_at IS NOT NULL AND v_req.expires_at < now() THEN
    UPDATE receival_edit_requests SET status = 'expired' WHERE id = p_edit_request_id;
    RAISE EXCEPTION 'Edit window expired. Please request a new edit.';
  END IF;

  -- ── 2. Lock the receival ────────────────────────────────────────────────────
  SELECT id, date INTO v_receival FROM receivals WHERE id = v_req.receival_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Receival % not found', v_req.receival_id;
  END IF;
  v_receival_date := v_receival.date;

  -- ── 3. Pre-flight LC check ──────────────────────────────────────────────────
  PERFORM 1 FROM landed_costs
  WHERE v_req.receival_id = ANY(attached_receival_ids)
    AND applied_at IS NOT NULL AND voided_at IS NULL
  FOR SHARE;

  SELECT EXISTS(
    SELECT 1 FROM landed_costs
    WHERE v_req.receival_id = ANY(attached_receival_ids)
      AND applied_at IS NOT NULL AND voided_at IS NULL
  ) INTO v_has_applied_lc;

  -- ── 4. Process each item ────────────────────────────────────────────────────
  FOR v_item_input IN SELECT * FROM jsonb_array_elements(p_items) LOOP

    SELECT ri.qty_received, ri.unit_cost, ri.brand_variant_id, ri.po_line_item_id
    INTO v_old_qty, v_old_cost, v_bv_id, v_pli_id
    FROM receival_items ri
    WHERE ri.id = (v_item_input->>'receival_item_id')::UUID
      AND ri.receival_id = v_req.receival_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'receival_item % not found (or does not belong to receival %)',
        v_item_input->>'receival_item_id', v_req.receival_id;
    END IF;

    v_new_qty  := (v_item_input->>'new_qty')::INT;
    v_new_cost := (v_item_input->>'new_unit_cost')::NUMERIC;
    v_delta    := v_new_qty - v_old_qty;

    IF v_new_qty IS NULL OR v_new_qty <= 0 THEN
      RAISE EXCEPTION 'new_qty must be a positive integer for item %', v_item_input->>'receival_item_id';
    END IF;
    IF v_new_cost IS NULL OR v_new_cost < 0 THEN
      RAISE EXCEPTION 'new_unit_cost must be non-negative for item %', v_item_input->>'receival_item_id';
    END IF;

    -- Sync PO line item received_qty (always, regardless of inventory linkage)
    IF v_delta <> 0 AND v_pli_id IS NOT NULL THEN
      UPDATE po_line_items
      SET received_qty = GREATEST(0, received_qty + v_delta)
      WHERE id = v_pli_id;
    END IF;

    CONTINUE WHEN v_bv_id IS NULL;

    -- ── QTY CHANGE ────────────────────────────────────────────────────────────
    IF v_delta <> 0 THEN
      IF v_has_applied_lc THEN
        RAISE EXCEPTION 'Cannot change qty: an applied Landed Cost references this receival. Void the LC first.';
      END IF;

      IF v_delta > 0 THEN
        UPDATE fifo_cost_layers
        SET qty           = qty           + v_delta,
            remaining_qty = remaining_qty + v_delta
        WHERE receival_id = v_req.receival_id::TEXT AND brand_variant_id = v_bv_id;

        UPDATE inventory_brand_variants
        SET stock_level = stock_level + v_delta, updated_at = now()
        WHERE id = v_bv_id;

        INSERT INTO inventory_stock_movements
          (brand_variant_id, item_name, sku, movement_type, qty, unit_cost,
           reference_type, reference_id, notes)
        SELECT v_bv_id, ii.name_en, ii.sku,
               'receival_edit', v_delta, v_old_cost,
               'receival_edit_request', p_edit_request_id,
               'Qty increase edit on receival ' || v_req.receival_id
        FROM inventory_brand_variants ibv
        JOIN inventory_items ii ON ii.id = ibv.item_id
        WHERE ibv.id = v_bv_id;

      ELSE  -- v_delta < 0
        SELECT COALESCE(SUM(remaining_qty), 0) INTO v_layer_remaining
        FROM (
          SELECT remaining_qty FROM fifo_cost_layers
          WHERE receival_id = v_req.receival_id::TEXT AND brand_variant_id = v_bv_id
          ORDER BY id ASC FOR UPDATE
        ) sub;

        IF v_layer_remaining < ABS(v_delta) THEN
          RAISE EXCEPTION
            'Cannot reduce qty by %: only % units remain from this receival (% were sold)',
            ABS(v_delta), v_layer_remaining, v_old_qty - v_layer_remaining;
        END IF;

        SELECT COALESCE(stock_level, 0), COALESCE(reserved_qty, 0)
        INTO v_stock_level, v_reserved_qty
        FROM inventory_brand_variants
        WHERE id = v_bv_id
        FOR UPDATE;

        IF (v_stock_level - ABS(v_delta)) < v_reserved_qty THEN
          RAISE EXCEPTION
            'Cannot reduce qty by % for variant %: new stock level (%) would be below reserved qty (%)',
            ABS(v_delta), v_bv_id,
            v_stock_level - ABS(v_delta),
            v_reserved_qty;
        END IF;

        UPDATE fifo_cost_layers
        SET qty           = qty           - ABS(v_delta),
            remaining_qty = remaining_qty - ABS(v_delta)
        WHERE receival_id = v_req.receival_id::TEXT AND brand_variant_id = v_bv_id;

        UPDATE inventory_brand_variants
        SET stock_level = stock_level - ABS(v_delta), updated_at = now()
        WHERE id = v_bv_id;

        INSERT INTO inventory_stock_movements
          (brand_variant_id, item_name, sku, movement_type, qty, unit_cost,
           reference_type, reference_id, notes)
        SELECT v_bv_id, ii.name_en, ii.sku,
               'receival_edit', -ABS(v_delta), v_old_cost,
               'receival_edit_request', p_edit_request_id,
               'Qty decrease edit on receival ' || v_req.receival_id
        FROM inventory_brand_variants ibv
        JOIN inventory_items ii ON ii.id = ibv.item_id
        WHERE ibv.id = v_bv_id;
      END IF;
    END IF;

    -- ── UNIT COST CHANGE ──────────────────────────────────────────────────────
    IF v_new_cost <> v_old_cost THEN
      IF v_has_applied_lc THEN
        RAISE EXCEPTION 'Cannot change unit cost: an applied Landed Cost references this receival. Void the LC first.';
      END IF;

      SELECT COALESCE(SUM(qty - remaining_qty), 0) INTO v_sold_qty
      FROM fifo_cost_layers
      WHERE receival_id = v_req.receival_id::TEXT AND brand_variant_id = v_bv_id;

      IF v_sold_qty > 0 THEN
        UPDATE cogs_entries
        SET unit_cost  = v_new_cost,
            total_cost = v_new_cost * qty
        WHERE id IN (
          SELECT id FROM cogs_entries
          WHERE brand_variant_id = v_bv_id
            AND unit_cost = v_old_cost
            AND date >= v_receival_date
          ORDER BY date ASC
          LIMIT v_sold_qty
        );
      END IF;

      UPDATE fifo_cost_layers
      SET unit_cost       = v_new_cost,
          total_unit_cost = v_new_cost + landed_cost_per_unit
      WHERE receival_id = v_req.receival_id::TEXT AND brand_variant_id = v_bv_id;
    END IF;

    PERFORM recalc_average_cost(v_bv_id);

    IF v_delta < 0 THEN
      FOR v_lc_rec IN
        SELECT id, attached_receival_ids FROM landed_costs
        WHERE v_req.receival_id = ANY(attached_receival_ids)
          AND applied_at IS NULL AND voided_at IS NULL
      LOOP
        SELECT COALESCE(SUM(fcl.remaining_qty), 0) INTO v_total_remaining
        FROM fifo_cost_layers fcl
        WHERE fcl.receival_id = ANY(
          SELECT unnest(v_lc_rec.attached_receival_ids)::TEXT
        );
        IF v_total_remaining = 0 THEN
          UPDATE landed_costs SET all_items_sold = TRUE, updated_at = now()
          WHERE id = v_lc_rec.id;
        END IF;
      END LOOP;
    END IF;

    UPDATE receival_items
    SET qty_received = v_new_qty, unit_cost = v_new_cost
    WHERE id = (v_item_input->>'receival_item_id')::UUID;

  END LOOP;

  -- ── 5. Mark edit request as completed ──────────────────────────────────────
  UPDATE receival_edit_requests
  SET status = 'completed'
  WHERE id = p_edit_request_id;

  RETURN jsonb_build_object('ok', true);
END;
$$;


-- ============================================================
-- Source: 20260630120000_fix_credit_approval_set_customer_type.sql
-- ============================================================
-- Fix: when a credit group change request is approved (normal, force, or auto),
-- the customer's customer_type must flip to 'credit'. Previously only
-- credit_group_id was updated, leaving customer_type = 'cash' — which caused
-- create_sale_order to skip the credit check even after approval.
--
-- Cash is the default state (customer_type = 'cash', credit_group_id = NULL).
-- A customer stays cash until their credit group request is fully approved.

BEGIN;

-- ── 1. submit: auto-approve when no workflow steps configured ─────────────

CREATE OR REPLACE FUNCTION public.submit_credit_group_change(
  p_customer_id        uuid,
  p_requested_group_id uuid
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_customer        RECORD;
  v_new_group       RECORD;
  v_profile_id      uuid;
  v_request_id      uuid;
  v_step            RECORD;
  v_step_count      integer := 0;
BEGIN
  SELECT id INTO v_profile_id FROM profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT id, credit_group_id,
         cr_url,
         establishment_id_url,
         signed_credit_form_url
    INTO v_customer
  FROM customers
  WHERE id = p_customer_id;
  IF v_customer.id IS NULL THEN
    RAISE EXCEPTION 'Customer not found';
  END IF;

  SELECT id, name, credit_limit INTO v_new_group
  FROM credit_groups WHERE id = p_requested_group_id;
  IF v_new_group.id IS NULL THEN
    RAISE EXCEPTION 'Credit group not found';
  END IF;

  IF COALESCE(v_new_group.credit_limit, 0) = 0 THEN
    RAISE EXCEPTION 'Approval only required for credit groups with a non-zero limit. Assign this group directly.';
  END IF;

  IF v_customer.credit_group_id = p_requested_group_id THEN
    RAISE EXCEPTION 'Customer is already on this credit group';
  END IF;

  IF v_customer.cr_url IS NULL
     OR v_customer.establishment_id_url IS NULL
     OR v_customer.signed_credit_form_url IS NULL THEN
    RAISE EXCEPTION 'Upload all 3 required docs first (CR, Establishment ID, Signed Credit Form)'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1 FROM customer_credit_group_requests
    WHERE customer_id = p_customer_id AND status = 'pending'
  ) THEN
    RAISE EXCEPTION 'There is already a pending credit-group change for this customer';
  END IF;

  INSERT INTO customer_credit_group_requests (
    customer_id, requested_group_id, previous_group_id, status, requested_by
  ) VALUES (
    p_customer_id, p_requested_group_id, v_customer.credit_group_id, 'pending', v_profile_id
  )
  RETURNING id INTO v_request_id;

  FOR v_step IN
    SELECT was.step_order, cr.name AS role_name
    FROM   approval_workflow_steps was
    JOIN   custom_roles            cr ON cr.id = was.role_id
    WHERE  was.workflow    = 'credit_group'
      AND  was.is_active   = true
      AND  was.archived_at IS NULL
    ORDER BY was.step_order
  LOOP
    INSERT INTO customer_credit_group_approvals (
      request_id, step_role, step_order, status, is_active, iteration
    ) VALUES (
      v_request_id, v_step.role_name, v_step.step_order, 'pending', true, 1
    );
    v_step_count := v_step_count + 1;
  END LOOP;

  IF v_step_count = 0 THEN
    -- No steps configured → auto-approve
    UPDATE customers
       SET credit_group_id = p_requested_group_id,
           customer_type   = 'credit',
           is_blocked      = false,
           block_reason    = NULL
     WHERE id = p_customer_id;
    UPDATE customer_credit_group_requests
      SET status = 'approved', decided_by = v_profile_id, decided_at = now()
      WHERE id = v_request_id;
  ELSE
    -- Block new customers (no previous group) while approval is pending
    IF v_customer.credit_group_id IS NULL THEN
      UPDATE customers
         SET is_blocked   = true,
             block_reason = 'Pending credit group approval'
       WHERE id = p_customer_id;
    END IF;
  END IF;

  INSERT INTO public.activity_log (action, module, entity_type, entity_id, performer_name, severity, details)
  VALUES (
    'Credit Group Change Requested',
    'customers',
    'customer',
    p_customer_id,
    (SELECT full_name FROM profiles WHERE id = v_profile_id),
    'info',
    jsonb_build_object(
      'request_id',       v_request_id,
      'requested_group',  v_new_group.name,
      'previous_group_id',v_customer.credit_group_id,
      'auto_approved',    v_step_count = 0
    )::text
  );

  RETURN jsonb_build_object(
    'request_id',  v_request_id,
    'step_count',  v_step_count,
    'status',      CASE WHEN v_step_count = 0 THEN 'approved' ELSE 'pending' END
  );
END;
$$;

-- ── 2. approve: set customer_type = 'credit' on full chain completion ─────

CREATE OR REPLACE FUNCTION public.approve_credit_group_change(
  p_approval_id uuid,
  p_comment     text DEFAULT NULL
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_row            RECORD;
  v_request        RECORD;
  v_profile_id     uuid;
  v_full_name      TEXT;
  v_all_done       BOOLEAN;
BEGIN
  SELECT id, full_name INTO v_profile_id, v_full_name
  FROM   profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT * INTO v_row FROM customer_credit_group_approvals
    WHERE id = p_approval_id FOR UPDATE;
  IF NOT FOUND OR v_row.status <> 'pending' OR NOT v_row.is_active THEN
    RAISE EXCEPTION 'Approval step not actionable';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM   user_custom_roles ucr
    JOIN   custom_roles cr ON cr.id = ucr.role_id
    WHERE  ucr.profile_id        = v_profile_id
      AND  cr.name               = v_row.step_role
      AND  cr.is_approval_slot   = true
      AND  cr.deleted_at         IS NULL
      AND  (ucr.approval_scopes IS NULL
            OR 'credit_group' = ANY(ucr.approval_scopes))
  ) THEN
    RAISE EXCEPTION 'You do not hold the role required for this approval step';
  END IF;

  IF EXISTS (
    SELECT 1 FROM customer_credit_group_approvals
    WHERE  request_id  = v_row.request_id
      AND  iteration   = v_row.iteration
      AND  decided_by  = v_profile_id
      AND  id          <> p_approval_id
  ) THEN
    RAISE EXCEPTION 'You have already actioned another step on this request';
  END IF;

  UPDATE customer_credit_group_approvals
  SET    status          = 'approved',
         decided_by      = v_profile_id,
         decided_by_name = v_full_name,
         decided_at      = now(),
         comment         = p_comment
  WHERE  id = p_approval_id;

  SELECT NOT EXISTS (
    SELECT 1 FROM customer_credit_group_approvals
    WHERE  request_id  = v_row.request_id
      AND  iteration   = v_row.iteration
      AND  status     <> 'approved'
  ) INTO v_all_done;

  IF v_all_done THEN
    SELECT * INTO v_request FROM customer_credit_group_requests
      WHERE id = v_row.request_id FOR UPDATE;

    UPDATE customers
       SET credit_group_id = v_request.requested_group_id,
           customer_type   = 'credit',
           is_blocked      = false,
           block_reason    = NULL
     WHERE id = v_request.customer_id;

    UPDATE customer_credit_group_requests
       SET status     = 'approved',
           decided_by = v_profile_id,
           decided_at = now()
     WHERE id = v_request.id;

    INSERT INTO public.activity_log (action, module, entity_type, entity_id, performer_name, severity, details)
    VALUES (
      'Credit Group Change Approved',
      'customers',
      'customer',
      v_request.customer_id,
      v_full_name,
      'info',
      jsonb_build_object('request_id', v_request.id)::text
    );
  END IF;
END;
$$;

-- ── 3. force-approve: set customer_type = 'credit' ────────────────────────

CREATE OR REPLACE FUNCTION public.force_approve_credit_group_change(
  p_request_id uuid,
  p_comment    text DEFAULT NULL
) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_profile_id   uuid;
  v_full_name    TEXT;
  v_is_owner     BOOLEAN;
  v_request      RECORD;
  v_iteration    INT;
  v_count        INT;
BEGIN
  SELECT id, full_name INTO v_profile_id, v_full_name
  FROM   profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM   user_custom_roles ucr
    JOIN   custom_roles cr ON cr.id = ucr.role_id
    WHERE  ucr.profile_id      = v_profile_id
      AND  cr.name             = 'Owner'
      AND  cr.is_approval_slot = true
      AND  cr.deleted_at       IS NULL
  ) INTO v_is_owner;
  IF NOT v_is_owner THEN
    RAISE EXCEPTION 'Only users with the Owner role can force-approve';
  END IF;

  SELECT * INTO v_request FROM customer_credit_group_requests
    WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Credit-group request not found';
  END IF;
  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'Request is no longer pending (status: %)', v_request.status;
  END IF;

  SELECT COALESCE(MAX(iteration), 1) INTO v_iteration
  FROM   customer_credit_group_approvals
  WHERE  request_id = p_request_id;

  UPDATE customer_credit_group_approvals
  SET    status          = 'approved',
         decided_by      = v_profile_id,
         decided_by_name = v_full_name,
         decided_at      = now(),
         force_approved  = true,
         force_comment   = NULLIF(TRIM(COALESCE(p_comment, '')), ''),
         comment         = COALESCE(comment, p_comment)
  WHERE  request_id = p_request_id
    AND  iteration  = v_iteration
    AND  status     = 'pending'
    AND  is_active  = true;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  IF v_count = 0 THEN
    RAISE EXCEPTION 'No pending steps to force-approve on this request';
  END IF;

  UPDATE customers
     SET credit_group_id = v_request.requested_group_id,
         customer_type   = 'credit',
         is_blocked      = false,
         block_reason    = NULL
   WHERE id = v_request.customer_id;

  UPDATE customer_credit_group_requests
     SET status     = 'approved',
         decided_by = v_profile_id,
         decided_at = now()
   WHERE id = p_request_id;

  INSERT INTO public.activity_log (
    action, module, entity_type, entity_id, performer_name, severity, details
  ) VALUES (
    'Credit Group Change Force-Approved',
    'customers',
    'customer',
    v_request.customer_id,
    v_full_name,
    'critical',
    jsonb_build_object(
      'request_id',     v_request.id,
      'iteration',      v_iteration,
      'forced_count',   v_count,
      'force_comment',  NULLIF(TRIM(COALESCE(p_comment, '')), '')
    )::text
  );

  RETURN v_count;
END;
$$;

NOTIFY pgrst, 'reload schema';

COMMIT;


-- ============================================================
-- Source: 20260630121000_fix_credit_approval_individual_docs.sql
-- ============================================================
-- Fix: submit_credit_group_change required all 3 docs (CR, Establishment ID,
-- Signed Credit Form) regardless of entity_type. Individuals only need the
-- Signed Credit Form; only business entities need all three.
--
-- Also: reject_credit_group_change now unblocks new customers on rejection
-- instead of leaving them permanently blocked.

BEGIN;

-- ── 1. submit: entity-aware doc validation ────────────────────────────────

CREATE OR REPLACE FUNCTION public.submit_credit_group_change(
  p_customer_id        uuid,
  p_requested_group_id uuid
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_customer        RECORD;
  v_new_group       RECORD;
  v_profile_id      uuid;
  v_request_id      uuid;
  v_step            RECORD;
  v_step_count      integer := 0;
BEGIN
  SELECT id INTO v_profile_id FROM profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT id, credit_group_id, entity_type,
         cr_url,
         establishment_id_url,
         signed_credit_form_url
    INTO v_customer
  FROM customers
  WHERE id = p_customer_id;
  IF v_customer.id IS NULL THEN
    RAISE EXCEPTION 'Customer not found';
  END IF;

  SELECT id, name, credit_limit INTO v_new_group
  FROM credit_groups WHERE id = p_requested_group_id;
  IF v_new_group.id IS NULL THEN
    RAISE EXCEPTION 'Credit group not found';
  END IF;

  IF COALESCE(v_new_group.credit_limit, 0) = 0 THEN
    RAISE EXCEPTION 'Approval only required for credit groups with a non-zero limit. Assign this group directly.';
  END IF;

  IF v_customer.credit_group_id = p_requested_group_id THEN
    RAISE EXCEPTION 'Customer is already on this credit group';
  END IF;

  -- Doc gate: business needs all 3, individual needs only signed credit form
  IF COALESCE(v_customer.entity_type, 'individual') = 'business' THEN
    IF v_customer.cr_url IS NULL
       OR v_customer.establishment_id_url IS NULL
       OR v_customer.signed_credit_form_url IS NULL THEN
      RAISE EXCEPTION 'Upload all 3 required docs (CR, Establishment ID, Signed Credit Form) for business customers'
        USING ERRCODE = 'P0001';
    END IF;
  ELSE
    IF v_customer.signed_credit_form_url IS NULL THEN
      RAISE EXCEPTION 'Upload the Signed Credit Form before requesting a credit group'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1 FROM customer_credit_group_requests
    WHERE customer_id = p_customer_id AND status = 'pending'
  ) THEN
    RAISE EXCEPTION 'There is already a pending credit-group change for this customer';
  END IF;

  INSERT INTO customer_credit_group_requests (
    customer_id, requested_group_id, previous_group_id, status, requested_by
  ) VALUES (
    p_customer_id, p_requested_group_id, v_customer.credit_group_id, 'pending', v_profile_id
  )
  RETURNING id INTO v_request_id;

  FOR v_step IN
    SELECT was.step_order, cr.name AS role_name
    FROM   approval_workflow_steps was
    JOIN   custom_roles            cr ON cr.id = was.role_id
    WHERE  was.workflow    = 'credit_group'
      AND  was.is_active   = true
      AND  was.archived_at IS NULL
    ORDER BY was.step_order
  LOOP
    INSERT INTO customer_credit_group_approvals (
      request_id, step_role, step_order, status, is_active, iteration
    ) VALUES (
      v_request_id, v_step.role_name, v_step.step_order, 'pending', true, 1
    );
    v_step_count := v_step_count + 1;
  END LOOP;

  IF v_step_count = 0 THEN
    -- No steps configured → auto-approve
    UPDATE customers
       SET credit_group_id = p_requested_group_id,
           customer_type   = 'credit',
           is_blocked      = false,
           block_reason    = NULL
     WHERE id = p_customer_id;
    UPDATE customer_credit_group_requests
      SET status = 'approved', decided_by = v_profile_id, decided_at = now()
      WHERE id = v_request_id;
  ELSE
    -- Block new customers (no previous group) while approval is pending
    IF v_customer.credit_group_id IS NULL THEN
      UPDATE customers
         SET is_blocked   = true,
             block_reason = 'Pending credit group approval'
       WHERE id = p_customer_id;
    END IF;
  END IF;

  INSERT INTO public.activity_log (action, module, entity_type, entity_id, performer_name, severity, details)
  VALUES (
    'Credit Group Change Requested',
    'customers',
    'customer',
    p_customer_id,
    (SELECT full_name FROM profiles WHERE id = v_profile_id),
    'info',
    jsonb_build_object(
      'request_id',       v_request_id,
      'requested_group',  v_new_group.name,
      'previous_group_id',v_customer.credit_group_id,
      'auto_approved',    v_step_count = 0
    )::text
  );

  RETURN jsonb_build_object(
    'request_id',  v_request_id,
    'step_count',  v_step_count,
    'status',      CASE WHEN v_step_count = 0 THEN 'approved' ELSE 'pending' END
  );
END;
$$;

-- ── 2. reject: unblock customer on rejection ──────────────────────────────

CREATE OR REPLACE FUNCTION public.reject_credit_group_change(
  p_approval_id uuid,
  p_reason      text
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_row        RECORD;
  v_request    RECORD;
  v_profile_id uuid;
  v_full_name  TEXT;
BEGIN
  IF NULLIF(TRIM(p_reason), '') IS NULL THEN
    RAISE EXCEPTION 'A reason is required when rejecting';
  END IF;

  SELECT id, full_name INTO v_profile_id, v_full_name
  FROM   profiles WHERE auth_user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  SELECT * INTO v_row FROM customer_credit_group_approvals
    WHERE id = p_approval_id FOR UPDATE;
  IF NOT FOUND OR v_row.status <> 'pending' OR NOT v_row.is_active THEN
    RAISE EXCEPTION 'Approval step not actionable';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM   user_custom_roles ucr
    JOIN   custom_roles cr ON cr.id = ucr.role_id
    WHERE  ucr.profile_id        = v_profile_id
      AND  cr.name               = v_row.step_role
      AND  cr.is_approval_slot   = true
      AND  cr.deleted_at         IS NULL
      AND  (ucr.approval_scopes IS NULL
            OR 'credit_group' = ANY(ucr.approval_scopes))
  ) THEN
    RAISE EXCEPTION 'You do not hold the role required for this approval step';
  END IF;

  -- Mark this step as rejected
  UPDATE customer_credit_group_approvals
  SET    status          = 'rejected',
         decided_by      = v_profile_id,
         decided_by_name = v_full_name,
         decided_at      = now(),
         reason          = p_reason
  WHERE  id = p_approval_id;

  -- Cancel all sibling pending steps in the same iteration
  UPDATE customer_credit_group_approvals
  SET    status    = 'rejected',
         reason    = 'Cancelled — sibling step rejected',
         is_active = false
  WHERE  request_id = v_row.request_id
    AND  iteration  = v_row.iteration
    AND  status     = 'pending'
    AND  id        <> p_approval_id;

  -- Close the request as rejected
  SELECT * INTO v_request FROM customer_credit_group_requests
    WHERE id = v_row.request_id FOR UPDATE;

  UPDATE customer_credit_group_requests
     SET status     = 'rejected',
         decided_by = v_profile_id,
         decided_at = now()
   WHERE id = v_request.id;

  -- Unblock customer (if they were blocked for pending approval)
  UPDATE customers
     SET is_blocked   = false,
         block_reason = NULL
   WHERE id = v_request.customer_id
     AND is_blocked   = true
     AND block_reason = 'Pending credit group approval';

  INSERT INTO public.activity_log (action, module, entity_type, entity_id, performer_name, severity, details)
  VALUES (
    'Credit Group Change Rejected',
    'customers',
    'customer',
    v_request.customer_id,
    v_full_name,
    'warning',
    jsonb_build_object(
      'request_id', v_request.id,
      'step_role',  v_row.step_role,
      'reason',     p_reason
    )::text
  );
END;
$$;

-- ── 3. Unblock Test 4 and any other stuck customers ───────────────────────

UPDATE customers
   SET is_blocked   = false,
       block_reason = NULL
 WHERE is_blocked   = true
   AND block_reason = 'Pending credit group approval'
   AND NOT EXISTS (
     SELECT 1 FROM customer_credit_group_requests
     WHERE customer_id = customers.id AND status = 'pending'
   );

NOTIFY pgrst, 'reload schema';

COMMIT;


-- ============================================================
-- Source: 20260630122000_customer_is_active.sql
-- ============================================================
-- Add is_active flag to customers. Disabled customers cannot be selected
-- when creating sale orders. All existing customers default to active.

ALTER TABLE public.customers
  ADD COLUMN IF NOT EXISTS is_active boolean NOT NULL DEFAULT true;

COMMENT ON COLUMN public.customers.is_active IS
  'When false, the customer is disabled and cannot be selected for new sale orders.';


-- ============================================================
-- Source: 20260701120000_po_pdf_cache.sql
-- ============================================================
-- Purchase Order PDF cache — pdf_url column, storage bucket, invalidation triggers
-- Mirrors the sales PDF cache pattern from 20260627101900.

-- ── 1. Column ──────────────────────────────────────────────────────────────

ALTER TABLE public.purchase_orders
  ADD COLUMN IF NOT EXISTS pdf_url TEXT;
COMMENT ON COLUMN public.purchase_orders.pdf_url IS
  'Public URL of the generated PO PDF. NULL = needs (re)generating.';

-- ── 2. Storage bucket ──────────────────────────────────────────────────────

INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES ('po-pdfs', 'po-pdfs', true, 10 * 1024 * 1024, ARRAY['application/pdf'])
ON CONFLICT (id) DO UPDATE SET
  public             = EXCLUDED.public,
  file_size_limit    = EXCLUDED.file_size_limit,
  allowed_mime_types = EXCLUDED.allowed_mime_types;

-- Storage policies — public read, service-role write/update
DO $$
DECLARE b TEXT := 'po-pdfs';
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'storage' AND tablename = 'objects'
      AND policyname = b || '_public_read'
  ) THEN
    EXECUTE format(
      'CREATE POLICY %I ON storage.objects FOR SELECT USING (bucket_id = %L)',
      b || '_public_read', b
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'storage' AND tablename = 'objects'
      AND policyname = b || '_service_write'
  ) THEN
    EXECUTE format(
      'CREATE POLICY %I ON storage.objects FOR INSERT TO service_role WITH CHECK (bucket_id = %L)',
      b || '_service_write', b
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'storage' AND tablename = 'objects'
      AND policyname = b || '_service_update'
  ) THEN
    EXECUTE format(
      'CREATE POLICY %I ON storage.objects FOR UPDATE TO service_role USING (bucket_id = %L) WITH CHECK (bucket_id = %L)',
      b || '_service_update', b, b
    );
  END IF;
END$$;

-- ── 3. Invalidation trigger ────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.purchase_orders_invalidate_pdf_cache_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF current_setting('app.skip_pdf_invalidation', true) = 'true' THEN
    RETURN NEW;
  END IF;
  NEW.pdf_url := NULL;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS purchase_orders_invalidate_pdf_cache ON public.purchase_orders;
CREATE TRIGGER purchase_orders_invalidate_pdf_cache
  BEFORE UPDATE ON public.purchase_orders
  FOR EACH ROW
  EXECUTE FUNCTION public.purchase_orders_invalidate_pdf_cache_fn();

-- Cascade from po_line_items: any insert/update/delete nulls the parent PO pdf_url
CREATE OR REPLACE FUNCTION public.po_line_items_invalidate_parent_pdf_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE v_po_id UUID;
BEGIN
  v_po_id := COALESCE(NEW.po_id, OLD.po_id);
  IF v_po_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  UPDATE public.purchase_orders
     SET pdf_url = NULL
   WHERE id = v_po_id
     AND pdf_url IS NOT NULL;
  RETURN COALESCE(NEW, OLD);
END;
$$;

DROP TRIGGER IF EXISTS po_line_items_cascade_pdf_invalidation ON public.po_line_items;
CREATE TRIGGER po_line_items_cascade_pdf_invalidation
  AFTER INSERT OR UPDATE OR DELETE ON public.po_line_items
  FOR EACH ROW
  EXECUTE FUNCTION public.po_line_items_invalidate_parent_pdf_fn();


-- ============================================================
-- Source: 20260701120100_po_pdf_cache_rpc.sql
-- ============================================================
-- PO PDF cache — service-role RPC to write the URL without tripping the
-- invalidation trigger. Mirrors the sales PDF RPCs from 20260627101901.

CREATE OR REPLACE FUNCTION public.set_po_pdf_url(p_id UUID, p_url TEXT)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  PERFORM set_config('app.skip_pdf_invalidation', 'true', true);
  UPDATE public.purchase_orders SET pdf_url = p_url WHERE id = p_id;
END;
$$;

REVOKE ALL ON FUNCTION public.set_po_pdf_url(UUID, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_po_pdf_url(UUID, TEXT) TO service_role;


-- ============================================================
-- Source: 20260702084615_po_pdf_multi_variant_cache.sql
-- ============================================================
-- PO PDF cache — 4 variants (RFQ, Draft, PO, Confirmed PO) + payment hash.
-- Replaces the single pdf_url column and single-arg RPC from 20260701120000/20260701120100.

-- ── 1. Add per-variant URL columns + payment hash ───────────────────────────
ALTER TABLE public.purchase_orders
  ADD COLUMN IF NOT EXISTS pdf_rfq_url       TEXT,
  ADD COLUMN IF NOT EXISTS pdf_draft_url     TEXT,
  ADD COLUMN IF NOT EXISTS pdf_po_url        TEXT,
  ADD COLUMN IF NOT EXISTS pdf_confirmed_url TEXT,
  ADD COLUMN IF NOT EXISTS pdf_payment_hash  TEXT;

COMMENT ON COLUMN public.purchase_orders.pdf_rfq_url       IS 'Public URL of the RFQ variant PDF. NULL = needs (re)generating.';
COMMENT ON COLUMN public.purchase_orders.pdf_draft_url     IS 'Public URL of the Draft PO variant PDF. NULL = needs (re)generating.';
COMMENT ON COLUMN public.purchase_orders.pdf_po_url        IS 'Public URL of the PO variant PDF. NULL = needs (re)generating.';
COMMENT ON COLUMN public.purchase_orders.pdf_confirmed_url IS 'Public URL of the Confirmed PO variant PDF. NULL = needs (re)generating.';
COMMENT ON COLUMN public.purchase_orders.pdf_payment_hash  IS 'Format "count:totalPaid" — hash of the payments used when the po/confirmed PDF was last generated. Mismatch triggers regen.';

-- ── 2. Migrate existing pdf_url → pdf_po_url, then drop the old column ─────
UPDATE public.purchase_orders SET pdf_po_url = pdf_url WHERE pdf_url IS NOT NULL;
ALTER TABLE public.purchase_orders DROP COLUMN IF EXISTS pdf_url;

-- ── 3. Update invalidation trigger — null all 4 URLs + hash ─────────────────
CREATE OR REPLACE FUNCTION public.purchase_orders_invalidate_pdf_cache_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF current_setting('app.skip_pdf_invalidation', true) = 'true' THEN
    RETURN NEW;
  END IF;
  NEW.pdf_rfq_url       := NULL;
  NEW.pdf_draft_url     := NULL;
  NEW.pdf_po_url        := NULL;
  NEW.pdf_confirmed_url := NULL;
  NEW.pdf_payment_hash  := NULL;
  RETURN NEW;
END;
$$;

-- ── 4. Update line-item cascade trigger — null all 4 URLs + hash on parent ──
CREATE OR REPLACE FUNCTION public.po_line_items_invalidate_parent_pdf_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE v_po_id UUID;
BEGIN
  v_po_id := COALESCE(NEW.po_id, OLD.po_id);
  IF v_po_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  UPDATE public.purchase_orders
     SET pdf_rfq_url       = NULL,
         pdf_draft_url     = NULL,
         pdf_po_url        = NULL,
         pdf_confirmed_url = NULL,
         pdf_payment_hash  = NULL
   WHERE id = v_po_id
     AND (pdf_rfq_url IS NOT NULL
       OR pdf_draft_url IS NOT NULL
       OR pdf_po_url IS NOT NULL
       OR pdf_confirmed_url IS NOT NULL
       OR pdf_payment_hash IS NOT NULL);
  RETURN COALESCE(NEW, OLD);
END;
$$;

-- ── 5. Replace RPC with variant-aware version ───────────────────────────────
DROP FUNCTION IF EXISTS public.set_po_pdf_url(UUID, TEXT);

CREATE OR REPLACE FUNCTION public.set_po_pdf_url(
  p_id           UUID,
  p_variant      TEXT,
  p_url          TEXT,
  p_payment_hash TEXT DEFAULT NULL
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  PERFORM set_config('app.skip_pdf_invalidation', 'true', true);

  IF p_variant = 'rfq' THEN
    UPDATE public.purchase_orders SET pdf_rfq_url = p_url WHERE id = p_id;
  ELSIF p_variant = 'draft' THEN
    UPDATE public.purchase_orders SET pdf_draft_url = p_url WHERE id = p_id;
  ELSIF p_variant = 'po' THEN
    UPDATE public.purchase_orders
       SET pdf_po_url = p_url, pdf_payment_hash = p_payment_hash
     WHERE id = p_id;
  ELSIF p_variant = 'confirmed' THEN
    UPDATE public.purchase_orders
       SET pdf_confirmed_url = p_url, pdf_payment_hash = p_payment_hash
     WHERE id = p_id;
  ELSE
    RAISE EXCEPTION 'Invalid PDF variant: %', p_variant;
  END IF;
END;
$$;

REVOKE ALL ON FUNCTION public.set_po_pdf_url(UUID, TEXT, TEXT, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_po_pdf_url(UUID, TEXT, TEXT, TEXT) TO service_role;


-- ============================================================
-- Source: 20260702100808_receival_check_pdf_cache.sql
-- ============================================================
-- Receival Check PDF cache — per-receival PDF only.
-- Blank check sheets never cache (running totals shift with each new receival).

-- ── 1. Cache column ────────────────────────────────────────────────────────
ALTER TABLE public.receivals
  ADD COLUMN IF NOT EXISTS check_sheet_pdf_url TEXT;

COMMENT ON COLUMN public.receivals.check_sheet_pdf_url IS
  'Public URL of the generated Receival Check PDF. NULL = needs (re)generating.';

-- ── 2. Storage bucket ──────────────────────────────────────────────────────
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES ('receival-check-pdfs', 'receival-check-pdfs', true, 10 * 1024 * 1024, ARRAY['application/pdf'])
ON CONFLICT (id) DO UPDATE SET
  public             = EXCLUDED.public,
  file_size_limit    = EXCLUDED.file_size_limit,
  allowed_mime_types = EXCLUDED.allowed_mime_types;

-- ── 3. Storage policies ────────────────────────────────────────────────────
DO $$
DECLARE b TEXT := 'receival-check-pdfs';
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname='storage' AND tablename='objects' AND policyname = b||'_public_read'
  ) THEN
    EXECUTE format(
      'CREATE POLICY %I ON storage.objects FOR SELECT USING (bucket_id = %L)',
      b||'_public_read', b
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname='storage' AND tablename='objects' AND policyname = b||'_service_write'
  ) THEN
    EXECUTE format(
      'CREATE POLICY %I ON storage.objects FOR INSERT TO service_role WITH CHECK (bucket_id = %L)',
      b||'_service_write', b
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname='storage' AND tablename='objects' AND policyname = b||'_service_update'
  ) THEN
    EXECUTE format(
      'CREATE POLICY %I ON storage.objects FOR UPDATE TO service_role USING (bucket_id = %L) WITH CHECK (bucket_id = %L)',
      b||'_service_update', b, b
    );
  END IF;
END$$;

-- ── 4. Invalidation trigger on receivals UPDATE ─────────────────────────────
CREATE OR REPLACE FUNCTION public.receivals_invalidate_check_pdf_fn()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  IF current_setting('app.skip_pdf_invalidation', true) = 'true' THEN
    RETURN NEW;
  END IF;
  NEW.check_sheet_pdf_url := NULL;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS receivals_invalidate_check_pdf ON public.receivals;
CREATE TRIGGER receivals_invalidate_check_pdf
  BEFORE UPDATE ON public.receivals
  FOR EACH ROW EXECUTE FUNCTION public.receivals_invalidate_check_pdf_fn();

-- ── 5. Cascade from receival_items → null parent URL ────────────────────────
CREATE OR REPLACE FUNCTION public.receival_items_invalidate_parent_pdf_fn()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE v_receival_id UUID;
BEGIN
  v_receival_id := COALESCE(NEW.receival_id, OLD.receival_id);
  IF v_receival_id IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;
  UPDATE public.receivals
     SET check_sheet_pdf_url = NULL
   WHERE id = v_receival_id
     AND check_sheet_pdf_url IS NOT NULL;
  RETURN COALESCE(NEW, OLD);
END;
$$;

DROP TRIGGER IF EXISTS receival_items_cascade_check_pdf_invalidation ON public.receival_items;
CREATE TRIGGER receival_items_cascade_check_pdf_invalidation
  AFTER INSERT OR UPDATE OR DELETE ON public.receival_items
  FOR EACH ROW EXECUTE FUNCTION public.receival_items_invalidate_parent_pdf_fn();

-- ── 6. RPC to persist cache URL without tripping invalidation ───────────────
CREATE OR REPLACE FUNCTION public.set_receival_check_pdf_url(p_id UUID, p_url TEXT)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  PERFORM set_config('app.skip_pdf_invalidation', 'true', true);
  UPDATE public.receivals SET check_sheet_pdf_url = p_url WHERE id = p_id;
END;
$$;

REVOKE ALL ON FUNCTION public.set_receival_check_pdf_url(UUID, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_receival_check_pdf_url(UUID, TEXT) TO service_role;


