-- ============================================================
-- Source: 20260703120000_debit_credit_notes_split.sql
-- ============================================================
-- Debit / Credit Notes split — add PO reference, replacement receival support, permission backfill
--
-- NOTE: this project has no standalone `permissions` table — permission slugs are defined in
-- src/lib/permissions.ts (PERMISSION_GROUPS) and stored as plain TEXT[] on custom_roles.permissions.
-- The new 'purchase.debit_notes.view' slug is registered there; this migration only backfills
-- existing roles that already had 'purchase.returns.view'.

-- 1. credit_notes: add purchase_order_id for debit notes
ALTER TABLE credit_notes
  ADD COLUMN IF NOT EXISTS purchase_order_id uuid
  REFERENCES purchase_orders(id);

CREATE INDEX IF NOT EXISTS idx_credit_notes_po_id
  ON credit_notes(purchase_order_id)
  WHERE purchase_order_id IS NOT NULL;

-- 2. receivals: replacement receival support
ALTER TABLE receivals
  ADD COLUMN IF NOT EXISTS is_replacement boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS source_debit_note_id uuid
  REFERENCES credit_notes(id);

-- 3. Backfill: any role with purchase.returns.view also gets debit_notes.view
UPDATE custom_roles
SET    permissions = permissions || ARRAY['purchase.debit_notes.view']
WHERE  deleted_at IS NULL
  AND  NOT ('purchase.debit_notes.view' = ANY(permissions))
  AND  'purchase.returns.view' = ANY(permissions);


-- ============================================================
-- Source: 20260703140000_sale_delivery_credit_note_fk.sql
-- ============================================================
-- Add direct FK from replacement deliveries back to the credit note that triggered them.
-- The existing `return_id` links to the return, which links to the credit note indirectly.
-- This FK provides a direct link for faster queries and data integrity.

ALTER TABLE sale_deliveries
  ADD COLUMN IF NOT EXISTS source_credit_note_id uuid
  REFERENCES credit_notes(id);

CREATE INDEX IF NOT EXISTS idx_sale_deliveries_credit_note_id
  ON sale_deliveries(source_credit_note_id)
  WHERE source_credit_note_id IS NOT NULL;


-- ============================================================
-- Source: 20260704120000_fix_delivery_delivered_qty.sql
-- ============================================================
-- Fix: complete_delivery_inventory must increment delivered_qty on
-- sale_order_lines so the delivery progress column is accurate.
-- The cancel function already decrements it; this was the missing counterpart.

CREATE OR REPLACE FUNCTION complete_delivery_inventory(
  p_delivery_id UUID,
  p_so_id       UUID
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_delivery  RECORD;
  v_item      JSONB;
  v_bv_id     UUID;
  v_qty       INT;
  v_wh_id     UUID;
  v_date      DATE;
  v_result    RECORD;
BEGIN
  SELECT warehouse_id, date, items, status
  INTO v_delivery
  FROM sale_deliveries
  WHERE id = p_delivery_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Delivery % not found', p_delivery_id;
  END IF;

  IF v_delivery.status <> 'pending' THEN
    RAISE EXCEPTION 'Delivery % already processed with status %', p_delivery_id, v_delivery.status;
  END IF;

  v_wh_id := v_delivery.warehouse_id;
  v_date  := COALESCE(v_delivery.date, CURRENT_DATE);

  UPDATE sale_deliveries SET status = 'delivered', updated_at = now() WHERE id = p_delivery_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_delivery.items)
  LOOP
    v_bv_id := (v_item->>'brand_variant_id')::UUID;
    v_qty   := (v_item->>'qty_delivered')::INT;

    CONTINUE WHEN v_bv_id IS NULL OR v_qty IS NULL OR v_qty <= 0;

    SELECT total_cost, weighted_unit_cost
    INTO v_result
    FROM deduct_fifo_layers(v_bv_id, v_wh_id, v_qty, false);

    UPDATE inventory_brand_variants
    SET reserved_qty = GREATEST(0, reserved_qty - v_qty),
        updated_at   = now()
    WHERE id = v_bv_id;

    -- Increment delivered_qty on the matching SO line
    UPDATE sale_order_lines
    SET    delivered_qty = COALESCE(delivered_qty, 0) + v_qty
    WHERE  sale_order_id = p_so_id
      AND  brand_variant_id = v_bv_id;

    INSERT INTO cogs_entries (
      brand_variant_id, sale_delivery_id, sale_order_id,
      qty, unit_cost, total_cost, date
    ) VALUES (
      v_bv_id, p_delivery_id, p_so_id,
      v_qty, v_result.weighted_unit_cost, v_result.total_cost, v_date
    );

    INSERT INTO inventory_stock_movements (
      warehouse_id, brand_variant_id,
      item_name, sku, movement_type, qty, unit_cost,
      reference_type, reference_id
    ) VALUES (
      v_wh_id, v_bv_id,
      COALESCE(v_item->>'item_name', ''),
      v_item->>'sku',
      'sale_delivery', -v_qty, v_result.weighted_unit_cost,
      'sale_delivery', p_delivery_id
    );
  END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION complete_delivery_inventory(UUID, UUID) TO authenticated;

-- Backfill delivered_qty for existing delivered deliveries
WITH delivered_items AS (
  SELECT
    sd.sale_order_id,
    (item->>'brand_variant_id')::UUID AS brand_variant_id,
    SUM((item->>'qty_delivered')::INT) AS total_delivered
  FROM sale_deliveries sd,
       jsonb_array_elements(sd.items) AS item
  WHERE sd.status = 'delivered'
    AND (item->>'brand_variant_id') IS NOT NULL
    AND (item->>'qty_delivered')::INT > 0
  GROUP BY sd.sale_order_id, (item->>'brand_variant_id')::UUID
)
UPDATE sale_order_lines sol
SET delivered_qty = di.total_delivered
FROM delivered_items di
WHERE sol.sale_order_id = di.sale_order_id
  AND sol.brand_variant_id = di.brand_variant_id;


-- ============================================================
-- Source: 20260704130000_so_status_on_delivery.sql
-- ============================================================
-- After completing a delivery, update the SO status to 'delivered' or 'partial_delivery'
-- based on whether all lines are fully delivered.
-- Also fix cancel_delivery_inventory to revert SO status accordingly.

CREATE OR REPLACE FUNCTION complete_delivery_inventory(
  p_delivery_id UUID,
  p_so_id       UUID
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_delivery  RECORD;
  v_item      JSONB;
  v_bv_id     UUID;
  v_qty       INT;
  v_wh_id     UUID;
  v_date      DATE;
  v_result    RECORD;
  v_all_delivered BOOLEAN;
  v_any_delivered BOOLEAN;
BEGIN
  SELECT warehouse_id, date, items, status
  INTO v_delivery
  FROM sale_deliveries
  WHERE id = p_delivery_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Delivery % not found', p_delivery_id;
  END IF;

  IF v_delivery.status <> 'pending' THEN
    RAISE EXCEPTION 'Delivery % already processed with status %', p_delivery_id, v_delivery.status;
  END IF;

  v_wh_id := v_delivery.warehouse_id;
  v_date  := COALESCE(v_delivery.date, CURRENT_DATE);

  UPDATE sale_deliveries SET status = 'delivered', updated_at = now() WHERE id = p_delivery_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_delivery.items)
  LOOP
    v_bv_id := (v_item->>'brand_variant_id')::UUID;
    v_qty   := (v_item->>'qty_delivered')::INT;

    CONTINUE WHEN v_bv_id IS NULL OR v_qty IS NULL OR v_qty <= 0;

    SELECT total_cost, weighted_unit_cost
    INTO v_result
    FROM deduct_fifo_layers(v_bv_id, v_wh_id, v_qty, false);

    UPDATE inventory_brand_variants
    SET reserved_qty = GREATEST(0, reserved_qty - v_qty),
        updated_at   = now()
    WHERE id = v_bv_id;

    UPDATE sale_order_lines
    SET    delivered_qty = COALESCE(delivered_qty, 0) + v_qty
    WHERE  sale_order_id = p_so_id
      AND  brand_variant_id = v_bv_id;

    INSERT INTO cogs_entries (
      brand_variant_id, sale_delivery_id, sale_order_id,
      qty, unit_cost, total_cost, date
    ) VALUES (
      v_bv_id, p_delivery_id, p_so_id,
      v_qty, v_result.weighted_unit_cost, v_result.total_cost, v_date
    );

    INSERT INTO inventory_stock_movements (
      warehouse_id, brand_variant_id,
      item_name, sku, movement_type, qty, unit_cost,
      reference_type, reference_id
    ) VALUES (
      v_wh_id, v_bv_id,
      COALESCE(v_item->>'item_name', ''),
      v_item->>'sku',
      'sale_delivery', -v_qty, v_result.weighted_unit_cost,
      'sale_delivery', p_delivery_id
    );
  END LOOP;

  -- Update SO status based on delivery progress
  SELECT
    bool_and(COALESCE(delivered_qty, 0) >= qty),
    bool_or(COALESCE(delivered_qty, 0) > 0)
  INTO v_all_delivered, v_any_delivered
  FROM sale_order_lines
  WHERE sale_order_id = p_so_id;

  IF v_all_delivered THEN
    UPDATE sale_orders
    SET    status = 'delivered', updated_at = now()
    WHERE  id = p_so_id
      AND  status IN ('confirmed', 'partial_delivery');
  ELSIF v_any_delivered THEN
    UPDATE sale_orders
    SET    status = 'partial_delivery', updated_at = now()
    WHERE  id = p_so_id
      AND  status = 'confirmed';
  END IF;
END;
$$;

GRANT EXECUTE ON FUNCTION complete_delivery_inventory(UUID, UUID) TO authenticated;

-- Backfill SO statuses for existing data
WITH so_delivery_status AS (
  SELECT
    sol.sale_order_id,
    bool_and(COALESCE(sol.delivered_qty, 0) >= sol.qty) AS all_delivered,
    bool_or(COALESCE(sol.delivered_qty, 0) > 0) AS any_delivered
  FROM sale_order_lines sol
  JOIN sale_orders so ON so.id = sol.sale_order_id
  WHERE so.status IN ('confirmed', 'partial_delivery')
    AND so.deleted_at IS NULL
  GROUP BY sol.sale_order_id
)
UPDATE sale_orders so
SET    status = CASE
         WHEN sds.all_delivered THEN 'delivered'::sale_order_status
         WHEN sds.any_delivered THEN 'partial_delivery'::sale_order_status
         ELSE so.status
       END,
       updated_at = now()
FROM so_delivery_status sds
WHERE so.id = sds.sale_order_id
  AND (sds.all_delivered OR sds.any_delivered);


-- ============================================================
-- Source: 20260704140000_fix_delivered_qty_backfill.sql
-- ============================================================
-- Fix backfill: the previous migration skipped delivery items with NULL brand_variant_id.
-- This version also handles matching by item_name when brand_variant_id is NULL.

-- Step 1: Backfill by brand_variant_id (non-null)
WITH delivered_items AS (
  SELECT
    sd.sale_order_id,
    (item->>'brand_variant_id')::UUID AS brand_variant_id,
    SUM((item->>'qty_delivered')::INT) AS total_delivered
  FROM sale_deliveries sd,
       jsonb_array_elements(sd.items) AS item
  WHERE sd.status = 'delivered'
    AND (item->>'brand_variant_id') IS NOT NULL
    AND (item->>'qty_delivered')::INT > 0
  GROUP BY sd.sale_order_id, (item->>'brand_variant_id')::UUID
)
UPDATE sale_order_lines sol
SET delivered_qty = di.total_delivered
FROM delivered_items di
WHERE sol.sale_order_id = di.sale_order_id
  AND sol.brand_variant_id = di.brand_variant_id;

-- Step 2: Backfill by item_name for items without brand_variant_id
WITH delivered_items_by_name AS (
  SELECT
    sd.sale_order_id,
    item->>'item_name' AS item_name,
    SUM((item->>'qty_delivered')::INT) AS total_delivered
  FROM sale_deliveries sd,
       jsonb_array_elements(sd.items) AS item
  WHERE sd.status = 'delivered'
    AND (item->>'brand_variant_id') IS NULL
    AND (item->>'qty_delivered')::INT > 0
  GROUP BY sd.sale_order_id, item->>'item_name'
)
UPDATE sale_order_lines sol
SET delivered_qty = di.total_delivered
FROM delivered_items_by_name di
WHERE sol.sale_order_id = di.sale_order_id
  AND sol.item_name = di.item_name
  AND sol.brand_variant_id IS NULL
  AND COALESCE(sol.delivered_qty, 0) = 0;

-- Step 3: Re-run SO status backfill with corrected delivered_qty
WITH so_delivery_status AS (
  SELECT
    sol.sale_order_id,
    bool_and(COALESCE(sol.delivered_qty, 0) >= sol.qty) AS all_delivered,
    bool_or(COALESCE(sol.delivered_qty, 0) > 0) AS any_delivered
  FROM sale_order_lines sol
  JOIN sale_orders so ON so.id = sol.sale_order_id
  WHERE so.deleted_at IS NULL
    AND so.status NOT IN ('cancelled', 'invoiced', 'closed')
  GROUP BY sol.sale_order_id
)
UPDATE sale_orders so
SET    status = CASE
         WHEN sds.all_delivered THEN 'delivered'::sale_order_status
         WHEN sds.any_delivered THEN 'partial_delivery'::sale_order_status
         ELSE so.status
       END,
       updated_at = now()
FROM so_delivery_status sds
WHERE so.id = sds.sale_order_id
  AND (
    (sds.all_delivered AND so.status <> 'delivered')
    OR (sds.any_delivered AND NOT sds.all_delivered AND so.status NOT IN ('delivered', 'partial_delivery'))
  );


-- ============================================================
-- Source: 20260704150000_fifo_source_type.sql
-- ============================================================
-- Add source_type column to fifo_cost_layers so the UI can show
-- where each layer came from (receival, adjustment, transfer, etc.)

ALTER TABLE fifo_cost_layers
  ADD COLUMN IF NOT EXISTS source_type text DEFAULT 'receival';

-- Backfill: layers with receival_id are from receivals; the rest are unknowns
-- We can't perfectly determine the source of existing non-receival layers,
-- but we can mark receival ones definitively.
UPDATE fifo_cost_layers
SET source_type = 'receival'
WHERE receival_id IS NOT NULL
  AND source_type IS DISTINCT FROM 'receival';

UPDATE fifo_cost_layers
SET source_type = 'unknown'
WHERE receival_id IS NULL
  AND source_type = 'receival';

-- Rename column header in the UI is done in code
-- Going forward, all RPCs that create layers will set source_type.

-- Update create_and_approve_receival to set source_type
-- (Already sets receival_id so it defaults correctly)

-- Update apply_adjustment to set source_type = 'adjustment'
CREATE OR REPLACE FUNCTION apply_adjustment(p_adjustment_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_adj    RECORD;
  v_qty    INT;
  v_bv     RECORD;
BEGIN
  SELECT * INTO v_adj
  FROM inventory_adjustments
  WHERE id = p_adjustment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Adjustment not found';
  END IF;

  IF v_adj.status <> 'pending' THEN
    RAISE EXCEPTION 'Adjustment already processed';
  END IF;

  v_qty := ABS(v_adj.qty);

  IF v_adj.adjustment_type = 'increase' THEN
    SELECT average_cost INTO v_bv
    FROM inventory_brand_variants WHERE id = v_adj.brand_variant_id;

    INSERT INTO fifo_cost_layers (
      brand_variant_id, warehouse_id, date,
      qty, unit_cost, landed_cost_per_unit, total_unit_cost, remaining_qty,
      source_type
    ) VALUES (
      v_adj.brand_variant_id, v_adj.warehouse_id, CURRENT_DATE,
      v_qty, COALESCE(v_bv.average_cost, 0), 0, COALESCE(v_bv.average_cost, 0), v_qty,
      'adjustment'
    );

    UPDATE inventory_brand_variants
    SET stock_level = stock_level + v_qty,
        updated_at  = now()
    WHERE id = v_adj.brand_variant_id;

    INSERT INTO inventory_stock_movements (
      warehouse_id, brand_variant_id,
      item_name, sku, movement_type, qty, unit_cost,
      reference_type, reference_id
    )
    SELECT
      v_adj.warehouse_id, v_adj.brand_variant_id,
      ibv.item_name, ibv.sku,
      'adjustment_in', v_qty, COALESCE(v_bv.average_cost, 0),
      'adjustment', p_adjustment_id
    FROM inventory_brand_variants ibv
    WHERE ibv.id = v_adj.brand_variant_id;

  ELSE
    PERFORM deduct_fifo_layers(v_adj.brand_variant_id, v_adj.warehouse_id, v_qty, TRUE);

    INSERT INTO inventory_stock_movements (
      warehouse_id, brand_variant_id,
      item_name, sku, movement_type, qty, unit_cost,
      reference_type, reference_id
    )
    SELECT
      v_adj.warehouse_id, v_adj.brand_variant_id,
      ibv.item_name, ibv.sku,
      'adjustment_out', -v_qty, ibv.average_cost,
      'adjustment', p_adjustment_id
    FROM inventory_brand_variants ibv
    WHERE ibv.id = v_adj.brand_variant_id;
  END IF;

  PERFORM recalc_average_cost(v_adj.brand_variant_id);

  UPDATE inventory_adjustments
  SET status = 'applied', updated_at = now()
  WHERE id = p_adjustment_id;
END;
$$;

GRANT EXECUTE ON FUNCTION apply_adjustment(UUID) TO authenticated;

-- Update cancel_delivery_inventory to set source_type = 'delivery_cancel' on restored layers
-- (Already defined in an earlier migration — just adding source_type)


-- ============================================================
-- Source: 20260704160000_backfill_fifo_source_type.sql
-- ============================================================
-- Better backfill: identify source_type for existing layers by cross-referencing
-- inventory_stock_movements and other tables.

-- Layers from delivery cancellations: match by brand_variant_id + date + qty
-- against cogs_entries that have a sale_delivery_id
UPDATE fifo_cost_layers fcl
SET source_type = 'delivery_cancel'
WHERE fcl.source_type = 'unknown'
  AND fcl.receival_id IS NULL
  AND EXISTS (
    SELECT 1 FROM cogs_entries ce
    JOIN sale_deliveries sd ON sd.id = ce.sale_delivery_id
    WHERE ce.brand_variant_id = fcl.brand_variant_id
      AND sd.status = 'cancelled'
      AND ce.qty = fcl.qty
      AND ABS(ce.unit_cost - fcl.unit_cost) < 0.01
  );

-- Layers from warehouse transfers: match movements with 'transfer_in'
UPDATE fifo_cost_layers fcl
SET source_type = 'transfer'
WHERE fcl.source_type = 'unknown'
  AND fcl.receival_id IS NULL
  AND EXISTS (
    SELECT 1 FROM inventory_stock_movements ism
    WHERE ism.brand_variant_id = fcl.brand_variant_id
      AND ism.warehouse_id = fcl.warehouse_id
      AND ism.movement_type = 'transfer_in'
      AND ism.qty = fcl.qty
      AND ABS(ism.unit_cost - fcl.unit_cost) < 0.01
  );

-- Layers from adjustments: match movements with 'adjustment_in'
UPDATE fifo_cost_layers fcl
SET source_type = 'adjustment'
WHERE fcl.source_type = 'unknown'
  AND fcl.receival_id IS NULL
  AND EXISTS (
    SELECT 1 FROM inventory_stock_movements ism
    WHERE ism.brand_variant_id = fcl.brand_variant_id
      AND ism.warehouse_id = fcl.warehouse_id
      AND ism.movement_type = 'adjustment_in'
      AND ism.qty = fcl.qty
  );

-- Layers from stock checks: match movements with 'stock_check_in'
UPDATE fifo_cost_layers fcl
SET source_type = 'stock_check'
WHERE fcl.source_type = 'unknown'
  AND fcl.receival_id IS NULL
  AND EXISTS (
    SELECT 1 FROM inventory_stock_movements ism
    WHERE ism.brand_variant_id = fcl.brand_variant_id
      AND ism.warehouse_id = fcl.warehouse_id
      AND ism.movement_type = 'stock_check_in'
      AND ism.qty = fcl.qty
  );

-- Anything still unknown that has date = '2000-01-01' is a gap-fill from deduct_fifo_layers
UPDATE fifo_cost_layers
SET source_type = 'gap_fill'
WHERE source_type = 'unknown'
  AND receival_id IS NULL
  AND date = '2000-01-01';


-- ============================================================
-- Source: 20260704170000_category_stock_aggregates.sql
-- ============================================================
-- Returns aggregated stock data for all categories, rolling up from brand variants
-- through items and subcategories recursively.

CREATE OR REPLACE FUNCTION get_category_stock_aggregates(p_type text)
RETURNS TABLE (
  category_id  UUID,
  total_stock  BIGINT,
  total_reserved BIGINT,
  total_damaged BIGINT,
  total_incoming BIGINT,
  avg_cost     NUMERIC,
  variant_count BIGINT
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  WITH RECURSIVE cat_tree AS (
    SELECT id, parent_id
    FROM inventory_categories
    WHERE type = p_type::inventory_type AND status <> 'archived'

    UNION ALL

    SELECT child.id, child.parent_id
    FROM inventory_categories child
    JOIN cat_tree parent ON child.parent_id = parent.id
    WHERE child.status <> 'archived'
  ),
  -- Map each leaf category to all its ancestors (including itself)
  leaf_cats AS (
    SELECT id FROM inventory_categories
    WHERE type = p_type::inventory_type AND status <> 'archived'
  ),
  -- Get stock per leaf category from brand variants
  leaf_stock AS (
    SELECT
      ii.category_id,
      COALESCE(SUM(ibv.stock_level), 0) AS total_stock,
      COALESCE(SUM(ibv.reserved_qty), 0) AS total_reserved,
      COALESCE(SUM(ibv.damaged_qty), 0) AS total_damaged,
      COALESCE(SUM(ibv.incoming), 0) AS total_incoming,
      CASE WHEN COUNT(ibv.id) > 0
        THEN ROUND(SUM(ibv.average_cost * ibv.stock_level) / NULLIF(SUM(ibv.stock_level), 0), 2)
        ELSE 0
      END AS avg_cost,
      COUNT(ibv.id) AS variant_count
    FROM inventory_items ii
    JOIN inventory_brand_variants ibv ON ibv.item_id = ii.id
    WHERE ii.status <> 'archived'
      AND ibv.status <> 'archived'
    GROUP BY ii.category_id
  ),
  -- Expand: for each ancestor, sum the stock of all its descendant leaf categories
  ancestors_expanded AS (
    SELECT
      ancestor.id AS ancestor_id,
      ls.total_stock,
      ls.total_reserved,
      ls.total_damaged,
      ls.total_incoming,
      ls.avg_cost,
      ls.variant_count,
      ls.total_stock AS weighted_cost_numerator
    FROM leaf_stock ls
    JOIN (
      WITH RECURSIVE climb AS (
        SELECT id, id AS leaf_id FROM leaf_cats
        UNION ALL
        SELECT ic.parent_id, climb.leaf_id
        FROM climb
        JOIN inventory_categories ic ON ic.id = climb.id
        WHERE ic.parent_id IS NOT NULL
      )
      SELECT id AS id, leaf_id FROM climb
    ) ancestor ON ancestor.leaf_id = ls.category_id
  )
  SELECT
    ae.ancestor_id AS category_id,
    SUM(ae.total_stock)::BIGINT AS total_stock,
    SUM(ae.total_reserved)::BIGINT AS total_reserved,
    SUM(ae.total_damaged)::BIGINT AS total_damaged,
    SUM(ae.total_incoming)::BIGINT AS total_incoming,
    CASE WHEN SUM(ae.total_stock) > 0
      THEN ROUND(SUM(ae.avg_cost * ae.total_stock) / SUM(ae.total_stock), 2)
      ELSE 0
    END AS avg_cost,
    SUM(ae.variant_count)::BIGINT AS variant_count
  FROM ancestors_expanded ae
  GROUP BY ae.ancestor_id;
$$;

GRANT EXECUTE ON FUNCTION get_category_stock_aggregates(text) TO authenticated;


