-- Source: 20260704180000_category_description.sql
-- ============================================================
-- Add description column to inventory_categories for internal notes
ALTER TABLE inventory_categories
  ADD COLUMN IF NOT EXISTS description text;


-- ============================================================
-- Source: 20260704190000_fix_return_fifo_layers.sql
-- ============================================================
-- Fix purchase returns and sale returns (good condition) to properly
-- interact with FIFO cost layers.
--
-- Problem:
--   Both functions only updated the legacy stock_level counter on
--   inventory_brand_variants, which warehouse_stock_view ignores.
--   The view is built from SUM(fifo_cost_layers.remaining_qty).
--
-- Fix:
--   1. rpc_process_po_return_dispatch: call deduct_fifo_layers() so
--      stock actually decreases in the warehouse view.
--   2. rpc_process_return_restock (good condition): create a new FIFO
--      layer at the weighted-average cost so stock increases in the view.

-- ═══════════════════════════════════════════════════════════════════════
-- 1. Purchase Return — deduct FIFO layers when dispatching back to supplier
-- ═══════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.rpc_process_po_return_dispatch(p_return_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_return  RECORD;
  v_item    JSONB;
  v_bv_id   UUID;
  v_qty     INT;
  v_sku     TEXT;
  v_result  RECORD;
BEGIN
  SELECT id, items, restock_warehouse_id, status, dispatched_at
  INTO   v_return
  FROM   returns
  WHERE  id = p_return_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Return % not found', p_return_id;
  END IF;

  IF v_return.dispatched_at IS NOT NULL THEN
    RETURN;
  END IF;

  IF v_return.status != 'dispatched' THEN
    RAISE EXCEPTION 'Return must have status=dispatched before processing inventory';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_return.items) LOOP
    v_bv_id := NULLIF(v_item->>'brand_variant_id', '')::UUID;
    v_qty   := COALESCE((v_item->>'qty')::INT, 0);

    IF v_bv_id IS NULL THEN
      v_sku := NULLIF(trim(v_item->>'sku'), '');
      IF v_sku IS NOT NULL THEN
        SELECT id INTO v_bv_id
        FROM   inventory_brand_variants
        WHERE  code = v_sku
        LIMIT  1;
      END IF;
    END IF;

    IF v_bv_id IS NULL OR v_qty <= 0 THEN
      CONTINUE;
    END IF;

    -- Deduct FIFO layers so warehouse_stock_view reflects the decrease.
    -- deduct_fifo_layers already updates stock_level and recalculates avg cost.
    SELECT total_cost, weighted_unit_cost
    INTO   v_result
    FROM   deduct_fifo_layers(v_bv_id, v_return.restock_warehouse_id, v_qty, false);

    INSERT INTO inventory_stock_movements (
      warehouse_id, brand_variant_id, item_name, sku,
      movement_type, qty, unit_cost,
      reference_type, reference_id, notes
    ) VALUES (
      v_return.restock_warehouse_id,
      v_bv_id,
      v_item->>'item_name',
      NULLIF(v_item->>'sku', ''),
      'purchase_return',
      -v_qty,
      v_result.weighted_unit_cost,
      'po_return',
      p_return_id,
      'Returned to supplier'
    );
  END LOOP;

  UPDATE returns SET dispatched_at = now() WHERE id = p_return_id;
END;
$$;

GRANT EXECUTE ON FUNCTION rpc_process_po_return_dispatch(uuid) TO authenticated;


-- ═══════════════════════════════════════════════════════════════════════
-- 2. Sale Return (Good) — create a FIFO layer so stock increases
-- ═══════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.rpc_process_return_restock(p_return_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_return   RECORD;
  v_item     JSONB;
  v_bv_id    UUID;
  v_qty      INT;
  v_cond     TEXT;
  v_avg_cost NUMERIC;
BEGIN
  SELECT id, items, restock_warehouse_id, status, restocked_at
  INTO   v_return
  FROM   returns
  WHERE  id = p_return_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Return % not found', p_return_id;
  END IF;

  IF v_return.restocked_at IS NOT NULL THEN
    RETURN;
  END IF;

  IF v_return.status != 'restocked' THEN
    RAISE EXCEPTION 'Return must have status=restocked before processing inventory';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_return.items) LOOP
    v_bv_id := NULLIF(v_item->>'brand_variant_id', '')::UUID;
    v_qty   := COALESCE((v_item->>'qty')::INT, 0);
    v_cond  := LOWER(COALESCE(v_item->>'condition', ''));

    IF v_bv_id IS NULL OR v_qty <= 0 THEN
      CONTINUE;
    END IF;

    IF v_cond = 'good' THEN
      -- Look up current weighted-average cost for this variant.
      SELECT COALESCE(average_cost, 0) INTO v_avg_cost
      FROM   inventory_brand_variants
      WHERE  id = v_bv_id;

      -- Create a new FIFO layer so warehouse_stock_view reflects the increase.
      INSERT INTO fifo_cost_layers (
        brand_variant_id, warehouse_id, date,
        qty, unit_cost, landed_cost_per_unit, total_unit_cost, remaining_qty,
        source_type
      ) VALUES (
        v_bv_id, v_return.restock_warehouse_id, CURRENT_DATE,
        v_qty, v_avg_cost, 0, v_avg_cost, v_qty,
        'sale_return'
      );

      UPDATE inventory_brand_variants
      SET    stock_level = stock_level + v_qty,
             updated_at  = now()
      WHERE  id = v_bv_id;

      PERFORM recalc_average_cost(v_bv_id);

      INSERT INTO inventory_stock_movements (
        warehouse_id, brand_variant_id, item_name, sku,
        movement_type, qty, unit_cost,
        reference_type, reference_id, notes
      ) VALUES (
        v_return.restock_warehouse_id,
        v_bv_id,
        v_item->>'item_name',
        NULLIF(v_item->>'sku', ''),
        'sale_return',
        v_qty,
        v_avg_cost,
        'return',
        p_return_id,
        'Restocked from sale return'
      );

    ELSIF v_cond = 'damaged' THEN
      -- Damaged items go to damaged_qty, not sellable stock.
      -- No FIFO layer needed — they are not sellable inventory.
      UPDATE inventory_brand_variants
      SET    damaged_qty = damaged_qty + v_qty
      WHERE  id = v_bv_id;

      INSERT INTO inventory_stock_movements (
        warehouse_id, brand_variant_id, item_name, sku,
        movement_type, qty, unit_cost,
        reference_type, reference_id, notes
      ) VALUES (
        v_return.restock_warehouse_id,
        v_bv_id,
        v_item->>'item_name',
        NULLIF(v_item->>'sku', ''),
        'sale_return_damaged',
        v_qty,
        0,
        'return',
        p_return_id,
        'Damaged item from sale return — awaiting assessment'
      );
    END IF;
  END LOOP;

  UPDATE returns SET restocked_at = now() WHERE id = p_return_id;
END;
$$;

GRANT EXECUTE ON FUNCTION rpc_process_return_restock(uuid) TO authenticated;


-- ============================================================
-- Source: 20260704200000_delivery_number_sequence.sql
-- ============================================================
-- Create a proper sequence for delivery numbers to prevent duplicate key errors.
-- Previously, three separate code paths generated DEL-XXXXX by querying the max
-- existing number and incrementing — a classic race condition.

-- 1. Find the current max delivery number to seed the sequence.
DO $$
DECLARE
  v_max INT;
BEGIN
  SELECT COALESCE(
    MAX(
      CASE
        WHEN delivery_number ~ '^DEL-[0-9]+$'
        THEN CAST(REPLACE(delivery_number, 'DEL-', '') AS INT)
        ELSE 0
      END
    ), 0
  ) INTO v_max
  FROM sale_deliveries;

  -- Create sequence starting after the current max
  EXECUTE format('CREATE SEQUENCE IF NOT EXISTS delivery_number_seq START WITH %s', v_max + 1);
END $$;

-- 2. Helper function: returns next delivery number as DEL-00001 format.
CREATE OR REPLACE FUNCTION next_delivery_number()
RETURNS TEXT
LANGUAGE sql
AS $$
  SELECT 'DEL-' || LPAD(nextval('delivery_number_seq')::TEXT, 5, '0');
$$;

GRANT EXECUTE ON FUNCTION next_delivery_number() TO authenticated;


-- ============================================================
-- Source: 20260704203944_aging_report_and_dashboard_rpcs.sql
-- ============================================================
-- Purchase Aging Report: groups outstanding bills (invoices where direction='ap') by supplier
CREATE OR REPLACE FUNCTION rpc_purchase_aging_report()
RETURNS TABLE (
  supplier_id       uuid,
  supplier_name     text,
  current_amt       numeric,
  days_1_30         numeric,
  days_31_60        numeric,
  days_61_90        numeric,
  days_over_90      numeric,
  total_outstanding numeric,
  bill_count        bigint
)
LANGUAGE sql STABLE
AS $$
  SELECT
    i.supplier_id,
    s.name AS supplier_name,
    COALESCE(SUM(CASE WHEN i.due_date >= CURRENT_DATE THEN i.total_amount - i.paid_amount END), 0) AS current_amt,
    COALESCE(SUM(CASE WHEN i.due_date BETWEEN CURRENT_DATE - 30 AND CURRENT_DATE - 1 THEN i.total_amount - i.paid_amount END), 0) AS days_1_30,
    COALESCE(SUM(CASE WHEN i.due_date BETWEEN CURRENT_DATE - 60 AND CURRENT_DATE - 31 THEN i.total_amount - i.paid_amount END), 0) AS days_31_60,
    COALESCE(SUM(CASE WHEN i.due_date BETWEEN CURRENT_DATE - 90 AND CURRENT_DATE - 61 THEN i.total_amount - i.paid_amount END), 0) AS days_61_90,
    COALESCE(SUM(CASE WHEN i.due_date < CURRENT_DATE - 90 THEN i.total_amount - i.paid_amount END), 0) AS days_over_90,
    COALESCE(SUM(i.total_amount - i.paid_amount), 0) AS total_outstanding,
    COUNT(*) AS bill_count
  FROM invoices i
  JOIN suppliers s ON s.id = i.supplier_id
  WHERE i.direction = 'ap'
    AND i.payment_status NOT IN ('paid')
    AND i.doc_status NOT IN ('draft', 'rejected')
    AND i.total_amount - i.paid_amount > 0
  GROUP BY i.supplier_id, s.name
  ORDER BY total_outstanding DESC;
$$;

-- Sales Aging Report: groups outstanding invoices (direction='ar') by customer
CREATE OR REPLACE FUNCTION rpc_sales_aging_report()
RETURNS TABLE (
  customer_id       uuid,
  customer_name     text,
  current_amt       numeric,
  days_1_30         numeric,
  days_31_60        numeric,
  days_61_90        numeric,
  days_over_90      numeric,
  total_outstanding numeric,
  invoice_count     bigint
)
LANGUAGE sql STABLE
AS $$
  SELECT
    i.customer_id,
    c.name AS customer_name,
    COALESCE(SUM(CASE WHEN i.due_date >= CURRENT_DATE THEN i.total_amount - i.paid_amount END), 0) AS current_amt,
    COALESCE(SUM(CASE WHEN i.due_date BETWEEN CURRENT_DATE - 30 AND CURRENT_DATE - 1 THEN i.total_amount - i.paid_amount END), 0) AS days_1_30,
    COALESCE(SUM(CASE WHEN i.due_date BETWEEN CURRENT_DATE - 60 AND CURRENT_DATE - 31 THEN i.total_amount - i.paid_amount END), 0) AS days_31_60,
    COALESCE(SUM(CASE WHEN i.due_date BETWEEN CURRENT_DATE - 90 AND CURRENT_DATE - 61 THEN i.total_amount - i.paid_amount END), 0) AS days_61_90,
    COALESCE(SUM(CASE WHEN i.due_date < CURRENT_DATE - 90 THEN i.total_amount - i.paid_amount END), 0) AS days_over_90,
    COALESCE(SUM(i.total_amount - i.paid_amount), 0) AS total_outstanding,
    COUNT(*) AS invoice_count
  FROM invoices i
  JOIN customers c ON c.id = i.customer_id
  WHERE i.direction = 'ar'
    AND i.payment_status NOT IN ('paid')
    AND i.doc_status NOT IN ('draft', 'rejected')
    AND i.total_amount - i.paid_amount > 0
  GROUP BY i.customer_id, c.name
  ORDER BY total_outstanding DESC;
$$;

-- Financial Dashboard: receivables, payables, overdue counts, monthly trend, top overdue
CREATE OR REPLACE FUNCTION rpc_financial_dashboard()
RETURNS jsonb
LANGUAGE plpgsql STABLE
AS $$
DECLARE
  result jsonb;
  receivables_total numeric;
  receivables_overdue numeric;
  receivables_overdue_count bigint;
  payables_total numeric;
  payables_overdue numeric;
  payables_overdue_count bigint;
  monthly_trend jsonb;
  top_overdue_customers jsonb;
  top_overdue_suppliers jsonb;
BEGIN
  -- Receivables (AR invoices)
  SELECT
    COALESCE(SUM(total_amount - paid_amount), 0),
    COALESCE(SUM(CASE WHEN due_date < CURRENT_DATE THEN total_amount - paid_amount END), 0),
    COALESCE(COUNT(CASE WHEN due_date < CURRENT_DATE THEN 1 END), 0)
  INTO receivables_total, receivables_overdue, receivables_overdue_count
  FROM invoices
  WHERE direction = 'ar'
    AND payment_status NOT IN ('paid')
    AND doc_status NOT IN ('draft', 'rejected')
    AND total_amount - paid_amount > 0;

  -- Payables (AP bills)
  SELECT
    COALESCE(SUM(total_amount - paid_amount), 0),
    COALESCE(SUM(CASE WHEN due_date < CURRENT_DATE THEN total_amount - paid_amount END), 0),
    COALESCE(COUNT(CASE WHEN due_date < CURRENT_DATE THEN 1 END), 0)
  INTO payables_total, payables_overdue, payables_overdue_count
  FROM invoices
  WHERE direction = 'ap'
    AND payment_status NOT IN ('paid')
    AND doc_status NOT IN ('draft', 'rejected')
    AND total_amount - paid_amount > 0;

  -- Monthly trend (last 6 months): sales invoiced vs purchase billed
  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.month), '[]'::jsonb)
  INTO monthly_trend
  FROM (
    SELECT
      TO_CHAR(m.month, 'YYYY-MM') AS month,
      TO_CHAR(m.month, 'Mon') AS label,
      COALESCE((
        SELECT SUM(total_amount) FROM invoices
        WHERE direction = 'ar'
          AND DATE_TRUNC('month', issued_date) = m.month
          AND doc_status NOT IN ('draft', 'rejected')
      ), 0) AS invoiced,
      COALESCE((
        SELECT SUM(total_amount) FROM invoices
        WHERE direction = 'ap'
          AND DATE_TRUNC('month', issued_date) = m.month
          AND doc_status NOT IN ('draft', 'rejected')
      ), 0) AS billed
    FROM generate_series(
      DATE_TRUNC('month', CURRENT_DATE) - INTERVAL '5 months',
      DATE_TRUNC('month', CURRENT_DATE),
      '1 month'
    ) AS m(month)
  ) t;

  -- Top 5 overdue customers
  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  INTO top_overdue_customers
  FROM (
    SELECT
      c.name,
      SUM(i.total_amount - i.paid_amount) AS amount,
      MIN(i.due_date) AS oldest_due
    FROM invoices i
    JOIN customers c ON c.id = i.customer_id
    WHERE i.direction = 'ar'
      AND i.due_date < CURRENT_DATE
      AND i.payment_status NOT IN ('paid')
      AND i.doc_status NOT IN ('draft', 'rejected')
      AND i.total_amount - i.paid_amount > 0
    GROUP BY c.id, c.name
    ORDER BY amount DESC
    LIMIT 5
  ) t;

  -- Top 5 overdue suppliers
  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  INTO top_overdue_suppliers
  FROM (
    SELECT
      s.name,
      SUM(i.total_amount - i.paid_amount) AS amount,
      MIN(i.due_date) AS oldest_due
    FROM invoices i
    JOIN suppliers s ON s.id = i.supplier_id
    WHERE i.direction = 'ap'
      AND i.due_date < CURRENT_DATE
      AND i.payment_status NOT IN ('paid')
      AND i.doc_status NOT IN ('draft', 'rejected')
      AND i.total_amount - i.paid_amount > 0
    GROUP BY s.id, s.name
    ORDER BY amount DESC
    LIMIT 5
  ) t;

  result := jsonb_build_object(
    'receivables', jsonb_build_object('total', receivables_total, 'overdue', receivables_overdue, 'overdue_count', receivables_overdue_count),
    'payables', jsonb_build_object('total', payables_total, 'overdue', payables_overdue, 'overdue_count', payables_overdue_count),
    'monthly_trend', monthly_trend,
    'top_overdue_customers', top_overdue_customers,
    'top_overdue_suppliers', top_overdue_suppliers
  );

  RETURN result;
END;
$$;


-- ============================================================
-- Source: 20260704205620_customer_statement_rpc.sql
-- ============================================================
-- Customer Statement: all transactions for a customer in a date range
-- Returns invoices (debit), payments (credit), credit notes (credit)
-- ordered by date. Running balance is calculated client-side.
CREATE OR REPLACE FUNCTION rpc_customer_statement(
  p_customer_id uuid,
  p_date_from date DEFAULT NULL,
  p_date_to date DEFAULT NULL
)
RETURNS TABLE (
  txn_date   date,
  txn_type   text,
  reference  text,
  description text,
  debit      numeric,
  credit     numeric
)
LANGUAGE sql STABLE
AS $$
  -- Invoices issued (debit — customer owes)
  SELECT
    i.issued_date AS txn_date,
    'invoice' AS txn_type,
    i.invoice_id AS reference,
    CASE
      WHEN i.due_date IS NOT NULL THEN 'Invoice — due ' || TO_CHAR(i.due_date, 'DD Mon YYYY')
      ELSE 'Invoice'
    END AS description,
    i.total_amount AS debit,
    0::numeric AS credit
  FROM invoices i
  WHERE i.direction = 'ar'
    AND i.customer_id = p_customer_id
    AND i.doc_status NOT IN ('draft', 'rejected')
    AND i.payment_status != 'void'
    AND (p_date_from IS NULL OR i.issued_date >= p_date_from)
    AND (p_date_to IS NULL OR i.issued_date <= p_date_to)

  UNION ALL

  -- Payments received (credit — reduces balance)
  SELECT
    p.date AS txn_date,
    'payment' AS txn_type,
    p.payment_id AS reference,
    'Payment — ' || COALESCE(p.method::text, 'unknown') AS description,
    0::numeric AS debit,
    p.amount AS credit
  FROM payments p
  WHERE p.direction = 'incoming'
    AND p.customer_id = p_customer_id
    AND p.status = 'completed'
    AND p.deleted_at IS NULL
    AND (p_date_from IS NULL OR p.date >= p_date_from)
    AND (p_date_to IS NULL OR p.date <= p_date_to)

  UNION ALL

  -- Credit notes (credit — reduces balance)
  SELECT
    cn.created_at::date AS txn_date,
    'credit_note' AS txn_type,
    cn.credit_note_id AS reference,
    'Credit Note — ' || COALESCE(cn.reason, cn.type) AS description,
    0::numeric AS debit,
    cn.total_amount AS credit
  FROM credit_notes cn
  JOIN invoices inv ON inv.id = cn.invoice_id
  WHERE cn.note_type = 'credit'
    AND cn.status NOT IN ('draft')
    AND inv.customer_id = p_customer_id
    AND (p_date_from IS NULL OR cn.created_at::date >= p_date_from)
    AND (p_date_to IS NULL OR cn.created_at::date <= p_date_to)

  ORDER BY txn_date, txn_type;
$$;


-- ============================================================
-- Source: 20260705210316_fix_customer_statement_rpc.sql
-- ============================================================
-- Fix rpc_customer_statement: resolve customer_id via joins because
-- payments.customer_id is often NULL (only backfilled for invoice-linked payments,
-- not SO or CN direct payments). Also broaden status filter to include pending.
CREATE OR REPLACE FUNCTION rpc_customer_statement(
  p_customer_id uuid,
  p_date_from date DEFAULT NULL,
  p_date_to date DEFAULT NULL
)
RETURNS TABLE (
  txn_date   date,
  txn_type   text,
  reference  text,
  description text,
  debit      numeric,
  credit     numeric
)
LANGUAGE sql STABLE
AS $$
  -- Invoices issued (debit — customer owes)
  SELECT
    i.issued_date AS txn_date,
    'invoice' AS txn_type,
    i.invoice_id AS reference,
    CASE
      WHEN i.due_date IS NOT NULL THEN 'Invoice — due ' || TO_CHAR(i.due_date, 'DD Mon YYYY')
      ELSE 'Invoice'
    END AS description,
    i.total_amount AS debit,
    0::numeric AS credit
  FROM invoices i
  WHERE i.direction = 'ar'
    AND i.customer_id = p_customer_id
    AND i.doc_status NOT IN ('draft', 'rejected')
    AND (p_date_from IS NULL OR i.issued_date >= p_date_from)
    AND (p_date_to IS NULL OR i.issued_date <= p_date_to)

  UNION ALL

  -- Payments received (credit — reduces balance)
  -- Customer resolved via COALESCE across three sources because
  -- payments.customer_id is only set for invoice-linked payments.
  SELECT
    p.date AS txn_date,
    'payment' AS txn_type,
    p.payment_id AS reference,
    'Payment — ' || COALESCE(p.method::text, 'unknown')
      || CASE WHEN p.reference IS NOT NULL THEN ' · ' || p.reference ELSE '' END AS description,
    0::numeric AS debit,
    p.amount AS credit
  FROM payments p
  LEFT JOIN sale_orders so ON so.id = p.source_id AND p.source_type = 'sale_order'
  LEFT JOIN invoices inv ON inv.id = p.invoice_id
  WHERE p.direction = 'incoming'
    AND p.deleted_at IS NULL
    AND p.status IN ('completed', 'pending', 'processing')
    AND COALESCE(p.customer_id, so.customer_id, inv.customer_id) = p_customer_id
    AND (p_date_from IS NULL OR p.date >= p_date_from)
    AND (p_date_to IS NULL OR p.date <= p_date_to)

  UNION ALL

  -- Credit notes (credit — reduces balance)
  SELECT
    cn.created_at::date AS txn_date,
    'credit_note' AS txn_type,
    cn.credit_note_id AS reference,
    'Credit Note — ' || COALESCE(cn.reason, cn.type) AS description,
    0::numeric AS debit,
    cn.total_amount AS credit
  FROM credit_notes cn
  JOIN invoices inv ON inv.id = cn.invoice_id
  WHERE cn.note_type = 'credit'
    AND cn.status NOT IN ('draft')
    AND inv.customer_id = p_customer_id
    AND (p_date_from IS NULL OR cn.created_at::date >= p_date_from)
    AND (p_date_to IS NULL OR cn.created_at::date <= p_date_to)

  ORDER BY txn_date, txn_type;
$$;


-- ============================================================
-- Source: 20260705211115_include_draft_invoices_in_reports.sql
-- ============================================================
-- Include draft invoices in statement + aging RPCs.
-- Reason: invoices are created as doc_status='draft' by default and only
-- leave that state when a user clicks "Send Invoice". In this codebase's
-- current usage most real invoices sit as drafts forever, so excluding
-- them made the reports show QAR 0 for customers with real charges.

-- ── Customer Statement ─────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION rpc_customer_statement(
  p_customer_id uuid,
  p_date_from date DEFAULT NULL,
  p_date_to date DEFAULT NULL
)
RETURNS TABLE (
  txn_date   date,
  txn_type   text,
  reference  text,
  description text,
  debit      numeric,
  credit     numeric
)
LANGUAGE sql STABLE
AS $$
  -- Invoices issued (debit)
  SELECT
    i.issued_date AS txn_date,
    'invoice' AS txn_type,
    i.invoice_id AS reference,
    CASE
      WHEN i.due_date IS NOT NULL THEN 'Invoice — due ' || TO_CHAR(i.due_date, 'DD Mon YYYY')
      ELSE 'Invoice'
    END AS description,
    i.total_amount AS debit,
    0::numeric AS credit
  FROM invoices i
  WHERE i.direction = 'ar'
    AND i.customer_id = p_customer_id
    AND i.doc_status != 'rejected'
    AND (p_date_from IS NULL OR i.issued_date >= p_date_from)
    AND (p_date_to IS NULL OR i.issued_date <= p_date_to)

  UNION ALL

  -- Payments received (credit)
  SELECT
    p.date AS txn_date,
    'payment' AS txn_type,
    p.payment_id AS reference,
    'Payment — ' || COALESCE(p.method::text, 'unknown')
      || CASE WHEN p.reference IS NOT NULL THEN ' · ' || p.reference ELSE '' END AS description,
    0::numeric AS debit,
    p.amount AS credit
  FROM payments p
  LEFT JOIN sale_orders so ON so.id = p.source_id AND p.source_type = 'sale_order'
  LEFT JOIN invoices inv ON inv.id = p.invoice_id
  WHERE p.direction = 'incoming'
    AND p.deleted_at IS NULL
    AND p.status IN ('completed', 'pending', 'processing')
    AND COALESCE(p.customer_id, so.customer_id, inv.customer_id) = p_customer_id
    AND (p_date_from IS NULL OR p.date >= p_date_from)
    AND (p_date_to IS NULL OR p.date <= p_date_to)

  UNION ALL

  -- Credit notes (credit)
  SELECT
    cn.created_at::date AS txn_date,
    'credit_note' AS txn_type,
    cn.credit_note_id AS reference,
    'Credit Note — ' || COALESCE(cn.reason, cn.type) AS description,
    0::numeric AS debit,
    cn.total_amount AS credit
  FROM credit_notes cn
  JOIN invoices inv ON inv.id = cn.invoice_id
  WHERE cn.note_type = 'credit'
    AND cn.status != 'draft'
    AND inv.customer_id = p_customer_id
    AND (p_date_from IS NULL OR cn.created_at::date >= p_date_from)
    AND (p_date_to IS NULL OR cn.created_at::date <= p_date_to)

  ORDER BY txn_date, txn_type;
$$;

-- ── Purchase Aging ─────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION rpc_purchase_aging_report()
RETURNS TABLE (
  supplier_id       uuid,
  supplier_name     text,
  current_amt       numeric,
  days_1_30         numeric,
  days_31_60        numeric,
  days_61_90        numeric,
  days_over_90      numeric,
  total_outstanding numeric,
  bill_count        bigint
)
LANGUAGE sql STABLE
AS $$
  SELECT
    i.supplier_id,
    s.name AS supplier_name,
    COALESCE(SUM(CASE WHEN i.due_date >= CURRENT_DATE THEN i.total_amount - i.paid_amount END), 0) AS current_amt,
    COALESCE(SUM(CASE WHEN i.due_date BETWEEN CURRENT_DATE - 30 AND CURRENT_DATE - 1 THEN i.total_amount - i.paid_amount END), 0) AS days_1_30,
    COALESCE(SUM(CASE WHEN i.due_date BETWEEN CURRENT_DATE - 60 AND CURRENT_DATE - 31 THEN i.total_amount - i.paid_amount END), 0) AS days_31_60,
    COALESCE(SUM(CASE WHEN i.due_date BETWEEN CURRENT_DATE - 90 AND CURRENT_DATE - 61 THEN i.total_amount - i.paid_amount END), 0) AS days_61_90,
    COALESCE(SUM(CASE WHEN i.due_date < CURRENT_DATE - 90 THEN i.total_amount - i.paid_amount END), 0) AS days_over_90,
    COALESCE(SUM(i.total_amount - i.paid_amount), 0) AS total_outstanding,
    COUNT(*) AS bill_count
  FROM invoices i
  JOIN suppliers s ON s.id = i.supplier_id
  WHERE i.direction = 'ap'
    AND i.payment_status != 'paid'
    AND i.doc_status != 'rejected'
    AND i.total_amount - i.paid_amount > 0
  GROUP BY i.supplier_id, s.name
  ORDER BY total_outstanding DESC;
$$;

-- ── Sales Aging ────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION rpc_sales_aging_report()
RETURNS TABLE (
  customer_id       uuid,
  customer_name     text,
  current_amt       numeric,
  days_1_30         numeric,
  days_31_60        numeric,
  days_61_90        numeric,
  days_over_90      numeric,
  total_outstanding numeric,
  invoice_count     bigint
)
LANGUAGE sql STABLE
AS $$
  SELECT
    i.customer_id,
    c.name AS customer_name,
    COALESCE(SUM(CASE WHEN i.due_date >= CURRENT_DATE THEN i.total_amount - i.paid_amount END), 0) AS current_amt,
    COALESCE(SUM(CASE WHEN i.due_date BETWEEN CURRENT_DATE - 30 AND CURRENT_DATE - 1 THEN i.total_amount - i.paid_amount END), 0) AS days_1_30,
    COALESCE(SUM(CASE WHEN i.due_date BETWEEN CURRENT_DATE - 60 AND CURRENT_DATE - 31 THEN i.total_amount - i.paid_amount END), 0) AS days_31_60,
    COALESCE(SUM(CASE WHEN i.due_date BETWEEN CURRENT_DATE - 90 AND CURRENT_DATE - 61 THEN i.total_amount - i.paid_amount END), 0) AS days_61_90,
    COALESCE(SUM(CASE WHEN i.due_date < CURRENT_DATE - 90 THEN i.total_amount - i.paid_amount END), 0) AS days_over_90,
    COALESCE(SUM(i.total_amount - i.paid_amount), 0) AS total_outstanding,
    COUNT(*) AS invoice_count
  FROM invoices i
  JOIN customers c ON c.id = i.customer_id
  WHERE i.direction = 'ar'
    AND i.payment_status != 'paid'
    AND i.doc_status != 'rejected'
    AND i.total_amount - i.paid_amount > 0
  GROUP BY i.customer_id, c.name
  ORDER BY total_outstanding DESC;
$$;

-- ── Financial Dashboard ────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION rpc_financial_dashboard()
RETURNS jsonb
LANGUAGE plpgsql STABLE
AS $$
DECLARE
  result jsonb;
  receivables_total numeric;
  receivables_overdue numeric;
  receivables_overdue_count bigint;
  payables_total numeric;
  payables_overdue numeric;
  payables_overdue_count bigint;
  monthly_trend jsonb;
  top_overdue_customers jsonb;
  top_overdue_suppliers jsonb;
BEGIN
  SELECT
    COALESCE(SUM(total_amount - paid_amount), 0),
    COALESCE(SUM(CASE WHEN due_date < CURRENT_DATE THEN total_amount - paid_amount END), 0),
    COALESCE(COUNT(CASE WHEN due_date < CURRENT_DATE THEN 1 END), 0)
  INTO receivables_total, receivables_overdue, receivables_overdue_count
  FROM invoices
  WHERE direction = 'ar'
    AND payment_status != 'paid'
    AND doc_status != 'rejected'
    AND total_amount - paid_amount > 0;

  SELECT
    COALESCE(SUM(total_amount - paid_amount), 0),
    COALESCE(SUM(CASE WHEN due_date < CURRENT_DATE THEN total_amount - paid_amount END), 0),
    COALESCE(COUNT(CASE WHEN due_date < CURRENT_DATE THEN 1 END), 0)
  INTO payables_total, payables_overdue, payables_overdue_count
  FROM invoices
  WHERE direction = 'ap'
    AND payment_status != 'paid'
    AND doc_status != 'rejected'
    AND total_amount - paid_amount > 0;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.month), '[]'::jsonb)
  INTO monthly_trend
  FROM (
    SELECT
      TO_CHAR(m.month, 'YYYY-MM') AS month,
      TO_CHAR(m.month, 'Mon') AS label,
      COALESCE((
        SELECT SUM(total_amount) FROM invoices
        WHERE direction = 'ar'
          AND DATE_TRUNC('month', issued_date) = m.month
          AND doc_status != 'rejected'
      ), 0) AS invoiced,
      COALESCE((
        SELECT SUM(total_amount) FROM invoices
        WHERE direction = 'ap'
          AND DATE_TRUNC('month', issued_date) = m.month
          AND doc_status != 'rejected'
      ), 0) AS billed
    FROM generate_series(
      DATE_TRUNC('month', CURRENT_DATE) - INTERVAL '5 months',
      DATE_TRUNC('month', CURRENT_DATE),
      '1 month'
    ) AS m(month)
  ) t;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  INTO top_overdue_customers
  FROM (
    SELECT
      c.name,
      SUM(i.total_amount - i.paid_amount) AS amount,
      MIN(i.due_date) AS oldest_due
    FROM invoices i
    JOIN customers c ON c.id = i.customer_id
    WHERE i.direction = 'ar'
      AND i.due_date < CURRENT_DATE
      AND i.payment_status != 'paid'
      AND i.doc_status != 'rejected'
      AND i.total_amount - i.paid_amount > 0
    GROUP BY c.id, c.name
    ORDER BY amount DESC
    LIMIT 5
  ) t;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  INTO top_overdue_suppliers
  FROM (
    SELECT
      s.name,
      SUM(i.total_amount - i.paid_amount) AS amount,
      MIN(i.due_date) AS oldest_due
    FROM invoices i
    JOIN suppliers s ON s.id = i.supplier_id
    WHERE i.direction = 'ap'
      AND i.due_date < CURRENT_DATE
      AND i.payment_status != 'paid'
      AND i.doc_status != 'rejected'
      AND i.total_amount - i.paid_amount > 0
    GROUP BY s.id, s.name
    ORDER BY amount DESC
    LIMIT 5
  ) t;

  result := jsonb_build_object(
    'receivables', jsonb_build_object('total', receivables_total, 'overdue', receivables_overdue, 'overdue_count', receivables_overdue_count),
    'payables', jsonb_build_object('total', payables_total, 'overdue', payables_overdue, 'overdue_count', payables_overdue_count),
    'monthly_trend', monthly_trend,
    'top_overdue_customers', top_overdue_customers,
    'top_overdue_suppliers', top_overdue_suppliers
  );

  RETURN result;
END;
$$;


-- ============================================================
-- Source: 20260705211423_customer_statement_v2_so_based.sql
-- ============================================================
-- Customer Statement v2 — SO-based (one row per Sale Order with Total/Paid/Outstanding).
-- Replaces the ledger-style rpc_customer_statement. Matches the mockup at
-- public/brand/customer-statement-preview.html.
--
-- Payment matching handles the three payment shapes:
--   1. source_type='sale_order' AND source_id=so.id           (pre-invoice)
--   2. source_type='invoice'    AND source_id=invoice.id      (post-invoice via triggers)
--   3. invoice_id=invoice.id                                   (legacy)
-- Where invoice.id = invoices.id WHERE sale_order_id=so.id AND direction='ar'.

CREATE OR REPLACE FUNCTION rpc_customer_statement_v2(p_customer_id uuid)
RETURNS jsonb
LANGUAGE plpgsql STABLE
AS $$
DECLARE
  result        jsonb;
  cust_name     text;
  cust_phone    text;
  cust_type     text;
  account_type  text;
  orders        jsonb;
  totals        jsonb;
  open_count    bigint;
BEGIN
  -- ── Customer info ─────────────────────────────────────────────
  SELECT c.name, c.phone, c.customer_type::text, cg.name
  INTO cust_name, cust_phone, cust_type, account_type
  FROM customers c
  LEFT JOIN credit_groups cg ON cg.id = c.credit_group_id
  WHERE c.id = p_customer_id;

  IF cust_name IS NULL THEN
    RAISE EXCEPTION 'Customer not found: %', p_customer_id USING ERRCODE = 'P0002';
  END IF;

  -- ── Orders ────────────────────────────────────────────────────
  WITH sos AS (
    SELECT so.id, so.so_number, so.created_at, so.status, so.total
    FROM sale_orders so
    WHERE so.customer_id = p_customer_id
      AND so.status != 'cancelled'
      AND so.deleted_at IS NULL
  ),
  so_inv AS (
    SELECT sos.id AS so_id, inv.id AS invoice_id
    FROM sos
    LEFT JOIN invoices inv
           ON inv.sale_order_id = sos.id AND inv.direction = 'ar'
  ),
  so_paid AS (
    SELECT si.so_id,
           COALESCE(SUM(COALESCE(p.amount_qar, p.amount)), 0) AS paid
    FROM so_inv si
    LEFT JOIN payments p
           ON p.deleted_at IS NULL
          AND (
                (p.source_type = 'sale_order' AND p.source_id = si.so_id)
             OR (si.invoice_id IS NOT NULL
                 AND p.source_type = 'invoice'
                 AND p.source_id = si.invoice_id)
             OR (si.invoice_id IS NOT NULL AND p.invoice_id = si.invoice_id)
              )
    GROUP BY si.so_id
  )
  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.created_at DESC), '[]'::jsonb)
  INTO orders
  FROM (
    SELECT sos.id,
           sos.so_number,
           sos.created_at,
           sos.status::text AS status,
           sos.total::numeric AS total,
           COALESCE(sp.paid, 0)::numeric AS paid,
           GREATEST(0, sos.total - COALESCE(sp.paid, 0))::numeric AS outstanding
    FROM sos
    LEFT JOIN so_paid sp ON sp.so_id = sos.id
  ) t;

  -- ── Aggregate totals & open count ─────────────────────────────
  SELECT jsonb_build_object(
           'total_orders_value', COALESCE(SUM((o->>'total')::numeric), 0),
           'total_paid',         COALESCE(SUM((o->>'paid')::numeric), 0),
           'total_outstanding',  COALESCE(SUM((o->>'outstanding')::numeric), 0)
         )
  INTO totals
  FROM jsonb_array_elements(orders) o;

  SELECT COALESCE(COUNT(*), 0)
  INTO open_count
  FROM jsonb_array_elements(orders) o
  WHERE (o->>'outstanding')::numeric > 0;

  -- ── Build result ──────────────────────────────────────────────
  result := jsonb_build_object(
    'customer', jsonb_build_object(
      'name',         cust_name,
      'phone',        cust_phone,
      'account_type', COALESCE(account_type, INITCAP(cust_type), 'Cash')
    ),
    'orders',            orders,
    'totals',            COALESCE(totals, jsonb_build_object(
                            'total_orders_value', 0,
                            'total_paid',         0,
                            'total_outstanding',  0)),
    'open_orders_count', open_count
  );

  RETURN result;
END;
$$;


-- ============================================================
-- Source: 20260705221500_financial_dashboard_v2.sql
-- ============================================================
-- Financial Dashboard v2 — adds cash flow tracking (actual payments) alongside
-- the existing invoiced/billed figures. Rationale: invoiced != collected;
-- the gap between "billed" and "collected" is the receivable at any point.

CREATE OR REPLACE FUNCTION rpc_financial_dashboard()
RETURNS jsonb
LANGUAGE plpgsql STABLE
AS $$
DECLARE
  result jsonb;

  receivables_total          numeric;
  receivables_overdue        numeric;
  receivables_overdue_count  bigint;

  payables_total             numeric;
  payables_overdue           numeric;
  payables_overdue_count     bigint;

  -- Cash actually moved this month
  cash_in_this_month         numeric;
  cash_out_this_month        numeric;
  cash_in_last_month         numeric;
  cash_out_last_month        numeric;

  -- Docs raised this month
  invoiced_this_month        numeric;
  billed_this_month          numeric;

  monthly_trend              jsonb;
  top_overdue_customers      jsonb;
  top_overdue_suppliers      jsonb;

  v_month_start              date := DATE_TRUNC('month', CURRENT_DATE)::date;
  v_last_month_start         date := (DATE_TRUNC('month', CURRENT_DATE) - INTERVAL '1 month')::date;
BEGIN
  -- Receivables (AR)
  SELECT
    COALESCE(SUM(total_amount - paid_amount), 0),
    COALESCE(SUM(CASE WHEN due_date < CURRENT_DATE THEN total_amount - paid_amount END), 0),
    COALESCE(COUNT(CASE WHEN due_date < CURRENT_DATE THEN 1 END), 0)
  INTO receivables_total, receivables_overdue, receivables_overdue_count
  FROM invoices
  WHERE direction = 'ar'
    AND payment_status != 'paid'
    AND doc_status != 'rejected'
    AND total_amount - paid_amount > 0;

  -- Payables (AP)
  SELECT
    COALESCE(SUM(total_amount - paid_amount), 0),
    COALESCE(SUM(CASE WHEN due_date < CURRENT_DATE THEN total_amount - paid_amount END), 0),
    COALESCE(COUNT(CASE WHEN due_date < CURRENT_DATE THEN 1 END), 0)
  INTO payables_total, payables_overdue, payables_overdue_count
  FROM invoices
  WHERE direction = 'ap'
    AND payment_status != 'paid'
    AND doc_status != 'rejected'
    AND total_amount - paid_amount > 0;

  -- Cash this month (real payments)
  SELECT COALESCE(SUM(COALESCE(amount_qar, amount)), 0)
  INTO cash_in_this_month
  FROM payments
  WHERE direction = 'incoming'
    AND status IN ('completed', 'pending', 'processing')
    AND deleted_at IS NULL
    AND date >= v_month_start
    AND date <= CURRENT_DATE;

  SELECT COALESCE(SUM(COALESCE(amount_qar, amount)), 0)
  INTO cash_out_this_month
  FROM payments
  WHERE direction = 'outgoing'
    AND status IN ('completed', 'pending', 'processing')
    AND deleted_at IS NULL
    AND date >= v_month_start
    AND date <= CURRENT_DATE;

  -- Cash last month (for MoM %)
  SELECT COALESCE(SUM(COALESCE(amount_qar, amount)), 0)
  INTO cash_in_last_month
  FROM payments
  WHERE direction = 'incoming'
    AND status IN ('completed', 'pending', 'processing')
    AND deleted_at IS NULL
    AND date >= v_last_month_start
    AND date < v_month_start;

  SELECT COALESCE(SUM(COALESCE(amount_qar, amount)), 0)
  INTO cash_out_last_month
  FROM payments
  WHERE direction = 'outgoing'
    AND status IN ('completed', 'pending', 'processing')
    AND deleted_at IS NULL
    AND date >= v_last_month_start
    AND date < v_month_start;

  -- Docs raised this month (for card sub-line)
  SELECT COALESCE(SUM(total_amount), 0)
  INTO invoiced_this_month
  FROM invoices
  WHERE direction = 'ar'
    AND doc_status != 'rejected'
    AND issued_date >= v_month_start
    AND issued_date <= CURRENT_DATE;

  SELECT COALESCE(SUM(total_amount), 0)
  INTO billed_this_month
  FROM invoices
  WHERE direction = 'ap'
    AND doc_status != 'rejected'
    AND issued_date >= v_month_start
    AND issued_date <= CURRENT_DATE;

  -- Monthly trend — invoiced vs collected on each side (last 6 months)
  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.month), '[]'::jsonb)
  INTO monthly_trend
  FROM (
    SELECT
      TO_CHAR(m.month, 'YYYY-MM') AS month,
      TO_CHAR(m.month, 'Mon') AS label,
      COALESCE((
        SELECT SUM(total_amount) FROM invoices
        WHERE direction = 'ar'
          AND DATE_TRUNC('month', issued_date) = m.month
          AND doc_status != 'rejected'
      ), 0) AS invoiced,
      COALESCE((
        SELECT SUM(total_amount) FROM invoices
        WHERE direction = 'ap'
          AND DATE_TRUNC('month', issued_date) = m.month
          AND doc_status != 'rejected'
      ), 0) AS billed,
      COALESCE((
        SELECT SUM(COALESCE(amount_qar, amount)) FROM payments
        WHERE direction = 'incoming'
          AND DATE_TRUNC('month', date) = m.month
          AND status IN ('completed', 'pending', 'processing')
          AND deleted_at IS NULL
      ), 0) AS collected,
      COALESCE((
        SELECT SUM(COALESCE(amount_qar, amount)) FROM payments
        WHERE direction = 'outgoing'
          AND DATE_TRUNC('month', date) = m.month
          AND status IN ('completed', 'pending', 'processing')
          AND deleted_at IS NULL
      ), 0) AS paid_out
    FROM generate_series(
      DATE_TRUNC('month', CURRENT_DATE) - INTERVAL '5 months',
      DATE_TRUNC('month', CURRENT_DATE),
      '1 month'
    ) AS m(month)
  ) t;

  -- Top overdue customers (with id for drill-down)
  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  INTO top_overdue_customers
  FROM (
    SELECT
      c.id,
      c.name,
      SUM(i.total_amount - i.paid_amount) AS amount,
      COUNT(*) AS invoice_count,
      MIN(i.due_date) AS oldest_due,
      (CURRENT_DATE - MIN(i.due_date))::int AS days_overdue
    FROM invoices i
    JOIN customers c ON c.id = i.customer_id
    WHERE i.direction = 'ar'
      AND i.due_date < CURRENT_DATE
      AND i.payment_status != 'paid'
      AND i.doc_status != 'rejected'
      AND i.total_amount - i.paid_amount > 0
    GROUP BY c.id, c.name
    ORDER BY amount DESC
    LIMIT 5
  ) t;

  -- Top overdue suppliers (with id for drill-down)
  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  INTO top_overdue_suppliers
  FROM (
    SELECT
      s.id,
      s.name,
      SUM(i.total_amount - i.paid_amount) AS amount,
      COUNT(*) AS bill_count,
      MIN(i.due_date) AS oldest_due,
      (CURRENT_DATE - MIN(i.due_date))::int AS days_overdue
    FROM invoices i
    JOIN suppliers s ON s.id = i.supplier_id
    WHERE i.direction = 'ap'
      AND i.due_date < CURRENT_DATE
      AND i.payment_status != 'paid'
      AND i.doc_status != 'rejected'
      AND i.total_amount - i.paid_amount > 0
    GROUP BY s.id, s.name
    ORDER BY amount DESC
    LIMIT 5
  ) t;

  result := jsonb_build_object(
    'receivables', jsonb_build_object(
      'total', receivables_total,
      'overdue', receivables_overdue,
      'overdue_count', receivables_overdue_count
    ),
    'payables', jsonb_build_object(
      'total', payables_total,
      'overdue', payables_overdue,
      'overdue_count', payables_overdue_count
    ),
    'cash_this_month', jsonb_build_object(
      'in',  cash_in_this_month,
      'out', cash_out_this_month,
      'net', cash_in_this_month - cash_out_this_month,
      'in_prev',  cash_in_last_month,
      'out_prev', cash_out_last_month,
      'invoiced', invoiced_this_month,
      'billed',   billed_this_month
    ),
    'monthly_trend', monthly_trend,
    'top_overdue_customers', top_overdue_customers,
    'top_overdue_suppliers', top_overdue_suppliers
  );

  RETURN result;
END;
$$;


-- ============================================================
-- Source: 20260706120000_grant_replace_user_custom_roles_v2.sql
-- ============================================================
-- The baseline schema creates replace_user_custom_roles_v2 but omits the GRANT.
-- PostgREST cannot expose functions without EXECUTE granted to the calling role.
CREATE OR REPLACE FUNCTION public.replace_user_custom_roles_v2(
  p_user_id     UUID,
  p_assignments JSONB
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  DELETE FROM user_custom_roles WHERE profile_id = p_user_id;

  IF p_assignments IS NOT NULL AND jsonb_array_length(p_assignments) > 0 THEN
    INSERT INTO user_custom_roles (profile_id, role_id, approval_scopes)
    SELECT
      p_user_id,
      (a->>'role_id')::uuid,
      CASE
        WHEN a->'approval_scopes' IS NULL OR a->'approval_scopes' = 'null'::jsonb
          THEN NULL
        WHEN jsonb_array_length(a->'approval_scopes') = 0
          THEN NULL
        ELSE ARRAY(SELECT jsonb_array_elements_text(a->'approval_scopes'))
      END
    FROM jsonb_array_elements(p_assignments) AS a;
  END IF;
END;
$$;

REVOKE ALL ON FUNCTION public.replace_user_custom_roles_v2(UUID, JSONB) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.replace_user_custom_roles_v2(UUID, JSONB) TO authenticated;


-- ============================================================
-- Source: 20260706130000_fresh_db_bootstrap.sql
-- ============================================================
-- =============================================================================
-- Fresh Database Bootstrap
-- =============================================================================
-- Makes a freshly-created Supabase project self-sufficient after `db push`.
--
-- Solves three problems that exist on a brand-new DB:
--   1. No system roles are seeded (Admin, warehouse roles, approval-slot roles)
--      were previously in migrations_archive/ and never re-applied.
--   2. Auth signup does not create a profiles row → user hits "no profile linked".
--   3. Even with ADMIN_BOOTSTRAP_EMAIL, the very first user has no role assigned
--      → RLS blocks their reads/writes on real tables.
--
-- After this migration + a fresh db push, the onboarding flow is:
--   a) Supabase Studio → Authentication → Add User (email + password)
--   b) Log into the app → profile auto-created, Admin role auto-assigned
--   c) Use the app normally to create additional users
--
-- Every INSERT is idempotent (ON CONFLICT DO NOTHING) so re-running is safe.
-- =============================================================================

BEGIN;

-- -----------------------------------------------------------------------------
-- 1. Seed the built-in "Admin" role.
--    is_system = true → locked in UI (cannot be edited or deleted).
-- -----------------------------------------------------------------------------
INSERT INTO public.custom_roles (name, description, color, permissions, is_system)
VALUES (
  'Admin',
  'Full system access — all modules and all actions.',
  'bg-rose-500/15 text-rose-600 border-rose-500/30',
  ARRAY[
    -- Master Data
    'master_data.companies.view',  'master_data.companies.manage',
    'master_data.divisions.view',  'master_data.divisions.manage',
    'master_data.warehouses.view', 'master_data.warehouses.manage',
    'master_data.inventory.view',  'master_data.inventory.manage',
    'master_data.suppliers.view',  'master_data.suppliers.manage',
    'master_data.users.view',      'master_data.users.manage',
    'master_data.roles.view',      'master_data.roles.manage',
    'master_data.audit.view',
    'master_data.admin.view',      'master_data.admin.manage',
    -- Purchase
    'purchase.orders.view', 'purchase.orders.create', 'purchase.orders.edit',
    'purchase.approvals.view', 'purchase.approvals.manage',
    'purchase.shipments.view', 'purchase.shipments.manage',
    'purchase.landed_costs.view', 'purchase.landed_costs.manage',
    'purchase.warehouses.view', 'purchase.warehouses.manage',
    'purchase.returns.view', 'purchase.returns.manage',
    'purchase.dead_stock.view',
    -- Sales
    'sales.orders.view', 'sales.orders.create', 'sales.orders.edit',
    'sales.returns.view', 'sales.returns.manage',
    -- Orders
    'orders.view', 'orders.create', 'orders.edit', 'orders.assign',
    -- Contracts
    'contracts.view', 'contracts.create', 'contracts.edit',
    -- Invoices & Payments
    'invoices.view', 'invoices.create', 'invoices.edit',
    'payments.view', 'payments.manage',
    -- Teams & Employees
    'teams.view', 'teams.manage',
    'employees.view', 'employees.manage',
    -- System
    'system.admin', 'system.import', 'system.export'
  ],
  true
)
ON CONFLICT (name) DO UPDATE
  SET description = EXCLUDED.description,
      permissions = EXCLUDED.permissions,
      is_system   = true;

-- -----------------------------------------------------------------------------
-- 2. Seed warehouse system roles: field_rp + inventory_manager.
-- -----------------------------------------------------------------------------
INSERT INTO public.custom_roles (name, description, is_system, permissions, color)
VALUES (
  'field_rp',
  'Field Responsible Person — physically manages a warehouse',
  true,
  ARRAY[
