-- ============================================================
-- Source: 20260712100000_inventory_unique_constraints.sql
-- ============================================================
-- ============================================================
-- Add unique constraints to inventory tables
--
-- Root cause: Excel import failed repeatedly because no unique
-- constraints existed. Partial imports left orphaned rows,
-- retries created duplicates, and the pipeline never completed
-- reliably. These constraints make upsert safe and prevent
-- duplicate data regardless of how many times import is retried.
-- ============================================================

BEGIN;

-- ── Step 1: Deduplicate existing data before adding constraints ──

-- 1a. inventory_categories: keep the oldest row per (lower(name_en), COALESCE(parent_id, '00000000-...'), type)
-- We use a sentinel UUID for NULL parent_id since UNIQUE treats NULLs as distinct.
DELETE FROM inventory_categories
WHERE id IN (
  SELECT id FROM (
    SELECT id,
           ROW_NUMBER() OVER (
             PARTITION BY lower(trim(name_en)), COALESCE(parent_id, '00000000-0000-0000-0000-000000000000'), type
             ORDER BY created_at ASC, id ASC
           ) AS rn
    FROM inventory_categories
  ) ranked
  WHERE rn > 1
);

-- 1b. inventory_items: keep the oldest row per (lower(name_en), category_id)
DELETE FROM inventory_items
WHERE id IN (
  SELECT id FROM (
    SELECT id,
           ROW_NUMBER() OVER (
             PARTITION BY lower(trim(name_en)), category_id
             ORDER BY created_at ASC, id ASC
           ) AS rn
    FROM inventory_items
  ) ranked
  WHERE rn > 1
);

-- 1c. inventory_brand_variants: keep the oldest row per (item_id, lower(brand))
DELETE FROM inventory_brand_variants
WHERE id IN (
  SELECT id FROM (
    SELECT id,
           ROW_NUMBER() OVER (
             PARTITION BY item_id, lower(trim(brand))
             ORDER BY created_at ASC, id ASC
           ) AS rn
    FROM inventory_brand_variants
  ) ranked
  WHERE rn > 1
);

-- ── Step 2: Add unique indexes ──

-- Categories: unique per (type, parent, name). Two indexes because
-- parent_id can be NULL and standard UNIQUE treats NULLs as distinct.
CREATE UNIQUE INDEX IF NOT EXISTS uq_inventory_categories_name_parent_type
  ON inventory_categories (type, parent_id, lower(trim(name_en)))
  WHERE parent_id IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uq_inventory_categories_name_root_type
  ON inventory_categories (type, lower(trim(name_en)))
  WHERE parent_id IS NULL;

-- Items: unique per (category, name)
CREATE UNIQUE INDEX IF NOT EXISTS uq_inventory_items_name_category
  ON inventory_items (category_id, lower(trim(name_en)));

-- Brand variants: unique per (item, brand)
CREATE UNIQUE INDEX IF NOT EXISTS uq_inventory_brand_variants_item_brand
  ON inventory_brand_variants (item_id, lower(trim(brand)));

COMMIT;

NOTIFY pgrst, 'reload schema';


-- ============================================================
-- Source: 20260712120000_avatars_storage_bucket.sql
-- ============================================================
-- Create avatars storage bucket for user profile photos
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES (
  'avatars',
  'avatars',
  true,
  5 * 1024 * 1024,
  ARRAY['image/jpeg', 'image/png', 'image/webp', 'image/gif']
)
ON CONFLICT (id) DO NOTHING;

-- Public read
CREATE POLICY "avatars_public_read"
  ON storage.objects FOR SELECT
  USING (bucket_id = 'avatars');

-- Authenticated users can upload their own avatar
CREATE POLICY "avatars_auth_insert"
  ON storage.objects FOR INSERT
  TO authenticated
  WITH CHECK (bucket_id = 'avatars');

-- Authenticated users can update their own avatar
CREATE POLICY "avatars_auth_update"
  ON storage.objects FOR UPDATE
  TO authenticated
  USING (bucket_id = 'avatars');

-- Authenticated users can delete their own avatar
CREATE POLICY "avatars_auth_delete"
  ON storage.objects FOR DELETE
  TO authenticated
  USING (bucket_id = 'avatars');


-- ============================================================
-- Source: 20260713100000_notifications_actioned_at.sql
-- ============================================================
-- Add actioned_at column to notifications for tracking whether the user
-- completed the required action (e.g. approved a PO, resolved a transfer).
-- read_at = user saw it, actioned_at = user completed the action.
ALTER TABLE public.notifications
  ADD COLUMN IF NOT EXISTS actioned_at timestamptz;

-- Index for querying pending (not actioned) notifications efficiently
CREATE INDEX IF NOT EXISTS idx_notifications_profile_pending
  ON public.notifications (profile_id, created_at DESC)
  WHERE actioned_at IS NULL;


-- ============================================================
-- Source: 20260713110000_notifications_auto_cleanup.sql
-- ============================================================
-- Auto-cleanup for completed notifications.
-- Deletes actioned notifications older than 45 days.
-- Intended to run quarterly via pg_cron (or manually).

CREATE OR REPLACE FUNCTION public.cleanup_old_notifications()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  deleted_count integer;
BEGIN
  DELETE FROM public.notifications
  WHERE actioned_at IS NOT NULL
    AND actioned_at < NOW() - INTERVAL '45 days';

  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;

-- Schedule quarterly cleanup (1st of Jan, Apr, Jul, Oct at 03:00 UTC).
-- pg_cron is enabled on Supabase Pro plans; on Free plan this is a no-op
-- and the function can be called manually instead.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_extension WHERE extname = 'pg_cron'
  ) THEN
    PERFORM cron.schedule(
      'cleanup-old-notifications',
      '0 3 1 1,4,7,10 *',
      'SELECT public.cleanup_old_notifications()'
    );
  END IF;
END;
$$;


-- ============================================================
-- Source: 20260713165620_fix_credit_summary_security.sql
-- ============================================================
-- Fix: customer_credit_summary was created WITHOUT security_invoker,
-- which bypasses RLS on the underlying customers table.
-- Any authenticated user could read every customer's credit data.
-- Re-create with security_invoker = true so RLS is enforced per-caller.

CREATE OR REPLACE VIEW public.customer_credit_summary
  WITH (security_invoker = true)
AS
SELECT
  c.id                                              AS customer_id,
  c.name                                            AS customer_name,
  c.name_ar                                         AS customer_name_ar,
  c.customer_type                                   AS customer_type,
  c.is_blocked                                      AS is_blocked,
  c.credit_group_id                                 AS credit_group_id,
  cg.name                                           AS credit_group_name,
  CASE
    WHEN c.customer_type = 'cash' THEN 0
    WHEN cg.credit_limit IS NOT NULL THEN cg.credit_limit
    ELSE COALESCE(c.credit_limit, 0)
  END                                               AS credit_limit,
  public.customer_credit_used(c.id, NULL)           AS credit_used,
  GREATEST(
    CASE
      WHEN c.customer_type = 'cash' THEN 0
      WHEN cg.credit_limit IS NOT NULL THEN cg.credit_limit
      ELSE COALESCE(c.credit_limit, 0)
    END
    - public.customer_credit_used(c.id, NULL),
    0
  )                                                 AS credit_available,
  CASE
    WHEN COALESCE(
           CASE WHEN c.customer_type = 'cash' THEN 0
                WHEN cg.credit_limit IS NOT NULL THEN cg.credit_limit
                ELSE COALESCE(c.credit_limit, 0) END,
           0) = 0
      THEN NULL
    ELSE LEAST(
      ROUND(
        public.customer_credit_used(c.id, NULL)
        / NULLIF(CASE
                   WHEN c.customer_type = 'cash' THEN 0
                   WHEN cg.credit_limit IS NOT NULL THEN cg.credit_limit
                   ELSE COALESCE(c.credit_limit, 0)
                 END, 0)
        * 100, 1),
      100
    )
  END                                               AS credit_utilization_pct
FROM   public.customers c
LEFT   JOIN public.credit_groups cg ON cg.id = c.credit_group_id;

GRANT SELECT ON public.customer_credit_summary TO authenticated, service_role;


-- ============================================================
-- Source: 20260713170000_fix_views_security_invoker.sql
-- ============================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- Fix: warehouse_stock_view missing security_invoker = true
--
-- Without security_invoker, the view runs as the view owner (postgres),
-- bypassing RLS on the underlying tables (fifo_cost_layers,
-- inventory_brand_variants, inventory_items, inventory_categories,
-- warehouse_stock_allocations).
--
-- The 5 compatibility views from the rename migration (approval_chains,
-- approval_chain_tiers, approval_requests, workflow_approval_steps,
-- service_change_requests) were already dropped in migration 20260627114000.
-- The 2 divisions compat views were dropped in 20260627116000.
-- customer_credit_summary was fixed in 20260713165620.
--
-- This leaves warehouse_stock_view as the only remaining view without
-- security_invoker.
-- ─────────────────────────────────────────────────────────────────────────────

ALTER VIEW public.warehouse_stock_view SET (security_invoker = true);


