-- ============================================================
-- Source: 20260713200100_cogs_entries_source_type.sql
-- ============================================================
-- Add source_type column to cogs_entries for clear differentiation
-- between sale COGS, landed cost adjustments, and LC reversals.

-- ── 1. Add column ───────────────────────────────────────────────────────────

ALTER TABLE public.cogs_entries
  ADD COLUMN IF NOT EXISTS source_type text NOT NULL DEFAULT 'sale';

COMMENT ON COLUMN public.cogs_entries.source_type IS
  'Origin of this COGS entry: sale, landed_cost, or landed_cost_reversal';

-- ── 2. Backfill existing rows ───────────────────────────────────────────────

UPDATE public.cogs_entries
SET source_type = CASE
  WHEN landed_cost_id IS NOT NULL AND total_cost < 0 THEN 'landed_cost_reversal'
  WHEN landed_cost_id IS NOT NULL                    THEN 'landed_cost'
  ELSE 'sale'
END
WHERE source_type = 'sale'
  AND landed_cost_id IS NOT NULL;

-- ── 3. Update complete_delivery_inventory — sale entries ────────────────────

CREATE OR REPLACE FUNCTION complete_delivery_inventory(
  p_delivery_id UUID,
  p_so_id       UUID
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_delivery  RECORD;
  v_item      JSONB;
  v_bv_id     UUID;
  v_qty       INT;
  v_wh_id     UUID;
  v_date      DATE;
  v_result    RECORD;
  v_all_delivered BOOLEAN;
  v_any_delivered BOOLEAN;
BEGIN
  SELECT warehouse_id, date, items, status
  INTO v_delivery
  FROM sale_deliveries
  WHERE id = p_delivery_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Delivery % not found', p_delivery_id;
  END IF;

  IF v_delivery.status <> 'pending' THEN
    RAISE EXCEPTION 'Delivery % already processed with status %', p_delivery_id, v_delivery.status;
  END IF;

  v_wh_id := v_delivery.warehouse_id;
  v_date  := COALESCE(v_delivery.date, CURRENT_DATE);

  UPDATE sale_deliveries SET status = 'delivered', updated_at = now() WHERE id = p_delivery_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_delivery.items)
  LOOP
    v_bv_id := (v_item->>'brand_variant_id')::UUID;
    v_qty   := (v_item->>'qty_delivered')::INT;

    CONTINUE WHEN v_bv_id IS NULL OR v_qty IS NULL OR v_qty <= 0;

    SELECT total_cost, weighted_unit_cost
    INTO v_result
    FROM deduct_fifo_layers(v_bv_id, v_wh_id, v_qty, false);

    UPDATE inventory_brand_variants
    SET reserved_qty = GREATEST(0, reserved_qty - v_qty),
        updated_at   = now()
    WHERE id = v_bv_id;

    UPDATE sale_order_lines
    SET    delivered_qty = COALESCE(delivered_qty, 0) + v_qty
    WHERE  sale_order_id = p_so_id
      AND  brand_variant_id = v_bv_id;

    INSERT INTO cogs_entries (
      brand_variant_id, sale_delivery_id, sale_order_id,
      qty, unit_cost, total_cost, date, source_type
    ) VALUES (
      v_bv_id, p_delivery_id, p_so_id,
      v_qty, v_result.weighted_unit_cost, v_result.total_cost, v_date,
      'sale'
    );

    INSERT INTO inventory_stock_movements (
      warehouse_id, brand_variant_id,
      item_name, sku, movement_type, qty, unit_cost,
      reference_type, reference_id
    ) VALUES (
      v_wh_id, v_bv_id,
      COALESCE(v_item->>'item_name', ''),
      v_item->>'sku',
      'sale_delivery', -v_qty, v_result.weighted_unit_cost,
      'sale_delivery', p_delivery_id
    );
  END LOOP;

  SELECT
    bool_and(COALESCE(delivered_qty, 0) >= qty),
    bool_or(COALESCE(delivered_qty, 0) > 0)
  INTO v_all_delivered, v_any_delivered
  FROM sale_order_lines
  WHERE sale_order_id = p_so_id;

  IF v_all_delivered THEN
    UPDATE sale_orders
    SET    status = 'delivered', updated_at = now()
    WHERE  id = p_so_id
      AND  status IN ('confirmed', 'partial_delivery');
  ELSIF v_any_delivered THEN
    UPDATE sale_orders
    SET    status = 'partial_delivery', updated_at = now()
    WHERE  id = p_so_id
      AND  status = 'confirmed';
  END IF;
END;
$$;

GRANT EXECUTE ON FUNCTION complete_delivery_inventory(UUID, UUID) TO authenticated;

-- ── 4. Update allocate_landed_cost — landed_cost entries ────────────────────

DROP FUNCTION IF EXISTS public.allocate_landed_cost(uuid);

CREATE FUNCTION public.allocate_landed_cost(p_lc_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lc                RECORD;
  v_apply_time        TIMESTAMPTZ := now();
  v_grand_total       NUMERIC := 0;
  v_total_remaining   BIGINT  := 0;
  v_allocations       JSONB   := '[]'::JSONB;
  v_snapshot          JSONB   := '[]'::JSONB;
  v_bv                RECORD;
  v_bv_lc_share       NUMERIC;
  v_bv_remaining      BIGINT;
  v_sold              BIGINT;
  v_per_unit_lc       NUMERIC;
  v_inventory_portion NUMERIC;
  v_cogs_portion      NUMERIC;
BEGIN
  SELECT * INTO v_lc FROM landed_costs WHERE id = p_lc_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Landed cost % not found', p_lc_id;
  END IF;
  IF v_lc.applied_at IS NOT NULL THEN
    RAISE EXCEPTION 'Landed cost % has already been applied', v_lc.lc_number;
  END IF;
  IF v_lc.voided_at IS NOT NULL THEN
    RAISE EXCEPTION 'Cannot apply voided landed cost %', v_lc.lc_number;
  END IF;

  SELECT COALESCE(SUM(ri.qty_received * ri.unit_cost), 0)
    INTO v_grand_total
    FROM receival_items ri
    JOIN receivals rv ON rv.id = ri.receival_id AND rv.status = 'approved'
   WHERE ri.receival_id = ANY(v_lc.attached_receival_ids)
     AND ri.is_free          = false
     AND ri.brand_variant_id IS NOT NULL
     AND ri.qty_received     > 0;

  IF v_grand_total = 0 THEN
    RAISE EXCEPTION 'No eligible receival items found for landed cost %', v_lc.lc_number;
  END IF;

  FOR v_bv IN (
    SELECT
      ri.brand_variant_id,
      MAX(ri.item_name)                   AS item_name,
      MAX(ri.sku)                          AS sku,
      SUM(ri.qty_received)::BIGINT         AS qty_received,
      SUM(ri.qty_received * ri.unit_cost)  AS total_value,
      CASE WHEN SUM(ri.qty_received) > 0
        THEN SUM(ri.qty_received * ri.unit_cost) / SUM(ri.qty_received)
        ELSE 0 END                         AS avg_unit_cost
    FROM receival_items ri
    JOIN receivals rv ON rv.id = ri.receival_id AND rv.status = 'approved'
   WHERE ri.receival_id = ANY(v_lc.attached_receival_ids)
     AND ri.is_free          = false
     AND ri.brand_variant_id IS NOT NULL
     AND ri.qty_received     > 0
   GROUP BY ri.brand_variant_id
  ) LOOP
    v_bv_lc_share := v_lc.total_amount * (v_bv.total_value / v_grand_total);

    WITH locked_layers AS (
      SELECT remaining_qty
        FROM fifo_cost_layers
       WHERE brand_variant_id = v_bv.brand_variant_id
         AND remaining_qty    > 0
       FOR UPDATE
    )
    SELECT COALESCE(SUM(remaining_qty), 0)
      INTO v_bv_remaining
      FROM locked_layers;

    v_sold        := GREATEST(v_bv.qty_received - v_bv_remaining, 0);
    v_per_unit_lc := v_bv_lc_share / NULLIF(v_bv.qty_received, 0);

    IF v_sold <= 0 THEN
      v_inventory_portion := v_bv_lc_share;
      v_cogs_portion      := 0;
    ELSIF v_bv_remaining <= 0 THEN
      v_inventory_portion := 0;
      v_cogs_portion      := v_bv_lc_share;
    ELSE
      v_inventory_portion := ROUND(v_bv_remaining * v_per_unit_lc, 2);
      v_cogs_portion      := v_bv_lc_share - v_inventory_portion;
    END IF;

    v_allocations := v_allocations || jsonb_build_array(jsonb_build_object(
      'brand_variant_id',     v_bv.brand_variant_id,
      'item_name',            v_bv.item_name,
      'sku',                  v_bv.sku,
      'qty_received',         v_bv.qty_received,
      'qty_remaining_at_lc',  v_bv_remaining,
      'sold_qty',             v_sold,
      'original_unit_cost',   ROUND(v_bv.avg_unit_cost, 4),
      'per_unit_lc',          ROUND(COALESCE(v_per_unit_lc, 0), 4),
      'lc_per_unit',          ROUND(COALESCE(v_per_unit_lc, 0), 4),
      'inventory_portion',    ROUND(v_inventory_portion, 2),
      'cogs_portion',         ROUND(v_cogs_portion, 2),
      'allocated_lc_total',   ROUND(v_bv_lc_share, 2),
      'updated_unit_cost',    ROUND(v_bv.avg_unit_cost + COALESCE(v_per_unit_lc, 0), 4),
      'allocated_cost',       ROUND(v_bv_lc_share / GREATEST(v_bv.qty_received, 1), 4)
    ));

    -- ── Inventory side ──────────────────────────────────────────────────────
    IF v_bv_remaining > 0 THEN
      SELECT v_snapshot || COALESCE(
        (SELECT jsonb_agg(jsonb_build_object(
          'layer_id',          id::TEXT,
          'brand_variant_id',  brand_variant_id::TEXT,
          'lc_per_unit_delta', v_per_unit_lc
        ))
        FROM fifo_cost_layers
        WHERE brand_variant_id = v_bv.brand_variant_id
          AND remaining_qty    > 0),
        '[]'::JSONB
      )
      INTO v_snapshot;

      UPDATE fifo_cost_layers
         SET landed_cost_per_unit = landed_cost_per_unit + v_per_unit_lc,
             total_unit_cost      = total_unit_cost      + v_per_unit_lc
       WHERE brand_variant_id = v_bv.brand_variant_id
         AND remaining_qty    > 0;

      PERFORM recalc_average_cost(v_bv.brand_variant_id);

      INSERT INTO inventory_stock_movements
        (brand_variant_id, item_name, sku, movement_type, qty, unit_cost,
         reference_type, reference_id, notes)
      VALUES
        (v_bv.brand_variant_id, v_bv.item_name, v_bv.sku,
         'cost_adjustment', v_bv_remaining, v_per_unit_lc,
         'landed_cost', p_lc_id,
         'LC ' || v_lc.lc_number || ': '
           || ROUND(v_inventory_portion, 2) || ' ' || v_lc.currency
           || ' over ' || v_bv_remaining || ' remaining units');

      v_total_remaining := v_total_remaining + v_bv_remaining;
    END IF;

    -- ── COGS side ───────────────────────────────────────────────────────────
    IF v_sold > 0 THEN
      INSERT INTO cogs_entries (
        brand_variant_id, sale_delivery_id, sale_order_id, landed_cost_id,
        qty, unit_cost, total_cost, date, notes, source_type
      ) VALUES (
        v_bv.brand_variant_id, NULL, NULL, p_lc_id,
        v_sold, ROUND(COALESCE(v_per_unit_lc, 0), 4),
        ROUND(v_cogs_portion, 2),
        v_apply_time::DATE,
        'LC ' || v_lc.lc_number || ' applied ' || v_apply_time::DATE
          || ' over ' || v_sold || ' sold units',
        'landed_cost'
      );
    END IF;
  END LOOP;

  UPDATE landed_costs
     SET item_allocations = v_allocations,
         applied_at       = v_apply_time,
         all_items_sold   = (v_total_remaining = 0),
         revert_snapshot  = v_snapshot,
         updated_at       = v_apply_time
   WHERE id = p_lc_id;

  RETURN v_allocations;
END;
$$;

GRANT EXECUTE ON FUNCTION allocate_landed_cost(uuid) TO authenticated;

-- ── 5. Update revert_landed_cost — landed_cost_reversal entries ─────────────

DROP FUNCTION IF EXISTS public.revert_landed_cost(uuid);
DROP FUNCTION IF EXISTS public.revert_landed_cost(uuid, text);

CREATE FUNCTION public.revert_landed_cost(p_lc_id uuid, p_performer_name text DEFAULT 'System'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lc      RECORD;
  v_layer   JSONB;
  v_bv_ids  UUID[] := '{}';
  v_bv_id   UUID;
  v_now     TIMESTAMPTZ := now();
BEGIN
  SELECT * INTO v_lc FROM landed_costs WHERE id = p_lc_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Landed cost % not found', p_lc_id;
  END IF;
  IF v_lc.applied_at IS NULL THEN
    RAISE EXCEPTION 'Landed cost % has not been applied', p_lc_id;
  END IF;

  -- ── Inventory side: subtract per-layer delta from snapshot ────────────────
  IF v_lc.revert_snapshot IS NOT NULL AND jsonb_array_length(v_lc.revert_snapshot) > 0 THEN
    FOR v_layer IN SELECT * FROM jsonb_array_elements(v_lc.revert_snapshot) LOOP
      UPDATE fifo_cost_layers
         SET landed_cost_per_unit = landed_cost_per_unit - (v_layer->>'lc_per_unit_delta')::NUMERIC,
             total_unit_cost      = total_unit_cost      - (v_layer->>'lc_per_unit_delta')::NUMERIC
       WHERE id = (v_layer->>'layer_id')::UUID;

      v_bv_id := (v_layer->>'brand_variant_id')::UUID;
      IF NOT (v_bv_id = ANY(v_bv_ids)) THEN
        v_bv_ids := v_bv_ids || v_bv_id;
      END IF;
    END LOOP;

    FOREACH v_bv_id IN ARRAY v_bv_ids LOOP
      PERFORM recalc_average_cost(v_bv_id);
    END LOOP;

    INSERT INTO inventory_stock_movements
      (brand_variant_id, item_name, sku, movement_type, qty, unit_cost,
       reference_type, reference_id, notes)
    SELECT
      brand_variant_id, item_name, sku, 'cost_adjustment', qty,
      -unit_cost, 'landed_cost', p_lc_id,
      'Reversal of LC ' || v_lc.lc_number || ' — reverted by ' || p_performer_name
    FROM inventory_stock_movements
    WHERE reference_type = 'landed_cost'
      AND reference_id   = p_lc_id
      AND movement_type  = 'cost_adjustment'
      AND unit_cost      > 0;
  END IF;

  -- ── COGS side: insert reversing rows for each original LC-adjustment row ──
  INSERT INTO cogs_entries (
    brand_variant_id, sale_delivery_id, sale_order_id, landed_cost_id,
    qty, unit_cost, total_cost, date, notes, source_type
  )
  SELECT
    brand_variant_id, NULL, NULL, p_lc_id,
    -qty, unit_cost, -total_cost, v_now::DATE,
    'Reversal of LC ' || v_lc.lc_number || ' — reverted by ' || p_performer_name,
    'landed_cost_reversal'
  FROM cogs_entries
  WHERE landed_cost_id = p_lc_id
    AND total_cost     > 0;

  -- ── Reset the LC ──────────────────────────────────────────────────────────
  UPDATE landed_costs
     SET applied_at       = NULL,
         all_items_sold   = FALSE,
         item_allocations = NULL,
         revert_snapshot  = NULL,
         updated_at       = v_now
   WHERE id = p_lc_id;
END;
$$;

GRANT EXECUTE ON FUNCTION revert_landed_cost(uuid, text) TO authenticated;


-- ============================================================
-- Source: 20260715100000_normalize_schema.sql
-- ============================================================
-- ============================================================
-- Schema Normalization Migration
-- ============================================================
-- 1. Drop redundant credit_notes.line_items JSON column
-- 2. Create po_version_lines table, migrate JSON data, drop column
-- 3. Convert text FK columns to uuid with proper foreign keys
-- ============================================================

BEGIN;

-- ============================================================
-- 1) credit_notes: normalize line_items JSON into credit_note_lines
-- ============================================================

-- Add missing columns to credit_note_lines
ALTER TABLE public.credit_note_lines
  ADD COLUMN IF NOT EXISTS sku text,
  ADD COLUMN IF NOT EXISTS line_type text DEFAULT 'returned' NOT NULL,
  ADD COLUMN IF NOT EXISTS condition text,
  ADD COLUMN IF NOT EXISTS condition_notes text;

ALTER TABLE public.credit_note_lines
  ALTER COLUMN description DROP NOT NULL;

-- Migrate JSON returned_lines into credit_note_lines for notes
-- that have JSON data but no rows in credit_note_lines yet
INSERT INTO public.credit_note_lines (
    credit_note_id, description, sku, qty, unit_price, line_type,
    condition, condition_notes
)
SELECT
    cn.id,
    COALESCE(item->>'item_name', 'Item'),
    item->>'sku',
    COALESCE((item->>'qty')::numeric, 0),
    COALESCE((item->>'unit_price')::numeric, 0),
    'returned',
    item->>'condition',
    item->>'condition_notes'
FROM public.credit_notes cn,
     jsonb_array_elements(cn.line_items->'returned_lines') AS item
WHERE cn.line_items IS NOT NULL
  AND cn.line_items->'returned_lines' IS NOT NULL
  AND jsonb_typeof(cn.line_items->'returned_lines') = 'array'
  AND NOT EXISTS (
    SELECT 1 FROM public.credit_note_lines cl
    WHERE cl.credit_note_id = cn.id AND cl.line_type = 'returned'
  );

-- Migrate JSON original_lines into credit_note_lines
INSERT INTO public.credit_note_lines (
    credit_note_id, description, sku, qty, unit_price, line_type
)
SELECT
    cn.id,
    COALESCE(item->>'item_name', 'Item'),
    item->>'sku',
    COALESCE((item->>'qty')::numeric, 0),
    COALESCE((item->>'unit_price')::numeric, 0),
    'original'
FROM public.credit_notes cn,
     jsonb_array_elements(cn.line_items->'original_lines') AS item
WHERE cn.line_items IS NOT NULL
  AND cn.line_items->'original_lines' IS NOT NULL
  AND jsonb_typeof(cn.line_items->'original_lines') = 'array';

-- Drop the JSON column
ALTER TABLE public.credit_notes
  DROP COLUMN IF EXISTS line_items;

CREATE INDEX idx_credit_note_lines_type ON public.credit_note_lines(credit_note_id, line_type);


-- ============================================================
-- 2) po_versions: create po_version_lines table to replace
--    the line_items JSON column
-- ============================================================

CREATE TABLE public.po_version_lines (
    id             uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    po_version_id  uuid NOT NULL REFERENCES public.po_versions(id) ON DELETE CASCADE,
    item_name      text NOT NULL,
    sku            text,
    qty            integer NOT NULL DEFAULT 0,
    received_qty   integer DEFAULT 0,
    unit           text NOT NULL DEFAULT 'pcs',
    unit_price     numeric NOT NULL DEFAULT 0,
    total_price    numeric NOT NULL DEFAULT 0,
    brand_variant_id uuid,
    tool_asset_item_id uuid,
    free_qty       integer DEFAULT 0 NOT NULL,
    brand_id       uuid,
    created_at     timestamptz DEFAULT now()
);

CREATE INDEX idx_po_version_lines_version ON public.po_version_lines(po_version_id);

-- Migrate existing JSON data into the new table
INSERT INTO public.po_version_lines (
    po_version_id, item_name, sku, qty, received_qty,
    unit, unit_price, total_price, brand_variant_id,
    tool_asset_item_id, free_qty, brand_id
)
SELECT
    pv.id AS po_version_id,
    COALESCE(item->>'item_name', 'Unknown')         AS item_name,
    item->>'sku'                                     AS sku,
    COALESCE((item->>'qty')::integer, 0)             AS qty,
    COALESCE((item->>'received_qty')::integer, 0)    AS received_qty,
    COALESCE(item->>'unit', 'pcs')                   AS unit,
    COALESCE((item->>'unit_price')::numeric, 0)      AS unit_price,
    COALESCE((item->>'total_price')::numeric, 0)     AS total_price,
    CASE WHEN item->>'brand_variant_id' IS NOT NULL
         AND item->>'brand_variant_id' != 'null'
         THEN (item->>'brand_variant_id')::uuid END  AS brand_variant_id,
    CASE WHEN item->>'tool_asset_item_id' IS NOT NULL
         AND item->>'tool_asset_item_id' != 'null'
         THEN (item->>'tool_asset_item_id')::uuid END AS tool_asset_item_id,
    COALESCE((item->>'free_qty')::integer, 0)        AS free_qty,
    CASE WHEN item->>'brand_id' IS NOT NULL
         AND item->>'brand_id' != 'null'
         THEN (item->>'brand_id')::uuid END           AS brand_id
FROM public.po_versions pv,
     jsonb_array_elements(pv.line_items) AS item
WHERE pv.line_items IS NOT NULL
  AND jsonb_typeof(pv.line_items) = 'array'
  AND jsonb_array_length(pv.line_items) > 0;

-- Drop the JSON column
ALTER TABLE public.po_versions
  DROP COLUMN line_items;


-- ============================================================
-- 3a) purchase_orders.supplier_id: text → uuid FK to suppliers
-- ============================================================

-- Add new uuid column
ALTER TABLE public.purchase_orders
  ADD COLUMN supplier_id_new uuid;

-- Populate from suppliers table by matching the text value as uuid
UPDATE public.purchase_orders po
SET supplier_id_new = s.id
FROM public.suppliers s
WHERE po.supplier_id::uuid = s.id;

-- For any rows where the text wasn't a valid uuid or didn't match,
-- try matching by supplier_name
UPDATE public.purchase_orders po
SET supplier_id_new = s.id
FROM public.suppliers s
WHERE po.supplier_id_new IS NULL
  AND po.supplier_name = s.name;

-- Swap columns
ALTER TABLE public.purchase_orders DROP COLUMN supplier_id;
ALTER TABLE public.purchase_orders RENAME COLUMN supplier_id_new TO supplier_id;
ALTER TABLE public.purchase_orders
  ADD CONSTRAINT purchase_orders_supplier_id_fkey
    FOREIGN KEY (supplier_id) REFERENCES public.suppliers(id);

CREATE INDEX idx_purchase_orders_supplier ON public.purchase_orders(supplier_id);


-- ============================================================
-- 3b) po_versions.supplier_id: text → uuid FK to suppliers
-- ============================================================

ALTER TABLE public.po_versions
  ADD COLUMN supplier_id_new uuid;

UPDATE public.po_versions pv
SET supplier_id_new = s.id
FROM public.suppliers s
WHERE pv.supplier_id::uuid = s.id;

UPDATE public.po_versions pv
SET supplier_id_new = s.id
FROM public.suppliers s
WHERE pv.supplier_id_new IS NULL
  AND pv.supplier_name = s.name;

ALTER TABLE public.po_versions DROP COLUMN supplier_id;
ALTER TABLE public.po_versions RENAME COLUMN supplier_id_new TO supplier_id;
ALTER TABLE public.po_versions
  ADD CONSTRAINT po_versions_supplier_id_fkey
    FOREIGN KEY (supplier_id) REFERENCES public.suppliers(id);

CREATE INDEX idx_po_versions_supplier ON public.po_versions(supplier_id);


-- ============================================================
-- 3c) fifo_cost_layers.receival_id: text → uuid FK to receivals
-- ============================================================

ALTER TABLE public.fifo_cost_layers
  ADD COLUMN receival_id_new uuid;

UPDATE public.fifo_cost_layers fcl
SET receival_id_new = r.id
FROM public.receivals r
WHERE fcl.receival_id IS NOT NULL
  AND fcl.receival_id::uuid = r.id;

-- Fallback: match by receival_number
UPDATE public.fifo_cost_layers fcl
SET receival_id_new = r.id
FROM public.receivals r
WHERE fcl.receival_id_new IS NULL
  AND fcl.receival_id IS NOT NULL
  AND fcl.receival_number = r.receival_number;

ALTER TABLE public.fifo_cost_layers DROP COLUMN receival_id;
ALTER TABLE public.fifo_cost_layers RENAME COLUMN receival_id_new TO receival_id;
ALTER TABLE public.fifo_cost_layers
  ADD CONSTRAINT fifo_cost_layers_receival_id_fkey
    FOREIGN KEY (receival_id) REFERENCES public.receivals(id);

CREATE INDEX idx_fifo_cost_layers_receival ON public.fifo_cost_layers(receival_id);


-- ============================================================
-- Enable RLS on new table (match existing pattern)
-- ============================================================

ALTER TABLE public.po_version_lines ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Authenticated users can read po_version_lines"
  ON public.po_version_lines FOR SELECT
  TO authenticated
  USING (true);

CREATE POLICY "Authenticated users can insert po_version_lines"
  ON public.po_version_lines FOR INSERT
  TO authenticated
  WITH CHECK (true);

CREATE POLICY "Authenticated users can delete po_version_lines"
  ON public.po_version_lines FOR DELETE
  TO authenticated
  USING (true);

COMMIT;


-- ============================================================
-- Source: 20260715120000_invoice_text_to_enum.sql
-- ============================================================
-- ============================================================
-- Convert invoice text columns to enums
-- ============================================================

BEGIN;

-- 1) Create enums
CREATE TYPE public.invoice_doc_status AS ENUM (
  'draft',
  'ready_to_send',
  'sent',
  'pending_approval',
  'approved',
  'rejected'
);

CREATE TYPE public.invoice_payment_status AS ENUM (
  'unpaid',
  'partially_paid',
  'paid',
  'overdue'
);

-- 2) Drop all dependents
DROP VIEW IF EXISTS public.customer_invoices;
DROP VIEW IF EXISTS public.supplier_bills;
DROP INDEX IF EXISTS public.idx_invoices_ar_status;
ALTER TABLE public.invoices DROP CONSTRAINT IF EXISTS invoices_doc_status_check;
ALTER TABLE public.invoices DROP CONSTRAINT IF EXISTS invoices_payment_status_check;

-- 3) Convert doc_status: text → enum
ALTER TABLE public.invoices
  ALTER COLUMN doc_status DROP DEFAULT;
ALTER TABLE public.invoices
  ALTER COLUMN doc_status TYPE public.invoice_doc_status
    USING doc_status::public.invoice_doc_status;
ALTER TABLE public.invoices
  ALTER COLUMN doc_status SET DEFAULT 'draft'::public.invoice_doc_status;

-- 4) Convert payment_status: text → enum
ALTER TABLE public.invoices
  ALTER COLUMN payment_status DROP DEFAULT;
ALTER TABLE public.invoices
  ALTER COLUMN payment_status TYPE public.invoice_payment_status
    USING payment_status::public.invoice_payment_status;
ALTER TABLE public.invoices
  ALTER COLUMN payment_status SET DEFAULT 'unpaid'::public.invoice_payment_status;

-- 5) Recreate index
CREATE INDEX idx_invoices_ar_status
  ON public.invoices USING btree (direction, status, payment_status)
  WHERE (direction = 'ar');

-- 6) Recreate views
CREATE VIEW public.customer_invoices WITH (security_invoker='true') AS
 SELECT id, invoice_id, customer_id, source, source_id, source_label,
        issued_date, due_date, status, subtotal, tax, total_amount,
        paid_amount, agent_name, division, notes, qb_synced,
        created_at, updated_at, direction, supplier_id,
        purchase_order_id, receival_id, sale_order_id, sale_delivery_id,
        needs_refresh, doc_status, payment_status, invoice_type,
        discount_amount, discount_label, manually_paid
   FROM public.invoices
  WHERE direction = 'ar';

CREATE VIEW public.supplier_bills WITH (security_invoker='true') AS
 SELECT id, invoice_id, customer_id, source, source_id, source_label,
        issued_date, due_date, status, subtotal, tax, total_amount,
        paid_amount, agent_name, division, notes, qb_synced,
        created_at, updated_at, direction, supplier_id,
        purchase_order_id, receival_id, sale_order_id, sale_delivery_id,
        needs_refresh, doc_status, payment_status, invoice_type,
        discount_amount, discount_label, manually_paid
   FROM public.invoices
  WHERE direction = 'ap';

COMMIT;


-- ============================================================
-- Source: 20260715140000_drop_warehouse_transfers_items_json.sql
-- ============================================================
-- ============================================================
-- Drop redundant warehouse_transfers.items JSON column
-- Data already lives in warehouse_transfer_items table
-- ============================================================

BEGIN;

-- Migrate any JSON items that don't yet have rows in warehouse_transfer_items
INSERT INTO public.warehouse_transfer_items (
    transfer_id, brand_variant_id, item_name, sku,
    requested_qty, unit_cost, shrinkage_qty
)
SELECT
    wt.id,
    (item->>'brand_variant_id')::uuid,
    COALESCE(item->>'item_name', 'Item'),
    item->>'sku',
    COALESCE((item->>'qty')::integer, 0),
    COALESCE((item->>'unit_cost')::numeric, 0),
    0
FROM public.warehouse_transfers wt,
     jsonb_array_elements(wt.items) AS item
WHERE wt.items IS NOT NULL
  AND jsonb_typeof(wt.items) = 'array'
  AND NOT EXISTS (
    SELECT 1 FROM public.warehouse_transfer_items wti
