-- Source: 20260715200000_add_fk_constraints_and_cleanup.sql
-- ============================================================
-- ============================================================
-- Add missing FK constraints, drop orphan column, add PK
-- ============================================================

BEGIN;

-- ── 1) Add FK constraints on brand_variant_id columns ───────────────────────
-- These columns store inventory_brand_variants IDs but had no FK constraint
-- because they were migrated from unstructured JSONB data.

ALTER TABLE public.return_lines
  ADD CONSTRAINT return_lines_brand_variant_id_fkey
    FOREIGN KEY (brand_variant_id) REFERENCES public.inventory_brand_variants(id);

ALTER TABLE public.sale_delivery_lines
  ADD CONSTRAINT sale_delivery_lines_brand_variant_id_fkey
    FOREIGN KEY (brand_variant_id) REFERENCES public.inventory_brand_variants(id);

ALTER TABLE public.landed_cost_item_allocations
  ADD CONSTRAINT landed_cost_item_alloc_brand_variant_id_fkey
    FOREIGN KEY (brand_variant_id) REFERENCES public.inventory_brand_variants(id);


-- ── 2) Drop orphan column sale_order_lines.item_id ──────────────────────────
-- Legacy text column with no FK constraint and zero app code references.
-- brand_variant_id (uuid FK) is the canonical relationship.

ALTER TABLE public.sale_order_lines
  DROP COLUMN IF EXISTS item_id;


-- ── 3) Add FK constraints to warehouse_stock_allocations ────────────────────
-- Table already has a PK; just add FK constraints if missing.

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'warehouse_stock_alloc_warehouse_id_fkey'
  ) THEN
    ALTER TABLE public.warehouse_stock_allocations
      ADD CONSTRAINT warehouse_stock_alloc_warehouse_id_fkey
        FOREIGN KEY (warehouse_id) REFERENCES public.warehouses(id);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'warehouse_stock_alloc_brand_variant_id_fkey'
  ) THEN
    ALTER TABLE public.warehouse_stock_allocations
      ADD CONSTRAINT warehouse_stock_alloc_brand_variant_id_fkey
        FOREIGN KEY (brand_variant_id) REFERENCES public.inventory_brand_variants(id);
  END IF;
END $$;

COMMIT;


-- ============================================================
-- Source: 20260715220000_invoice_type_direction_enums.sql
-- ============================================================
-- ============================================================
-- Convert invoices.invoice_type (text→enum) and
--          invoices.direction   (text→enum)
--
-- Must drop all dependent objects first:
--   - 2 views (customer_invoices, supplier_bills)
--   - 2 partial indexes (idx_invoices_ar_status, idx_invoices_customer_phone_ar)
--   - 2 CHECK constraints (invoices_invoice_type_check, invoices_direction_check)
--
-- PL/pgSQL functions are NOT dropped — they auto-resolve
-- untyped string literals to the new enum type at call time.
-- ============================================================

BEGIN;

-- ── 0) Drop dependent objects ──────────────────────────────────────────────

DROP VIEW IF EXISTS public.customer_invoices;
DROP VIEW IF EXISTS public.supplier_bills;

DROP INDEX IF EXISTS public.idx_invoices_ar_status;
DROP INDEX IF EXISTS public.idx_invoices_customer_phone_ar;

ALTER TABLE public.invoices DROP CONSTRAINT IF EXISTS invoices_invoice_type_check;
ALTER TABLE public.invoices DROP CONSTRAINT IF EXISTS invoices_direction_check;


-- ── 1) invoice_type text → enum ────────────────────────────────────────────

DO $$ BEGIN
  CREATE TYPE public.invoice_type AS ENUM ('cash', 'credit');
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

ALTER TABLE public.invoices
  ALTER COLUMN invoice_type DROP DEFAULT;

ALTER TABLE public.invoices
  ALTER COLUMN invoice_type TYPE public.invoice_type
    USING invoice_type::public.invoice_type;

ALTER TABLE public.invoices
  ALTER COLUMN invoice_type SET DEFAULT 'credit'::public.invoice_type;

ALTER TABLE public.invoices
  ALTER COLUMN invoice_type SET NOT NULL;


-- ── 2) direction text → enum ───────────────────────────────────────────────

DO $$ BEGIN
  CREATE TYPE public.invoice_direction AS ENUM ('ar', 'ap');
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

ALTER TABLE public.invoices
  ALTER COLUMN direction DROP DEFAULT;

ALTER TABLE public.invoices
  ALTER COLUMN direction TYPE public.invoice_direction
    USING direction::public.invoice_direction;

ALTER TABLE public.invoices
  ALTER COLUMN direction SET DEFAULT 'ar'::public.invoice_direction;

ALTER TABLE public.invoices
  ALTER COLUMN direction SET NOT NULL;


-- ── 3) Recreate partial indexes with enum-typed WHERE ──────────────────────

CREATE INDEX idx_invoices_ar_status
  ON public.invoices USING btree (direction, status, payment_status)
  WHERE (direction = 'ar'::public.invoice_direction);

CREATE INDEX idx_invoices_customer_phone_ar
  ON public.invoices USING btree (customer_id, phone_id)
  WHERE (direction = 'ar'::public.invoice_direction);


-- ── 4) Recreate views with security_invoker ────────────────────────────────

CREATE VIEW public.customer_invoices WITH (security_invoker='true') AS
 SELECT id, invoice_id, customer_id, source, source_id, source_label,
        issued_date, due_date, status, subtotal, tax, total_amount,
        paid_amount, agent_name, division, notes, qb_synced,
        created_at, updated_at, direction, supplier_id,
        purchase_order_id, receival_id, sale_order_id, sale_delivery_id,
        needs_refresh, doc_status, payment_status, invoice_type,
        discount_amount, discount_label, manually_paid
   FROM public.invoices
  WHERE direction = 'ar'::public.invoice_direction;

CREATE VIEW public.supplier_bills WITH (security_invoker='true') AS
 SELECT id, invoice_id, customer_id, source, source_id, source_label,
        issued_date, due_date, status, subtotal, tax, total_amount,
        paid_amount, agent_name, division, notes, qb_synced,
        created_at, updated_at, direction, supplier_id,
        purchase_order_id, receival_id, sale_order_id, sale_delivery_id,
        needs_refresh, doc_status, payment_status, invoice_type,
        discount_amount, discount_label, manually_paid
   FROM public.invoices
  WHERE direction = 'ap'::public.invoice_direction;

COMMIT;


-- ============================================================
-- Source: 20260715230000_add_status_check_constraints.sql
-- ============================================================
-- Add CHECK constraints on 8 text status columns that lack value validation.
-- All existing data has been verified against production — no rows violate these constraints.

BEGIN;

-- 1. inventory_brand_variants: active | archived
ALTER TABLE public.inventory_brand_variants
  ADD CONSTRAINT inventory_brand_variants_status_check
    CHECK (status = ANY (ARRAY['active'::text, 'archived'::text]));

-- 2. inventory_categories: active | archived
ALTER TABLE public.inventory_categories
  ADD CONSTRAINT inventory_categories_status_check
    CHECK (status = ANY (ARRAY['active'::text, 'archived'::text]));

-- 3. inventory_items: active | archived
ALTER TABLE public.inventory_items
  ADD CONSTRAINT inventory_items_status_check
    CHECK (status = ANY (ARRAY['active'::text, 'archived'::text]));

-- 4. inventory_checks: draft → in_progress → pending_approval → approved | rejected
ALTER TABLE public.inventory_checks
  ADD CONSTRAINT inventory_checks_status_check
    CHECK (status = ANY (ARRAY[
      'draft'::text,
      'in_progress'::text,
      'pending_approval'::text,
      'approved'::text,
      'rejected'::text
    ]));

-- 5. inventory_check_approvals: pending → approved | rejected
--    (already has inv_check_approvals_rejected_needs_notes_chk, adding value constraint)
ALTER TABLE public.inventory_check_approvals
  ADD CONSTRAINT inventory_check_approvals_status_check
    CHECK (status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text]));

-- 6. inventory_check_assignments: pending → completed
ALTER TABLE public.inventory_check_assignments
  ADD CONSTRAINT inventory_check_assignments_status_check
    CHECK (status = ANY (ARRAY['pending'::text, 'completed'::text]));

-- 7. stock_adjustments: pending_approval → approved | rejected
ALTER TABLE public.stock_adjustments
  ADD CONSTRAINT stock_adjustments_status_check
    CHECK (status = ANY (ARRAY[
      'pending_approval'::text,
      'approved'::text,
      'rejected'::text
    ]));

-- 8. payment_sessions: open → completed | expired | cancelled
ALTER TABLE public.payment_sessions
  ADD CONSTRAINT payment_sessions_status_check
    CHECK (status = ANY (ARRAY[
      'open'::text,
      'completed'::text,
      'expired'::text,
      'cancelled'::text
    ]));

COMMIT;


