-- ============================================================
-- Source: 20260716100000_rpc_profitability_drilldown.sql
-- ============================================================
-- SO-level drill-down for Product Profitability KPI cards.
-- Returns an array of sale orders with nested line items,
-- showing revenue, COGS, and profit at both SO and line level.
-- Uses ce.qty (not sol.qty) for revenue to avoid overcounting
-- when multiple FIFO layers exist per SO line.

CREATE OR REPLACE FUNCTION public.rpc_profitability_drilldown(
  p_start_date date,
  p_end_date   date
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF p_start_date IS NULL OR p_end_date IS NULL THEN
    RAISE EXCEPTION 'Start and end dates are required';
  END IF;
  IF p_end_date < p_start_date THEN
    RAISE EXCEPTION 'End date must be >= start date';
  END IF;

  RETURN COALESCE((
    WITH line_data AS (
      SELECT
        ce.sale_order_id,
        ce.brand_variant_id,
        SUM(ce.qty)::numeric                              AS qty,
        SUM(ce.qty * sol.unit_price)                      AS line_revenue,
        SUM(ce.total_cost)                                AS line_cogs,
        SUM(ce.qty * sol.unit_price) - SUM(ce.total_cost) AS line_profit,
        sol.unit_price,
        (array_agg(sol.item_name ORDER BY sol.created_at DESC))[1] AS item_name,
        (array_agg(sol.sku       ORDER BY sol.created_at DESC))[1] AS sku
      FROM cogs_entries ce
      JOIN sale_order_lines sol
        ON sol.sale_order_id  = ce.sale_order_id
       AND sol.brand_variant_id = ce.brand_variant_id
      WHERE ce.date >= p_start_date
        AND ce.date <= p_end_date
        AND ce.sale_order_id IS NOT NULL
      GROUP BY ce.sale_order_id, ce.brand_variant_id, sol.unit_price
    ),
    so_agg AS (
      SELECT
        ld.sale_order_id,
        so.so_number,
        so.created_at::date              AS order_date,
        COALESCE(c.name, 'Walk-in')      AS customer_name,
        COUNT(*)::int                    AS item_count,
        SUM(ld.line_revenue)             AS revenue,
        SUM(ld.line_cogs)                AS cogs,
        SUM(ld.line_profit)              AS profit,
        CASE WHEN SUM(ld.line_revenue) = 0 THEN NULL
             ELSE ROUND((SUM(ld.line_profit) / SUM(ld.line_revenue)) * 100, 2)
        END                              AS margin_pct,
        jsonb_agg(
          jsonb_build_object(
            'brand_variant_id', ld.brand_variant_id,
            'item_name',        ld.item_name,
            'sku',              ld.sku,
            'qty',              ld.qty,
            'unit_price',       ld.unit_price,
            'revenue',          ld.line_revenue,
            'cogs',             ld.line_cogs,
            'profit',           ld.line_profit
          ) ORDER BY ld.line_cogs DESC
        ) AS lines
      FROM line_data ld
      JOIN sale_orders so ON so.id = ld.sale_order_id
      LEFT JOIN customers c ON c.id = so.customer_id
      GROUP BY ld.sale_order_id, so.so_number, so.created_at, c.name
    )
    SELECT jsonb_agg(
      jsonb_build_object(
        'sale_order_id', sale_order_id,
        'so_number',     so_number,
        'order_date',    order_date,
        'customer_name', customer_name,
        'item_count',    item_count,
        'revenue',       revenue,
        'cogs',          cogs,
        'profit',        profit,
        'margin_pct',    margin_pct,
        'lines',         lines
      ) ORDER BY cogs DESC
    )
    FROM so_agg
  ), '[]'::jsonb);
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_profitability_drilldown(date, date) TO authenticated;
NOTIFY pgrst, 'reload schema';


-- ============================================================
-- Source: 20260716120000_add_missing_fks_and_enum_conversions.sql
-- ============================================================
-- Part 1: Add 'booking' to notification_category enum.
-- ALTER TYPE ... ADD VALUE cannot run inside a transaction,
-- and the new value must be fully committed before it can be
-- used in a USING cast, so this is a separate migration.

ALTER TYPE public.notification_category ADD VALUE IF NOT EXISTS 'booking';


-- ============================================================
-- Source: 20260716120100_add_fks_and_convert_columns.sql
-- ============================================================
-- Part 2: Add missing FK constraints (idempotent) and convert text columns to enums.
-- Depends on 20260716120000 (adds 'booking' to notification_category).

-- ── 1. cogs_entries — FK on sale_delivery_id ─────────────────────────────────

DO $$ BEGIN
  ALTER TABLE public.cogs_entries
    ADD CONSTRAINT cogs_entries_sale_delivery_id_fkey
    FOREIGN KEY (sale_delivery_id) REFERENCES public.sale_deliveries(id);
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

CREATE INDEX IF NOT EXISTS idx_cogs_entries_sale_delivery_id
  ON public.cogs_entries(sale_delivery_id)
  WHERE sale_delivery_id IS NOT NULL;

-- ── 2. cogs_entries — FK on sale_order_id ────────────────────────────────────

DO $$ BEGIN
  ALTER TABLE public.cogs_entries
    ADD CONSTRAINT cogs_entries_sale_order_id_fkey
    FOREIGN KEY (sale_order_id) REFERENCES public.sale_orders(id);
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

CREATE INDEX IF NOT EXISTS idx_cogs_entries_sale_order_id
  ON public.cogs_entries(sale_order_id)
  WHERE sale_order_id IS NOT NULL;

-- ── 3. po_line_items — FK on brand_id ────────────────────────────────────────

DO $$ BEGIN
  ALTER TABLE public.po_line_items
    ADD CONSTRAINT po_line_items_brand_id_fkey
    FOREIGN KEY (brand_id) REFERENCES public.brands(id);
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

CREATE INDEX IF NOT EXISTS idx_po_line_items_brand_id
  ON public.po_line_items(brand_id)
  WHERE brand_id IS NOT NULL;

-- ── 4. customer_addresses.address_type — varchar → enum (idempotent) ─────────

DO $$ BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'customer_addresses'
      AND column_name = 'address_type'
      AND udt_name != 'address_type'
  ) THEN
    ALTER TABLE public.customer_addresses
      ALTER COLUMN address_type TYPE public.address_type
      USING address_type::public.address_type;
  END IF;
END $$;

-- ── 5. notification_config.category — text → enum ────────────────────────────

ALTER TABLE public.notification_config
  ALTER COLUMN category TYPE public.notification_category
  USING category::public.notification_category;

-- ── 6. notification_config.trigger_type — text → enum ────────────────────────

ALTER TABLE public.notification_config
  ALTER COLUMN trigger_type TYPE public.notification_trigger
  USING trigger_type::public.notification_trigger;

NOTIFY pgrst, 'reload schema';


-- ============================================================
-- Source: 20260718200000_receival_number_sequence.sql
-- ============================================================
-- Move receival number generation from client-side to DB-side
-- to eliminate the TOCTOU race condition under concurrent creations.

-- Step 1: Create a sequence seeded from the current max receival number
DO $$
DECLARE
  v_max INT;
BEGIN
  SELECT COALESCE(
    MAX(NULLIF(regexp_replace(receival_number, '^RCV-', ''), '')::INT),
    0
  ) INTO v_max
  FROM receivals
  WHERE receival_number ~ '^RCV-\d+$';

  EXECUTE format('CREATE SEQUENCE IF NOT EXISTS receival_number_seq START WITH %s', v_max + 1);
END;
$$;

-- Step 2: Update the RPC to generate the number internally when p_receival_number is empty
CREATE OR REPLACE FUNCTION public.create_and_approve_receival(
  p_po_id uuid,
  p_warehouse_id uuid,
  p_date date,
  p_received_by_name text,
  p_receival_number text,
  p_notes text,
  p_items jsonb
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_receival_id UUID;
  v_receival_number TEXT;
  v_item        JSONB;
  v_bv_id       UUID;
  v_bv_ids      UUID[] := '{}';
  v_bv_id_elem  UUID;
  v_qty         INT;
  v_cost        NUMERIC;
  v_pli_id      UUID;
BEGIN
  -- Generate receival number atomically from sequence if not provided
  IF p_receival_number IS NULL OR p_receival_number = '' THEN
    v_receival_number := 'RCV-' || lpad(nextval('receival_number_seq')::TEXT, 5, '0');
  ELSE
    v_receival_number := p_receival_number;
  END IF;

  INSERT INTO receivals (
    receival_number, po_id, warehouse_id, date,
    received_by_name, notes, status
  ) VALUES (
    v_receival_number, p_po_id, p_warehouse_id, p_date,
    p_received_by_name, p_notes, 'approved'
  ) RETURNING id INTO v_receival_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    CONTINUE WHEN (v_item->>'qty_received') IS NULL OR (v_item->>'unit_cost') IS NULL;

    v_bv_id  := NULLIF(v_item->>'brand_variant_id', '')::UUID;
    v_qty    := (v_item->>'qty_received')::INT;
    v_cost   := (v_item->>'unit_cost')::NUMERIC;
    v_pli_id := NULLIF(v_item->>'po_line_item_id', '')::UUID;

    INSERT INTO receival_items (
      receival_id, po_line_item_id, brand_variant_id,
      item_name, sku, qty_received, unit_cost, is_free
    ) VALUES (
      v_receival_id, v_pli_id, v_bv_id,
      v_item->>'item_name',
      NULLIF(v_item->>'sku', ''),
      v_qty, v_cost,
      COALESCE((v_item->>'is_free')::BOOLEAN, false)
    );

    CONTINUE WHEN COALESCE((v_item->>'is_free')::BOOLEAN, false) = TRUE
               OR v_bv_id IS NULL
               OR v_qty <= 0;

    INSERT INTO fifo_cost_layers (
      brand_variant_id, warehouse_id, receival_id, receival_number,
      date, qty, unit_cost, landed_cost_per_unit, total_unit_cost, remaining_qty
    ) VALUES (
      v_bv_id, p_warehouse_id, v_receival_id::TEXT, v_receival_number,
      p_date, v_qty, v_cost, 0, v_cost, v_qty
    );

    UPDATE inventory_brand_variants
    SET stock_level = stock_level + v_qty,
        updated_at  = now()
    WHERE id = v_bv_id;

    IF v_pli_id IS NOT NULL THEN
      UPDATE po_line_items
      SET received_qty = received_qty + v_qty
      WHERE id = v_pli_id;
    END IF;

    INSERT INTO inventory_stock_movements (
      warehouse_id, brand_variant_id, item_name, sku,
      movement_type, qty, unit_cost, reference_type, reference_id
    ) VALUES (
      p_warehouse_id, v_bv_id,
      v_item->>'item_name', NULLIF(v_item->>'sku', ''),
      'purchase_receival', v_qty, v_cost,
      'receival', v_receival_id
    );

    IF NOT (v_bv_id = ANY(v_bv_ids)) THEN
      v_bv_ids := v_bv_ids || v_bv_id;
    END IF;
  END LOOP;

  FOREACH v_bv_id_elem IN ARRAY v_bv_ids LOOP
    PERFORM recalc_average_cost(v_bv_id_elem);
  END LOOP;

  PERFORM refresh_po_status(p_po_id);

  RETURN jsonb_build_object('receival_id', v_receival_id, 'receival_number', v_receival_number);
END;
$$;


-- ============================================================
-- Source: 20260718210000_atomic_po_approval_action.sql
-- ============================================================
-- Consolidate PO approval mutations into a single atomic RPC.
-- Eliminates TOCTOU races between step update and tier advancement.

CREATE OR REPLACE FUNCTION public.po_approval_action(
  p_po_id uuid,
  p_step_id uuid,              -- NULL only for 'force_approve_all'
  p_approver_email text,
  p_approver_name text,
  p_approver_profile_id uuid,
  p_action text,               -- 'approve' | 'force_approve' | 'force_approve_all' | 'reject_cancel' | 'reject_draft'
  p_comment text DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_today         DATE := CURRENT_DATE;
  v_now           TIMESTAMPTZ := now();
  v_step          RECORD;
  v_iteration     INT;
  v_po            RECORD;
  v_approved_roles TEXT[] := '{}';
  v_pending_ids   UUID[];
  v_is_owner      BOOLEAN;
BEGIN
  -- Advisory lock prevents concurrent approval actions on the same PO
  PERFORM pg_advisory_xact_lock(hashtext(p_po_id::text));

  -- ── APPROVE ──────────────────────────────────────────────────────────
  IF p_action = 'approve' THEN
    IF p_step_id IS NULL THEN
      RAISE EXCEPTION 'p_step_id is required for approve action';
    END IF;

    SELECT tier_rank, iteration, role, status, is_active
      INTO v_step
      FROM po_approvals WHERE id = p_step_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Approval step not found'; END IF;
    IF v_step.status != 'pending' OR v_step.is_active != true THEN
      RAISE EXCEPTION 'Step is not pending/active';
    END IF;

    -- Four-eyes check: same user must not have approved another role in this tier+iteration
    IF EXISTS (
      SELECT 1 FROM po_approvals
       WHERE po_id = p_po_id
         AND tier_rank = v_step.tier_rank
         AND iteration = v_step.iteration
         AND status = 'approved'
         AND approved_by = p_approver_email
         AND id != p_step_id
    ) THEN
      RAISE EXCEPTION 'Four-eyes violation: you already approved another role in this tier';
    END IF;

    UPDATE po_approvals SET
      status = 'approved', approved_by = p_approver_email,
      date = v_today, comment = p_comment
    WHERE id = p_step_id;

    v_approved_roles := ARRAY[v_step.role];

    -- Log activity
    INSERT INTO activity_log (entity_type, entity_id, module, action, details, performer_name, severity)
    VALUES ('purchase_order', p_po_id, 'purchase_orders',
            'Approved: ' || v_step.role, p_comment, p_approver_name, 'info');

  -- ── FORCE APPROVE (single step) ─────────────────────────────────────
  ELSIF p_action = 'force_approve' THEN
    IF p_step_id IS NULL THEN
      RAISE EXCEPTION 'p_step_id is required for force_approve action';
    END IF;
    IF p_comment IS NULL OR trim(p_comment) = '' THEN
      RAISE EXCEPTION 'A comment is required for force-approve';
    END IF;

    -- Owner check
    SELECT EXISTS (
      SELECT 1 FROM user_custom_roles ucr
        JOIN custom_roles cr ON cr.id = ucr.custom_role_id
       WHERE ucr.profile_id = p_approver_profile_id
         AND cr.name = 'Owner' AND cr.is_approval_slot = true AND cr.deleted_at IS NULL
    ) INTO v_is_owner;
    IF NOT v_is_owner THEN RAISE EXCEPTION 'Only Owner role can force-approve'; END IF;

    SELECT role INTO v_step FROM po_approvals WHERE id = p_step_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Approval step not found'; END IF;

    UPDATE po_approvals SET
      status = 'approved', approved_by = p_approver_email,
      date = v_today, force_approved = true, force_comment = p_comment
    WHERE id = p_step_id;

    v_approved_roles := ARRAY[v_step.role];

    INSERT INTO activity_log (entity_type, entity_id, module, action, details, performer_name, severity)
    VALUES ('purchase_order', p_po_id, 'purchase_orders',
            'Force Approved: ' || v_step.role, p_comment, p_approver_name, 'critical');

  -- ── FORCE APPROVE ALL ────────────────────────────────────────────────
  ELSIF p_action = 'force_approve_all' THEN
    -- Owner check
    SELECT EXISTS (
      SELECT 1 FROM user_custom_roles ucr
        JOIN custom_roles cr ON cr.id = ucr.custom_role_id
       WHERE ucr.profile_id = p_approver_profile_id
         AND cr.name = 'Owner' AND cr.is_approval_slot = true AND cr.deleted_at IS NULL
    ) INTO v_is_owner;
    IF NOT v_is_owner THEN RAISE EXCEPTION 'Only Owner role can force-approve'; END IF;

    SELECT COALESCE(MAX(iteration), 1) INTO v_iteration
      FROM po_approvals WHERE po_id = p_po_id;

    SELECT array_agg(id), array_agg(role)
      INTO v_pending_ids, v_approved_roles
      FROM po_approvals
     WHERE po_id = p_po_id AND iteration = v_iteration
       AND status = 'pending' AND is_active = true;

    IF v_pending_ids IS NULL OR array_length(v_pending_ids, 1) IS NULL THEN
      RAISE EXCEPTION 'No pending steps to force-approve';
    END IF;

    UPDATE po_approvals SET
      status = 'approved', approved_by = p_approver_email,
      date = v_today, force_approved = true,
      force_comment = CASE WHEN trim(COALESCE(p_comment,'')) != '' THEN p_comment ELSE NULL END
    WHERE id = ANY(v_pending_ids);

    -- One log entry per role
    FOR i IN 1..array_length(v_approved_roles, 1) LOOP
      INSERT INTO activity_log (entity_type, entity_id, module, action, details, performer_name, severity)
      VALUES ('purchase_order', p_po_id, 'purchase_orders',
              'Force Approved: ' || v_approved_roles[i],
              CASE WHEN trim(COALESCE(p_comment,'')) != '' THEN p_comment ELSE NULL END,
              p_approver_name, 'critical');
    END LOOP;

  -- ── REJECT (cancel or send-back-to-draft) ───────────────────────────
  ELSIF p_action IN ('reject_cancel', 'reject_draft') THEN
    IF p_step_id IS NULL THEN
      RAISE EXCEPTION 'p_step_id is required for reject action';
    END IF;

    SELECT COALESCE(MAX(iteration), 1) INTO v_iteration
      FROM po_approvals WHERE po_id = p_po_id;

    SELECT role INTO v_step FROM po_approvals WHERE id = p_step_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Approval step not found'; END IF;

    -- Reject this step
    UPDATE po_approvals SET
      status = 'rejected', approved_by = p_approver_email,
      date = v_today, comment = p_comment
    WHERE id = p_step_id;

    -- Cancel all other active pending steps in this iteration
    UPDATE po_approvals SET status = 'rejected'
     WHERE po_id = p_po_id AND iteration = v_iteration
       AND status = 'pending' AND is_active = true AND id != p_step_id;

    -- Update PO status
    IF p_action = 'reject_cancel' THEN
      UPDATE purchase_orders SET status = 'cancelled' WHERE id = p_po_id;
    ELSE
      UPDATE purchase_orders SET status = 'draft' WHERE id = p_po_id;
    END IF;

    v_approved_roles := ARRAY[v_step.role];

    INSERT INTO activity_log (entity_type, entity_id, module, action, details, performer_name, severity)
    VALUES ('purchase_order', p_po_id, 'purchase_orders',
            CASE WHEN p_action = 'reject_cancel'
              THEN 'Rejected by ' || v_step.role || ' — PO Cancelled'
              ELSE 'Rejected by ' || v_step.role || ' — Sent Back to Draft'
            END,
            p_comment, p_approver_name, 'warning');

    -- Notify PO creator
    SELECT created_by, po_number INTO v_po
      FROM purchase_orders WHERE id = p_po_id;
    IF v_po.created_by IS NOT NULL THEN
      INSERT INTO notifications (profile_id, type, title, related_id, related_type)
      VALUES (v_po.created_by, 'po_rejected',
              'PO ' || v_po.po_number || ' was rejected by ' || p_approver_email,
              p_po_id, 'purchase_order');
    END IF;

    -- Clear ghost notifications and return early (no tier advancement for rejections)
    UPDATE notifications SET read_at = v_now
     WHERE related_id = p_po_id AND type = 'po_approval_requested' AND read_at IS NULL;

    RETURN jsonb_build_object(
      'ok', true, 'po_status',
      CASE WHEN p_action = 'reject_cancel' THEN 'cancelled' ELSE 'draft' END,
      'action', p_action, 'roles', to_jsonb(v_approved_roles)
    );

  ELSE
    RAISE EXCEPTION 'Unknown action: %', p_action;
  END IF;

  -- ── Common post-approve path: clear notifications + advance tier ────
  UPDATE notifications SET read_at = v_now
   WHERE related_id = p_po_id AND type = 'po_approval_requested' AND read_at IS NULL;

  -- Inline tier advancement (same logic as advance_po_approval_tier but within this transaction)
  DECLARE
    v_adv_iteration INT;
    v_next_rank     INT;
    v_all_done      BOOLEAN;
  BEGIN
    IF NOT EXISTS (
      SELECT 1 FROM purchase_orders WHERE id = p_po_id AND status = 'pending_approval'
    ) THEN
      SELECT status INTO v_po FROM purchase_orders WHERE id = p_po_id;
      RETURN jsonb_build_object('ok', true, 'po_status', v_po.status, 'action', p_action, 'roles', to_jsonb(v_approved_roles));
    END IF;

    SELECT COALESCE(MAX(iteration), 1) INTO v_adv_iteration
      FROM po_approvals WHERE po_id = p_po_id;

    SELECT NOT EXISTS (
      SELECT 1 FROM po_approvals
       WHERE po_id = p_po_id AND iteration = v_adv_iteration
         AND is_active = true AND status != 'approved'
    ) INTO v_all_done;

    IF v_all_done THEN
      SELECT MIN(tier_rank) INTO v_next_rank
        FROM po_approvals
       WHERE po_id = p_po_id AND iteration = v_adv_iteration
         AND is_active = false AND status = 'pending';

      IF v_next_rank IS NOT NULL THEN
        UPDATE po_approvals SET is_active = true
         WHERE po_id = p_po_id AND iteration = v_adv_iteration AND tier_rank = v_next_rank;
      ELSE
        UPDATE purchase_orders SET status = 'approved' WHERE id = p_po_id;

        -- Notify creator of full approval
        SELECT created_by, po_number INTO v_po FROM purchase_orders WHERE id = p_po_id;
        IF v_po.created_by IS NOT NULL THEN
          INSERT INTO notifications (profile_id, type, title, related_id, related_type)
          VALUES (v_po.created_by, 'po_approved',
                  'PO ' || v_po.po_number || ' has been fully approved',
                  p_po_id, 'purchase_order');
        END IF;

        INSERT INTO activity_log (entity_type, entity_id, module, action, performer_name, severity)
        VALUES ('purchase_order', p_po_id, 'purchase_orders',
                CASE WHEN p_action LIKE 'force%' THEN 'PO Fully Approved (Force)' ELSE 'PO Fully Approved' END,
                p_approver_name,
                CASE WHEN p_action LIKE 'force%' THEN 'critical' ELSE 'info' END);
      END IF;
    END IF;
  END;

  SELECT status INTO v_po FROM purchase_orders WHERE id = p_po_id;
  RETURN jsonb_build_object(
    'ok', true, 'po_status', v_po.status,
    'action', p_action, 'roles', to_jsonb(v_approved_roles)
  );
END;
$$;


-- ============================================================
-- Source: 20260718220000_add_missing_fk_indexes.sql
-- ============================================================
-- PostgreSQL does NOT auto-create indexes on FK columns.
-- These indexes cover high-traffic join/filter columns identified in the architecture audit.

-- sale_orders
CREATE INDEX IF NOT EXISTS idx_sale_orders_customer_id ON sale_orders (customer_id);
CREATE INDEX IF NOT EXISTS idx_sale_orders_created_by ON sale_orders (created_by);
CREATE INDEX IF NOT EXISTS idx_sale_orders_division_id ON sale_orders (division_id);

-- purchase_orders
CREATE INDEX IF NOT EXISTS idx_purchase_orders_created_by ON purchase_orders (created_by);
CREATE INDEX IF NOT EXISTS idx_purchase_orders_division_id ON purchase_orders (division_id);
CREATE INDEX IF NOT EXISTS idx_purchase_orders_warehouse_id ON purchase_orders (warehouse_id);

-- invoices
CREATE INDEX IF NOT EXISTS idx_invoices_supplier_id ON invoices (supplier_id);
CREATE INDEX IF NOT EXISTS idx_invoices_purchase_order_id ON invoices (purchase_order_id);
CREATE INDEX IF NOT EXISTS idx_invoices_sale_order_id ON invoices (sale_order_id);
CREATE INDEX IF NOT EXISTS idx_invoices_sale_delivery_id ON invoices (sale_delivery_id);

-- payments
CREATE INDEX IF NOT EXISTS idx_payments_customer_id ON payments (customer_id);
CREATE INDEX IF NOT EXISTS idx_payments_supplier_id ON payments (supplier_id);

-- profiles
CREATE INDEX IF NOT EXISTS idx_profiles_division_id ON profiles (division_id);

-- receivals
CREATE INDEX IF NOT EXISTS idx_receivals_warehouse_id ON receivals (warehouse_id);

-- warehouse_transfers
CREATE INDEX IF NOT EXISTS idx_warehouse_transfers_from_warehouse_id ON warehouse_transfers (from_warehouse_id);
CREATE INDEX IF NOT EXISTS idx_warehouse_transfers_to_warehouse_id ON warehouse_transfers (to_warehouse_id);

-- inventory_checks
CREATE INDEX IF NOT EXISTS idx_inventory_checks_warehouse_id ON inventory_checks (warehouse_id);


-- ============================================================
-- Source: 20260719200000_backfill_admin_permissions.sql
-- ============================================================
-- Backfill Admin role with complete permission set.
-- The original seed (20260706130000) was missing *.access nav-gate keys
-- and many *.view keys added in later migrations. Without the access keys,
-- the nav dropdowns are invisible even for Admin users.

UPDATE public.custom_roles
SET permissions = ARRAY[
  -- Nav access gates
  'master_data.access',
  'purchase_sales.access',
  'warehouse.access',
  'orders.access',
  'contracts.access',
  'invoices.access',
  'teams.access',
