  'master_data.users.view',           'master_data.users.manage',
  'master_data.roles.view',           'master_data.roles.manage',
  'master_data.audit.view',
  'master_data.admin.view',           'master_data.admin.manage',

  -- Purchase
  'purchase.orders.view',             'purchase.orders.manage',
  'purchase.orders.create',           'purchase.orders.edit',
  'purchase.approvals.view',          'purchase.approvals.manage',
  'purchase.approvals.chain.manage',  'purchase.approvals.bypass',
  'purchase.shipments.view',          'purchase.shipments.manage',
  'purchase.receivals.view',          'purchase.receivals.manage',
  'purchase.landed_costs.view',       'purchase.landed_costs.manage',
  'purchase.bills.view',              'purchase.bills.manage',
  'purchase.dead_stock.view',
  'purchase.returns.view',            'purchase.returns.manage',
  'purchase.debit_notes.view',
  'purchase.warehouses.view',         'purchase.warehouses.manage',

  -- Sales
  'sales.orders.view',                'sales.orders.manage',
  'sales.orders.create',              'sales.orders.edit',
  'sales.approvals.view',             'sales.approvals.manage',
  'sales.invoices.view',              'sales.invoices.manage',
  'sales.returns.view',               'sales.returns.manage',
  'sales.deliveries.view',            'sales.deliveries.manage',
  'sales.credit_notes.view',          'sales.credit_notes.manage',

  -- Warehouse
  'warehouse.warehouses.view',        'warehouse.settings.manage',
  'warehouse.stock.view',
  'warehouse.transfers.view',         'warehouse.transfer.create',
  'warehouse.transfer.dispatch',      'warehouse.transfer.receive',
  'warehouse.transfer.approve',
  'warehouse.adjustments.view',       'warehouse.adjustment.request',
  'warehouse.checks.view',            'warehouse.check.count',
  'warehouse.check.create',
  'warehouse.stock_value.view',
  'warehouse.movements.view',
  'warehouse.receivals.view',

  -- Orders
  'orders.view',                      'orders.manage',
  'orders.create',                    'orders.edit',
  'orders.assign',
  'follow_ups.request',               'follow_ups.confirm',
  'quotations.view',                  'quotations.manage',

  -- Contracts
  'contracts.quotations.view',        'contracts.quotations.manage',
  'contracts.live.view',              'contracts.live.manage',
  'contracts.activate',
  'contracts.view',                   'contracts.create',
  'contracts.edit',

  -- Invoices & Payments
  'invoices.view',                    'invoices.manage',
  'invoices.create',                  'invoices.edit',
  'payments.view',                    'payments.manage',

  -- Teams & Employees
  'teams.view',                       'teams.manage',
  'employees.view',                   'employees.manage',
  'teams.team_leader.view',           'teams.team_leader.manage',
  'teams.map.view',                   'teams.map.manage',
  'calendar.view',                    'calendar.manage',

  -- Reports
  'reports.view',                     'reports.manage',

  -- Contact Centre
  'contact_centre.view',

  -- System
  'system.admin',                     'system.import',
  'system.export'
]
WHERE name = 'Admin' AND deleted_at IS NULL;


-- ============================================================
-- Source: 20260720120000_fix_approval_notification_actioned.sql
-- ============================================================
-- Fix: po_approval_action RPC only set read_at on approval notifications,
-- but the UI filters pending notifications by actioned_at IS NULL.
-- This caused approved/rejected PO notifications to stay in "Pending" forever.
-- Now sets both read_at AND actioned_at so notifications move to "Completed".

CREATE OR REPLACE FUNCTION public.po_approval_action(
  p_po_id uuid,
  p_step_id uuid,
  p_approver_email text,
  p_approver_name text,
  p_approver_profile_id uuid,
  p_action text,
  p_comment text DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_today         DATE := CURRENT_DATE;
  v_now           TIMESTAMPTZ := now();
  v_step          RECORD;
  v_iteration     INT;
  v_po            RECORD;
  v_approved_roles TEXT[] := '{}';
  v_pending_ids   UUID[];
  v_is_owner      BOOLEAN;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext(p_po_id::text));

  -- ── APPROVE ──────────────────────────────────────────────────────────
  IF p_action = 'approve' THEN
    IF p_step_id IS NULL THEN
      RAISE EXCEPTION 'p_step_id is required for approve action';
    END IF;

    SELECT tier_rank, iteration, role, status, is_active
      INTO v_step
      FROM po_approvals WHERE id = p_step_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Approval step not found'; END IF;
    IF v_step.status != 'pending' OR v_step.is_active != true THEN
      RAISE EXCEPTION 'Step is not pending/active';
    END IF;

    IF EXISTS (
      SELECT 1 FROM po_approvals
       WHERE po_id = p_po_id
         AND tier_rank = v_step.tier_rank
         AND iteration = v_step.iteration
         AND status = 'approved'
         AND approved_by = p_approver_email
         AND id != p_step_id
    ) THEN
      RAISE EXCEPTION 'Four-eyes violation: you already approved another role in this tier';
    END IF;

    UPDATE po_approvals SET
      status = 'approved', approved_by = p_approver_email,
      date = v_today, comment = p_comment
    WHERE id = p_step_id;

    v_approved_roles := ARRAY[v_step.role];

    INSERT INTO activity_log (entity_type, entity_id, module, action, details, performer_name, severity)
    VALUES ('purchase_order', p_po_id, 'purchase_orders',
            'Approved: ' || v_step.role, p_comment, p_approver_name, 'info');

  -- ── FORCE APPROVE (single step) ─────────────────────────────────────
  ELSIF p_action = 'force_approve' THEN
    IF p_step_id IS NULL THEN
      RAISE EXCEPTION 'p_step_id is required for force_approve action';
    END IF;
    IF p_comment IS NULL OR trim(p_comment) = '' THEN
      RAISE EXCEPTION 'A comment is required for force-approve';
    END IF;

    SELECT EXISTS (
      SELECT 1 FROM user_custom_roles ucr
        JOIN custom_roles cr ON cr.id = ucr.custom_role_id
       WHERE ucr.profile_id = p_approver_profile_id
         AND cr.name = 'Owner' AND cr.is_approval_slot = true AND cr.deleted_at IS NULL
    ) INTO v_is_owner;
    IF NOT v_is_owner THEN RAISE EXCEPTION 'Only Owner role can force-approve'; END IF;

    SELECT role INTO v_step FROM po_approvals WHERE id = p_step_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Approval step not found'; END IF;

    UPDATE po_approvals SET
      status = 'approved', approved_by = p_approver_email,
      date = v_today, force_approved = true, force_comment = p_comment
    WHERE id = p_step_id;

    v_approved_roles := ARRAY[v_step.role];

    INSERT INTO activity_log (entity_type, entity_id, module, action, details, performer_name, severity)
    VALUES ('purchase_order', p_po_id, 'purchase_orders',
            'Force Approved: ' || v_step.role, p_comment, p_approver_name, 'critical');

  -- ── FORCE APPROVE ALL ────────────────────────────────────────────────
  ELSIF p_action = 'force_approve_all' THEN
    SELECT EXISTS (
      SELECT 1 FROM user_custom_roles ucr
        JOIN custom_roles cr ON cr.id = ucr.custom_role_id
       WHERE ucr.profile_id = p_approver_profile_id
         AND cr.name = 'Owner' AND cr.is_approval_slot = true AND cr.deleted_at IS NULL
    ) INTO v_is_owner;
    IF NOT v_is_owner THEN RAISE EXCEPTION 'Only Owner role can force-approve'; END IF;

    SELECT COALESCE(MAX(iteration), 1) INTO v_iteration
      FROM po_approvals WHERE po_id = p_po_id;

    SELECT array_agg(id), array_agg(role)
      INTO v_pending_ids, v_approved_roles
      FROM po_approvals
     WHERE po_id = p_po_id AND iteration = v_iteration
       AND status = 'pending' AND is_active = true;

    IF v_pending_ids IS NULL OR array_length(v_pending_ids, 1) IS NULL THEN
      RAISE EXCEPTION 'No pending steps to force-approve';
    END IF;

    UPDATE po_approvals SET
      status = 'approved', approved_by = p_approver_email,
      date = v_today, force_approved = true,
      force_comment = CASE WHEN trim(COALESCE(p_comment,'')) != '' THEN p_comment ELSE NULL END
    WHERE id = ANY(v_pending_ids);

    FOR i IN 1..array_length(v_approved_roles, 1) LOOP
      INSERT INTO activity_log (entity_type, entity_id, module, action, details, performer_name, severity)
      VALUES ('purchase_order', p_po_id, 'purchase_orders',
              'Force Approved: ' || v_approved_roles[i],
              CASE WHEN trim(COALESCE(p_comment,'')) != '' THEN p_comment ELSE NULL END,
              p_approver_name, 'critical');
    END LOOP;

  -- ── REJECT (cancel or send-back-to-draft) ───────────────────────────
  ELSIF p_action IN ('reject_cancel', 'reject_draft') THEN
    IF p_step_id IS NULL THEN
      RAISE EXCEPTION 'p_step_id is required for reject action';
    END IF;

    SELECT COALESCE(MAX(iteration), 1) INTO v_iteration
      FROM po_approvals WHERE po_id = p_po_id;

    SELECT role INTO v_step FROM po_approvals WHERE id = p_step_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Approval step not found'; END IF;

    UPDATE po_approvals SET
      status = 'rejected', approved_by = p_approver_email,
      date = v_today, comment = p_comment
    WHERE id = p_step_id;

    UPDATE po_approvals SET status = 'rejected'
     WHERE po_id = p_po_id AND iteration = v_iteration
       AND status = 'pending' AND is_active = true AND id != p_step_id;

    IF p_action = 'reject_cancel' THEN
      UPDATE purchase_orders SET status = 'cancelled' WHERE id = p_po_id;
    ELSE
      UPDATE purchase_orders SET status = 'draft' WHERE id = p_po_id;
    END IF;

    v_approved_roles := ARRAY[v_step.role];

    INSERT INTO activity_log (entity_type, entity_id, module, action, details, performer_name, severity)
    VALUES ('purchase_order', p_po_id, 'purchase_orders',
            CASE WHEN p_action = 'reject_cancel'
              THEN 'Rejected by ' || v_step.role || ' — PO Cancelled'
              ELSE 'Rejected by ' || v_step.role || ' — Sent Back to Draft'
            END,
            p_comment, p_approver_name, 'warning');

    SELECT created_by, po_number INTO v_po
      FROM purchase_orders WHERE id = p_po_id;
    IF v_po.created_by IS NOT NULL THEN
      INSERT INTO notifications (profile_id, type, title, related_id, related_type)
      VALUES (v_po.created_by, 'po_rejected',
              'PO ' || v_po.po_number || ' was rejected by ' || p_approver_email,
              p_po_id, 'purchase_order');
    END IF;

    -- Mark approval notifications as actioned so they move to Completed
    UPDATE notifications SET read_at = v_now, actioned_at = v_now
     WHERE related_id = p_po_id AND type = 'po_approval_requested' AND actioned_at IS NULL;

    RETURN jsonb_build_object(
      'ok', true, 'po_status',
      CASE WHEN p_action = 'reject_cancel' THEN 'cancelled' ELSE 'draft' END,
      'action', p_action, 'roles', to_jsonb(v_approved_roles)
    );

  ELSE
    RAISE EXCEPTION 'Unknown action: %', p_action;
  END IF;

  -- ── Common post-approve path: mark notifications actioned + advance tier ──
  UPDATE notifications SET read_at = v_now, actioned_at = v_now
   WHERE related_id = p_po_id AND type = 'po_approval_requested' AND actioned_at IS NULL;

  DECLARE
    v_adv_iteration INT;
    v_next_rank     INT;
    v_all_done      BOOLEAN;
  BEGIN
    IF NOT EXISTS (
      SELECT 1 FROM purchase_orders WHERE id = p_po_id AND status = 'pending_approval'
    ) THEN
      SELECT status INTO v_po FROM purchase_orders WHERE id = p_po_id;
      RETURN jsonb_build_object('ok', true, 'po_status', v_po.status, 'action', p_action, 'roles', to_jsonb(v_approved_roles));
    END IF;

    SELECT COALESCE(MAX(iteration), 1) INTO v_adv_iteration
      FROM po_approvals WHERE po_id = p_po_id;

    SELECT NOT EXISTS (
      SELECT 1 FROM po_approvals
       WHERE po_id = p_po_id AND iteration = v_adv_iteration
         AND is_active = true AND status != 'approved'
    ) INTO v_all_done;

    IF v_all_done THEN
      SELECT MIN(tier_rank) INTO v_next_rank
        FROM po_approvals
       WHERE po_id = p_po_id AND iteration = v_adv_iteration
         AND is_active = false AND status = 'pending';

      IF v_next_rank IS NOT NULL THEN
        UPDATE po_approvals SET is_active = true
         WHERE po_id = p_po_id AND iteration = v_adv_iteration AND tier_rank = v_next_rank;
      ELSE
        UPDATE purchase_orders SET status = 'approved' WHERE id = p_po_id;

        SELECT created_by, po_number INTO v_po FROM purchase_orders WHERE id = p_po_id;
        IF v_po.created_by IS NOT NULL THEN
          INSERT INTO notifications (profile_id, type, title, related_id, related_type)
          VALUES (v_po.created_by, 'po_approved',
                  'PO ' || v_po.po_number || ' has been fully approved',
                  p_po_id, 'purchase_order');
        END IF;

        INSERT INTO activity_log (entity_type, entity_id, module, action, performer_name, severity)
        VALUES ('purchase_order', p_po_id, 'purchase_orders',
                CASE WHEN p_action LIKE 'force%' THEN 'PO Fully Approved (Force)' ELSE 'PO Fully Approved' END,
                p_approver_name,
                CASE WHEN p_action LIKE 'force%' THEN 'critical' ELSE 'info' END);
      END IF;
    END IF;
  END;

  SELECT status INTO v_po FROM purchase_orders WHERE id = p_po_id;
  RETURN jsonb_build_object(
    'ok', true, 'po_status', v_po.status,
    'action', p_action, 'roles', to_jsonb(v_approved_roles)
  );
END;
$$;

-- Backfill: mark any existing stale po_approval_requested notifications as actioned
-- where the PO is no longer pending_approval
UPDATE notifications n
   SET actioned_at = COALESCE(n.read_at, now()),
       read_at     = COALESCE(n.read_at, now())
  FROM purchase_orders po
 WHERE n.related_id = po.id
   AND n.type = 'po_approval_requested'
   AND n.actioned_at IS NULL
   AND po.status NOT IN ('pending_approval');


-- ============================================================
-- Source: 20260720130000_clear_duplicate_brand_variants.sql
-- ============================================================
-- Backfill: clear brand values that duplicate the item's family name.
--
-- Context: `inventory_brand_variants.brand` was seeded with product-family
-- strings (e.g. "FLARE NUT" on an item named "FLARE NUT 3/8''") instead of
-- manufacturer names. The Brand column in the Dead Stock report and elsewhere
-- ended up echoing the item name.
--
-- Strategy: replace `brand` with an empty string wherever it exactly matches
-- the item's `name_en` OR is a whole-word prefix of it (i.e. followed by a
-- space in the item name). Empty strings preserve the existing NOT NULL
-- constraint. Frontend code already treats empty strings as "no brand".
--
-- Users can then enter real manufacturer names via the brand variant form
-- (which shows placeholder "e.g. LG, Alfacool").

DO $$
DECLARE
  v_affected INT;
BEGIN
  SELECT COUNT(*) INTO v_affected
  FROM inventory_brand_variants ibv
  JOIN inventory_items ii ON ii.id = ibv.item_id
  WHERE ibv.brand IS NOT NULL
    AND TRIM(ibv.brand) <> ''
    AND (
         LOWER(TRIM(ibv.brand)) = LOWER(TRIM(ii.name_en))
      OR LOWER(TRIM(ii.name_en)) LIKE LOWER(TRIM(ibv.brand)) || ' %'
    );

  RAISE NOTICE 'Clearing brand on % rows where it duplicates the item family name', v_affected;

  UPDATE inventory_brand_variants ibv
     SET brand = ''
    FROM inventory_items ii
   WHERE ii.id = ibv.item_id
     AND ibv.brand IS NOT NULL
     AND TRIM(ibv.brand) <> ''
     AND (
          LOWER(TRIM(ibv.brand)) = LOWER(TRIM(ii.name_en))
       OR LOWER(TRIM(ii.name_en)) LIKE LOWER(TRIM(ibv.brand)) || ' %'
     );
END $$;


-- ============================================================
-- Source: 20260720140000_brands_table_and_fk.sql
-- ============================================================
-- Link inventory brand variants to the existing `public.brands` lookup table.
--
-- `public.brands` already exists in the baseline schema (used by
-- service_brands, brand_group_members, contract_services). Inventory kept its
-- own free-text `brand` column on `inventory_brand_variants` which drifted —
-- values like "FLARE NUT" ended up echoing the item family. This migration
-- reuses the existing brands table, adds a proper FK, backfills, and updates
-- the dead-stock RPC to read via the join.
--
-- The legacy `brand` text column stays for read-side backward compat (other
-- app code selects `inventory_brand_variants.brand` directly). A trigger keeps
-- it in sync with `brand_id` so writes only need to touch the FK.

-- ─── 1. Merge existing inventory brand text values into public.brands ─────────
-- Skip any that already exist in the brands table (case-insensitive match)

INSERT INTO public.brands (name)
SELECT DISTINCT TRIM(ibv.brand)
  FROM public.inventory_brand_variants ibv
 WHERE ibv.brand IS NOT NULL
   AND TRIM(ibv.brand) <> ''
   AND NOT EXISTS (
     SELECT 1 FROM public.brands b
      WHERE LOWER(TRIM(b.name)) = LOWER(TRIM(ibv.brand))
   );

-- ─── 2. Add brand_id FK on inventory_brand_variants ───────────────────────────

ALTER TABLE public.inventory_brand_variants
  ADD COLUMN brand_id uuid REFERENCES public.brands(id) ON DELETE SET NULL;

CREATE INDEX idx_inventory_brand_variants_brand_id
  ON public.inventory_brand_variants (brand_id);

-- Backfill brand_id via case-insensitive text match
UPDATE public.inventory_brand_variants ibv
   SET brand_id = b.id
  FROM public.brands b
 WHERE LOWER(TRIM(b.name)) = LOWER(TRIM(ibv.brand))
   AND ibv.brand IS NOT NULL
   AND TRIM(ibv.brand) <> '';

-- ─── 3. Sync trigger — writes to brand_id keep brand text current ─────────────
-- Existing app reads select `inventory_brand_variants.brand` directly in many
-- places (WhAdjustmentsTab, ReceivalFormDialog, BillFormDialog, etc.). Rather
-- than refactor every read site, we keep the text column in sync so any legacy
-- read still returns the right value.

CREATE OR REPLACE FUNCTION public.sync_brand_variant_brand_text()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  IF NEW.brand_id IS NOT NULL THEN
    SELECT name INTO NEW.brand FROM public.brands WHERE id = NEW.brand_id;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_sync_brand_variants_brand_text
BEFORE INSERT OR UPDATE OF brand_id ON public.inventory_brand_variants
FOR EACH ROW
EXECUTE FUNCTION public.sync_brand_variant_brand_text();

-- ─── 4. Update get_dead_stock_report to prefer brand_id → brands.name ─────────

CREATE OR REPLACE FUNCTION public.get_dead_stock_report()
RETURNS TABLE(
  brand_variant_id     uuid,
  item_name            text,
  category_name        text,
  brand                text,
  sku                  text,
  stock_level          numeric,
  average_cost         numeric,
  total_value          numeric,
  last_movement_date   timestamp with time zone,
  last_movement_source text,
  days_idle            integer,
  status               text
)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $$
  WITH
  latest_movements AS (
    SELECT brand_variant_id, MAX(created_at) AS last_movement_at
      FROM inventory_stock_movements
     GROUP BY brand_variant_id
  ),
  oldest_fifo AS (
    SELECT brand_variant_id, MIN(date) AS oldest_layer_date
      FROM fifo_cost_layers
     WHERE remaining_qty > 0
     GROUP BY brand_variant_id
  ),
  computed AS (
    SELECT
      ibv.id                                                      AS brand_variant_id,
      ii.name_en                                                  AS item_name,
      ic.name_en                                                  AS category_name,
      COALESCE(b.name, NULLIF(TRIM(ibv.brand), ''))               AS brand,
      ibv.code                                                    AS sku,
      ibv.stock_level,
      COALESCE(ibv.average_cost, 0)                               AS average_cost,
      ibv.stock_level * COALESCE(ibv.average_cost, 0)             AS total_value,
      COALESCE(lm.last_movement_at,
               of.oldest_layer_date::timestamptz,
               ibv.created_at)                                    AS last_movement_date,
      CASE
        WHEN lm.last_movement_at  IS NOT NULL THEN 'movement'
        WHEN of.oldest_layer_date IS NOT NULL THEN 'fifo'
        WHEN ibv.created_at       IS NOT NULL THEN 'created'
        ELSE NULL
      END                                                         AS last_movement_source,
      EXTRACT(DAY FROM
        CURRENT_TIMESTAMP -
        COALESCE(lm.last_movement_at,
                 of.oldest_layer_date::timestamptz,
                 ibv.created_at)
      )::int                                                      AS days_idle
    FROM       public.inventory_brand_variants ibv
    JOIN       public.inventory_items          ii ON ii.id = ibv.item_id
    LEFT JOIN  public.inventory_categories     ic ON ic.id = ii.category_id
    LEFT JOIN  public.brands                   b  ON b.id  = ibv.brand_id
    LEFT JOIN  latest_movements                lm ON lm.brand_variant_id = ibv.id
    LEFT JOIN  oldest_fifo                     of ON of.brand_variant_id = ibv.id
    WHERE ibv.stock_level > 0
  )
  SELECT
    brand_variant_id, item_name, category_name, brand, sku,
    stock_level, average_cost, total_value, last_movement_date,
    last_movement_source, days_idle,
    CASE
      WHEN days_idle <= 30  THEN 'active'
      WHEN days_idle <= 90  THEN 'slow_moving'
      WHEN days_idle <= 180 THEN 'at_risk'
      ELSE                       'dead'
    END AS status
  FROM computed;
$$;

-- ─── 5. Report migration outcome ──────────────────────────────────────────────

DO $$
DECLARE
  v_brands_count    INT;
  v_variants_total  INT;
  v_variants_linked INT;
BEGIN
  SELECT COUNT(*) INTO v_brands_count  FROM public.brands;
  SELECT COUNT(*) INTO v_variants_total FROM public.inventory_brand_variants;
  SELECT COUNT(*) INTO v_variants_linked
    FROM public.inventory_brand_variants WHERE brand_id IS NOT NULL;

  RAISE NOTICE 'Total brands (existing + merged): %', v_brands_count;
  RAISE NOTICE 'Variants total: %', v_variants_total;
  RAISE NOTICE 'Variants linked to a brand: %', v_variants_linked;
  RAISE NOTICE 'Variants without a brand: %', v_variants_total - v_variants_linked;
END $$;


-- ============================================================
-- Source: 20260721100000_merge_cx_extension_column.sql
-- ============================================================
-- Migration: Merge cx_extension into threecx_extension, then drop the old column
-- Reviewer feedback: "Why is there cx_extension AND threecx_extension? We need one."

-- Step 1: Copy any non-null cx_extension values where threecx_extension is null
UPDATE public.profiles
SET    threecx_extension = cx_extension
WHERE  cx_extension IS NOT NULL
  AND  (threecx_extension IS NULL OR threecx_extension = '');

-- Step 2: Drop the old column
ALTER TABLE public.profiles DROP COLUMN IF EXISTS cx_extension;


-- ============================================================
-- Source: 20260721100001_rename_is_field_rp.sql
-- ============================================================
-- Migration: Rename is_field_rp → is_warehouse_responsible on custom_roles
-- Reviewer feedback: "What does field_rp mean? Just call it warehouse_responsible_person"

ALTER TABLE public.custom_roles
  RENAME COLUMN is_field_rp TO is_warehouse_responsible;

-- Update the RPC that checks this flag (is_field_rp_of)
CREATE OR REPLACE FUNCTION public.is_field_rp_of(p_profile_id uuid, p_warehouse_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM   public.warehouse_field_rps wfr
    WHERE  wfr.profile_id   = p_profile_id
      AND  wfr.warehouse_id = p_warehouse_id
  );
$$;


-- ============================================================
-- Source: 20260721100002_rename_pricing_factors_table.sql
-- ============================================================
-- Migration: Rename pricing_factors → contract_pricing_factors
-- Reviewer feedback: "Pricing factor is for contract? We need to make it clear."

ALTER TABLE public.pricing_factors RENAME TO contract_pricing_factors;

-- Rename FK constraints to match new table name
ALTER TABLE public.contract_pricing_factors
  RENAME CONSTRAINT pricing_factors_pkey TO contract_pricing_factors_pkey;

ALTER TABLE public.contract_pricing_factors
  RENAME CONSTRAINT pricing_factors_created_by_fkey TO contract_pricing_factors_created_by_fkey;

-- division FK was originally to divisions; may have been updated to company_divisions
DO $$
BEGIN
  ALTER TABLE public.contract_pricing_factors
    RENAME CONSTRAINT pricing_factors_division_id_fkey TO contract_pricing_factors_division_id_fkey;
EXCEPTION WHEN undefined_object THEN NULL;
END $$;

-- Rename the update trigger
DROP TRIGGER IF EXISTS set_pricing_factors_updated_at ON public.contract_pricing_factors;
CREATE TRIGGER set_contract_pricing_factors_updated_at
  BEFORE UPDATE ON public.contract_pricing_factors
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- Rename RLS policies
ALTER POLICY "Internal users can read pricing_factors"   ON public.contract_pricing_factors RENAME TO "Internal users can read contract_pricing_factors";
ALTER POLICY "Internal users can insert pricing_factors" ON public.contract_pricing_factors RENAME TO "Internal users can insert contract_pricing_factors";
ALTER POLICY "Internal users can update pricing_factors" ON public.contract_pricing_factors RENAME TO "Internal users can update contract_pricing_factors";
ALTER POLICY "Internal users can delete pricing_factors" ON public.contract_pricing_factors RENAME TO "Internal users can delete contract_pricing_factors";

-- Create a compatibility view so existing queries don't break during transition
CREATE OR REPLACE VIEW public.pricing_factors AS
  SELECT * FROM public.contract_pricing_factors;


-- ============================================================
-- Source: 20260721100003_add_tool_asset_to_delivery_return_lines.sql
-- ============================================================
-- Migration: Add tool_asset_item_id to sale_delivery_lines and return_lines
-- Reviewer feedback: "sale_order_lines has brand_variant_id AND tool_asset_item_id,
--   but delivery/return lines only have brand_variant_id"

-- sale_delivery_lines: add tool_asset_item_id
ALTER TABLE public.sale_delivery_lines
  ADD COLUMN IF NOT EXISTS tool_asset_item_id uuid;

-- return_lines: add tool_asset_item_id
ALTER TABLE public.return_lines
  ADD COLUMN IF NOT EXISTS tool_asset_item_id uuid;

-- FK constraints — only add if the referenced table exists (staging DBs may lack it)
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'tool_asset_items') THEN
    BEGIN
      ALTER TABLE public.sale_delivery_lines
        ADD CONSTRAINT sale_delivery_lines_tool_asset_item_id_fkey
          FOREIGN KEY (tool_asset_item_id) REFERENCES public.tool_asset_items(id);
    EXCEPTION WHEN duplicate_object THEN NULL;
    END;
    BEGIN
      ALTER TABLE public.return_lines
        ADD CONSTRAINT return_lines_tool_asset_item_id_fkey
          FOREIGN KEY (tool_asset_item_id) REFERENCES public.tool_asset_items(id);
    EXCEPTION WHEN duplicate_object THEN NULL;
    END;
  END IF;
END $$;


-- ============================================================
-- Source: 20260721100004_add_division_id_to_warehouses.sql
-- ============================================================
-- Migration: Add division_id directly to warehouses table
-- Reviewer feedback: "How can you separate costing and warehousing tables by divisions?
--   I don't see division relations there."
-- Previously division was inferred via warehouse_field_rps → profiles (fragile 2-hop).
-- Now warehouses own their division directly — set when creating/editing a warehouse.

-- ── Step 1: Add the column (nullable — existing rows need backfill) ──────────
ALTER TABLE public.warehouses
  ADD COLUMN IF NOT EXISTS division_id uuid;

DO $$
BEGIN
  ALTER TABLE public.warehouses
    ADD CONSTRAINT warehouses_division_id_fkey
      FOREIGN KEY (division_id) REFERENCES public.company_divisions(id);
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

-- ── Step 2: Backfill from user_company_divisions (where unambiguous) ─────────
-- For each warehouse, find all Field RPs → their divisions.
-- Only assign when EVERY RP of the warehouse shares exactly ONE common division.
-- Ambiguous cases (RPs in multiple divisions, or mixed divisions) stay NULL
-- for manual assignment via the UI.
UPDATE public.warehouses w
SET    division_id = sub.single_division_id
FROM (
  SELECT
    wfr.warehouse_id,
    MIN(ucd.division_id) AS single_division_id
  FROM   public.warehouse_field_rps wfr
  JOIN   public.user_company_divisions ucd ON ucd.profile_id = wfr.profile_id
  GROUP BY wfr.warehouse_id
  HAVING COUNT(DISTINCT ucd.division_id) = 1
) sub
WHERE  w.id = sub.warehouse_id
  AND  w.division_id IS NULL;

-- ── Step 3: Fallback — warehouses with no RP or ambiguous RPs ────────────────
-- Assign the first active division so no warehouse is left without one.
-- The admin can reassign via the UI later.
UPDATE public.warehouses
SET    division_id = (
  SELECT id FROM public.company_divisions
  WHERE  is_active = true
  ORDER BY sort_order ASC
  LIMIT 1
)
WHERE division_id IS NULL;

-- ── Step 4: Now that all rows are filled, enforce NOT NULL ───────────────────
ALTER TABLE public.warehouses
  ALTER COLUMN division_id SET NOT NULL;

-- ── Step 5: Index for division-based filtering / reports ─────────────────────
CREATE INDEX IF NOT EXISTS idx_warehouses_division_id ON public.warehouses(division_id);


-- ============================================================
-- Source: 20260721100005_drop_profiles_division_id.sql
-- ============================================================
-- Migration: Drop unused profiles.division_id column
-- The app never writes to this column. Division access is managed entirely
-- through user_company_divisions junction table + JWT claims.

-- Drop the FK constraint
ALTER TABLE public.profiles
  DROP CONSTRAINT IF EXISTS profiles_division_id_fkey;

-- Drop the index
