-- ============================================================
-- Source: 20260721120002_normalize_warehouse_transfer_actors.sql
-- ============================================================
-- ============================================================
-- Issue 6: Normalize warehouse_transfers actor columns
--
-- 1. Drop created_by (text, always NULL — replaced by created_by_profile_id)
-- 2. Drop approved_by (text, always NULL — never written by any code)
-- 3. Add approved_by_profile_id (uuid FK to profiles) to match the
--    dispatched_by / received_by / cancelled_by pattern
-- 4. Update reject_transfer_v2 to write approved_by_profile_id
-- ============================================================

BEGIN;

-- 1. Drop dead columns
ALTER TABLE public.warehouse_transfers
  DROP COLUMN IF EXISTS created_by;

ALTER TABLE public.warehouse_transfers
  DROP COLUMN IF EXISTS approved_by;

-- 2. Add approved_by_profile_id with FK
ALTER TABLE public.warehouse_transfers
  ADD COLUMN IF NOT EXISTS approved_by_profile_id uuid
    REFERENCES public.profiles(id);

CREATE INDEX IF NOT EXISTS idx_warehouse_transfers_approved_by_profile_id
  ON public.warehouse_transfers (approved_by_profile_id);

-- 3. Update reject_transfer_v2 to write the new column
CREATE OR REPLACE FUNCTION public.reject_transfer_v2(
  p_transfer_id uuid,
  p_rejected_by_profile_id uuid,
  p_rejected_by_name text
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
  v_transfer RECORD;
  v_item RECORD;
  v_avg_cost NUMERIC;
BEGIN
  SELECT id, from_warehouse_id, to_warehouse_id, status, date
  INTO v_transfer
  FROM warehouse_transfers
  WHERE id = p_transfer_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transfer % not found', p_transfer_id;
  END IF;

  IF v_transfer.status NOT IN ('pending', 'in_transit') THEN
    RAISE EXCEPTION 'Transfer % cannot be rejected — current status: %',
      p_transfer_id, v_transfer.status;
  END IF;

  UPDATE warehouse_transfers
  SET status = 'rejected',
      approved_by_profile_id = p_rejected_by_profile_id,
      approved_by_name = p_rejected_by_name,
      approved_date = CURRENT_DATE
  WHERE id = p_transfer_id;

  FOR v_item IN
    SELECT * FROM warehouse_transfer_items
    WHERE transfer_id = p_transfer_id
    ORDER BY brand_variant_id
  LOOP
    IF v_transfer.status = 'pending' THEN
      UPDATE warehouse_stock_allocations
      SET allocated_qty = GREATEST(allocated_qty - v_item.requested_qty, 0),
          updated_at = now()
      WHERE warehouse_id = v_transfer.from_warehouse_id
        AND brand_variant_id = v_item.brand_variant_id;

    ELSIF v_transfer.status = 'in_transit' THEN
      SELECT ABS(unit_cost) INTO v_avg_cost
      FROM inventory_stock_movements
      WHERE reference_id = p_transfer_id
        AND brand_variant_id = v_item.brand_variant_id
        AND movement_type = 'transfer_out'
      LIMIT 1;

      v_avg_cost := COALESCE(v_avg_cost, v_item.unit_cost);

      INSERT INTO fifo_cost_layers (
        brand_variant_id, warehouse_id, date,
        qty, unit_cost, landed_cost_per_unit, total_unit_cost, remaining_qty
      ) VALUES (
        v_item.brand_variant_id, v_transfer.from_warehouse_id,
        CURRENT_DATE,
        v_item.requested_qty, v_avg_cost, 0, v_avg_cost, v_item.requested_qty
      );

      INSERT INTO inventory_stock_movements (
        warehouse_id, brand_variant_id, item_name, sku,
        movement_type, qty, unit_cost, reference_type, reference_id, notes
      ) VALUES (
        v_transfer.from_warehouse_id, v_item.brand_variant_id,
        v_item.item_name, v_item.sku,
        'transfer_in', v_item.requested_qty, v_avg_cost,
        'transfer', p_transfer_id,
        'Transfer rejected — stock returned'
      );
    END IF;
  END LOOP;
END;
$$;

COMMIT;


-- ============================================================
-- Source: 20260721120003_add_invoices_division_id.sql
-- ============================================================
-- ============================================================
-- Issue 7: Add invoices.division_id (proper FK)
--
-- The existing invoices.division TEXT column is never populated.
-- The get_customer_pending_balances RPC already references
-- i.division_id and LEFT JOINs company_divisions — it was
-- written assuming this column exists. Adding it fixes the RPC.
--
-- Steps:
--   1. Add division_id uuid FK to company_divisions(id)
--   2. Backfill AR invoices from linked sale_orders
--   3. Backfill AP invoices from linked purchase_orders
--   4. Update generate_invoice_from_so to set division_id
-- ============================================================

BEGIN;

-- 1. Add column
ALTER TABLE public.invoices
  ADD COLUMN IF NOT EXISTS division_id uuid
    REFERENCES public.company_divisions(id);

CREATE INDEX IF NOT EXISTS idx_invoices_division_id
  ON public.invoices (division_id);

-- 2. Backfill AR invoices from sale_orders
UPDATE public.invoices i
SET division_id = so.division_id
FROM public.sale_orders so
WHERE i.sale_order_id = so.id
  AND i.direction = 'ar'
  AND i.division_id IS NULL
  AND so.division_id IS NOT NULL;

-- 3. Backfill AP invoices from purchase_orders
UPDATE public.invoices i
SET division_id = po.division_id
FROM public.purchase_orders po
WHERE i.purchase_order_id = po.id
  AND i.direction = 'ap'
  AND i.division_id IS NULL
  AND po.division_id IS NOT NULL;

-- 4. Update generate_invoice_from_so to include division_id
CREATE OR REPLACE FUNCTION public.generate_invoice_from_so(p_so_id uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_so               RECORD;
  v_invoice_id_str   TEXT;
  v_invoice_type     TEXT;
  v_issued_date      DATE;
  v_due_date         DATE;
  v_inv_count        INT;
  v_new_inv_id       uuid;
  v_new_inv_str      TEXT;
  v_paid_amount      NUMERIC;
  v_payment_status   TEXT;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('invoices_serial'));

  IF EXISTS (
    SELECT 1 FROM invoices
    WHERE  sale_order_id = p_so_id AND direction = 'ar'
  ) THEN
    RAISE EXCEPTION 'invoice_exists';
  END IF;

  SELECT
    so.id, so.so_number, so.status, so.customer_id,
    so.division_id,
    so.subtotal,
    COALESCE(so.tax, 0)                 AS tax,
    so.total                            AS total_amount,
    COALESCE(c.customer_type, 'credit') AS customer_type
  INTO v_so
  FROM sale_orders so
  JOIN customers   c  ON c.id = so.customer_id
  WHERE so.id = p_so_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'so_not_found';
  END IF;

  IF v_so.status NOT IN ('confirmed', 'partial_delivery', 'delivered') THEN
    RAISE EXCEPTION 'so_not_invoiceable';
  END IF;

  SELECT COALESCE(SUM(COALESCE(amount_qar, amount)), 0)
    INTO v_paid_amount
  FROM   public.payments
  WHERE  source_type = 'sale_order'
    AND  source_id   = p_so_id
    AND  deleted_at IS NULL;

  v_payment_status := CASE
    WHEN v_paid_amount >= v_so.total_amount THEN 'paid'
    WHEN v_paid_amount > 0                  THEN 'partially_paid'
    ELSE                                          'unpaid'
  END;

  SELECT COUNT(*) + 1 INTO v_inv_count FROM invoices;
  v_invoice_id_str := 'INV-' || LPAD(v_inv_count::text, 5, '0');

  v_invoice_type := v_so.customer_type;
  v_issued_date  := CURRENT_DATE;
  v_due_date     := CASE v_invoice_type
    WHEN 'cash' THEN CURRENT_DATE
    ELSE             CURRENT_DATE + 30
  END;

  INSERT INTO invoices (
    invoice_id, customer_id, direction, sale_order_id,
    division_id,
    invoice_type, doc_status, status, payment_status, needs_refresh,
    total_amount, subtotal, tax, paid_amount,
    issued_date, due_date,
    source, source_id, source_label
  ) VALUES (
    v_invoice_id_str, v_so.customer_id, 'ar', p_so_id,
    v_so.division_id,
    v_invoice_type, 'draft', 'draft', v_payment_status, false,
    v_so.total_amount, v_so.subtotal, v_so.tax, v_paid_amount,
    v_issued_date, v_due_date,
    'order', p_so_id::text, 'SO #' || v_so.so_number
  )
  RETURNING id, invoice_id INTO v_new_inv_id, v_new_inv_str;

  UPDATE public.payments
  SET    source_type = 'invoice',
         source_id   = v_new_inv_id
  WHERE  source_type = 'sale_order'
    AND  source_id   = p_so_id
    AND  deleted_at IS NULL;

  INSERT INTO invoice_line_items (invoice_id, description, qty, unit_price, total)
  SELECT v_new_inv_id, sol.item_name, sol.qty, sol.unit_price, sol.total
  FROM   sale_order_lines sol
  WHERE  sol.sale_order_id = p_so_id;

  RETURN jsonb_build_object(
    'id',           v_new_inv_id,
    'invoice_id',   v_new_inv_str,
    'invoice_type', v_invoice_type,
    'paid_amount',  v_paid_amount
  );
END;
$$;

COMMIT;


