-- ============================================================
-- Source: 20260722160000_restore_tool_asset_items.sql
-- ============================================================
-- STAGING-ONLY: restore `tool_asset_items` so the purchase chain
-- (po_line_items → receival_items → return_lines / sale_delivery_lines
-- → sale_order_lines) can actually FK to it.
--
-- Background:
-- • `tool_asset_items` was dropped from staging on 2026-07-13 as part of
--   the "not needed for inventory build" cleanup.
-- • But the tool-asset purchase-chain feature is active in prod. Since
--   2026-07-21, migrations have been adding `tool_asset_item_id` columns
--   to PO/receival/return/sale-delivery/sale-order line-item tables,
--   guarding the FK with `IF EXISTS (tool_asset_items)` so staging
--   wouldn't blow up.
-- • The result: those FK constraints exist in prod but NOT in staging.
--   Staging can write dangling tool_asset_item_id values with no target.
--
-- This restores the item catalog table AND retro-fits the deferred FK
-- constraints. Units / assignments are not restored — the purchase chain
-- only needs items.
--
-- NO matching migration in `supabase/migrations/` (prod). Prod already
-- has this table; only staging needs to catch up.

BEGIN;

CREATE TABLE IF NOT EXISTS public.tool_asset_items (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  category_id uuid,
  name_en    text NOT NULL,
  name_ar    text,
  created_at timestamptz DEFAULT now()
);

ALTER TABLE public.tool_asset_items ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Authenticated users can manage tool_asset_items"
  ON public.tool_asset_items TO authenticated USING (true) WITH CHECK (true);

-- Retro-add the FK constraints that the guarded prod migrations skipped
-- on staging because the target table wasn't there.

DO $$ BEGIN
  ALTER TABLE public.po_line_items
    ADD CONSTRAINT po_line_items_tool_asset_item_id_fkey
      FOREIGN KEY (tool_asset_item_id) REFERENCES public.tool_asset_items(id);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE public.po_version_lines
    ADD CONSTRAINT po_version_lines_tool_asset_item_id_fkey
      FOREIGN KEY (tool_asset_item_id) REFERENCES public.tool_asset_items(id);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE public.receival_items
    ADD CONSTRAINT receival_items_tool_asset_item_id_fkey
      FOREIGN KEY (tool_asset_item_id) REFERENCES public.tool_asset_items(id);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE public.sale_order_lines
    ADD CONSTRAINT sale_order_lines_tool_asset_item_id_fkey
      FOREIGN KEY (tool_asset_item_id) REFERENCES public.tool_asset_items(id);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE public.sale_delivery_lines
    ADD CONSTRAINT sale_delivery_lines_tool_asset_item_id_fkey
      FOREIGN KEY (tool_asset_item_id) REFERENCES public.tool_asset_items(id);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE public.return_lines
    ADD CONSTRAINT return_lines_tool_asset_item_id_fkey
      FOREIGN KEY (tool_asset_item_id) REFERENCES public.tool_asset_items(id);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

COMMIT;


-- ============================================================
-- Source: 20260722170000_bill_paid_amount_auto_recompute.sql
-- ============================================================
-- ============================================================================
-- Auto-recompute bills.paid_amount from payments
-- ============================================================================
-- Missing AP mirror of invoice_recompute_paid_fn: when a supplier payment is
-- recorded against a PO, bills.paid_amount stays $0. The invoice/bill split
-- spec (§7.2) listed this as required but it was never created.
--
-- This migration adds:
--   • bill_recompute_paid_fn(bill_id uuid) — recomputes paid_amount +
--     payment_status for one bill.
--   • payments_trigger_bill_recompute_fn — AFTER INSERT/UPDATE/DELETE on
--     payments, recomputes bills for any bill touched directly (via
--     payments.bill_id / source_type='bill') OR indirectly (via the payment's
--     purchase_order_id, since 1 PO = 1 bill in this app).
--   • bill_recompute_paid_trg — the trigger itself.
--
-- Also backfills every existing bill's paid_amount so historical rows are
-- correct after the migration runs.
--
-- manually_paid is retained as a column and honored as an override — if a
-- bill is explicitly manually_paid=true, its status is not overwritten by
-- the recompute. New writes of manually_paid come exclusively from data
-- fixes; the UI toggle is removed in a follow-up code change.
-- ============================================================================

BEGIN;

-- ── 1. Per-bill recompute function ─────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.bill_recompute_paid_fn(p_bill_id uuid)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_total     NUMERIC;
  v_manually  BOOLEAN;
  v_po_id     UUID;
  v_paid      NUMERIC := 0;
  v_new       TEXT;
BEGIN
  SELECT total_amount, manually_paid, purchase_order_id
  INTO   v_total, v_manually, v_po_id
  FROM   public.bills WHERE id = p_bill_id;

  IF NOT FOUND THEN RETURN; END IF;

  -- Direct payments (source_type='bill' or bill_id set)
  v_paid := v_paid + COALESCE((
    SELECT SUM(COALESCE(amount_qar, amount))
    FROM   public.payments
    WHERE  (
             (source_type = 'bill' AND source_id = p_bill_id)
             OR bill_id = p_bill_id
           )
      AND  direction = 'outgoing'
      AND  deleted_at IS NULL
  ), 0);

  -- payment_bill_allocations (explicit multi-allocation)
  v_paid := v_paid + COALESCE((
    SELECT SUM(amount)
    FROM   public.payment_bill_allocations
    WHERE  bill_id = p_bill_id
  ), 0);

  -- PO-level payments (source_type='purchase_order' with source_id=this bill's PO)
  IF v_po_id IS NOT NULL THEN
    v_paid := v_paid + COALESCE((
      SELECT SUM(COALESCE(amount_qar, amount))
      FROM   public.payments
      WHERE  source_type = 'purchase_order'
        AND  source_id   = v_po_id
        AND  direction   = 'outgoing'
        AND  deleted_at  IS NULL
    ), 0);
  END IF;

  -- Cap at total_amount so paid_amount never exceeds total
  v_paid := LEAST(v_paid, COALESCE(v_total, 0));

  v_new := CASE
    WHEN COALESCE(v_total, 0) > 0 AND v_paid >= v_total THEN 'paid'
    WHEN v_paid > 0                                     THEN 'partially_paid'
    ELSE                                                     'unpaid'
  END;

  UPDATE public.bills
  SET    paid_amount    = v_paid,
         payment_status = CASE WHEN v_manually THEN payment_status ELSE v_new END
  WHERE  id = p_bill_id;
END;
$$;

-- ── 2. Trigger function on payments ────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.payments_trigger_bill_recompute_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  v_new_bill_id uuid;
  v_old_bill_id uuid;
  v_new_po_id   uuid;
  v_old_po_id   uuid;
  b_rec         RECORD;
BEGIN
  -- Collect all bill_ids and po_ids potentially affected by this change.
  IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
    v_new_bill_id := NEW.bill_id;
    IF NEW.source_type = 'bill'           THEN v_new_bill_id := NEW.source_id; END IF;
    IF NEW.source_type = 'purchase_order' THEN v_new_po_id   := NEW.source_id; END IF;
  END IF;

  IF TG_OP = 'UPDATE' OR TG_OP = 'DELETE' THEN
    v_old_bill_id := OLD.bill_id;
    IF OLD.source_type = 'bill'           THEN v_old_bill_id := OLD.source_id; END IF;
    IF OLD.source_type = 'purchase_order' THEN v_old_po_id   := OLD.source_id; END IF;
  END IF;

  -- Recompute directly-referenced bills.
  IF v_new_bill_id IS NOT NULL THEN
    PERFORM public.bill_recompute_paid_fn(v_new_bill_id);
  END IF;
  IF v_old_bill_id IS NOT NULL AND v_old_bill_id IS DISTINCT FROM v_new_bill_id THEN
    PERFORM public.bill_recompute_paid_fn(v_old_bill_id);
  END IF;

  -- Recompute bills linked via PO (1 PO = 1 bill in this app, but loop for safety).
  IF v_new_po_id IS NOT NULL THEN
    FOR b_rec IN SELECT id FROM public.bills WHERE purchase_order_id = v_new_po_id LOOP
      PERFORM public.bill_recompute_paid_fn(b_rec.id);
    END LOOP;
  END IF;
  IF v_old_po_id IS NOT NULL AND v_old_po_id IS DISTINCT FROM v_new_po_id THEN
    FOR b_rec IN SELECT id FROM public.bills WHERE purchase_order_id = v_old_po_id LOOP
      PERFORM public.bill_recompute_paid_fn(b_rec.id);
    END LOOP;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;

-- ── 3. Wire up the trigger ─────────────────────────────────────────────────

DROP TRIGGER IF EXISTS bill_recompute_paid_trg ON public.payments;

CREATE TRIGGER bill_recompute_paid_trg
AFTER INSERT OR UPDATE OR DELETE ON public.payments
FOR EACH ROW EXECUTE FUNCTION public.payments_trigger_bill_recompute_fn();

-- ── 4. Also recompute when payment_bill_allocations changes ────────────────

CREATE OR REPLACE FUNCTION public.payment_bill_allocations_trigger_recompute_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
    PERFORM public.bill_recompute_paid_fn(NEW.bill_id);
  END IF;
  IF TG_OP = 'UPDATE' OR TG_OP = 'DELETE' THEN
    IF OLD.bill_id IS DISTINCT FROM COALESCE(NEW.bill_id, OLD.bill_id) THEN
      PERFORM public.bill_recompute_paid_fn(OLD.bill_id);
    ELSIF TG_OP = 'DELETE' THEN
      PERFORM public.bill_recompute_paid_fn(OLD.bill_id);
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;

DROP TRIGGER IF EXISTS payment_bill_allocations_recompute_trg ON public.payment_bill_allocations;

CREATE TRIGGER payment_bill_allocations_recompute_trg
AFTER INSERT OR UPDATE OR DELETE ON public.payment_bill_allocations
FOR EACH ROW EXECUTE FUNCTION public.payment_bill_allocations_trigger_recompute_fn();

-- ── 5. Backfill existing bills ─────────────────────────────────────────────

DO $$
DECLARE r RECORD;
BEGIN
  FOR r IN SELECT id FROM public.bills LOOP
    PERFORM public.bill_recompute_paid_fn(r.id);
  END LOOP;
END $$;

COMMIT;


-- ============================================================
-- Source: 20260722180000_reset_bill_manually_paid.sql
-- ============================================================
-- Reset manually_paid on all bills so the auto-recompute trigger owns
-- payment_status. The UI "Mark as Paid" button was removed in favor of
-- automatic tracking via bill_recompute_paid_fn; the flag is preserved
-- as a column for future one-off overrides but not set from the UI.
--
-- Also NULL out cached bill PDF URLs so the next view regenerates them
-- with the corrected paid_amount + payment list.

BEGIN;

UPDATE public.bills SET manually_paid = false WHERE manually_paid = true;

-- Force PDF regeneration by clearing cached URLs.
UPDATE public.bills SET pdf_url = NULL WHERE pdf_url IS NOT NULL;

-- Rerun the recompute for every bill now that manually_paid is off, so
-- payment_status matches the real paid_amount instead of the old override.
DO $$
DECLARE r RECORD;
BEGIN
  FOR r IN SELECT id FROM public.bills LOOP
    PERFORM public.bill_recompute_paid_fn(r.id);
  END LOOP;
END $$;

COMMIT;


-- ============================================================
-- Source: 20260722190000_bill_recompute_use_original_currency.sql
-- ============================================================
-- Fix bill_recompute_paid_fn to sum payments in the bill's currency, not QAR.
--
-- Previous version summed COALESCE(amount_qar, amount), which mixes
-- currencies: bill.total_amount is stored in the PO's currency (e.g. USD),
-- but amount_qar is the payment converted to QAR. Comparing them treated
-- a $15,000 USD payment as QAR 54,750 and marked a $53,500 USD bill as
-- fully paid.
--
-- Payments are recorded in the parent (PO/bill) currency. amount is
-- authoritative and comparable to bill.total_amount directly. amount_qar
-- is a bookkeeping mirror for QAR-denominated reporting only.

BEGIN;

CREATE OR REPLACE FUNCTION public.bill_recompute_paid_fn(p_bill_id uuid)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_total     NUMERIC;
  v_manually  BOOLEAN;
  v_po_id     UUID;
  v_paid      NUMERIC := 0;
  v_new       TEXT;
BEGIN
  SELECT total_amount, manually_paid, purchase_order_id
  INTO   v_total, v_manually, v_po_id
  FROM   public.bills WHERE id = p_bill_id;

  IF NOT FOUND THEN RETURN; END IF;

  -- Direct payments (source_type='bill' or bill_id set).
  -- Use amount (original currency) so we compare like-for-like with total_amount.
  v_paid := v_paid + COALESCE((
    SELECT SUM(amount)
    FROM   public.payments
    WHERE  (
             (source_type = 'bill' AND source_id = p_bill_id)
             OR bill_id = p_bill_id
           )
      AND  direction = 'outgoing'
      AND  deleted_at IS NULL
  ), 0);

  -- payment_bill_allocations — already in the bill's currency.
  v_paid := v_paid + COALESCE((
    SELECT SUM(amount)
    FROM   public.payment_bill_allocations
    WHERE  bill_id = p_bill_id
  ), 0);

  -- PO-level payments — original currency, same as PO/bill.
  IF v_po_id IS NOT NULL THEN
    v_paid := v_paid + COALESCE((
      SELECT SUM(amount)
      FROM   public.payments
      WHERE  source_type = 'purchase_order'
        AND  source_id   = v_po_id
        AND  direction   = 'outgoing'
        AND  deleted_at  IS NULL
    ), 0);
  END IF;

  v_paid := LEAST(v_paid, COALESCE(v_total, 0));

  v_new := CASE
    WHEN COALESCE(v_total, 0) > 0 AND v_paid >= v_total THEN 'paid'
    WHEN v_paid > 0                                     THEN 'partially_paid'
    ELSE                                                     'unpaid'
  END;

  UPDATE public.bills
  SET    paid_amount    = v_paid,
         payment_status = CASE WHEN v_manually THEN payment_status ELSE v_new END
  WHERE  id = p_bill_id;
END;
$$;

-- Rerun for every bill so historical rows correct themselves.
DO $$
DECLARE r RECORD;
BEGIN
  FOR r IN SELECT id FROM public.bills LOOP
    PERFORM public.bill_recompute_paid_fn(r.id);
  END LOOP;
END $$;

-- Force PDF regeneration.
UPDATE public.bills SET pdf_url = NULL WHERE pdf_url IS NOT NULL;

COMMIT;


-- ============================================================
-- Source: 20260722200000_po_bill_monthly_numbering.sql
-- ============================================================
-- ============================================================================
-- PO / Bill numbering rework
-- ============================================================================
-- New scheme:
--   • PO number: PO-YYYY-MM-NNN — 3-digit counter resets each month.
--   • Bill number: <PO number>-B — no counter (enforced 1 PO = 1 bill).
--
-- This migration:
--   1. Verifies no PO currently has >1 bill (fails loudly if any do — needs
--      manual reconciliation before we can add the UNIQUE constraint).
--   2. Adds UNIQUE(purchase_order_id) on bills so the DB enforces 1:1.
--   3. Renumbers existing POs (2 rows in staging today) using
--      ROW_NUMBER() partitioned by year+month of created_at.
--   4. Renames existing bill numbers to <new PO number>-B.
--   5. Replaces next_po_number() with a monthly-reset version using an
--      advisory lock keyed by year+month for concurrency safety.
--   6. Drops the now-unused po_number_seq sequence.
--   7. Clears cached PDF URLs on bills / receivals / returns so future
--      renders pick up the new numbers.
-- ============================================================================

BEGIN;

-- ── 1. Pre-flight: fail if any PO has multiple bills ───────────────────────

DO $$
DECLARE
  v_dups int;
BEGIN
  SELECT COUNT(*) INTO v_dups FROM (
    SELECT purchase_order_id
    FROM   public.bills
    WHERE  purchase_order_id IS NOT NULL
    GROUP  BY purchase_order_id
    HAVING COUNT(*) > 1
  ) x;
  IF v_dups > 0 THEN
    RAISE EXCEPTION 'Refusing to migrate: % PO(s) have more than one bill. Reconcile before applying.', v_dups;
  END IF;
END $$;

-- ── 2. Enforce 1 PO = 1 bill ───────────────────────────────────────────────

ALTER TABLE public.bills
  ADD CONSTRAINT bills_purchase_order_id_unique UNIQUE (purchase_order_id);

-- ── 3. Renumber existing POs to PO-YYYY-MM-NNN ─────────────────────────────

WITH ranked AS (
  SELECT
    id,
    'PO-' || TO_CHAR(created_at, 'YYYY-MM') || '-' ||
      LPAD(
        ROW_NUMBER() OVER (
          PARTITION BY DATE_TRUNC('month', created_at)
          ORDER BY created_at, id
        )::TEXT,
        3, '0'
      ) AS new_po_number
  FROM public.purchase_orders
  WHERE po_number ~ '^PO-[0-9]+$'  -- only old-format numbers
)
UPDATE public.purchase_orders p
SET    po_number = r.new_po_number
FROM   ranked r
WHERE  p.id = r.id;

-- ── 4. Rename existing bill numbers to <new PO number>-B ───────────────────

UPDATE public.bills b
SET    bill_number = p.po_number || '-B'
FROM   public.purchase_orders p
WHERE  b.purchase_order_id = p.id;

-- ── 5. Replace next_po_number() with the monthly-reset version ─────────────

CREATE OR REPLACE FUNCTION public.next_po_number()
RETURNS TEXT
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_year   TEXT := TO_CHAR(CURRENT_DATE, 'YYYY');
  v_month  TEXT := TO_CHAR(CURRENT_DATE, 'MM');
  v_prefix TEXT := 'PO-' || v_year || '-' || v_month || '-';
  v_next   INT;
BEGIN
  -- Serialize concurrent creates within the same year+month.
  PERFORM pg_advisory_xact_lock(hashtext('po_number_' || v_year || v_month));

  SELECT COUNT(*) + 1 INTO v_next
  FROM   public.purchase_orders
  WHERE  po_number LIKE v_prefix || '%';

  RETURN v_prefix || LPAD(v_next::TEXT, 3, '0');
END $$;

GRANT EXECUTE ON FUNCTION public.next_po_number() TO authenticated;

-- ── 6. Drop the now-unused sequence ────────────────────────────────────────

DROP SEQUENCE IF EXISTS public.po_number_seq;

-- ── 7. Clear cached PDF URLs on rows that display these numbers ────────────

UPDATE public.bills      SET pdf_url = NULL WHERE pdf_url IS NOT NULL;
UPDATE public.receivals
   SET receipt_pdf_url = NULL, check_sheet_pdf_url = NULL
 WHERE receipt_pdf_url IS NOT NULL OR check_sheet_pdf_url IS NOT NULL;
UPDATE public.returns    SET pdf_url = NULL WHERE pdf_url IS NOT NULL;

COMMIT;


-- ============================================================
-- Source: 20260723100000_invoice_recompute_use_original_currency.sql
-- ============================================================
-- Fix invoice_recompute_paid_fn + recalculate_ar_invoice_payment_status
-- to sum payments in the invoice's currency, not QAR. Mirror of the
-- bill_recompute fix in 20260722190000.

BEGIN;

CREATE OR REPLACE FUNCTION public.invoice_recompute_paid_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  v_invoice_id     uuid;
  v_old_invoice_id uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.source_type = 'invoice' THEN v_invoice_id := OLD.source_id;
    ELSIF OLD.invoice_id IS NOT NULL THEN v_invoice_id := OLD.invoice_id;
    END IF;
  ELSE
    IF NEW.source_type = 'invoice' THEN v_invoice_id := NEW.source_id;
    ELSIF NEW.invoice_id IS NOT NULL THEN v_invoice_id := NEW.invoice_id;
    END IF;
  END IF;

  IF v_invoice_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  WITH summed AS (
    SELECT COALESCE(SUM(amount), 0) AS paid  -- FIX: was COALESCE(amount_qar, amount)
    FROM   public.payments
    WHERE  (
             (source_type = 'invoice' AND source_id = v_invoice_id)
             OR invoice_id = v_invoice_id
           )
      AND  deleted_at IS NULL
      AND  direction  = 'incoming'
  )
  UPDATE public.invoices i
  SET    paid_amount    = summed.paid,
         payment_status = (CASE
           WHEN i.total_amount > 0 AND summed.paid >= i.total_amount THEN 'paid'
           WHEN summed.paid > 0                                      THEN 'partially_paid'
           ELSE                                                           'unpaid'
         END)::public.invoice_payment_status
  FROM   summed
  WHERE  i.id = v_invoice_id;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.source_type = 'invoice' THEN v_old_invoice_id := OLD.source_id;
    ELSIF OLD.invoice_id IS NOT NULL THEN v_old_invoice_id := OLD.invoice_id;
    END IF;

    IF v_old_invoice_id IS NOT NULL AND v_old_invoice_id <> v_invoice_id THEN
      WITH summed AS (
        SELECT COALESCE(SUM(amount), 0) AS paid
        FROM   public.payments
        WHERE  (
                 (source_type = 'invoice' AND source_id = v_old_invoice_id)
                 OR invoice_id = v_old_invoice_id
               )
          AND  deleted_at IS NULL
          AND  direction  = 'incoming'
      )
      UPDATE public.invoices i
      SET    paid_amount    = summed.paid,
             payment_status = (CASE
               WHEN i.total_amount > 0 AND summed.paid >= i.total_amount THEN 'paid'
               WHEN summed.paid > 0                                      THEN 'partially_paid'
               ELSE                                                           'unpaid'
             END)::public.invoice_payment_status
      FROM   summed
      WHERE  i.id = v_old_invoice_id;
    END IF;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;

CREATE OR REPLACE FUNCTION public.recalculate_ar_invoice_payment_status(p_invoice_id uuid)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_total NUMERIC;
  v_paid  NUMERIC;
  v_new   public.invoice_payment_status;
BEGIN
  SELECT total_amount INTO v_total FROM invoices WHERE id = p_invoice_id;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT COALESCE(SUM(amount), 0) INTO v_paid  -- FIX: was COALESCE(amount_qar, amount)
  FROM   payments
  WHERE  (
           (source_type = 'invoice' AND source_id = p_invoice_id)
           OR invoice_id = p_invoice_id
         )
    AND  deleted_at IS NULL
    AND  direction  = 'incoming';

  v_new := CASE
    WHEN COALESCE(v_total, 0) > 0 AND v_paid >= v_total THEN 'paid'
    WHEN v_paid > 0                                     THEN 'partially_paid'
    ELSE                                                     'unpaid'
  END;

  UPDATE invoices
  SET    paid_amount    = v_paid,
         payment_status = v_new
  WHERE  id = p_invoice_id;
END;
$$;

-- Rerun the recompute for every invoice to correct paid_amount + status.
DO $$
DECLARE r RECORD;
BEGIN
  FOR r IN SELECT id FROM public.invoices LOOP
    PERFORM public.recalculate_ar_invoice_payment_status(r.id);
  END LOOP;
END $$;

COMMIT;


-- ============================================================
-- Source: 20260723105000_drop_invoice_dibsy_columns.sql
-- ============================================================
-- Option A: rip Dibsy out of public.invoices. Sales-order invoices are
-- paid via cash / bank transfer / cheque only. Both endpoints that
-- wrote these columns are being deleted in the same task.
--
-- Telelink (tl_invoices) uses its OWN dibsy_* columns and is untouched.
--
-- public.customer_invoices is a passthrough view over public.invoices
-- (see 20260721140000_split_invoices_into_bills.sql) and selects
-- dibsy_payment_id / dibsy_checkout_url explicitly, so it must be
-- dropped and recreated without those columns before the ALTER TABLE
-- can succeed.

BEGIN;

DROP VIEW IF EXISTS public.customer_invoices;

ALTER TABLE public.invoices DROP COLUMN IF EXISTS dibsy_payment_id;
ALTER TABLE public.invoices DROP COLUMN IF EXISTS dibsy_checkout_url;

CREATE VIEW public.customer_invoices WITH (security_invoker='true') AS
 SELECT id, invoice_id, customer_id, source, source_id, source_label,
        issued_date, due_date, status, subtotal, tax, total_amount,
        paid_amount, agent_name, notes, qb_synced,
        created_at, updated_at,
        sale_order_id, sale_delivery_id,
        needs_refresh, doc_status, payment_status, invoice_type,
        discount_amount, discount_label, manually_paid,
        phone_id, division_id
   FROM public.invoices;

COMMIT;


-- ============================================================
-- Source: 20260723115000_rename_invoices_to_so_invoices.sql
-- ============================================================
-- Rename public.invoices → public.so_invoices for clear separation from
-- Telelink service invoices (tl_invoices). Sales-order invoices only.
--
-- Postgres binds VIEWS, FK CONSTRAINTS, RLS POLICIES, and TRIGGERS to the
-- table by OID, so the rename cascades automatically for those. FUNCTIONS
-- store their body as text and DON'T auto-update — this migration
-- explicitly rewrites every function whose body contains a whole-word
-- reference to `invoices` (skipping tl_invoices / customer_invoices /
-- so_invoices / any *_invoices identifier via the \m \M word boundaries).
--
-- customer_invoices was rebuilt in 20260723105000 as a text-defined view;
-- Postgres also auto-updates its parse tree on the rename, so no separate
-- rebuild here.

BEGIN;

-- 1. Rename the table itself.
ALTER TABLE public.invoices RENAME TO so_invoices;

-- 2. Rewrite every function/RPC whose body contains the whole word
--    "invoices" (not tl_invoices, customer_invoices, so_invoices, etc.).
--    Uses pg_get_functiondef to snapshot the current CREATE OR REPLACE
--    statement, regexp_replace to swap `\minvoices\M` for `so_invoices`,
--    and EXECUTE to redefine.
--
--    Word boundaries: \m matches start-of-word, \M matches end-of-word.
--    Underscore is a word character in Postgres regex, so `_invoices`
--    (customer_invoices, tl_invoices, so_invoices) is NOT matched by
--    `\minvoices\M` — safe.
DO $$
DECLARE
  r RECORD;
  new_def TEXT;
BEGIN
  FOR r IN
    SELECT p.oid, p.proname, pg_get_functiondef(p.oid) AS def
    FROM   pg_proc p
    JOIN   pg_namespace n ON n.oid = p.pronamespace
    WHERE  n.nspname = 'public'
      AND  p.prokind = 'f'
      AND  pg_get_functiondef(p.oid) ~ '\minvoices\M'
  LOOP
    new_def := regexp_replace(r.def, '\minvoices\M', 'so_invoices', 'g');
    IF new_def <> r.def THEN
      EXECUTE new_def;
      RAISE NOTICE 'Rewrote function: %', r.proname;
    END IF;
  END LOOP;
END $$;

-- 3. Sanity: no function should still reference the bare `\minvoices\M` word.
DO $$
DECLARE
  v_stragglers INT;
BEGIN
  SELECT COUNT(*) INTO v_stragglers
  FROM   pg_proc p
  JOIN   pg_namespace n ON n.oid = p.pronamespace
  WHERE  n.nspname = 'public'
    AND  p.prokind = 'f'
    AND  pg_get_functiondef(p.oid) ~ '\minvoices\M';

  IF v_stragglers > 0 THEN
    RAISE EXCEPTION 'Rename left % function(s) still referencing bare `invoices`', v_stragglers;
  END IF;
END $$;

COMMIT;


-- ============================================================
-- Source: 20260723120000_reset_so_invoice_manually_paid.sql
-- ============================================================
-- Task 3 (SO/Invoice Parity) — reset so_invoices.manually_paid so the
-- trigger owns payment_status. The manual "Mark as Paid" toggle (if
-- any) is removed in the accompanying code change; the column stays
-- for one-off future overrides but is no longer written from the UI
-- or from any live code path (the Dibsy webhook branches that used to
-- set it were deleted in Task 2).
--
-- Also clears cached invoice PDFs so any invoice whose displayed
-- status changes as a result of the reset re-renders correctly.

BEGIN;

UPDATE public.so_invoices SET manually_paid = false WHERE manually_paid = true;

UPDATE public.so_invoices SET pdf_url = NULL WHERE pdf_url IS NOT NULL;

DO $$
DECLARE r RECORD;
BEGIN
  FOR r IN SELECT id FROM public.so_invoices LOOP
    PERFORM public.recalculate_ar_invoice_payment_status(r.id);
  END LOOP;
END $$;

COMMIT;


-- ============================================================
-- Source: 20260723130000_enforce_one_invoice_per_so.sql
-- ============================================================
-- Task 4 (SO/Invoice Parity) — enforce 1 SO = 1 invoice at the DB
-- level. generate_invoice_from_so already refuses to create a second
-- one, but the DB should be the ultimate arbiter — a rogue INSERT via
-- any other path also has to fail.
--
-- Matches the AP-side UNIQUE(purchase_order_id) on bills.

BEGIN;

DO $$
DECLARE
  v_dups int;
BEGIN
  SELECT COUNT(*) INTO v_dups FROM (
    SELECT sale_order_id
    FROM   public.so_invoices
    WHERE  sale_order_id IS NOT NULL
    GROUP  BY sale_order_id
    HAVING COUNT(*) > 1
  ) x;
  IF v_dups > 0 THEN
    RAISE EXCEPTION 'Refusing to add UNIQUE(sale_order_id): % SO(s) have more than one invoice. Reconcile before applying.', v_dups;
  END IF;
END $$;

ALTER TABLE public.so_invoices
  ADD CONSTRAINT so_invoices_sale_order_id_unique UNIQUE (sale_order_id);

COMMIT;


-- ============================================================
-- Source: 20260723140000_so_invoice_monthly_numbering.sql
-- ============================================================
-- Task 5 (SO/Invoice Parity) — new numbering scheme:
--   • SO number:      SO-YYYY-MM-NNN — 3-digit counter resets each month.
--   • Invoice number: <SO number>-I — one per SO (Task 4 enforces UNIQUE).
--
-- Mirror of the PO/Bill monthly rework (20260722200000).
--
-- This migration:
--   1. Creates next_so_number() with an advisory lock keyed by year+month.
--   2. Patches create_sale_order to call next_so_number() instead of the
--      inline `SO-NNNNN` generation. Uses pg_get_functiondef +
--      regexp_replace to preserve the rest of the (large) function body.
--   3. Rewrites generate_invoice_from_so:
--       a) invoice_id becomes <so_number>-I (not INV-NNNNN)
--       b) fixes the residual currency bug in the paid-so-far sum
--          (matches Task 1's fix: SUM(amount), not SUM(COALESCE(amount_qar, amount)),
--          and filters direction='incoming').
--
-- Historical SOs and invoices keep their old numbers until Task 6.

BEGIN;

-- ── 1. next_so_number() ────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.next_so_number()
RETURNS TEXT
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_year   TEXT := TO_CHAR(CURRENT_DATE, 'YYYY');
  v_month  TEXT := TO_CHAR(CURRENT_DATE, 'MM');
  v_prefix TEXT := 'SO-' || v_year || '-' || v_month || '-';
  v_next   INT;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('so_number_' || v_year || v_month));

  SELECT COUNT(*) + 1 INTO v_next
  FROM   public.sale_orders
  WHERE  so_number LIKE v_prefix || '%';

  RETURN v_prefix || LPAD(v_next::TEXT, 3, '0');
END $$;

GRANT EXECUTE ON FUNCTION public.next_so_number() TO authenticated;

-- ── 2. Patch create_sale_order — swap its inline `SO-NNNNN` generation ─────
--
-- Uses pg_get_functiondef + regexp_replace to modify only the two lines
-- that generate the SO number, preserving the ~350-line body otherwise.
-- Verifies exactly one replacement site exists first — refuses to run if
-- the body has already been changed or the pattern isn't found.

DO $$
DECLARE
  v_def      TEXT;
  v_new_def  TEXT;
  v_pattern  TEXT := 'SELECT COUNT\(\*\) \+ 1 INTO v_count FROM sale_orders;\s*\n\s*v_so_number := ''SO-'' \|\| LPAD\(v_count::text, 5, ''0''\);';
  v_replace  TEXT := 'v_so_number := public.next_so_number();';
  v_hits     INT;
BEGIN
  SELECT pg_get_functiondef(oid) INTO v_def
  FROM   pg_proc
  WHERE  proname = 'create_sale_order'
    AND  pronamespace = 'public'::regnamespace;

  IF v_def IS NULL THEN
    RAISE EXCEPTION 'create_sale_order not found';
  END IF;

  SELECT COUNT(*) INTO v_hits
  FROM   regexp_matches(v_def, v_pattern, 'g');

  IF v_hits <> 1 THEN
    RAISE EXCEPTION 'Expected exactly 1 match of the SO-number inline pattern in create_sale_order body; found %', v_hits;
  END IF;

  v_new_def := regexp_replace(v_def, v_pattern, v_replace);
  EXECUTE v_new_def;
  RAISE NOTICE 'create_sale_order patched: now calls next_so_number()';
END $$;

-- ── 3. Rewrite generate_invoice_from_so ────────────────────────────────────
--
-- Changes vs current body:
--   • Removes the v_inv_count declaration + the two lines that compute
--     'INV-NNNNN'. invoice_id now := v_so.so_number || '-I'.
--   • paid-so-far sum: SUM(amount) filtered by direction='incoming' (was
--     SUM(COALESCE(amount_qar, amount)) — same currency bug we fixed on
--     the trigger in Task 1).
--   • Rest of the function body preserved verbatim.

CREATE OR REPLACE FUNCTION public.generate_invoice_from_so(p_so_id uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_so               RECORD;
  v_invoice_id_str   TEXT;
  v_invoice_type     TEXT;
  v_issued_date      DATE;
  v_due_date         DATE;
  v_new_inv_id       uuid;
  v_new_inv_str      TEXT;
  v_paid_amount      NUMERIC;
  v_payment_status   TEXT;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('invoices_serial'));

  IF EXISTS (
    SELECT 1 FROM so_invoices
    WHERE  sale_order_id = p_so_id
  ) THEN
    RAISE EXCEPTION 'invoice_exists';
  END IF;

  SELECT
    so.id, so.so_number, so.status, so.customer_id,
    so.division_id,
    so.subtotal,
    COALESCE(so.tax, 0)                 AS tax,
    so.total                            AS total_amount,
    COALESCE(c.customer_type, 'credit') AS customer_type
  INTO v_so
  FROM sale_orders so
  JOIN customers   c  ON c.id = so.customer_id
  WHERE so.id = p_so_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'so_not_found';
  END IF;

  IF v_so.status NOT IN ('confirmed', 'partial_delivery', 'delivered') THEN
    RAISE EXCEPTION 'so_not_invoiceable';
  END IF;

  SELECT COALESCE(SUM(amount), 0)
    INTO v_paid_amount
  FROM   public.payments
  WHERE  source_type = 'sale_order'
    AND  source_id   = p_so_id
    AND  direction   = 'incoming'
    AND  deleted_at IS NULL;

  v_payment_status := CASE
    WHEN v_paid_amount >= v_so.total_amount THEN 'paid'
    WHEN v_paid_amount > 0                  THEN 'partially_paid'
    ELSE                                          'unpaid'
  END;

  v_invoice_id_str := v_so.so_number || '-I';

  v_invoice_type := v_so.customer_type;
  v_issued_date  := CURRENT_DATE;
  v_due_date     := CASE v_invoice_type
    WHEN 'cash' THEN CURRENT_DATE
    ELSE             CURRENT_DATE + 30
  END;

  INSERT INTO so_invoices (
    invoice_id, customer_id, sale_order_id,
    division_id,
    invoice_type, doc_status, status, payment_status, needs_refresh,
    total_amount, subtotal, tax, paid_amount,
    issued_date, due_date,
    source, source_id, source_label
  ) VALUES (
    v_invoice_id_str, v_so.customer_id, p_so_id,
    v_so.division_id,
    v_invoice_type::public.invoice_type, 'draft', 'draft', v_payment_status::public.invoice_payment_status, false,
    v_so.total_amount, v_so.subtotal, v_so.tax, v_paid_amount,
    v_issued_date, v_due_date,
    'order', p_so_id::text, 'SO #' || v_so.so_number
  )
  RETURNING id, invoice_id INTO v_new_inv_id, v_new_inv_str;

  UPDATE public.payments
  SET    source_type = 'invoice',
         source_id   = v_new_inv_id
  WHERE  source_type = 'sale_order'
    AND  source_id   = p_so_id
    AND  deleted_at IS NULL;

  INSERT INTO invoice_line_items (invoice_id, description, qty, unit_price, total)
  SELECT v_new_inv_id, sol.item_name, sol.qty, sol.unit_price, sol.total
  FROM   sale_order_lines sol
  WHERE  sol.sale_order_id = p_so_id;

  RETURN jsonb_build_object(
    'id',           v_new_inv_id,
    'invoice_id',   v_new_inv_str,
    'invoice_type', v_invoice_type,
    'paid_amount',  v_paid_amount
  );
END;
$$;

COMMIT;


-- ============================================================
-- Source: 20260723150000_renumber_existing_sos_and_invoices.sql
-- ============================================================
-- Task 6 (SO/Invoice Parity) — renumber historical SOs to SO-YYYY-MM-NNN
-- and invoices to <SO>-I. Uses ROW_NUMBER() partitioned by year+month of
-- created_at, ordered by created_at + id for stable results.
--
-- Same rules as the PO renumber (20260722200000):
--   • Only touch rows in the old format (SO-NNNNN / INV-NNNNN).
--   • Invoices follow their SO.
--   • Clear cached PDFs (so_invoices, sale_deliveries, returns,
--     credit_notes) so future views regenerate with the new numbers.

BEGIN;

-- ── 1. Renumber SOs ────────────────────────────────────────────────────────

WITH ranked AS (
  SELECT
    id,
    'SO-' || TO_CHAR(created_at, 'YYYY-MM') || '-' ||
      LPAD(
        ROW_NUMBER() OVER (
          PARTITION BY DATE_TRUNC('month', created_at)
          ORDER BY created_at, id
        )::TEXT, 3, '0'
      ) AS new_so_number
  FROM public.sale_orders
  WHERE so_number ~ '^SO-[0-9]+$'  -- only old-format numbers
)
UPDATE public.sale_orders s
SET    so_number = r.new_so_number
FROM   ranked r
WHERE  s.id = r.id;

-- ── 2. Rewrite invoice numbers to <new SO number>-I ────────────────────────

UPDATE public.so_invoices i
SET    invoice_id = s.so_number || '-I'
FROM   public.sale_orders s
WHERE  i.sale_order_id = s.id
  AND  i.invoice_id ~ '^INV-[0-9]+$';  -- only touch old-format invoice numbers

-- ── 3. Clear cached PDFs so they regenerate with the new numbers ──────────

UPDATE public.so_invoices     SET pdf_url = NULL WHERE pdf_url IS NOT NULL;
UPDATE public.sale_deliveries SET pdf_url = NULL WHERE pdf_url IS NOT NULL;
UPDATE public.returns         SET pdf_url = NULL WHERE pdf_url IS NOT NULL;
UPDATE public.credit_notes    SET pdf_url = NULL WHERE pdf_url IS NOT NULL;

COMMIT;


-- ============================================================
-- Source: 20260723160000_drop_doc_status_rename_source_order_to_sale_order.sql
-- ============================================================
-- SO Invoices cleanup:
--   1. Drop so_invoices.doc_status column entirely (feature retired — invoices
--      are internal documents, not sent through the app).
--   2. Drop the invoice_doc_status enum type (no other table uses it).
--   3. Rename invoice_source enum value 'order' → 'sale_order' for clarity
--      (matches the sale_orders table + the sales.* permission namespace).
--
-- Downstream:
--   • public.customer_invoices view depends on doc_status + source — drop and
--     recreate without doc_status (source column carries the renamed value).
--   • generate_invoice_from_so writes doc_status='draft' and source='order' —
--     rewritten below to drop the doc_status insert and use 'sale_order'.
--   • rpc_customer_statement, rpc_financial_dashboard, rpc_sales_aging_report
--     filter on `doc_status != 'rejected'` — regex-stripped from each body
--     (the concept is gone, so the filter is trivially satisfied by every row).
--
-- Postgres binds the customer_invoices view + all RPC OIDs by identity so the
-- ALTER TYPE ... RENAME VALUE step doesn't require rewriting anything that
-- READS the enum — Postgres updates the label everywhere transparently. Only
-- literals in RPC bodies that WRITE 'order' need updating.

BEGIN;

-- 1. Rename the enum value first. This propagates to every existing row
--    (source='order' becomes source='sale_order' automatically). Cheap +
--    atomic in Postgres — no full-table rewrite.
ALTER TYPE public.invoice_source RENAME VALUE 'order' TO 'sale_order';

-- 2. Strip `doc_status != 'rejected'` filter from any RPC body that has it.
--    Matches both `AND doc_status != 'rejected'` (inline / trailing) and the
--    less-common `WHERE doc_status != 'rejected' AND` (leading). Also strips
--    the standalone `doc_status != 'rejected'` if it's the only condition.
DO $$
DECLARE
  r RECORD;
  new_def TEXT;
BEGIN
  FOR r IN
    SELECT p.oid, p.proname, pg_get_functiondef(p.oid) AS def
    FROM   pg_proc p
    JOIN   pg_namespace n ON n.oid = p.pronamespace
    WHERE  n.nspname = 'public'
      AND  p.prokind = 'f'
      AND  pg_get_functiondef(p.oid) ~ 'doc_status'
  LOOP
    new_def := r.def;
    -- Inline / trailing: ` AND doc_status != 'rejected'`
    new_def := regexp_replace(new_def, '\s+AND\s+doc_status\s*!=\s*''rejected''', '', 'g');
    -- Leading: `WHERE doc_status != 'rejected' AND ` → `WHERE `
    new_def := regexp_replace(new_def, 'WHERE\s+doc_status\s*!=\s*''rejected''\s+AND\s+', 'WHERE ', 'g');
    -- Standalone: `WHERE doc_status != 'rejected'` → drop the WHERE
    new_def := regexp_replace(new_def, 'WHERE\s+doc_status\s*!=\s*''rejected''', '', 'g');

    IF new_def <> r.def THEN
      EXECUTE new_def;
      RAISE NOTICE 'Stripped doc_status filter from: %', r.proname;
    END IF;
  END LOOP;
END $$;

-- 3. Rewrite generate_invoice_from_so:
--    a) stops writing doc_status='draft'
--    b) uses 'sale_order' instead of 'order' as the source value
--    Everything else preserved from the Task 5 version.
CREATE OR REPLACE FUNCTION public.generate_invoice_from_so(p_so_id uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_so               RECORD;
  v_invoice_id_str   TEXT;
  v_invoice_type     TEXT;
  v_issued_date      DATE;
  v_due_date         DATE;
  v_new_inv_id       uuid;
  v_new_inv_str      TEXT;
  v_paid_amount      NUMERIC;
  v_payment_status   TEXT;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('invoices_serial'));

  IF EXISTS (
    SELECT 1 FROM so_invoices
    WHERE  sale_order_id = p_so_id
  ) THEN
    RAISE EXCEPTION 'invoice_exists';
  END IF;

  SELECT
    so.id, so.so_number, so.status, so.customer_id,
    so.division_id,
    so.subtotal,
    COALESCE(so.tax, 0)                 AS tax,
    so.total                            AS total_amount,
    COALESCE(c.customer_type, 'credit') AS customer_type
  INTO v_so
  FROM sale_orders so
  JOIN customers   c  ON c.id = so.customer_id
  WHERE so.id = p_so_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'so_not_found';
  END IF;

  IF v_so.status NOT IN ('confirmed', 'partial_delivery', 'delivered') THEN
    RAISE EXCEPTION 'so_not_invoiceable';
  END IF;

  SELECT COALESCE(SUM(amount), 0)
    INTO v_paid_amount
  FROM   public.payments
  WHERE  source_type = 'sale_order'
    AND  source_id   = p_so_id
    AND  direction   = 'incoming'
    AND  deleted_at IS NULL;

  v_payment_status := CASE
    WHEN v_paid_amount >= v_so.total_amount THEN 'paid'
    WHEN v_paid_amount > 0                  THEN 'partially_paid'
    ELSE                                          'unpaid'
  END;

  v_invoice_id_str := v_so.so_number || '-I';

  v_invoice_type := v_so.customer_type;
  v_issued_date  := CURRENT_DATE;
  v_due_date     := CASE v_invoice_type
    WHEN 'cash' THEN CURRENT_DATE
    ELSE             CURRENT_DATE + 30
  END;

  INSERT INTO so_invoices (
    invoice_id, customer_id, sale_order_id,
    division_id,
    invoice_type, status, payment_status, needs_refresh,
    total_amount, subtotal, tax, paid_amount,
    issued_date, due_date,
    source, source_id, source_label
  ) VALUES (
    v_invoice_id_str, v_so.customer_id, p_so_id,
    v_so.division_id,
    v_invoice_type::public.invoice_type, 'draft', v_payment_status::public.invoice_payment_status, false,
    v_so.total_amount, v_so.subtotal, v_so.tax, v_paid_amount,
    v_issued_date, v_due_date,
    'sale_order', p_so_id::text, 'SO #' || v_so.so_number
  )
  RETURNING id, invoice_id INTO v_new_inv_id, v_new_inv_str;

  UPDATE public.payments
  SET    source_type = 'invoice',
         source_id   = v_new_inv_id
  WHERE  source_type = 'sale_order'
    AND  source_id   = p_so_id
    AND  deleted_at IS NULL;

  INSERT INTO invoice_line_items (invoice_id, description, qty, unit_price, total)
  SELECT v_new_inv_id, sol.item_name, sol.qty, sol.unit_price, sol.total
  FROM   sale_order_lines sol
  WHERE  sol.sale_order_id = p_so_id;

  RETURN jsonb_build_object(
    'id',           v_new_inv_id,
    'invoice_id',   v_new_inv_str,
    'invoice_type', v_invoice_type,
    'paid_amount',  v_paid_amount
  );
END;
$$;

-- 4. Rebuild customer_invoices without doc_status. The Task 2 rebuild selected
--    doc_status explicitly; drop + recreate the view to remove it.
DROP VIEW IF EXISTS public.customer_invoices;

CREATE VIEW public.customer_invoices WITH (security_invoker='true') AS
 SELECT id, invoice_id, customer_id, source, source_id, source_label,
        issued_date, due_date, status, subtotal, tax, total_amount,
        paid_amount, agent_name, notes, qb_synced,
        created_at, updated_at,
        sale_order_id, sale_delivery_id,
        needs_refresh, payment_status, invoice_type,
        discount_amount, discount_label, manually_paid,
        phone_id, division_id
   FROM public.so_invoices;

-- 5. Drop the column now that no view / RPC references it.
ALTER TABLE public.so_invoices DROP COLUMN IF EXISTS doc_status;

-- 6. Drop the enum type — safe because no other column uses it (verified via
--    information_schema.columns before writing this migration).
DROP TYPE IF EXISTS public.invoice_doc_status;

COMMIT;


-- ============================================================
-- Source: 20260723170000_migrate_tool_asset_items_to_inventory.sql
-- ============================================================
-- Phase 2 of the tools→inventory merge.
-- For every tool_asset_items row, ensure a matching inventory_items +
-- inventory_brand_variants exists, then repoint the purchase chain.
-- Idempotent: safe to run against an empty tool_asset_items (staging).

BEGIN;

-- 1. Ensure a "Tools & Assets" top-level category exists for the tools type.
INSERT INTO public.inventory_categories (name_en, type, sort_order)
SELECT 'Tools & Assets (Migrated)', 'tools', 999
WHERE NOT EXISTS (
  SELECT 1 FROM public.inventory_categories
  WHERE type = 'tools' AND parent_id IS NULL
);

-- 2. For each tool_asset_items row, create matching inventory_items +
--    a single inventory_brand_variants (SKU derived from tool id).
--    Track mapping in a temp table so we can update purchase chain FKs.

CREATE TEMP TABLE _tool_variant_map (
  tool_asset_item_id uuid PRIMARY KEY,
  brand_variant_id   uuid NOT NULL
);

WITH root_cat AS (
  SELECT id AS cat_id
  FROM public.inventory_categories
  WHERE type = 'tools' AND parent_id IS NULL
  ORDER BY sort_order, name_en
  LIMIT 1
),
new_items AS (
  INSERT INTO public.inventory_items (category_id, name_en, name_ar)
  SELECT
    COALESCE(tai.category_id, (SELECT cat_id FROM root_cat)),
    tai.name_en,
    tai.name_ar
  FROM public.tool_asset_items tai
  WHERE NOT EXISTS (
    -- avoid re-inserting if we already migrated this row (idempotency)
    SELECT 1 FROM public.inventory_items ii
    WHERE ii.name_en = tai.name_en
      AND ii.category_id = COALESCE(tai.category_id, (SELECT cat_id FROM root_cat))
  )
  RETURNING id, name_en, category_id
),
new_variants AS (
  INSERT INTO public.inventory_brand_variants (item_id, brand, code, cost_price, selling_price)
  SELECT ni.id, 'Migrated', 'TOOL-' || SUBSTRING(ni.id::text, 1, 8), 0, 0
  FROM new_items ni
  RETURNING id, item_id
)
INSERT INTO _tool_variant_map (tool_asset_item_id, brand_variant_id)
SELECT
  tai.id,
  nv.id
FROM public.tool_asset_items tai
JOIN public.inventory_items ii
  ON ii.name_en = tai.name_en
 AND ii.category_id = COALESCE(tai.category_id, (SELECT cat_id FROM root_cat))
JOIN public.inventory_brand_variants nv ON nv.item_id = ii.id;

-- 3. Repoint the purchase chain — six tables.
UPDATE public.po_line_items       SET brand_variant_id = m.brand_variant_id, tool_asset_item_id = NULL
FROM _tool_variant_map m WHERE public.po_line_items.tool_asset_item_id       = m.tool_asset_item_id;

UPDATE public.po_version_lines    SET brand_variant_id = m.brand_variant_id, tool_asset_item_id = NULL
FROM _tool_variant_map m WHERE public.po_version_lines.tool_asset_item_id    = m.tool_asset_item_id;

UPDATE public.receival_items      SET brand_variant_id = m.brand_variant_id, tool_asset_item_id = NULL
FROM _tool_variant_map m WHERE public.receival_items.tool_asset_item_id      = m.tool_asset_item_id;

UPDATE public.return_lines        SET brand_variant_id = m.brand_variant_id, tool_asset_item_id = NULL
FROM _tool_variant_map m WHERE public.return_lines.tool_asset_item_id        = m.tool_asset_item_id;

UPDATE public.sale_order_lines    SET brand_variant_id = m.brand_variant_id, tool_asset_item_id = NULL
FROM _tool_variant_map m WHERE public.sale_order_lines.tool_asset_item_id    = m.tool_asset_item_id;

UPDATE public.sale_delivery_lines SET brand_variant_id = m.brand_variant_id, tool_asset_item_id = NULL
FROM _tool_variant_map m WHERE public.sale_delivery_lines.tool_asset_item_id = m.tool_asset_item_id;

-- 4. Sanity: after this migration, no tool_asset_item_id anywhere should
--    reference a tool_asset_items row (they've all been repointed).
DO $$
DECLARE
  v_remaining int;
BEGIN
  SELECT COUNT(*) INTO v_remaining FROM (
    SELECT 1 FROM public.po_line_items       WHERE tool_asset_item_id IS NOT NULL UNION ALL
    SELECT 1 FROM public.po_version_lines    WHERE tool_asset_item_id IS NOT NULL UNION ALL
    SELECT 1 FROM public.receival_items      WHERE tool_asset_item_id IS NOT NULL UNION ALL
    SELECT 1 FROM public.return_lines        WHERE tool_asset_item_id IS NOT NULL UNION ALL
    SELECT 1 FROM public.sale_order_lines    WHERE tool_asset_item_id IS NOT NULL UNION ALL
    SELECT 1 FROM public.sale_delivery_lines WHERE tool_asset_item_id IS NOT NULL
  ) x;
  IF v_remaining > 0 THEN
    RAISE EXCEPTION 'Migration incomplete: % rows still have tool_asset_item_id set', v_remaining;
  END IF;
END $$;

DROP TABLE _tool_variant_map;

COMMIT;


-- ============================================================
-- Source: 20260723190000_fix_aliased_doc_status_strip.sql
-- ============================================================
-- Follow-up to 20260723160000_drop_doc_status_rename_source_order_to_sale_order.
--
-- That migration stripped `AND doc_status != 'rejected'` from function bodies
-- but its regex did not account for the aliased form `AND <alias>.doc_status
-- != 'rejected'`. rpc_financial_dashboard, rpc_customer_statement, and
-- rpc_sales_aging_report use `AND i.doc_status != 'rejected'` in a few clauses,
-- so those references survived, and once so_invoices.doc_status was dropped
-- the RPCs began failing with `column i.doc_status does not exist` (400).
--
-- Fix: re-run the same strip loop with a regex that permits an optional
-- `<alias>.` prefix (identifier + dot) before `doc_status`.

BEGIN;

DO $$
DECLARE
  r RECORD;
  new_def TEXT;
BEGIN
  FOR r IN
    SELECT p.oid, p.proname, pg_get_functiondef(p.oid) AS def
    FROM   pg_proc p
    JOIN   pg_namespace n ON n.oid = p.pronamespace
    WHERE  n.nspname = 'public'
      AND  p.prokind = 'f'
      AND  pg_get_functiondef(p.oid) ~ 'doc_status'
  LOOP
    new_def := r.def;
    -- Inline / trailing: ` AND [alias.]doc_status != 'rejected'`
    new_def := regexp_replace(new_def,
      '\s+AND\s+([A-Za-z_][A-Za-z0-9_]*\.)?doc_status\s*!=\s*''rejected''', '', 'g');
    -- Leading: `WHERE [alias.]doc_status != 'rejected' AND ` → `WHERE `
    new_def := regexp_replace(new_def,
      'WHERE\s+([A-Za-z_][A-Za-z0-9_]*\.)?doc_status\s*!=\s*''rejected''\s+AND\s+', 'WHERE ', 'g');
    -- Standalone: `WHERE [alias.]doc_status != 'rejected'`
    new_def := regexp_replace(new_def,
      'WHERE\s+([A-Za-z_][A-Za-z0-9_]*\.)?doc_status\s*!=\s*''rejected''', '', 'g');

    IF new_def <> r.def THEN
      EXECUTE new_def;
      RAISE NOTICE 'Stripped aliased doc_status filter from: %', r.proname;
    END IF;
  END LOOP;
END $$;

-- Sanity: no function should still reference doc_status now.
DO $$
DECLARE
  v_stragglers INT;
  v_names TEXT;
BEGIN
  SELECT COUNT(*), string_agg(p.proname, ', ')
    INTO v_stragglers, v_names
  FROM   pg_proc p
  JOIN   pg_namespace n ON n.oid = p.pronamespace
  WHERE  n.nspname = 'public'
    AND  p.prokind = 'f'
    AND  pg_get_functiondef(p.oid) ~ '\mdoc_status\M';
  IF v_stragglers > 0 THEN
    RAISE EXCEPTION 'Still % function(s) reference doc_status: %', v_stragglers, v_names;
  END IF;
END $$;

COMMIT;


-- ============================================================
-- Source: 20260723200000_restore_tool_asset_items_and_units.sql
-- ============================================================
-- Roll back 20260723180000_drop_tool_asset_items_and_columns.sql.
--
-- Reason: the drop broke the master-data Tools & Assets UI + Team tool
-- assignment feature, which still use useToolAssetItems / useToolAssetUnits
-- hooks. Migrating those features to inventory_items / inventory_brand_variants
-- is out of scope for the current tools→inventory merge plan.
--
-- Restores:
--   • tool_asset_items table (empty — staging had zero rows)
--   • tool_asset_units table (empty — never restored after 2026-07-13 drop)
--   • six tool_asset_item_id columns on the purchase chain + their FKs
--
-- Idempotent — every step uses IF NOT EXISTS / duplicate_object guards.

BEGIN;

-- 1. Recreate tool_asset_items (same shape as 20260722160000_restore).
CREATE TABLE IF NOT EXISTS public.tool_asset_items (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  category_id uuid,
  name_en     text NOT NULL,
  name_ar     text,
  created_at  timestamptz DEFAULT now()
);

ALTER TABLE public.tool_asset_items ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
  CREATE POLICY "Authenticated users can manage tool_asset_items"
    ON public.tool_asset_items TO authenticated USING (true) WITH CHECK (true);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- 2. Recreate tool_asset_units (used by team↔tool assignments).
CREATE TABLE IF NOT EXISTS public.tool_asset_units (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  item_id       uuid REFERENCES public.tool_asset_items(id) ON DELETE CASCADE,
  serial_number text,
  brand         text,
  condition     text DEFAULT 'Good',
  status        text DEFAULT 'available',
  expiry        date,
  assigned_to   uuid,
  created_at    timestamptz DEFAULT now()
);

ALTER TABLE public.tool_asset_units ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
  CREATE POLICY "Authenticated users can manage tool_asset_units"
    ON public.tool_asset_units TO authenticated USING (true) WITH CHECK (true);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- 3. Re-add the six tool_asset_item_id columns to the purchase chain.
ALTER TABLE public.po_line_items       ADD COLUMN IF NOT EXISTS tool_asset_item_id uuid;
ALTER TABLE public.po_version_lines    ADD COLUMN IF NOT EXISTS tool_asset_item_id uuid;
ALTER TABLE public.receival_items      ADD COLUMN IF NOT EXISTS tool_asset_item_id uuid;
ALTER TABLE public.return_lines        ADD COLUMN IF NOT EXISTS tool_asset_item_id uuid;
ALTER TABLE public.sale_order_lines    ADD COLUMN IF NOT EXISTS tool_asset_item_id uuid;
ALTER TABLE public.sale_delivery_lines ADD COLUMN IF NOT EXISTS tool_asset_item_id uuid;

-- 4. Re-add the FKs (guarded — duplicate_object if a prior migration already
--    re-created them on this DB).
DO $$ BEGIN
  ALTER TABLE public.po_line_items
    ADD CONSTRAINT po_line_items_tool_asset_item_id_fkey
      FOREIGN KEY (tool_asset_item_id) REFERENCES public.tool_asset_items(id);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE public.po_version_lines
    ADD CONSTRAINT po_version_lines_tool_asset_item_id_fkey
      FOREIGN KEY (tool_asset_item_id) REFERENCES public.tool_asset_items(id);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE public.receival_items
    ADD CONSTRAINT receival_items_tool_asset_item_id_fkey
      FOREIGN KEY (tool_asset_item_id) REFERENCES public.tool_asset_items(id);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE public.return_lines
    ADD CONSTRAINT return_lines_tool_asset_item_id_fkey
      FOREIGN KEY (tool_asset_item_id) REFERENCES public.tool_asset_items(id);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE public.sale_order_lines
    ADD CONSTRAINT sale_order_lines_tool_asset_item_id_fkey
      FOREIGN KEY (tool_asset_item_id) REFERENCES public.tool_asset_items(id);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE public.sale_delivery_lines
    ADD CONSTRAINT sale_delivery_lines_tool_asset_item_id_fkey
      FOREIGN KEY (tool_asset_item_id) REFERENCES public.tool_asset_items(id);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

COMMIT;


