-- ============================================================
-- Source: 20260723220000_remap_tool_asset_units_to_inventory.sql
-- ============================================================
-- Remap tool_asset_units.item_id from tool_asset_items(id) to inventory_items(id).
--
-- After 20260723210000_seed_tool_asset_items.sql, 1298 units point at
-- tool_asset_items rows that mirror inventory_items 1:1 but have different
-- IDs. The master-data Tools UI now reads items from inventory_items, so
-- the units UI (which queries tool_asset_units by item_id) shows empty.
--
-- Mapping strategy: for each tool_asset_item, find the inventory_item(s)
-- in the same category whose name_en starts with the tool_asset_item's
-- name_en (inventory names carry a " — <variant>" suffix). When multiple
-- tool_asset_items share a base name in a category (e.g. two "OIL FILLED
-- PRESSURE GAUGE BOTTOM MOUNTING" rows → HP + LP variants), pair them by
-- ROW_NUMBER() ordered by id on both sides. Not semantically perfect for
-- HP-vs-LP within a duplicate group but preserves total unit count and
-- puts units under an inventory item of the right family.

BEGIN;

-- 1. Drop the current FK so we can point item_id at inventory_items(id).
ALTER TABLE public.tool_asset_units
  DROP CONSTRAINT IF EXISTS tool_asset_units_item_id_fkey;

-- 2. Build the mapping and remap.
WITH numbered_tai AS (
  SELECT
    id,
    category_id,
    name_en,
    ROW_NUMBER() OVER (PARTITION BY category_id, name_en ORDER BY id) AS rn
  FROM public.tool_asset_items
),
numbered_inv AS (
  SELECT
    ii.id            AS inv_id,
    ii.category_id,
    -- Strip the " — <variant>" suffix (em dash U+2014) to get the base name
    -- that matches the tool_asset_items row.
    SPLIT_PART(ii.name_en, ' — ', 1) AS base_name,
    ROW_NUMBER() OVER (
      PARTITION BY ii.category_id, SPLIT_PART(ii.name_en, ' — ', 1)
      ORDER BY ii.id
    ) AS rn
  FROM public.inventory_items ii
  JOIN public.inventory_categories ic ON ic.id = ii.category_id
  WHERE ic.type = 'tools'
),
mapping AS (
  SELECT n.id AS tai_id, i.inv_id
  FROM numbered_tai n
  JOIN numbered_inv i
    ON i.category_id = n.category_id
   AND i.base_name   = n.name_en
   AND i.rn          = n.rn
)
UPDATE public.tool_asset_units u
SET item_id = m.inv_id
FROM mapping m
WHERE u.item_id = m.tai_id;

-- 3. Any tool_asset_units whose item_id doesn't now resolve to a row in
--    inventory_items (i.e. an unmapped tool_asset_item, or an id that
--    was never valid) must be NULLed before we can add the new FK.
--    Report the count so it's visible in the push output.
DO $$
DECLARE
  v_unmapped INT;
BEGIN
  SELECT COUNT(*) INTO v_unmapped
  FROM public.tool_asset_units u
  WHERE u.item_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.inventory_items ii WHERE ii.id = u.item_id);

  IF v_unmapped > 0 THEN
    RAISE NOTICE 'NULLing % tool_asset_units.item_id values that don''t resolve to inventory_items', v_unmapped;
    UPDATE public.tool_asset_units u
    SET item_id = NULL
    WHERE u.item_id IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM public.inventory_items ii WHERE ii.id = u.item_id);
  ELSE
    RAISE NOTICE 'All tool_asset_units successfully remapped to inventory_items';
  END IF;
END $$;

-- 4. Add the new FK targeting inventory_items. ON DELETE SET NULL so
--    deleting an inventory item doesn't cascade-nuke unit tracking.
ALTER TABLE public.tool_asset_units
  ADD CONSTRAINT tool_asset_units_item_id_fkey
    FOREIGN KEY (item_id) REFERENCES public.inventory_items(id) ON DELETE SET NULL;

COMMIT;


-- ============================================================
-- Source: 20260723230000_create_tool_item_with_default_variant_rpc.sql
-- ============================================================
-- RPC to atomically create a tool inventory_item plus a default
-- inventory_brand_variants row so the item is immediately pickable in
-- the cascade selector (PO/SO line-item picker relies on brand_variant_id).
--
-- Used by ToolAssetItemEditDialog on the Master Data → Tools & Assets tab.

BEGIN;

CREATE OR REPLACE FUNCTION public.create_tool_item_with_default_variant(
  p_name_en     text,
  p_name_ar     text,
  p_category_id uuid
) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_item_id uuid;
BEGIN
  IF p_name_en IS NULL OR btrim(p_name_en) = '' THEN
    RAISE EXCEPTION 'name_en is required';
  END IF;

  INSERT INTO public.inventory_items (name_en, name_ar, category_id)
  VALUES (btrim(p_name_en), NULLIF(btrim(p_name_ar), ''), p_category_id)
  RETURNING id INTO v_item_id;

  INSERT INTO public.inventory_brand_variants (item_id, brand, cost_price, selling_price)
  VALUES (v_item_id, 'Default', 0, 0);

  RETURN v_item_id;
END $$;

GRANT EXECUTE ON FUNCTION public.create_tool_item_with_default_variant(text, text, uuid) TO authenticated;

COMMIT;


-- ============================================================
-- Source: 20260723240000_fix_create_tool_item_rpc_sku.sql
-- ============================================================
-- Fix create_tool_item_with_default_variant: inventory_items.sku is NOT NULL,
-- but the initial RPC didn't set it. Auto-generate a short unique sku from
-- the row's UUID so the caller doesn't need to pass one.

BEGIN;

CREATE OR REPLACE FUNCTION public.create_tool_item_with_default_variant(
  p_name_en     text,
  p_name_ar     text,
  p_category_id uuid
) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_item_id uuid;
  v_sku     text;
BEGIN
  IF p_name_en IS NULL OR btrim(p_name_en) = '' THEN
    RAISE EXCEPTION 'name_en is required';
  END IF;

  v_item_id := gen_random_uuid();
  v_sku     := 'TOOL-' || SUBSTRING(v_item_id::text, 1, 8);

  INSERT INTO public.inventory_items (id, name_en, name_ar, category_id, sku)
  VALUES (v_item_id, btrim(p_name_en), NULLIF(btrim(p_name_ar), ''), p_category_id, v_sku);

  INSERT INTO public.inventory_brand_variants (item_id, brand, cost_price, selling_price)
  VALUES (v_item_id, 'Default', 0, 0);

  RETURN v_item_id;
END $$;

COMMIT;


-- ============================================================
-- Source: 20260723250000_fix_create_tool_item_rpc_unit.sql
-- ============================================================
-- Add unit + cost_price defaults to create_tool_item_with_default_variant.
-- inventory_items.unit is NOT NULL. cost_price may also be NOT NULL depending
-- on schema; setting a safe 0 avoids another round trip if so.

BEGIN;

CREATE OR REPLACE FUNCTION public.create_tool_item_with_default_variant(
  p_name_en     text,
  p_name_ar     text,
  p_category_id uuid
) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_item_id uuid;
  v_sku     text;
BEGIN
  IF p_name_en IS NULL OR btrim(p_name_en) = '' THEN
    RAISE EXCEPTION 'name_en is required';
  END IF;

  v_item_id := gen_random_uuid();
  v_sku     := 'TOOL-' || SUBSTRING(v_item_id::text, 1, 8);

  INSERT INTO public.inventory_items (id, name_en, name_ar, category_id, sku, unit, cost_price)
  VALUES (v_item_id, btrim(p_name_en), NULLIF(btrim(p_name_ar), ''), p_category_id, v_sku, 'pcs', 0);

  INSERT INTO public.inventory_brand_variants (item_id, brand, cost_price, selling_price)
  VALUES (v_item_id, 'Default', 0, 0);

  RETURN v_item_id;
END $$;

COMMIT;


-- ============================================================
-- Source: 20260723260000_renumber_tool_skus_and_serials.sql
-- ============================================================
-- Renumber tool SKUs + unit serials into a human-readable scheme.
--
-- Old:  inventory_items.sku = "VAC1STAG-1032" (cryptic)
--       tool_asset_units.serial_number = "TOOL-0001-001" (opaque global ordinal)
-- New:  inventory_items.sku = "VP-001"  (category-prefix + tool-ordinal)
--       tool_asset_units.serial_number = "VP-001-001" (item sku + unit-ordinal)
--
-- Also cleans obvious duplicated " — <suffix>" tails on name_en where the
-- suffix duplicates the base (e.g. "AC CLEANING COVER BAG TYPE Q-537 —
-- BAG TYPE Q-537").
--
-- Scope: inventory_items where category.type = 'tools' AND every
-- tool_asset_units row (all currently point at inventory_items rows).
-- Products / spare parts / consumables untouched.

BEGIN;

-- 1. Category → prefix mapping (stable across reruns of this migration).
CREATE TEMP TABLE _tool_cat_prefix (
  category_id uuid PRIMARY KEY,
  prefix      text NOT NULL
);

INSERT INTO _tool_cat_prefix (category_id, prefix)
SELECT id, CASE name_en
  WHEN 'AC Cleaning Covers'      THEN 'ACC'
  WHEN 'Adaptor / Quick Coupler' THEN 'AD'
  WHEN 'Clamp Meter'             THEN 'CM'
  WHEN 'Cleaning Machines'       THEN 'CLM'
  WHEN 'Flaring Tool'            THEN 'FT'
  WHEN 'Gauge'                   THEN 'GA'
  WHEN 'General'                 THEN 'GN'
  WHEN 'Hygrometer'              THEN 'HY'
  WHEN 'Manifold Gauge'          THEN 'MG'
  WHEN 'Multimeter'              THEN 'MM'
  WHEN 'Power Tools'             THEN 'PT'
  WHEN 'Pressure Washers'        THEN 'PW'
  WHEN 'Test for new Mitigation' THEN 'TST'
  WHEN 'Testing & Measurement'   THEN 'TM'
  WHEN 'Thermometer'             THEN 'TH'
  WHEN 'Tools & Equipment'       THEN 'TE'
  WHEN 'Tube Bender'             THEN 'TB'
  WHEN 'Tube Cutter'             THEN 'TC'
  WHEN 'Vacuum Pump'             THEN 'VP'
  ELSE 'TL' || SUBSTRING(id::text, 1, 4)  -- fallback for any new category
END
FROM public.inventory_categories
WHERE type = 'tools';

-- 2. Clean obvious duplicated " — <suffix>" tails.
--    Case A: suffix exactly equals base → strip entire tail
--    Case B: suffix is a substring of base (case-insensitive) → strip entire tail
UPDATE public.inventory_items ii
SET name_en = btrim(base)
FROM (
  SELECT ii2.id,
         split_part(ii2.name_en, ' — ', 1) AS base,
         NULLIF(split_part(ii2.name_en, ' — ', 2), '') AS suffix
  FROM public.inventory_items ii2
  JOIN public.inventory_categories ic ON ic.id = ii2.category_id
  WHERE ic.type = 'tools'
    AND ii2.name_en LIKE '% — %'
) x
WHERE ii.id = x.id
  AND x.suffix IS NOT NULL
  AND (
       btrim(lower(x.suffix)) = btrim(lower(x.base))
    OR btrim(lower(x.base)) ILIKE '%' || btrim(lower(x.suffix)) || '%'
  );

-- 3. Renumber inventory_items.sku for tools.
--    Ordering: created_at ASC, id ASC (stable across reruns).
WITH numbered AS (
  SELECT ii.id,
         cp.prefix,
         ROW_NUMBER() OVER (PARTITION BY ii.category_id ORDER BY ii.created_at, ii.id) AS rn
  FROM public.inventory_items ii
  JOIN _tool_cat_prefix cp ON cp.category_id = ii.category_id
)
UPDATE public.inventory_items ii
SET sku = n.prefix || '-' || LPAD(n.rn::text, 3, '0')
FROM numbered n
WHERE ii.id = n.id;

-- 4. Renumber tool_asset_units.serial_number.
--    Format: <item.sku>-<unit-ordinal-3d>
--    Ordering within an item: created_at ASC, id ASC.
WITH numbered_units AS (
  SELECT u.id,
         ii.sku AS item_sku,
         ROW_NUMBER() OVER (PARTITION BY u.item_id ORDER BY u.created_at, u.id) AS un
  FROM public.tool_asset_units u
  JOIN public.inventory_items ii ON ii.id = u.item_id
)
UPDATE public.tool_asset_units u
SET serial_number = n.item_sku || '-' || LPAD(n.un::text, 3, '0')
FROM numbered_units n
WHERE u.id = n.id;

-- 5. Sanity checks.
DO $$
DECLARE
  v_dup_sku    INT;
  v_dup_serial INT;
BEGIN
  SELECT COUNT(*) INTO v_dup_sku FROM (
    SELECT sku FROM public.inventory_items
    WHERE sku IS NOT NULL
    GROUP BY sku HAVING COUNT(*) > 1
  ) d;
  SELECT COUNT(*) INTO v_dup_serial FROM (
    SELECT serial_number FROM public.tool_asset_units
    WHERE serial_number IS NOT NULL
    GROUP BY serial_number HAVING COUNT(*) > 1
  ) d;

  IF v_dup_sku    > 0 THEN RAISE EXCEPTION 'duplicate sku after renumber: % groups', v_dup_sku;    END IF;
  IF v_dup_serial > 0 THEN RAISE EXCEPTION 'duplicate serial after renumber: % groups', v_dup_serial; END IF;

  RAISE NOTICE 'Renumber complete: SKUs + serials all unique.';
END $$;

DROP TABLE _tool_cat_prefix;

COMMIT;


-- ============================================================
-- Source: 20260723270000_remap_activity_log_tool_asset_entity_ids.sql
-- ============================================================
-- Remap activity_log rows with entity_type='tool_asset' from
-- tool_asset_items(id) to the corresponding inventory_items(id) and
-- retag entity_type='inventory_item' so the frontend audit resolver
-- can look them up after tool_asset_items is dropped.
--
-- Same (category_id, base_name, row_number) pairing as the
-- tool_asset_units remap on 2026-07-23.

BEGIN;

WITH numbered_tai AS (
  SELECT id, category_id, name_en,
         ROW_NUMBER() OVER (PARTITION BY category_id, name_en ORDER BY id) AS rn
  FROM public.tool_asset_items
),
numbered_inv AS (
  SELECT ii.id AS inv_id, ii.category_id,
         SPLIT_PART(ii.name_en, ' — ', 1) AS base_name,
         ROW_NUMBER() OVER (
           PARTITION BY ii.category_id, SPLIT_PART(ii.name_en, ' — ', 1)
           ORDER BY ii.id
         ) AS rn
  FROM public.inventory_items ii
  JOIN public.inventory_categories ic ON ic.id = ii.category_id
  WHERE ic.type = 'tools'
),
mapping AS (
  SELECT n.id::text AS tai_id, i.inv_id::text AS inv_id
  FROM numbered_tai n
  JOIN numbered_inv i
    ON i.category_id = n.category_id
   AND i.base_name   = n.name_en
   AND i.rn          = n.rn
)
UPDATE public.activity_log a
SET    entity_id   = m.inv_id::uuid,
       entity_type = 'inventory_item'
FROM   mapping m
WHERE  a.entity_type = 'tool_asset'
  AND  a.entity_id::text = m.tai_id;

DO $$
DECLARE v_orphans INT;
BEGIN
  SELECT COUNT(*) INTO v_orphans FROM public.activity_log
    WHERE entity_type = 'tool_asset';
  IF v_orphans > 0 THEN
    RAISE NOTICE '% activity_log rows still tagged entity_type=tool_asset (unmapped); leaving in place', v_orphans;
  ELSE
    RAISE NOTICE 'activity_log tool_asset remap complete';
  END IF;
END $$;

COMMIT;


-- ============================================================
-- Source: 20260723280000_drop_dead_tables_and_columns.sql
-- ============================================================
-- Drop dead schema — no rows, no readers, no writers.
--
-- Identified via the column-usage audit on 2026-07-22:
--   • 4 entirely-dead tables (0 rows, 0 code refs across src/ + edge fns)
--   • 8 dead columns on otherwise-live tables
--
-- If any of these features come back, the schema gets designed with the
-- code that actually needs it — no orphan tables/columns lying around.

BEGIN;

-- ── Entirely dead tables ────────────────────────────────────────────────────
DROP TABLE IF EXISTS public.payment_sessions       CASCADE;
DROP TABLE IF EXISTS public.notification_trail     CASCADE;
DROP TABLE IF EXISTS public.webhook_logs           CASCADE;
DROP TABLE IF EXISTS public.warehouse_manager_log  CASCADE;

-- ── Dead columns on live tables ─────────────────────────────────────────────
ALTER TABLE public.customers                DROP COLUMN IF EXISTS pending_balance;
ALTER TABLE public.customers                DROP COLUMN IF EXISTS subscription_tag;
ALTER TABLE public.inventory_brand_variants DROP COLUMN IF EXISTS incoming_eta;
ALTER TABLE public.notification_templates   DROP COLUMN IF EXISTS button_type;
ALTER TABLE public.notification_templates   DROP COLUMN IF EXISTS button_url_suffix_param;
ALTER TABLE public.notification_templates   DROP COLUMN IF EXISTS has_buttons;
ALTER TABLE public.notification_templates   DROP COLUMN IF EXISTS param_count;
ALTER TABLE public.notification_templates   DROP COLUMN IF EXISTS param_names;

COMMIT;


-- ============================================================
-- Source: 20260723290000_drop_tool_asset_items_and_columns.sql
-- ============================================================
-- Final drop of tool_asset_items + its six purchase-chain FK columns.
--
-- The 2026-07-23 first attempt at this drop was rolled back because 4
-- master-data hooks + the Teams tool sheet + the audit-log resolver
-- still touched tool_asset_items. Follow-up tasks 1–4 rewired all of
-- those to inventory_items and today's commits removed the last dead
-- hooks. Now safe.
--
-- Data status on staging:
--   • tool_asset_items — 139 rows (mirrored to inventory_items on
--     2026-07-13); nothing joins to them anymore.
--   • Six tool_asset_item_id columns — all NULL after the 2026-07-23
--     Task-4 data migration.
--
-- tool_asset_units + related enums stay — that layer is preserved.

BEGIN;

-- Refuse to drop if any purchase-chain row still has a tool_asset_item_id.
DO $$
DECLARE v_remaining INT;
BEGIN
  SELECT COUNT(*) INTO v_remaining FROM (
    SELECT 1 FROM public.po_line_items       WHERE tool_asset_item_id IS NOT NULL UNION ALL
    SELECT 1 FROM public.po_version_lines    WHERE tool_asset_item_id IS NOT NULL UNION ALL
    SELECT 1 FROM public.receival_items      WHERE tool_asset_item_id IS NOT NULL UNION ALL
    SELECT 1 FROM public.return_lines        WHERE tool_asset_item_id IS NOT NULL UNION ALL
    SELECT 1 FROM public.sale_order_lines    WHERE tool_asset_item_id IS NOT NULL UNION ALL
    SELECT 1 FROM public.sale_delivery_lines WHERE tool_asset_item_id IS NOT NULL
  ) x;
  IF v_remaining > 0 THEN
    RAISE EXCEPTION 'Refusing to drop: % rows still have tool_asset_item_id set', v_remaining;
  END IF;
END $$;

ALTER TABLE public.po_line_items       DROP COLUMN IF EXISTS tool_asset_item_id;
ALTER TABLE public.po_version_lines    DROP COLUMN IF EXISTS tool_asset_item_id;
ALTER TABLE public.receival_items      DROP COLUMN IF EXISTS tool_asset_item_id;
ALTER TABLE public.return_lines        DROP COLUMN IF EXISTS tool_asset_item_id;
ALTER TABLE public.sale_order_lines    DROP COLUMN IF EXISTS tool_asset_item_id;
ALTER TABLE public.sale_delivery_lines DROP COLUMN IF EXISTS tool_asset_item_id;

DROP TABLE IF EXISTS public.tool_asset_items CASCADE;

COMMIT;


-- ============================================================
-- Source: 20260723300000_restore_teams_module_tables.sql
-- ============================================================
-- Restore the Teams-module tables that were dropped without a DROP
-- migration on record (probably lost during a manual db reset). Original
-- shapes taken verbatim from baseline_schema.sql — the app code assumed
-- these still existed, so the Teams UI has been failing at runtime and
-- TypeScript is producing hundreds of errors for stale field references.
--
-- Tables restored: employees, teams, schedules, team_activity_log,
-- team_schedule_assignments, tool_assignments, vehicles.
-- Enums restored: employee_status, team_tag.
--
-- All statements guarded so the migration is idempotent.

BEGIN;

-- 1. Enums ─────────────────────────────────────────────────────────────
DO $$ BEGIN
  CREATE TYPE public.employee_status AS ENUM ('active','vacation','archived','unassigned','on-task');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE TYPE public.team_tag AS ENUM ('normal','emergency','qc','site-visit');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- 2. schedules ─────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.schedules (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name        text NOT NULL,
  days        jsonb NOT NULL,
  created_at  timestamptz DEFAULT now(),
  updated_at  timestamptz DEFAULT now(),
  deleted_at  timestamptz
);

-- 3. teams ─────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.teams (
  id                     uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name                   text NOT NULL,
  tag                    public.team_tag DEFAULT 'normal',
  vehicle_id             uuid,
  schedule_id            uuid,
  schedule_start         integer DEFAULT 7,
  schedule_end           integer DEFAULT 17,
  leader_id              uuid,
  created_at             timestamptz DEFAULT now(),
  updated_at             timestamptz DEFAULT now(),
  is_emergency           boolean DEFAULT false NOT NULL,
  is_qc                  boolean DEFAULT false NOT NULL,
  traccar_device_id      text,
  deleted_at             timestamptz,
  name_en                text DEFAULT '' NOT NULL,
  name_ar                text,
  phone                  text,
  site_visit_order       boolean DEFAULT false NOT NULL,
  site_visit_quotation   boolean DEFAULT false NOT NULL,
  division_id            uuid,
  is_normal              boolean DEFAULT false NOT NULL,
  CONSTRAINT check_qc_exclusive CHECK (NOT (is_qc AND (is_normal OR is_emergency)))
);

-- 4. employees ─────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.employees (
  id                     uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name                   text NOT NULL,
  name_ar                text,
  phone                  text NOT NULL,
  skills                 text[] DEFAULT '{}',
  status                 public.employee_status DEFAULT 'active',
  team_id                uuid,
  avatar                 text,
  join_date              date NOT NULL,
  nationality            text,
  created_at             timestamptz DEFAULT now(),
  updated_at             timestamptz DEFAULT now(),
  site_visit_order       boolean DEFAULT false NOT NULL,
  site_visit_quotation   boolean DEFAULT false NOT NULL,
  avatar_url             text,
  deleted_at             timestamptz,
  division_id            uuid,
  profile_id             uuid
);

-- 5. vehicles ──────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.vehicles (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  type               text NOT NULL,
  plate              text NOT NULL,
  team_id            uuid,
  created_at         timestamptz DEFAULT now(),
  updated_at         timestamptz DEFAULT now(),
  traccar_device_id  text,
  deleted_at         timestamptz,
  name               text
);

-- 6. team_activity_log ─────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.team_activity_log (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  actor_id     uuid,
  action       text NOT NULL,
  entity_type  text NOT NULL,
  entity_id    uuid NOT NULL,
  before_data  jsonb,
  after_data   jsonb,
  created_at   timestamptz DEFAULT now() NOT NULL
);

-- 7. team_schedule_assignments ─────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.team_schedule_assignments (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  team_id      uuid NOT NULL,
  schedule_id  uuid NOT NULL,
  start_date   date NOT NULL,
  end_date     date,
  created_at   timestamptz DEFAULT now()
);

-- 8. tool_assignments ──────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.tool_assignments (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tool_unit_id  uuid NOT NULL,
  assigned_to   text NOT NULL,
  team_id       uuid,
  employee_id   uuid,
  assigned_at   timestamptz DEFAULT now() NOT NULL,
  notes         text,
  CONSTRAINT one_target CHECK (
    ((team_id IS NOT NULL) AND (employee_id IS NULL))
    OR ((employee_id IS NOT NULL) AND (team_id IS NULL))
  ),
  CONSTRAINT tool_assignments_assigned_to_check CHECK (assigned_to = ANY (ARRAY['team','employee']))
);

