-- ── DELTA: 20260721110000_fix_approval_rpc_column_name.sql ──
-- Fix: po_approval_action references ucr.custom_role_id but the column is ucr.role_id
-- This caused "column ucr.custom_role_id does not exist" on force-approve actions.

CREATE OR REPLACE FUNCTION public.po_approval_action(
  p_po_id uuid,
  p_step_id uuid,
  p_approver_email text,
  p_approver_name text,
  p_approver_profile_id uuid,
  p_action text,
  p_comment text DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_today         DATE := CURRENT_DATE;
  v_now           TIMESTAMPTZ := now();
  v_step          RECORD;
  v_iteration     INT;
  v_po            RECORD;
  v_approved_roles TEXT[] := '{}';
  v_pending_ids   UUID[];
  v_is_owner      BOOLEAN;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext(p_po_id::text));

  -- ── APPROVE ──────────────────────────────────────────────────────────
  IF p_action = 'approve' THEN
    IF p_step_id IS NULL THEN
      RAISE EXCEPTION 'p_step_id is required for approve action';
    END IF;

    SELECT tier_rank, iteration, role, status, is_active
      INTO v_step
      FROM po_approvals WHERE id = p_step_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Approval step not found'; END IF;
    IF v_step.status != 'pending' OR v_step.is_active != true THEN
      RAISE EXCEPTION 'Step is not pending/active';
    END IF;

    IF EXISTS (
      SELECT 1 FROM po_approvals
       WHERE po_id = p_po_id
         AND tier_rank = v_step.tier_rank
         AND iteration = v_step.iteration
         AND status = 'approved'
         AND approved_by = p_approver_email
         AND id != p_step_id
    ) THEN
      RAISE EXCEPTION 'Four-eyes violation: you already approved another role in this tier';
    END IF;

    UPDATE po_approvals SET
      status = 'approved', approved_by = p_approver_email,
      date = v_today, comment = p_comment
    WHERE id = p_step_id;

    v_approved_roles := ARRAY[v_step.role];

    INSERT INTO activity_log (entity_type, entity_id, module, action, details, performer_name, severity)
    VALUES ('purchase_order', p_po_id, 'purchase_orders',
            'Approved: ' || v_step.role, p_comment, p_approver_name, 'info');

  -- ── FORCE APPROVE (single step) ─────────────────────────────────────
  ELSIF p_action = 'force_approve' THEN
    IF p_step_id IS NULL THEN
      RAISE EXCEPTION 'p_step_id is required for force_approve action';
    END IF;
    IF p_comment IS NULL OR trim(p_comment) = '' THEN
      RAISE EXCEPTION 'A comment is required for force-approve';
    END IF;

    SELECT EXISTS (
      SELECT 1 FROM user_custom_roles ucr
        JOIN custom_roles cr ON cr.id = ucr.role_id
       WHERE ucr.profile_id = p_approver_profile_id
         AND cr.name = 'Owner' AND cr.is_approval_slot = true AND cr.deleted_at IS NULL
    ) INTO v_is_owner;
    IF NOT v_is_owner THEN RAISE EXCEPTION 'Only Owner role can force-approve'; END IF;

    SELECT role INTO v_step FROM po_approvals WHERE id = p_step_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Approval step not found'; END IF;

    UPDATE po_approvals SET
      status = 'approved', approved_by = p_approver_email,
      date = v_today, force_approved = true, force_comment = p_comment
    WHERE id = p_step_id;

    v_approved_roles := ARRAY[v_step.role];

    INSERT INTO activity_log (entity_type, entity_id, module, action, details, performer_name, severity)
    VALUES ('purchase_order', p_po_id, 'purchase_orders',
            'Force Approved: ' || v_step.role, p_comment, p_approver_name, 'critical');

  -- ── FORCE APPROVE ALL ────────────────────────────────────────────────
  ELSIF p_action = 'force_approve_all' THEN
    SELECT EXISTS (
      SELECT 1 FROM user_custom_roles ucr
        JOIN custom_roles cr ON cr.id = ucr.role_id
       WHERE ucr.profile_id = p_approver_profile_id
         AND cr.name = 'Owner' AND cr.is_approval_slot = true AND cr.deleted_at IS NULL
    ) INTO v_is_owner;
    IF NOT v_is_owner THEN RAISE EXCEPTION 'Only Owner role can force-approve'; END IF;

    SELECT COALESCE(MAX(iteration), 1) INTO v_iteration
      FROM po_approvals WHERE po_id = p_po_id;

    SELECT array_agg(id), array_agg(role)
      INTO v_pending_ids, v_approved_roles
      FROM po_approvals
     WHERE po_id = p_po_id AND iteration = v_iteration
       AND status = 'pending' AND is_active = true;

    IF v_pending_ids IS NULL OR array_length(v_pending_ids, 1) IS NULL THEN
      RAISE EXCEPTION 'No pending steps to force-approve';
    END IF;

    UPDATE po_approvals SET
      status = 'approved', approved_by = p_approver_email,
      date = v_today, force_approved = true,
      force_comment = CASE WHEN trim(COALESCE(p_comment,'')) != '' THEN p_comment ELSE NULL END
    WHERE id = ANY(v_pending_ids);

    FOR i IN 1..array_length(v_approved_roles, 1) LOOP
      INSERT INTO activity_log (entity_type, entity_id, module, action, details, performer_name, severity)
      VALUES ('purchase_order', p_po_id, 'purchase_orders',
              'Force Approved: ' || v_approved_roles[i],
              CASE WHEN trim(COALESCE(p_comment,'')) != '' THEN p_comment ELSE NULL END,
              p_approver_name, 'critical');
    END LOOP;

  -- ── REJECT (cancel or send-back-to-draft) ───────────────────────────
  ELSIF p_action IN ('reject_cancel', 'reject_draft') THEN
    IF p_step_id IS NULL THEN
      RAISE EXCEPTION 'p_step_id is required for reject action';
    END IF;

    SELECT COALESCE(MAX(iteration), 1) INTO v_iteration
      FROM po_approvals WHERE po_id = p_po_id;

    SELECT role INTO v_step FROM po_approvals WHERE id = p_step_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Approval step not found'; END IF;

    UPDATE po_approvals SET
      status = 'rejected', approved_by = p_approver_email,
      date = v_today, comment = p_comment
    WHERE id = p_step_id;

    UPDATE po_approvals SET status = 'rejected'
     WHERE po_id = p_po_id AND iteration = v_iteration
       AND status = 'pending' AND is_active = true AND id != p_step_id;

    IF p_action = 'reject_cancel' THEN
      UPDATE purchase_orders SET status = 'cancelled' WHERE id = p_po_id;
    ELSE
      UPDATE purchase_orders SET status = 'draft' WHERE id = p_po_id;
    END IF;

    v_approved_roles := ARRAY[v_step.role];

    INSERT INTO activity_log (entity_type, entity_id, module, action, details, performer_name, severity)
    VALUES ('purchase_order', p_po_id, 'purchase_orders',
            CASE WHEN p_action = 'reject_cancel'
              THEN 'Rejected by ' || v_step.role || ' — PO Cancelled'
              ELSE 'Rejected by ' || v_step.role || ' — Sent Back to Draft'
            END,
            p_comment, p_approver_name, 'warning');

    SELECT created_by, po_number INTO v_po
      FROM purchase_orders WHERE id = p_po_id;
    IF v_po.created_by IS NOT NULL THEN
      INSERT INTO notifications (profile_id, type, title, related_id, related_type)
      VALUES (v_po.created_by, 'po_rejected',
              'PO ' || v_po.po_number || ' was rejected by ' || p_approver_email,
              p_po_id, 'purchase_order');
    END IF;

    UPDATE notifications SET read_at = v_now
     WHERE related_id = p_po_id AND type = 'po_approval_requested' AND read_at IS NULL;

    RETURN jsonb_build_object(
      'ok', true, 'po_status',
      CASE WHEN p_action = 'reject_cancel' THEN 'cancelled' ELSE 'draft' END,
      'action', p_action, 'roles', to_jsonb(v_approved_roles)
    );

  ELSE
    RAISE EXCEPTION 'Unknown action: %', p_action;
  END IF;

  -- ── Common post-approve path: clear notifications + advance tier ────
  UPDATE notifications SET read_at = v_now
   WHERE related_id = p_po_id AND type = 'po_approval_requested' AND read_at IS NULL;

  DECLARE
    v_adv_iteration INT;
    v_next_rank     INT;
    v_all_done      BOOLEAN;
  BEGIN
    IF NOT EXISTS (
      SELECT 1 FROM purchase_orders WHERE id = p_po_id AND status = 'pending_approval'
    ) THEN
      SELECT status INTO v_po FROM purchase_orders WHERE id = p_po_id;
      RETURN jsonb_build_object('ok', true, 'po_status', v_po.status, 'action', p_action, 'roles', to_jsonb(v_approved_roles));
    END IF;

    SELECT COALESCE(MAX(iteration), 1) INTO v_adv_iteration
      FROM po_approvals WHERE po_id = p_po_id;

    SELECT NOT EXISTS (
      SELECT 1 FROM po_approvals
       WHERE po_id = p_po_id AND iteration = v_adv_iteration
         AND is_active = true AND status != 'approved'
    ) INTO v_all_done;

    IF v_all_done THEN
      SELECT MIN(tier_rank) INTO v_next_rank
        FROM po_approvals
       WHERE po_id = p_po_id AND iteration = v_adv_iteration
         AND is_active = false AND status = 'pending';

      IF v_next_rank IS NOT NULL THEN
        UPDATE po_approvals SET is_active = true
         WHERE po_id = p_po_id AND iteration = v_adv_iteration AND tier_rank = v_next_rank;
      ELSE
        UPDATE purchase_orders SET status = 'approved' WHERE id = p_po_id;

        SELECT created_by, po_number INTO v_po FROM purchase_orders WHERE id = p_po_id;
        IF v_po.created_by IS NOT NULL THEN
          INSERT INTO notifications (profile_id, type, title, related_id, related_type)
          VALUES (v_po.created_by, 'po_approved',
                  'PO ' || v_po.po_number || ' has been fully approved',
                  p_po_id, 'purchase_order');
        END IF;

        INSERT INTO activity_log (entity_type, entity_id, module, action, performer_name, severity)
        VALUES ('purchase_order', p_po_id, 'purchase_orders',
                CASE WHEN p_action LIKE 'force%' THEN 'PO Fully Approved (Force)' ELSE 'PO Fully Approved' END,
                p_approver_name,
                CASE WHEN p_action LIKE 'force%' THEN 'critical' ELSE 'info' END);
      END IF;
    END IF;
  END;

  SELECT status INTO v_po FROM purchase_orders WHERE id = p_po_id;
  RETURN jsonb_build_object(
    'ok', true, 'po_status', v_po.status,
    'action', p_action, 'roles', to_jsonb(v_approved_roles)
  );
END;
$$;


-- ── DELTA: 20260724000000_drop_dead_feature_tables.sql ──
-- Drop tables that back features the deploy branch no longer ships.
--
-- Audit trail (grep of src/ + supabase/migrations/ on 2026-07-24):
--   Tables below have zero .from()/.rpc()/join references in application code.
--   Their backing UIs (Teams module, Team-Leader mode, Calendar, Map, Contact
--   Centre reminders, Vehicles admin) were removed on this branch. Related
--   RPCs are dropped in the same migration so the schema doesn't leave
--   broken functions behind.
--
-- Kept intentionally:
--   * tool_asset_units — still used by the Inventory Tools & Assets tab.
--   * warehouse_stock_summary / warehouse_stock_allocations — populated by
--     triggers, read via warehouse_stock_view.
--   * customer_credit_group_approvals / customer_credit_group_requests —
--     used by the shipping credit-group admin.
--
-- Safe to reverse: the previous migration
-- (20260723300000_restore_teams_module_tables.sql) contains the CREATE
-- statements for the team-module tables should this ever need reinstating.

BEGIN;

-- ── 1. Drop functions that reference tables about to disappear ────────
DROP FUNCTION IF EXISTS public.assign_team_leader(uuid, uuid)                                                              CASCADE;
DROP FUNCTION IF EXISTS public.check_is_division_manager(uuid)                                                             CASCADE;
DROP FUNCTION IF EXISTS public.get_date_team_availability(date[], time without time zone, time without time zone)          CASCADE;
DROP FUNCTION IF EXISTS public.get_team_leader_visits(uuid, date)                                                          CASCADE;
DROP FUNCTION IF EXISTS public.swap_visit_team(uuid, uuid)                                                                 CASCADE;
DROP FUNCTION IF EXISTS public.sync_team_active_schedule(uuid)                                                             CASCADE;
DROP FUNCTION IF EXISTS public.upsert_employee_services(uuid, uuid[])                                                      CASCADE;
DROP FUNCTION IF EXISTS public.save_employee(uuid, text, text, text, date, text, text, uuid[])                             CASCADE;
DROP FUNCTION IF EXISTS public.save_employee(uuid, text, text, text, date, text, text, uuid[], uuid)                       CASCADE;
DROP FUNCTION IF EXISTS public.save_employee(uuid, text, text, text, date, text, boolean, boolean, text, uuid[])           CASCADE;
DROP FUNCTION IF EXISTS public.schedule_day_end(jsonb)                                                                     CASCADE;
DROP FUNCTION IF EXISTS public.schedule_day_start(jsonb)                                                                   CASCADE;

-- ── 2. Drop feature tables (CASCADE handles residual FKs / views) ─────
DROP TABLE IF EXISTS public.tool_assignments           CASCADE;
DROP TABLE IF EXISTS public.team_schedule_assignments  CASCADE;
DROP TABLE IF EXISTS public.team_activity_log          CASCADE;
DROP TABLE IF EXISTS public.vehicles                   CASCADE;
DROP TABLE IF EXISTS public.employees                  CASCADE;
DROP TABLE IF EXISTS public.teams                      CASCADE;
DROP TABLE IF EXISTS public.schedules                  CASCADE;

DROP TABLE IF EXISTS public.customer_blocks            CASCADE;
DROP TABLE IF EXISTS public.document_terms             CASCADE;
DROP TABLE IF EXISTS public.notification_config        CASCADE;
DROP TABLE IF EXISTS public.notification_templates     CASCADE;

-- ── 3. Enums that were owned only by the team tables ──────────────────
DROP TYPE IF EXISTS public.employee_status CASCADE;
DROP TYPE IF EXISTS public.team_tag        CASCADE;

COMMIT;


-- ── DELTA: 20260724010000_schema_cleanup_calendar_returns_wh_rp.sql ──
-- Schema cleanup pass on the deploy branch:
--   1. Drop company_divisions.calendar_schedule_id — its target
--      (public.schedules) was dropped in 20260724000000, so the FK
--      already CASCADEd but the column itself lingered.
--   2. Trim return_source_type enum: remove 'order', which backed the
--      now-deleted Customer Orders module. Any orphan returns rows are
--      deleted first (their source_id pointed at a dropped table).
--   3. Rename warehouse_field_rps -> warehouse_responsible_persons for
--      clarity ("field RP" was jargon left over from a previous project).
--      RPC replace_warehouse_field_rps renamed to match.
--
-- No .from()/.rpc() reference in application code will be left dangling
-- after the companion code changes on this same branch.

BEGIN;

-- ── 1. Drop calendar_schedule_id column ───────────────────────────────
ALTER TABLE public.company_divisions
  DROP COLUMN IF EXISTS calendar_schedule_id;

-- ── 2. Trim return_source_type enum ───────────────────────────────────
-- Postgres can't DROP VALUE from an enum, so recreate + swap.
-- First, purge any dead 'order' rows (source_id points at the deleted
-- Customer Orders table so they are unusable regardless).
DELETE FROM public.returns WHERE source_type::text = 'order';

ALTER TYPE public.return_source_type RENAME TO return_source_type_old;
CREATE TYPE public.return_source_type AS ENUM ('sale_order', 'purchase_order');

ALTER TABLE public.returns
  ALTER COLUMN source_type TYPE public.return_source_type
  USING source_type::text::public.return_source_type;

DROP TYPE public.return_source_type_old;

-- ── 3. Rename warehouse_field_rps -> warehouse_responsible_persons ────
ALTER TABLE IF EXISTS public.warehouse_field_rps
  RENAME TO warehouse_responsible_persons;

-- Constraint + index renames follow the table rename convention.
DO $$ BEGIN
  ALTER TABLE public.warehouse_responsible_persons
    RENAME CONSTRAINT warehouse_field_rps_pkey TO warehouse_responsible_persons_pkey;
EXCEPTION WHEN undefined_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE public.warehouse_responsible_persons
    RENAME CONSTRAINT warehouse_field_rps_warehouse_id_fkey TO warehouse_responsible_persons_warehouse_id_fkey;
EXCEPTION WHEN undefined_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE public.warehouse_responsible_persons
    RENAME CONSTRAINT warehouse_field_rps_profile_id_fkey TO warehouse_responsible_persons_profile_id_fkey;
EXCEPTION WHEN undefined_object THEN NULL; END $$;

-- Rename the RPC that writes to this table so its name matches too.
DO $$
DECLARE
  fn_sig text;
BEGIN
  SELECT p.oid::regprocedure::text INTO fn_sig
    FROM pg_proc p
   WHERE p.proname = 'replace_warehouse_field_rps'
     AND p.pronamespace = 'public'::regnamespace
   LIMIT 1;
  IF fn_sig IS NOT NULL THEN
    EXECUTE format('ALTER FUNCTION %s RENAME TO replace_warehouse_responsible_persons', fn_sig);
  END IF;
END $$;

COMMIT;


-- ── DELTA: 20260724020000_drop_customers_phone.sql ──
-- Drop the legacy customers.phone scalar column.
--
-- Multi-phone support lives on customer_phones, but historical writes
-- through CustomerDialog only stamped customers.phone (never
-- customer_phones). Backfill first so no rows lose their number.
--
-- Backfill rules:
--   * For every customer whose customers.phone is NOT NULL:
--       - if the customer already has a customer_phones row with the
--         same phone value, leave it alone.
--       - if the customer already has ANY customer_phones row (even
--         with a different number), leave it alone. customers.phone is
--         considered stale.
--       - otherwise, insert a customer_phones row with is_primary=true
--         copying the phone.
--   * After backfill, drop customers.phone.

BEGIN;

-- ON CONFLICT DO NOTHING covers the case where two customers historically
-- shared the same phone (test/duplicate data). The second customer keeps no
-- customer_phones row and must have one added manually.
INSERT INTO public.customer_phones (customer_id, phone, is_primary, created_at)
SELECT c.id, c.phone, true, now()
  FROM public.customers c
 WHERE c.phone IS NOT NULL
   AND NOT EXISTS (
     SELECT 1 FROM public.customer_phones cp WHERE cp.customer_id = c.id
   )
ON CONFLICT (phone) DO NOTHING;

ALTER TABLE public.customers DROP COLUMN IF EXISTS phone;

COMMIT;


-- ── DELTA: 20260724030000_patch_customer_statement_rpc_for_phones.sql ──
-- customers.phone was dropped in 20260724020000. Any function that still
-- selected c.phone is now broken. Patch rpc_customer_statement_v2 — the
-- only such function called by shipping code — to derive phone from
-- customer_phones (primary if present, else the first row, else null).

BEGIN;

CREATE OR REPLACE FUNCTION public.rpc_customer_statement_v2(p_customer_id uuid)
RETURNS jsonb
LANGUAGE plpgsql STABLE
AS $$
DECLARE
  result        jsonb;
  cust_name     text;
  cust_phone    text;
  cust_type     text;
  account_type  text;
  orders        jsonb;
  totals        jsonb;
  open_count    bigint;
BEGIN
  SELECT c.name, c.customer_type::text, cg.name
  INTO cust_name, cust_type, account_type
  FROM customers c
  LEFT JOIN credit_groups cg ON cg.id = c.credit_group_id
  WHERE c.id = p_customer_id;

  IF cust_name IS NULL THEN
    RAISE EXCEPTION 'Customer not found: %', p_customer_id USING ERRCODE = 'P0002';
  END IF;

  -- Phone: prefer the primary row, else the first available row.
  SELECT phone INTO cust_phone
  FROM customer_phones
  WHERE customer_id = p_customer_id
  ORDER BY is_primary DESC NULLS LAST, created_at ASC
  LIMIT 1;

  WITH sos AS (
    SELECT so.id, so.so_number, so.created_at, so.status, so.total
    FROM sale_orders so
    WHERE so.customer_id = p_customer_id
      AND so.status != 'cancelled'
      AND so.deleted_at IS NULL
  ),
  so_inv AS (
    SELECT sos.id AS so_id, inv.id AS invoice_id
    FROM sos
    LEFT JOIN so_invoices inv
           ON inv.sale_order_id = sos.id
  ),
  so_paid AS (
    SELECT si.so_id,
           COALESCE(SUM(COALESCE(p.amount_qar, p.amount)), 0) AS paid
    FROM so_inv si
    LEFT JOIN payments p
           ON p.deleted_at IS NULL
          AND (
                (p.source_type = 'sale_order' AND p.source_id = si.so_id)
             OR (si.invoice_id IS NOT NULL
                 AND p.source_type = 'invoice'
                 AND p.source_id = si.invoice_id)
             OR (si.invoice_id IS NOT NULL AND p.invoice_id = si.invoice_id)
              )
    GROUP BY si.so_id
  )
  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.created_at DESC), '[]'::jsonb)
  INTO orders
  FROM (
    SELECT sos.id,
           sos.so_number,
           sos.created_at,
           sos.status::text AS status,
           sos.total::numeric AS total,
           COALESCE(sp.paid, 0)::numeric AS paid,
           GREATEST(0, sos.total - COALESCE(sp.paid, 0))::numeric AS outstanding
    FROM sos
    LEFT JOIN so_paid sp ON sp.so_id = sos.id
  ) t;

  SELECT jsonb_build_object(
           'total_orders_value', COALESCE(SUM((o->>'total')::numeric), 0),
           'total_paid',         COALESCE(SUM((o->>'paid')::numeric), 0),
           'total_outstanding',  COALESCE(SUM((o->>'outstanding')::numeric), 0)
         )
  INTO totals
  FROM jsonb_array_elements(orders) o;

  SELECT COALESCE(COUNT(*), 0)
  INTO open_count
  FROM jsonb_array_elements(orders) o
  WHERE (o->>'outstanding')::numeric > 0;

  result := jsonb_build_object(
    'customer', jsonb_build_object(
      'name',         cust_name,
      'phone',        cust_phone,
      'account_type', COALESCE(account_type, INITCAP(cust_type), 'Cash')
    ),
    'orders',            orders,
    'totals',            COALESCE(totals, jsonb_build_object(
                            'total_orders_value', 0,
                            'total_paid',         0,
                            'total_outstanding',  0)),
    'open_orders_count', open_count
  );

  RETURN result;
END;
$$;

COMMIT;


-- ── DELTA: 20260724040000_save_customer_phones_rpc.sql ──
-- Atomic multi-phone save for a customer.
--
-- Semantics:
--   * p_phones is a JSON array of {phone, is_primary}. Empty array is
--     an error (a customer must have at least one phone).
--   * Exactly one entry must have is_primary=true.
--   * If any phone in the list is currently owned by a DIFFERENT
--     customer, the call fails with 23505 so the UI can surface
--     "already assigned to another customer".
--   * Phones the same customer already owns keep their id + created_at;
--     only their is_primary flag is updated.
--   * Phones on this customer that are NOT in the list are removed.

BEGIN;

CREATE OR REPLACE FUNCTION public.save_customer_phones(
  p_customer_id uuid,
  p_phones      jsonb
) RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_phones        text[];
  v_primary_count int;
  v_conflict_row  record;
BEGIN
  IF p_customer_id IS NULL THEN
    RAISE EXCEPTION 'customer_id is required';
  END IF;

  IF p_phones IS NULL OR jsonb_typeof(p_phones) <> 'array' OR jsonb_array_length(p_phones) = 0 THEN
    RAISE EXCEPTION 'At least one phone is required';
  END IF;

  SELECT count(*) INTO v_primary_count
  FROM jsonb_array_elements(p_phones) elem
  WHERE (elem->>'is_primary')::boolean IS TRUE;

  IF v_primary_count <> 1 THEN
    RAISE EXCEPTION 'Exactly one phone must be marked primary (got %)', v_primary_count;
  END IF;

  SELECT array_agg(elem->>'phone') INTO v_phones
  FROM jsonb_array_elements(p_phones) elem;

  -- Cross-customer collision check.
  SELECT cp.phone, cp.customer_id
    INTO v_conflict_row
    FROM public.customer_phones cp
   WHERE cp.phone = ANY(v_phones)
     AND cp.customer_id <> p_customer_id
   LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'Phone number % is already assigned to another customer', v_conflict_row.phone
      USING ERRCODE = '23505';
  END IF;

  -- Remove rows on this customer that aren't in the new list.
  DELETE FROM public.customer_phones
   WHERE customer_id = p_customer_id
     AND phone <> ALL(v_phones);

  -- Upsert. ON CONFLICT (phone) is safe here — the collision check above
  -- already established that every phone in the list either doesn't
  -- exist yet or already belongs to this customer.
  INSERT INTO public.customer_phones (customer_id, phone, is_primary)
  SELECT p_customer_id,
         elem->>'phone',
         (elem->>'is_primary')::boolean
    FROM jsonb_array_elements(p_phones) elem
   ON CONFLICT (phone) DO UPDATE
     SET is_primary = EXCLUDED.is_primary;
END;
$$;

GRANT EXECUTE ON FUNCTION public.save_customer_phones(uuid, jsonb) TO authenticated;

COMMIT;

